window.LECTURE.units.push({"id":112,"title":"제4절 특수불법행위","chapter":"제4장 불법행위","book":"불법행위","start":112,"end":145,"content":[{"type":"h2","text":"제4절 특수불법행위","emphasis":[],"underline":[],"highlight":[],"strike":[],"headingLevel":2,"pageStart":112,"pageEnd":112,"anchor":"source-112-0"},{"type":"h3","text":"Ⅰ. 특수불법행위의 유형","emphasis":[[0,13]],"underline":[],"highlight":[],"strike":[],"headingLevel":3,"pageStart":112,"pageEnd":112,"anchor":"source-112-1"},{"type":"h3","text":"1. 특수불법행위의 유형","emphasis":[[0,13]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":112,"pageEnd":112,"anchor":"source-112-2"},{"type":"p","text":"불법행위에 대하여 민법 제750조는 불법행위의 기본적인 구성요건이 된다. 이와 달리 불법행위에 대한 개별적인 특칙은 제755조부터 제759조까지, 그리고 제760조에서 정하고 있다. 특수한 불법행위는 일반불법행위와 달리 직접적인 가해행위를 하지 않은 자가 일정한 지위(감독자, 사용자, 도급인) 때문에 또는 관리·감독에 대하여 책임을 지도록 규정하고 있다. 따라서 특수불법행위를 “타인행위에 대한 책임” 또는 “물건의 관리․감독에 대한 책임”으로 부르기도 한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":112,"pageEnd":112,"anchor":"source-112-3"},{"type":"table","html":"<table><caption>강의자료 112쪽 · 비교표</caption><tbody><tr><th rowspan=\"1\" colspan=\"3\">불법행위법 규정</th></tr><tr><td rowspan=\"4\" colspan=\"1\">일반불법행위</td><td rowspan=\"1\" colspan=\"1\">불법행위의 기본적인 책임구성요건</td><td rowspan=\"1\" colspan=\"1\">제750조</td></tr><tr><td rowspan=\"1\" colspan=\"1\">재산이외의 손해의 배상</td><td rowspan=\"1\" colspan=\"1\">제751조</td></tr><tr><td rowspan=\"1\" colspan=\"1\">생명침해로 인한 위자료</td><td rowspan=\"1\" colspan=\"1\">제752조</td></tr><tr><td rowspan=\"1\" colspan=\"1\">책임무능력자(미성년자, 심신상실자)</td><td rowspan=\"1\" colspan=\"1\">제753조․제754조</td></tr><tr><td rowspan=\"6\" colspan=\"1\">특수불법행위 (타인행위에 대한 책임)</td><td rowspan=\"1\" colspan=\"1\">책임무능력자의 감독자책임</td><td rowspan=\"1\" colspan=\"1\">제755조</td></tr><tr><td rowspan=\"1\" colspan=\"1\">사용자책임</td><td rowspan=\"1\" colspan=\"1\">제756조</td></tr><tr><td rowspan=\"1\" colspan=\"1\">도급인의 책임</td><td rowspan=\"1\" colspan=\"1\">제757조</td></tr><tr><td rowspan=\"1\" colspan=\"1\">공작물 등의 점유자․소유자의 책임</td><td rowspan=\"1\" colspan=\"1\">제758조</td></tr><tr><td rowspan=\"1\" colspan=\"1\">동물의 점유자의 책임</td><td rowspan=\"1\" colspan=\"1\">제759조</td></tr><tr><td rowspan=\"1\" colspan=\"1\">공동불법행위</td><td rowspan=\"1\" colspan=\"1\">제760조</td></tr></tbody></table>","text":"불법행위법 규정 일반불법행위 불법행위의 기본적인 책임구성요건 제750조 재산이외의 손해의 배상 제751조 생명침해로 인한 위자료 제752조 책임무능력자(미성년자, 심신상실자) 제753조․제754조 특수불법행위 (타인행위에 대한 책임) 책임무능력자의 감독자책임 제755조 사용자책임 제756조 도급인의 책임 제757조 공작물 등의 점유자․소유자의 책임 제758조 동물의 점유자의 책임 제759조 공동불법행위 제760조","pageStart":112,"pageEnd":112,"anchor":"source-112-4"},{"type":"h3","text":"2. 일반불법행위와 특수불법행위의 적용순서","emphasis":[[0,23]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":112,"pageEnd":112,"anchor":"source-112-5"},{"type":"p","text":"일반불법행위에 대한 제750조 규정에 대하여 특수한 불법행위에 대한 규정은 특칙이므로, 불법행위의 사안을 검토할 때 언제나 특수불법행위에 해당하는지를 먼저 검토하여야 한다. 그러나 주의하여야 할 점은 같은 사안에 특수불법행위규정과 일반불법행위규정(제750조)이 동시에 적용될 수 있다(예: 사용자의 제756조에 따른 사용자책임과 피용자의 제750조 책임)는 점이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":112,"pageEnd":112,"anchor":"source-112-6"},{"type":"h3","text":"Ⅱ. 책임무능력자의 감독자의 책임","emphasis":[[0,18]],"underline":[],"highlight":[],"strike":[],"headingLevel":3,"pageStart":112,"pageEnd":112,"anchor":"source-112-7"},{"type":"p","text":"제755조【감독자의 책임】 ① 다른 자에게 손해를 가한 사람이 제753조 또는 제754조에 따라 책임이 없는 경우에는 그를 감독할 법정의무가 있는 자가 그 손해를 배상할 책임이 있다. 다만, 감독의무를 게을리하지 아니한 경우에는 그러하지 아니하다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"statute","group":"민법4_강의자료(불법행위)-151","continued":false,"pageStart":112,"pageEnd":112,"anchor":"source-112-8"},{"type":"p","text":"② 감독의무자를 갈음하여 제753조 또는 제754조에 따라 책임이 없는 사람을 감독하는 자도 제1항의 책임이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"statute","group":"민법4_강의자료(불법행위)-151","continued":false,"pageStart":112,"pageEnd":113,"anchor":"source-112-9"},{"type":"p","text":"[사례] 초등생 '5억 람보르기니 테러', 수리비가…헉!, 온라인 중앙일보, 2012. 07. 26.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-152","continued":false,"pageStart":113,"pageEnd":113,"anchor":"source-113-1"},{"type":"p","text":"악동 초등학생들이 장난으로 5억 원짜리 람보르기니를 엉망으로 만들었다는 소식. 수리비가 1억 5000만 원이나 나왔다. 한 달이 넘도록 배상문제가 해결되지 않고 있다. 무슨 문제가 있는 것일까? 지난달 18일 광주광역시의 아파트. 초등학생 남자 아이들이 승용차에 소화기를 마구 뿌려댄다. 놀이터 미끄럼틀에 오르듯 차 위를 오르락내리락, 신이 났다. 아이들이 장난감처럼 갖고 놀다 파손한 차량은 람보르기니 무르시엘라고 LP640. 새 차 가격이 5억 원에 이른다. 아이들은 차량 파손 혐의로 경찰 조사를 받았고 부모가 수리비를 물어주기로 약속했다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-152","continued":false,"pageStart":113,"pageEnd":113,"anchor":"source-113-2"},{"type":"p","text":"[람보르기니 차주 : 확실히 되는 건 없고 진행되고 있어요. 합의도 몇 명은 안 되고 있고…]","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-152","continued":false,"pageStart":113,"pageEnd":113,"anchor":"source-113-3"},{"type":"p","text":"문제는 1억 5000만 원에 이르는 엄청난 수리비. 앞뒤 범퍼를 교환하는 비용은 웬만한 풀옵션 중형차 가격인 3000만 원. 엔진룸 후드와 라이트를 바꾸는 데도 2000만 원이 들어간다. 소화기 분말로 엉망이 된 차체를 도색하는 데 1000만 원. 외부 부품을 교환하는 데 1000만 원, 엔진을 청소하고 다시 세팅하는 데 4000만 원. 썬루프는 4000만 원 가량이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-152","continued":false,"pageStart":113,"pageEnd":113,"anchor":"source-113-4"},{"type":"p","text":"[수입차 정비업체 : 모든 걸 다 한다면 견적은 1억2000만 원에서 1억5000만 원쯤 할 거고요. 차주분이 손상된 부분에 대해 저희가 낸 건 그 정도 나와요.]","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-152","continued":false,"pageStart":113,"pageEnd":113,"anchor":"source-113-5"},{"type":"p","text":"수리비가 많은 데다 학생들의 가담 정도를 가리지 못해 한 달이 지났지만 배상이 이뤄지지 않고 있다. 현재 람보르기니는 정비를 위해 대기하고 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-152","continued":false,"pageStart":113,"pageEnd":113,"anchor":"source-113-6"},{"type":"p","text":"[김덕은/변호사 : 합의가 되지 않으면 법원에서 법정의 판단을 받을 수밖에 없을 것 같습니다]","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-152","continued":false,"pageStart":113,"pageEnd":113,"anchor":"source-113-7"},{"type":"p","text":"초등학생 악동들의 철부지 장난이 민사소송으로 번질 처지에 놓였다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-152","continued":false,"pageStart":113,"pageEnd":113,"anchor":"source-113-8"},{"type":"p","text":"온라인 중앙일보, 정진명 기자.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-152","continued":false,"pageStart":113,"pageEnd":113,"anchor":"source-113-9"},{"type":"p","text":"[사례] 고등학교 2학년에 재학 중이던 甲․乙․丙은 술에 취해, 평소 甲과 사귀던 중학교 3학년에 재학 중인 여학생 丁이 가출을 했다는 이유로 혼을 내주겠다며 丙의 자취방으로 데려갔다. 자취방에서 乙이 주먹으로 丁의 얼굴을 가격한 다음, 丙은 병에 든 석유를 丁의 머리에 붓고 甲은 버너용 플라스틱 알코올병에 있던 알코올을 丁의 목 부위에 붓고 불을 붙였다. 이로 인해 丁은 2개월의 치료를 요하는 전신 3도의 화상을 입게 되었다. 이때 丁은 누구를 상대로 손해배상을 청구할 수 있는가?","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-153","continued":false,"pageStart":113,"pageEnd":113,"anchor":"source-113-10"},{"type":"p","text":"≪해설≫ 丁에 대해서 가해행위를 한 자는 甲․乙․丙이므로 이들은 제750조에 따라 불법행위책임을 진다. 다음으로 甲․乙․丙이 책임능력 있는 미성년자이므로 이들 외에 그들의 부모들이 책임을 지는지가 문제 된다. 판례의 경우 책임능력 있는 미성년자의 친권자도 감독의무소홀에 따른 일반불법행위책임(제750조)을 진다고 보므로, 사안에서 甲․乙․丙과 더불어 그들의 친권자들도 책임을 진다. 그리고 이들 간에는 공동불법행위가 성립하므로, 丁의 손해에 대하여 모두 연대하여 책임을 지게 될 것이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-153","continued":false,"pageStart":113,"pageEnd":113,"anchor":"source-113-11"},{"type":"h3","text":"1. 의의","emphasis":[[0,5]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":113,"pageEnd":113,"anchor":"source-113-12"},{"type":"p","text":"책임무능력자가 제3자에게 손해를 가한 경우에, 그 책임무능력자를 감독할 법정의무 있는 자(친권자·후견인) 또는 그에 갈음하여 책임무능력자를 감독하는 자(예, 보모·유치원장·초등학교장·정신병원장 등)가 그 손해에 대하여 배상책임을 지는 것을 말한다(제755조).","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":113,"pageEnd":113,"anchor":"source-113-13"},{"type":"p","text":"F 책임무능력자의 감독자 책임은 일반 불법행위에 있어서의 책임이론과 다른 성질을 갖고 있다. ㈀ 이 책임은 책임무능력자의 가해의 결과에 대한 책임이다. 즉, 감독채무자 스스로 가해행위를 하여 발생한 책임이 아니다. ㈁ 이 책임에 있어서 감독의무자의 과실은 책임무능력자의 행위에 대한 감독을 게을리한 것에 있다. 책임무능력자가 가해행위를 한 것 자체에 대한 과실은 아니다. ㈂ 감독의무자의 과실에 관한 입증책임이 전환되어 있다. 따라서 감독의무자가 감독을 게을리하지 않았음을 입증하지 않는 한 책임을 면하지 못한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"comment","group":"민법4_강의자료(불법행위)-154","continued":false,"pageStart":113,"pageEnd":113,"anchor":"source-113-14"},{"type":"h3","text":"2. 감독자책임의 요건","emphasis":[[0,12]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":113,"pageEnd":113,"anchor":"source-113-15"},{"type":"h3","text":"(1) 책임무능력자의 고의·과실에 의한 위법한 가해행위","emphasis":[[0,30]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":113,"pageEnd":113,"anchor":"source-113-16"},{"type":"p","text":"제753조【미성년자의 책임능력】 미성년자가 타인에게 손해를 가한 경우에 그 행위의 책임을 변식할 지능이 없는 때에는 배상의 책임이 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"statute","group":"민법4_강의자료(불법행위)-155","continued":false,"pageStart":113,"pageEnd":113,"anchor":"source-113-17"},{"type":"p","text":"제754조【심신상실자의 책임능력】 심신상실중에 타인에게 손해를 가한 자는 배상의 책임이 없다. 그러나 고의 또는 과실로 인하여 심신상실을 초래한 때에는 그러하지 아니하다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"statute","group":"민법4_강의자료(불법행위)-156","continued":false,"pageStart":114,"pageEnd":114,"anchor":"source-114-0"},{"type":"p","text":"제755조【감독자의 책임】 ① 다른 자에게 손해를 가한 사람이 제753조 또는 제754조에 따라 책임이 없는 경우에는 그를 감독할 법정의무가 있는 자가 그 손해를 배상할 책임이 있다. 다만, 감독의무를 게을리하지 아니한 경우에는 그러하지 아니하다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"statute","group":"민법4_강의자료(불법행위)-157","continued":false,"pageStart":114,"pageEnd":114,"anchor":"source-114-1"},{"type":"p","text":"② 감독의무자를 갈음하여 제753조 또는 제754조에 따라 책임이 없는 사람을 감독하는 자도 제1항의 책임이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"statute","group":"민법4_강의자료(불법행위)-157","continued":false,"pageStart":114,"pageEnd":114,"anchor":"source-114-2"},{"type":"p","text":"피감독자인 책임무능력자가 고의 또는 과실에 의한 위법행위로 타인에게 손해를 가하여야 한다. 즉, 책임무능력자의 불법행위가 있어야 한다. 따라서 미성년자 등에게 책임능력이 있어서 스스로 불법행위책임을 지는 경우라면 비록 감독의무자의 감독에 과실이 있다고 하여도 감독자가 본조에 의한 책임을 지지 않는다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":114,"pageEnd":114,"anchor":"source-114-3"},{"type":"p","text":"그러나 피감독자로 인한 손해를 감독의무자가 제755조에 따라 보충적으로만 부담한다는 결론은 때에 따라 부당한 결과를 가져온다. 현재 대법원은 미성년자 등이 가해행위 당시에 책임능력을 가지고 있었다고 하여도 그 가해행위로 발생한 손해와 감독의무자의 감독의무위반 사이에 상당인과관계가 있으면 감독의무자는 일반 불법행위자로서 손해배상책임을 부담하는 것으로 보고 있다(구체적인 것은 아래 관련 부분 참고).","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":114,"pageEnd":114,"anchor":"source-114-4"},{"type":"p","text":"피감독자의 고의 또는 과실에 대한 입증책임은 불법행위의 일반원칙에 따라서 손해배상청구권자(피해자)가 부담한다. 가해자가 행위 시에 책임능력이 없었다는 점에 대해서도 제755조의 손해배상을 청구하는 피해자가 주장·입증해야 한다. 피해자가 가해자의 책임무능력을 이유로 감독자에게 손해배상을 청구하고 있기 때문이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":114,"pageEnd":114,"anchor":"source-114-5"},{"type":"p","text":"v 대법원 1978. 11. 28. 선고 78다1805 판결 : [사실관계] 가해자인 소외 최00(가해자, 피고의 아들)는 사고 당시에 만 14세 2개월 된 소년으로서 중학교 3학년에 재학중이었는데 동네 콘크리트로 된 다리 위에서 원고(피해자)는 정00과 1조가 되고 최00(가해자)는 조00와 다른 1조가 되어 각기 한사람씩 대결하는 소위 태그매치 방식의 레스링 놀이를 하게 되었고 그 레스링 놀이에서 원고와 조00가 어울려 레스링을 하던 중 조00이 원고의 밑에 깔리게 되자 교량 난간에서 이를 보고 있던 최00(가해자)가 조00를 구원하기 위하여 오른발로 원고의 등을 예고 없이 갑자기 밀어버림으로써 원고가 콘크리트 교량 바닥에 얼굴을 부딪혀 치아 5개가 탈락되는 상해를 입게 되었다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-158","continued":false,"pageStart":114,"pageEnd":114,"anchor":"source-114-6"},{"type":"p","text":"[법원의 판단] 가해자가 14년 2개월 된 중학생이라고는 하나 사고 당시가 야간이고 동 레스링을 한 장소가 다치기 쉬운 콘크리트로 된 다리의 맨바닥이었으며 그러한 맨바닥 위에서 얼굴을 지면으로 향하여 엎드려 있는 피해자를 갑자기 아무런 예고 없이 발로 밀어버린 최00(가해자)의 소위는 다른 사정이 없는 한 불법행위의 책임을 변식할 수 있는 지능을 가진 사람의 행위라고 볼 수는 없는 것이므로 결국 가해자의 아버지인 피고는 그 보호감독자로서의 주의의무를 해태하지 아니하였음을 주장입증하지 못한 본건에 있어서 가해자의 과실행위로 인하여 원고에게 가한 모든 손해를 배상할 책임이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-158","continued":false,"pageStart":114,"pageEnd":114,"anchor":"source-114-7"},{"type":"h3","text":"(2) 감독의무자의 감독의무 위반","emphasis":[[0,18]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":114,"pageEnd":114,"anchor":"source-114-8"},{"type":"p","text":"감독자책임은 자기의 직접적인 행위가 아닌 타인의 위법행위에 대한 책임이다. 책임무능력자의 감독자책임은 가족단체의 통솔자로서의 가장의 책임에서 유래하였다. 이것이 과실책임과 절충하여, 감독의무의 태만을 요건으로 하여 감독자책임이 인정되었다. 따라서 감독상의 주의를 다했다는 점을 증명하면 면책되는 중간책임(= 추정과실책임, vermutete Verschuldenshaftung)에 해당한다. 현재 법정감독의무자(제755조 제1항)에는 미성년자의 친권자, 양육자, 후견인 등이 있고, 감독의무자에 갈음하여 책임무능력자를 감독하는 자(제755조 제2항)에는 교사, 소년원 직원 등이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":114,"pageEnd":114,"anchor":"source-114-9"},{"type":"p","text":"감독상의 의무란 구체적 가해행위에 대한 감독이 아니라, 일반적인 생활에 대한 감독이다. 단, 법정감독의무자의 책임범위와 대리감독의무자의 책임범위는 서로 차이가 있다. 법정감독의무자는 전생활관계에 대하여 일반적인 감독의무가 있으므로 구체적인 가해행위에 대한 감독의무위반과 상관없이 책임을 진다. 제755조의 법문상으로는 법정감독자와 대리감독자 사이에 책임의 차이가 없는 것으로 규정되어 있지만, 법원은 양자 간 차이를 두고 있다. 가령 대리감독자인 교사의 경우 가해행위가 교육활동과 관련되어 있고, 예측가능성(구체적 위험성)이 있는 경우에만 감독자책임을 진다. 따라서 이 경우 제755조보다는 제750조에 의한 책임에 가깝다고도 할 수 있다. 책임능력 있는 미성년자의 부모가 제750조에 기초해서 지는 책임과 판단기준이 유사하기 때문이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":114,"pageEnd":115,"anchor":"source-114-10"},{"type":"p","text":"감독자는 자신이 감독의무를 해태하지 않았다는 것을 입증한 경우에만 면책될 수 있다(제755조 제1항 단서). 따라서 감독의무자가 자신의 의무를 게을리하였음을 피해자가 입증할 필요는 없다. 제755조 제1항의 조문 구조상 감독의무의 해태는 추정되며 면책사유의 증명은 현실적으로 쉽지 않다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":115,"pageEnd":115,"anchor":"source-115-1"},{"type":"p","text":"v 대법원 2007. 4. 26. 선고 2005다24318 판결 등 다수의 판결 : 지방자치단체가 설치·경영하는 학교의 교장이나 교사는 학생을 보호·감독할 의무를 지는데, 이러한 보호·감독의무는 교육법에 따라 학생들을 친권자 등 법정감독의무자에 대신하여 감독을 하여야 하는 의무로서 학교 내에서의 학생의 모든 생활관계에 미치는 것은 아니지만, 학교에서의 교육활동 및 이와 밀접 불가분의 관계에 있는 생활관계에 속하고, 교육활동의 때와 장소, 가해자의 분별능력, 가해자의 성행, 가해자와 피해자의 관계, 기타 여러 사정을 고려하여 사고가 학교생활에서 통상 발생할 수 있다고 하는 것이 예측되거나 또는 예측가능성(사고발생의 구체적 위험성)이 있는 경우에는 교장이나 교사는 보호·감독의무 위반에 대한 책임을 진다. [대리감독자의 감독의무의 내용] 교육활동과의 밀접성, 예측가능성(구체적 위험성)을 기준으로 하여 감독의무 위반을 판단함","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-159","continued":false,"pageStart":115,"pageEnd":115,"anchor":"source-115-2"},{"type":"p","text":"v 대법원 2007. 4. 26. 선고 2005다24318 판결 : [사실관계] 초등학교 6학년인 가해학생들의 집단따돌림으로 인해 피해자가 자살.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-160","continued":false,"pageStart":115,"pageEnd":115,"anchor":"source-115-3"},{"type":"p","text":"[법원의 판단] 가해학생들은 12세 남짓된 초등학교 6학년 학생들로서 비록 책임을 변식할 지능을 갖추지 못하고 있다고 하더라도 상당한 정도의 자율능력, 분별능력은 가지고 있다고 보아야 할 것이고, 당시 학교에서의 집단 괴롭힘이 사회문제화 되어 학교에서 이에 대한 예방교육이 실시되고 있었으며, 가해학생들 역시 그와 같은 교육을 받아 그 폐해를 잘 알고 있었다 할 것인바, 이러한 사정들을 종합하여 보면, 가해학생들의 폭행 등 괴롭힘과 망인의 자살 사이에는 상당인과관계가 있다 할 것이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-160","continued":false,"pageStart":115,"pageEnd":115,"anchor":"source-115-4"},{"type":"p","text":"민법 제755조에 의하여 책임능력 없는 미성년자를 감독할 친권자 등 법정감독의무자의 보호감독책임은 미성년자의 생활 전반에 미치는 것이고, 법정감독의무자에 대신하여 보호감독의무를 부담하는 교사 등의 보호감독책임은 학교 내에서의 학생의 모든 생활관계에 미치는 것이 아니라, 학교에서의 교육활동 및 이와 밀접 불가분의 관계에 있는 생활관계에 한하며, 이와 같은 대리감독자가 있다는 사실만 가지고서 곧 친권자의 법정감독책임이 면탈된다고는 볼 수 없다 할 것이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-160","continued":false,"pageStart":115,"pageEnd":115,"anchor":"source-115-5"},{"type":"p","text":"망인은 가해학생들로부터 수개월에 걸쳐 이유 없이 폭행 등 괴롭힘을 당한 결과 충격 후 스트레스 장애 등의 증상에 시달리다 결국 자살에까지 이르게 되었음을 알 수 있고, 가해학생들의 망인에 대한 폭행 등은 거의 대부분 학교 내에서 휴식시간 중에 이루어졌고, 또한 수개월에 걸쳐 지속되었으며 당시 학교 내 집단 괴롭힘이 심각한 사회문제로 대두되어 있었으므로, 망인의 담임교사인 소외 1로서는 학생들의 동향 등을 보다 면밀히 파악하였더라면 망인에 대한 폭행 등을 적발하여 망인의 자살이라는 결과를 사전에 예방할 수 있었던 것으로 보이며, 나아가 망인에 대한 폭행사실이 적발된 후에도 소외 1, 2는 망인의 정신적 피해상태를 과소 평가한 나머지 망인의 부모로부터 가해학생들과 망인을 격리해 줄 것을 요청받고도 이를 거절하면서 가해학생들로부터 반성문을 제출받고 가해학생들의 부모들로부터 치료비에 대한 부담과 재발방지 약속을 받는 데 그치는 등 미온적으로 대처하였고, 또한 그 이후의 수학여행 중에도 망인에 대하여 보다 특별한 주의를 기울였어야 함에도 불구하고, 특별교우관계에 있는 학생을 붙여주는 이외에 별다른 조치를 취하지 아니함으로써 결과적으로 망인이 자살에 이르게 하도록 한 원인을 제공한 과실이 있다고 할 것이므로, 피고 경기도는 국가배상법 제2조 제1항에 의하여 그 소속 공무원인 소외 1, 2의 위와 같은 공무수행상의 과실로 인하여 망인 및 원고들이 입은 손해를 배상할 책임이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-160","continued":false,"pageStart":115,"pageEnd":115,"anchor":"source-115-6"},{"type":"p","text":"[정리] 대리감독자의 과실이 가해행위와 구체적인 인과관계에 있다는 점을 설시한 후, 국가배상법 제2조를 적용하여 경기도의 책임을 인정하였음.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-160","continued":false,"pageStart":115,"pageEnd":115,"anchor":"source-115-7"},{"type":"p","text":"v 대법원 1997. 6. 27. 선고 97다15258 판결 : [1] 초등학교의 교장이나 교사는 학생을 보호․감독할 의무를 지는 것이나 이러한 학생에 대한 보호․감독의무는 학교 내에서의 학생의 모든 생활관계에 미치는 것은 아니고 학교에서의 교육활동 및 이에 밀접불가분의 관계에 있는 생활관계에 한하며, 그 의무의 범위 내의 생활관계라고 하더라도 사고가 학교생활에서 통상 발생할 수 있다고 하는 것이 예측되거나 또는 예측가능성(사고발생의 구체적 위험성)이 있는 경우에만 교장이나 교사는 보호․감독의무위반에 대한 책임을 진다고 할 것이고, 그 예측가능성에 대하여는 교육활동의 때, 장소, 가해자의 분별능력, 가해자의 성행, 가해자와 피해자의 관계, 기타 여러 사정을 고려하여 판단할 필요가 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-161","continued":false,"pageStart":115,"pageEnd":115,"anchor":"source-115-8"},{"type":"p","text":"가해자와 피해자가 초등학교 6학년생들로서 비록 책임을 변식할 지능을 갖추지 못하고 있다고 하더라도 초등학교 6학년 정도라면, 대체로 학교생활에 적응하여 상당한 정도의 자율능력, 분별능력을 가지고 있다고 보아야 할 것이고, 가해자의 성격도 친구들과 잘 사귀고, 책임감이 강한 학생이었으며 피해자와도 원만한 사이였고, 이전에는 교실에서 학생들 사이에 아크릴판을 던지는 등의 장난 등은 없었던 경우, 호기심이 많은 학생들이 장난 등 돌발적인 행동을 할 가능성이 많다고 하여 자율학습이 시작되기 전에 교실에서 주인을 찾아주려는 마음에서 실과수업교재인 아크릴판을 던지는 등으로 인하여 잘못되면, 신체에 커다란 충격을 줄 수 있는 위험한 행위를 하리라는 구체적인 위험성이 있다거나 담임교사 등이 이를 예측하였거나 예측가능하였다고 보여지지는 아니하다면, 특별한 사정이 없는 한 돌발적이거나 우연한 사고에 대해서까지 교사 등에게 보호·감독의무위반의 책임을 지울 수는 없다. (정규 학습 시작시간 전에 교실에서 주인을 찾아주기 위해 아크릴판을 던져 중간에 앉아 있던 급우의 눈을 다치게 한 경우, 교사 등에게 보호·감독의무위반의 책임을 지울 수 없다고 했다).","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-161","continued":false,"pageStart":115,"pageEnd":116,"anchor":"source-115-9"},{"type":"p","text":"v 대법원 2008. 1. 17. 선고 2007다40437 판결: 유치원이나 학교의 원장·교장 및 교사는 교육기본법 등 관련 법령에 따라 그들로부터 교육을 받는 유치원생과 학생들을 친권자 등 법정감독의무자에 대신하여 보호·감독할 의무를 진다. 그런데 유치원생이나 학생들을 대상으로 한 교육활동이 유치원이나 학교에서만 이루어지는 것은 아니고, 특히 우리의 교육현실을 보면 학원의 설립·운영 및 과외교습에 관한 법률에 따라 설립·운영되는 학원이나 교습소에서 학교교육의 보충 또는 특기·적성교육을 위하여 지식·기술·예능을 교습하는 형태의 사교육이 광범위하게 이루어지고 있으며, 이러한 사교육은 학교 안에서 이루어지는 공교육 못지않은 중요한 역할을 수행하고 있는바, 공교육을 담당하는 교사 등과 마찬가지로 위와 같은 형태의 사교육을 담당하는 학원의 설립·운영자나 교습자에게도 당해 학원에서 교습을 받는 수강생을 보호·감독할 의무가 있다고 봄이 상당하다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-162","continued":false,"pageStart":116,"pageEnd":116,"anchor":"source-116-1"},{"type":"p","text":"v 대법원 2002. 12. 10. 선고 2000다55126 판결 : 국립 전남대학교에서 한총련 산하 남총련의 간부들이 엉뚱한 사람을 경찰프락치라고 속단하여 감금폭행하여 사망에 이르게 한 경우, 그 사망사고가 전남대학교의 불법행위자들에 대한 교육활동이나 이에 밀접한 생활관계와 연관성이 있다고 보기 어려울 뿐만 아니라 전남대학교에 학교생활에서 위와 같은 사망사고가 발생하리라는 점에 대한 예견가능성이 있었다고 보기 어렵다는 이유로 전남대학교(국가)측의 손해배상책임을 부정한 사례.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-163","continued":false,"pageStart":116,"pageEnd":116,"anchor":"source-116-2"},{"type":"p","text":"v 대법원 2000. 4. 11. 선고 99다44205 판결 : [사실관계] 원고 2(피해학생)는 피고(인천시)에 소속된 하도진중학교 2학년 8반에 재학중이던 1996. 12. 14. 10:00경 체육시간이 끝나고 교실로 들어와 쉬는 시간에 같은 반 학생인 제1심 공동피고로부터 폭행을 당하여 좌측 안와골절상을 입게 되었는데, 폭행을 당한 이유는 원고 2등이 체육시간에 학교 담을 넘어 나갔다 오다가 들키는 바람에 체육교사인 소외 유00으로부터 같은 반 학생들이 단체로 벌을 받아 화가 났기 때문이다. (원고는 감독자책임을 물어 손해배상청구를 했고, 피고는 감독상의 과실이 없으며, 이 사건 사고가 우발적인 것이어서 예상할 수 없었다고 주장했다.)","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-164","continued":false,"pageStart":116,"pageEnd":116,"anchor":"source-116-3"},{"type":"p","text":"[원심의 판단] 유00 등 교사들은 원고 2등의 잘못으로 같은 반 학생들 모두에게 벌을 주었으면 혹시라도 다른 학생들이 이에 불만을 품고 원고 2등에게 앙갚음을 할 가능성이 있으므로 이를 방지하기 위하여 특별히 지도를 하였어야 할 의무가 있음에도 이를 게을리 한 잘못이 있으므로 피고는 위 유00 등의 사용자로서 원고들이 입은 손해를 배상할 책임이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-164","continued":false,"pageStart":116,"pageEnd":116,"anchor":"source-116-4"},{"type":"p","text":"학교 교사로서는 어느 학생의 잘못으로 같은 반 학생 전체에게 벌을 주는 등의 특별한 경우에는 아직 성숙하지 아니한 중학생들이 이에 대한 앙갚음을 하는 등의 갑작스러운 행동을 할 수 있음을 충분히 예상하여야 한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-164","continued":false,"pageStart":116,"pageEnd":116,"anchor":"source-116-5"},{"type":"p","text":"[대법원의 판단] 체육시간 수업 직후의 휴식시간은 다음 수업을 위하여 잠시 쉬거나 수업의 정리·준비 등을 하는 시간으로서 교육활동과 질적, 시간적으로 밀접 불가분의 관계에 있어, 그 시간 중의 교실 내에서의 학생의 행위에 대하여는 교사의 일반적 보호·감독의무가 미친다고 할 수 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-164","continued":false,"pageStart":116,"pageEnd":116,"anchor":"source-116-6"},{"type":"p","text":"그러나 이 사건 사고 당시 가해자인 제1심 공동피고(1982. 8. 12. 생)는 만 14세 4개월 정도로서 충분한 분별능력이 있고, 비록 공부를 못하고 성격이 급하나 본성이 착하여 평소 친구들을 때리거나 괴롭힌 일이 없으며, 피해자인 원고 2와 같은 급우로서 별문제 없이 지내왔고, 원고 2도 비록 공부는 못하나 심성이 고운 학생으로 친구들 사이에서 별다른 문제가 없는 학생이었으며, 유00이 단체기합을 주게 된 동기와 약 5분 정도에 걸쳐 쪼그려뛰기 20회, 엎드렸다 일어나기 20회, 팔벌려뛰기 20회를 실시한 체벌의 방법과 정도로 보아 교육적 차원에서 정당하고, 그 단체기합으로 인하여 같은 반 학생들이 원고 2등에게 반감을 가질 정도의 것은 아니라고 보이므로 이러한 가해자의 성행, 피해자와의 관계, 사고발생의 때와 장소 등을 고려할 때 체육교사인 유00이나 담임교사 등이 이 사건 사고를 예측하였거나 예측할 수 있었다고 보기 어렵고, 사고에 앞서 유00이 위와 같은 단체기합을 주었다는 사정만으로 사고의 발생에 대한 구체적 위험성이 있다고도 할 수 없다. 따라서 이 사건 사고는 돌발적이거나 우연한 사고로서 유00 등 교사에게 보호·감독의무 위반의 책임을 물을 수 없다고 보아야 할 것이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-164","continued":false,"pageStart":116,"pageEnd":116,"anchor":"source-116-7"},{"type":"p","text":"v 대법원 1997. 6. 13. 선고 96다44433 판결 : 중학교 1학년생이 휴식시간에 먹고 있던 도시락에 급우가 오물을 떨어지게 했다는 이유로 그 급우를 구타하여 상해를 입힌 사안에서, 사고가 일어난 3교시 수업 직후의 휴식시간은 다음 수업을 위하여 잠시 쉬거나 수업의 정리, 준비 등을 하는 시간으로서 교육활동과 질적, 시간적으로 밀접 불가분의 관계에 있어, 그 시간 중의 교실 내에서의 학생의 행위에 대하여는 교사의 일반적 보호·감독의무가 미친다고 할 수 있으나, 가해자가 성격이 거칠어서 평소 자기보다 약한 급우를 괴롭히다가 담임교사로부터 꾸중을 듣기도 하였다고 하더라도 가해자는 중학교 1학년 학급의 반장으로서 학업성적이 우수하고 매사에 적극적이었으며 피해자와는 같은 반 친구로서 지내던 사이였으므로, 이러한 가해자의 성행, 피해자와의 관계, 사고발생의 때와 장소 등을 고려할 때 사고가 담임교사가 이를 예측하였거나 예측할 수 있었다고 보기 어려운 돌발적이거나 우연한 사고로서 담임교사에게 보호·감독의무 위반의 책임을 물을 수 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-165","continued":false,"pageStart":116,"pageEnd":116,"anchor":"source-116-8"},{"type":"p","text":"v 대법원 2007. 6. 15. 선고 2004다48775 판결 : [사실관계] 평소 망인과 그의 친구들은 학생들을 상대로 폭력을 행사하고 금품을 빼앗는 등의 행동을 해왔는데, 소외 1도 망인으로부터 피해를 당했다. 소외 1은 중학교 1학년 때부터 수시로 보건실을 드나들면서 복통, 두통을 호소하고, 간혹 분노를 조절하지 못하는 모습을 보였다. 사고 당일 망인과 그의 친구들이 소외 1을 비롯한 여러 학생들을 폭행했고, 소외 1은 수업 중인 교실에 칼을 들고 들어가 망인을 찔러 사망에 이르게 했다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-166","continued":false,"pageStart":116,"pageEnd":117,"anchor":"source-116-9"},{"type":"p","text":"[법원의 판단] 이 사건 사고는 수업시간 중에 발생한 것으로 학교에서의 교육활동 중에 발생한 것이므로 교장이나 교사의 일반적 보호감독의무가 미친다고 할 수 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-166","continued":true,"pageStart":117,"pageEnd":117,"anchor":"source-117-1"},{"type":"p","text":"또한, 학교폭력이 상당히 사회문제화되고 있는 현실 속에서 학교를 설립하여 운영하는 지방자치단체인 피고 및 그 소속 교사들은 어느 특정 개인의 폭력성 여부를 떠나 폭력행위가 학교 내에서 발생하지 않도록 함으로써 학생들을 보호할 일반적 주의의무가 있다고 할 것인데, 이 사건을 살펴보면, 평소 망인과 그의 친구들은 학생들을 상대로 폭력을 행사하고 금품을 빼앗는 등의 행동을 해옴으로써 많은 학생들이 피해의식을 느껴왔고 교사들도 이를 알고 있었으므로 실효성 있는 대책을 강구하지 않으면 또 다른 폭력이 행해지리라는 것은 예견이 가능한 상태였다는 점, 이러한 와중에 망인과 그 친구들이 사고 당일 휴식시간 및 점심시간에 여러 학생들에 대한 폭행을 한 것이 결국 이 사건 사고의 직접적인 원인이 되었다는 점, 이러한 위 학교의 상황에 비추어 볼 때, 폭력성 있는 학생들로 인하여 시작된 폭력이 또 다른 폭력을 야기할 위험성을 내포하고 있었고 소외 1의 이 사건 가해행위는 이러한 위험성이 구체화되어 나타난 것으로 볼 수 있다는 점, 이 사건 사고는 학교 수업시간 중에 담당교사가 수업을 진행하는 면전에서 일어났다는 점 등을 종합하여 보면, 이 사건 사고가 피고나 그 소속교사들의 예견가능성의 범위를 벗어난 영역에서 발생하였다고 보기는 어렵다. [정리] 가해행위가 수업시간에 발생했다는 점과, 구체적 위험성이 실현되었다는 점에서 감독자책임을 인정했다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-166","continued":true,"pageStart":117,"pageEnd":117,"anchor":"source-117-2"},{"type":"p","text":"v 대법원 2002. 5. 10. 선고 2002다10585,10592 판결 : 유치원 운영자의 원아에 대한 단 1회의 성추행을 방지하지 못한 유치원 교사의 손해배상책임을 부정한 사례.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-167","continued":false,"pageStart":117,"pageEnd":117,"anchor":"source-117-3"},{"type":"p","text":"v 대법원 2021. 7. 29. 선고 2018다228486 판결: [1] 구 정신보건법(2016. 5. 29. 법률 제14224호 정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률로 전부 개정되기 전의 것, 이하 같다) 제3조 제1호는 ‘정신질환자’란 ‘정신병(기질적 정신병을 포함한다)·인격장애·알코올 및 약물중독 기타 비정신병적정신장애를 가진 자’라고 정의하고 있고, 제21조 제1항 본문은 “정신질환자의 민법상의 부양의무자 또는 후견인(이하 ‘부양의무자 등’이라 한다)은 정신질환자의 보호의무자가 된다.”라고 정하고 있다. 또한 제22조 제2항은 “보호의무자는 보호하고 있는 정신질환자가 자신 또는 타인을 해치지 아니하도록 유의하여야 한다.”라고 정하여 부양의무자 등에게 피보호자인 정신질환자에 대한 감독의무를 부과하고 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-168","continued":false,"pageStart":117,"pageEnd":117,"anchor":"source-117-4"},{"type":"p","text":"정신질환자가 심신상실 중에 타인에게 손해를 가하여 배상의 책임이 없는 경우에는 제755조 제1항에 따라 그를 감독할 법정의무 있는 자가 손해를 배상할 책임이 있다. 정신질환자가 책임능력이 있는 경우에도 그 손해가 감독의무자의 감독의무 위반과 인과관계가 있으면 감독의무자는 일반불법행위자로서 제750조에 따라 손해를 배상할 책임이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-168","continued":false,"pageStart":117,"pageEnd":117,"anchor":"source-117-5"},{"type":"p","text":"위와 같은 법규정의 문언과 체계 등에 비추어 보면, 부양의무자 등은 피보호자인 정신질환자에 대한 법률상 감독의무를 부담하므로 그 의무 위반으로 타인에게 손해를 가하는 경우에 이를 배상할 책임이 있으나, 이러한 감독의무는 정신질환자의 행동을 전적으로 통제하고 그 행동으로 인한 모든 결과를 방지해야 하는 일반적인 의무가 아니라 구 정신보건법 등 관련 법령의 취지, 신의성실의 원칙, 형평의 원칙 등을 종합적으로 고려하여 합리적으로 제한된 범위에서의 의무라고 해석함이 타당하다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-168","continued":false,"pageStart":117,"pageEnd":117,"anchor":"source-117-6"},{"type":"p","text":"구체적인 사안에서 부양의무자 등이 피보호자인 정신질환자에 관한 감독의무를 위반하였는지는 정신질환자의 생활이나 심신의 상태 등과 함께 친족 관계와 동거 여부, 일상적인 접촉 정도, 정신질환자의 재산관리 관여 상황 등 정신질환자와의 관계, 정신질환자가 과거에도 타인에게 위해를 가하는 행동을 한 적이 있는지 여부와 그 내용, 정신질환자의 상태에 대응하는 보호와 치료 상황 등 모든 사정을 종합적으로 고려하여, 피보호자인 정신질환자가 타인을 위해할 가능성이 있다는 구체적인 위험을 인지하였는데도 대비를 하지 않은 경우와 같이 부양의무자 등에게 정신질환자의 행위에 관해서 책임을 묻는 것이 타당한 객관적 상황이 인정되는지 여부에 따라 개별적으로 판단해야 한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-168","continued":false,"pageStart":117,"pageEnd":117,"anchor":"source-117-7"},{"type":"p","text":"[2] 양극성 정동장애를 앓고 있는 정신질환자인 甲이 아파트 방에서 불을 질렀다가 甲의 아버지인 乙이 불을 껐는데, 약 4시간 후 甲이 방 안에서 다시 불을 질러 인접 호수의 아파트로 불이 옮겨붙어 丙 등에게 손해가 발생한 사안에서, 乙에게는 甲이 타인을 위해할 가능성이 있다는 구체적인 위험을 인지하였는데도 대비를 하지 않아 甲의 행위에 관해서 책임을 묻는 것이 타당한 객관적 상황이 인정되므로, 乙이 甲의 직계존속으로서 甲의 방화 등 우발적인 행동을 미리 방지하고 이와 같은 우발적인 행동이 있더라도 손해가 발생하거나 확대되지 않도록 할 주의의무가 있었는데도 이를 위반한 과실로 丙 등에게 손해가 발생하였다는 이유로 乙의 손해배상책임을 인정한 원심판단이 정당하다고 한 사례","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-168","continued":false,"pageStart":117,"pageEnd":117,"anchor":"source-117-8"},{"type":"h3","text":"(3) 인과관계의 존재","emphasis":[[0,12]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":117,"pageEnd":117,"anchor":"source-117-9"},{"type":"p","text":"감독의무 해태와 책임무능력자의 가해행위 사이에 인과관계가 존재해야 한다. 즉, 감독의무자가 감독을 게을리하지 않았더라도 손해가 생겼으리라는 것이 입증되면 감독의무자는 그 책임을 면할 수 있다. 이와 같이 감독의무자 등이 인과관계의 부존재를 증명함으로써 면책될 수 있는가에 대하여 ① 다수설은 제756조 제1항 단서를 유추하여 면책을 긍정하는 반면, ② 소수설은 피감독자의 위법행위로 발생한 손해를 감독의무자 등이 대신 배상하는 것이 책임무능력자의 감독자책임의 기본취지이므로 인과관계의 존부와 관계없이 감독의무자 등은 책임을 진다고 본다. 현실적으로는 감독의무자가 감독을 게을리하지 않았더라도 손해가 생겼으리라는 것을 입증하는 것은 거의 불가능하다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":117,"pageEnd":118,"anchor":"source-117-10"},{"type":"h3","text":"3. 효과","emphasis":[[0,5]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":118,"pageEnd":118,"anchor":"source-118-1"},{"type":"p","text":"책임무능력자에 갈음하여 배상책임을 부담하는 것은 법정감독의무자 및 감독의무자에 갈음하여 책임무능력자를 감독하는 대리감독자이다. 책임무능력자의 법정감독의무자는 미성년자의 경우 친권자(제913조)와 후견인(제945조)이고, 금치산자에 있어서는 후견인(제947조)이다. 금치산선고를 받지 않은 심신상실자의 경우 관습법 또는 조리에 의하여 적당한 지위에 있는 자가 그 감독의무자가 된다. 판례는 조리상 妻, 부모 등의 순서로 감독의무자가 된다고 한다(대판 1957. 7. 25. 4290민상302). 대리감독자가 법정감독의무자에 갈음하여 감독하게 된 이유는 계약에 의하든 또는 법률에 의하든 이를 묻지 않는다. 손해배상범위(제393조)에서 ‘특별한 사정’에 대한 인식은 감독자를 기준으로 결정한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":118,"pageEnd":118,"anchor":"source-118-2"},{"type":"p","text":"만일 이들의 책임이 모두 발생한 경우에 ① 대리감독자가 감독의무를 다하였음에도 피감독자의 가해행위가 있었던 경우라면 최종적으로 법정감독의무자에게 배상책임이 있다고 할 것이며, 대리감독자를 두었다는 사실만 가지고서 곧 법정감독의무자의 감독책임이 면책될 수는 없다. ② 대리감독자도 감독의무를 다하지 않고 법정감독의무자도 대리감독자에게 감독케 한 것에 과실이 없었음을 증명하지 못하여 책임을 지게 되는 경우 양자의 책임은 부진정연대채무의 관계에 있게 된다. 따라서 피해자는 전부의 배상을 받을 때까지 어느 쪽에 대해서도 책임을 물을 수 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":118,"pageEnd":118,"anchor":"source-118-3"},{"type":"p","text":"v 대법원 2007. 4. 26. 선고 2005다24318 판결 : [1] 민법 제755조에 의하여 책임능력 없는 미성년자를 감독할 친권자 등 법정감독의무자의 보호·감독책임은 미성년자의 생활 전반에 미치는 것이고, 법정감독의무자에 대신하여 보호·감독의무를 부담하는 교사 등의 보호·감독책임은 학교 내에서의 학생의 모든 생활관계에 미치는 것이 아니라 학교에서의 교육활동 및 이와 밀접 불가분의 관계에 있는 생활관계에 한하며, 이와 같은 대리감독자가 있다는 사실만 가지고 곧 친권자의 법정감독책임이 면탈된다고는 볼 수 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-169","continued":false,"pageStart":118,"pageEnd":118,"anchor":"source-118-4"},{"type":"p","text":"[2] 지방자치단체가 설치·경영하는 학교의 교장이나 교사는 학생을 보호·감독할 의무를 지는데, 이러한 보호·감독의무는 교육법에 따라 학생들을 친권자 등 법정감독의무자에 대신하여 감독을 하여야 하는 의무로서 학교 내에서의 학생의 모든 생활관계에 미치는 것은 아니지만, 학교에서의 교육활동 및 이와 밀접 불가분의 관계에 있는 생활관계에 속하고, 교육활동의 때와 장소, 가해자의 분별능력, 가해자의 성행, 가해자와 피해자의 관계, 기타 여러 사정을 고려하여 사고가 학교생활에서 통상 발생할 수 있다고 하는 것이 예측되거나 또는 예측가능성(사고발생의 구체적 위험성)이 있는 경우에는 교장이나 교사는 보호·감독의무 위반에 대한 책임을 진다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-169","continued":false,"pageStart":118,"pageEnd":118,"anchor":"source-118-5"},{"type":"p","text":"[3] 학교폭력 가해학생들의 부모의 과실과 담임교사, 교장의 과실이 경합하여 피해학생의 자살 사건이 발생하였다는 이유로, 부모들과 지방자치단체에게 공동불법행위자로서의 손해배상책임을 인정한 사례.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-169","continued":false,"pageStart":118,"pageEnd":118,"anchor":"source-118-6"},{"type":"h3","text":"4. 책임능력 있는 미성년자의 감독자책임","emphasis":[[0,22]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":118,"pageEnd":118,"anchor":"source-118-7"},{"type":"h3","text":"(1) 문제점","emphasis":[[0,7]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":118,"pageEnd":118,"anchor":"source-118-8"},{"type":"p","text":"책임능력 있는 미성년자가 가해행위를 한 경우, 제755조의 문언에 따르면 친권자나 감독자들은 손해배상책임을 지지 않는다. 그러나 미성년자들은 일반적으로 변제자력이 없기 때문에 이 경우 피해자 구제가 사실상 불가능해지는 불합리한 결과가 초래된다. 따라서 책임능력 있는 미성년자의 불법행위로 발생한 피해자의 손해를 구제하기 위하여 제755조의 문언을 피할 수 있는 이론이 필요하게 된다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":118,"pageEnd":118,"anchor":"source-118-9"},{"type":"p","text":"v 대법원 1989. 1. 24. 선고 87다카2118 판결 : [사실관계] 소외 1은 만 18세로 고등학교 3학년 재학 중에 운전면허 없이 친구인 소외 최00을 무등록의 90씨씨 오토바이 뒷좌석에 태우고 운행하다 소외회사의 차량과 충돌하여 위 최00으로 하여금 뇌좌상 등의 상해를 입게 하였다. 위 소외회사와 자동차종합보험계약을 체결한 원고는 소외회사를 대위하여 위 최00과 그 부모 등에게 손해배상금을 지급하였다. 원고는 가해자인 소외 1의 부모에게 구상금을 청구하였다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-170","continued":false,"pageStart":118,"pageEnd":118,"anchor":"source-118-10"},{"type":"p","text":"[원고의 주장] 피고들은 미성년자인 소외 1의 감독의무자로서 위 사고로 인한 최00등의 손해를 위 소외회사와 연대하여 배상할 의무가 있는데 원고가 위 소외회사를 대위하여 그 손해전부를 배상하였으므로 위 소외 회사의 피고들에 대한 구상금채권을 구한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-170","continued":false,"pageStart":118,"pageEnd":118,"anchor":"source-118-11"},{"type":"p","text":"[법원의 판단] 소외1은 사회통념상 자기행위에 대한 책임을 변식할 지능이 있었다고 볼 수 있으므로 그 친권자인 피고들에게는 아들의 불법행위에 대한 아무런 책임이 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-170","continued":false,"pageStart":118,"pageEnd":119,"anchor":"source-118-12"},{"type":"h3","text":"(2) 학설 및 판례","emphasis":[[0,11]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":119,"pageEnd":119,"anchor":"source-119-1"},{"type":"p","text":"㈀ 제755조 확대적용설 : 제755조가 정하는 감독자책임은 미성년자에게 책임능력이 없는 경우 발생하는 보충적 책임이 아니라, 미성년자의 책임과 감독자의 책임이 병존한다는 사실을 표현한 것이라고 이해하는 견해이다. 즉, 감독자의 책임은 위험책임과 같은 성질을 갖는다고 이해하는 견해이다. 그러나 이 견해는 법문에 정면으로 배치되어 해석의 한계를 벗어난다는 비판을 받는다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":119,"pageEnd":119,"anchor":"source-119-2"},{"type":"p","text":"㈁ 제750조 적용설 : 친권자는 子를 보호하고 교양할 권리·의무가 있으므로(제913조), 친권자의 子에 대한 교양의무위반과 손해발생 사이에 상당인과관계가 있으면 친권자는 민법 제750조의 일반불법행위책임을 부담한다는 견해이다. 이 경우 의무위반은 일반적으로 子에 대한 교양의무 등 감독의무 위반을 의미하는 것이며, 문제가 된 불법행위 자체와 관련된 감독의무 위반을 의미하는 것은 아니다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":119,"pageEnd":119,"anchor":"source-119-3"},{"type":"p","text":"㈂ 판례 : 판례는 우여곡절을 겪은 끝에 1994년의 전원합의체판결 이후 책임능력 있는 미성년자의 감독의무자 책임을 제750조에 따른 책임으로 인정하고 있다. 감독의무자가 제750조에 의해 배상책임을 지는 경우, 감독의무위반 및 의무위반과 손해발생 간의 상당인과관계의 존부는 이를 주장하여 손해배상을 청구하는 피해자 측에서 입증해야 한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":119,"pageEnd":119,"anchor":"source-119-4"},{"type":"p","text":"v 대법원 1994. 2. 8. 선고 93다13605 판결 전원합의체 판결 : 책임능력 없는 미성년자를 감독할 법정의 의무 있는 자가 지는 손해배상책임은 그 미성년자에게 책임이 없음을 전제로 하여 이를 보충하는 책임이고, 그 경우에 감독의무자 자신이 감독의무를 해태하지 아니하였음을 입증하지 아니하는 한 책임을 면할 수 없는 것이나, 반면에 미성년자가 책임 능력이 있어 그 스스로 불법행위책임을 지는 경우에는 그 손해가 당해 미성년자의 감독의무자의 의무위반과 상당인과관계가 있으면 감독의무자는 일반 불법행위자로서 손해배상 책임이 있다 할 것이므로, 이 경우에 그러한 감독의무위반사실 및 손해발생과의 상당인과관계의 존재는 이를 주장하는 자가 입증하여야 할 것이다. 당원 1984. 7. 10. 선고,84다카474 판결의 해석은 위와 같은 견해와 저촉되는 것이므로 이를 변경하기로 한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-171","continued":false,"pageStart":119,"pageEnd":119,"anchor":"source-119-5"},{"type":"p","text":"소외 김00(미성년자)은 그가 오토바이를 운전하던 중 일으킨 교통사고 당시 만 17세 9개월 남짓된 고등학교 3학년생으로서 자기 행위에 대한 책임을 변식할 지능이 있었으므로 그 부모인 피고들은 피해자(원고들)에 대하여 민법 제755조 제1항에 의한 손해배상책임이 없고, 위 김00은 이 사건 사고를 일으키기 8개월여전에 원동기장치자전거운전면허를 취득하였는데, 그 판시와 같은 원고들의 입증만으로는 피고들이 위 김00에 대한 감독을 게을리한 과실이 있고, 그로 말미암아 위 사고가 발생하였다고 인정하기에 부족하고, 달리 증거가 없으므로 피고들에게는 민법 제750조에 의한 손해배상책임이 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-171","continued":false,"pageStart":119,"pageEnd":119,"anchor":"source-119-6"},{"type":"p","text":"F 민법초안 제750조(입법되었다면 제756조 다음에 규정되었을 것) : “전 4조의 규정에 의하여 미성년자, 심신상실자, 감독의무자 또는 사용인에게 손해배상의 책임이 없는 경우에도 법원은 당사자의 경제상황 및 기타 사정을 참작하여 그에게 손해의 전부 또는 일부의 배상을 명할 수 있다.” 그러나 무과실책임은 특별법을 통해 인정하는 것이 타당하다는 이유로 삭제됨.","emphasis":[],"underline":[[56,68],[69,99]],"highlight":[],"strike":[],"role":"comment","group":"민법4_강의자료(불법행위)-172","continued":false,"pageStart":119,"pageEnd":119,"anchor":"source-119-7"},{"type":"p","text":"v 대법원 1997. 3. 28. 선고 96다15374 판결 : [사실관계] 사고 당시 17세 남짓한 피고 2는 부모인 피고 3, 4와 동거하면서 운전면허가 없음에도 가끔 그의 숙부인 피고 서00 소유의 사고 화물차를 운전한 적이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-173","continued":false,"pageStart":119,"pageEnd":119,"anchor":"source-119-8"},{"type":"p","text":"황색점멸등이 설치되어 있는 삼거리 교차로상에서 피고 2가 운전하던 피고 1소유의 화물차와 원고 1이 운전하던 오토바이가 충돌하였다. 피고 2가 먼저 교차로에 진입하기는 하였지만 마주오던 오토바이의 동태를 주의깊게 살피지 아니한 채 급하게 교차로를 통과하려고 하다가 오토바이를 충돌한 과실이 있다. 원고 1으로서도 운전면허 없이 주취상태에서 안전모도 착용하지 아니한 채 화물차보다 먼저 교차로를 통과하기 위하여 무리하게 교차로에 진입한 과실이 있다(원고 1의 과실비율 60%)","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-173","continued":false,"pageStart":119,"pageEnd":119,"anchor":"source-119-9"},{"type":"p","text":"[법원의 판단] 피고3, 4는 피고 2의 부모로서 미성년의 아들이 무면허운전을 하지 못하도록 보호감독하여야 할 주의의무를 게을리하여 사고 화물차를 운전하도록 방치한 과실이 있고, 피고 3, 4의 위와 같은 보호감독상의 과실은 사고 발생의 원인이 되었으므로 원고들이 입은 손해를 배상할 책임이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-173","continued":false,"pageStart":119,"pageEnd":119,"anchor":"source-119-10"},{"type":"p","text":"v 대법원 2022. 4. 14. 선고 2020다240021 판결: 미성년자가 책임능력이 있어 스스로 불법행위책임을 지는 경우에도 그 손해가 미성년자의 감독의무자의 의무 위반과 상당인과관계가 있으면 감독의무자는 제750조에 따라 일반불법행위자로서 손해배상책임이 있다. 이 경우 그러한 감독의무 위반사실과 손해 발생과의 상당인과관계는 이를 주장하는 자가 증명하여야 한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-174","continued":false,"pageStart":119,"pageEnd":119,"anchor":"source-119-11"},{"type":"p","text":"미성년 자녀를 양육하며 친권을 행사하는 부모는 자녀를 경제적으로 부양하고 보호하며 교양할 법적인 의무가 있다(제913조). 부모와 함께 살면서 경제적으로 부모에게 의존하는 미성년자는 부모의 전면적인 보호·감독 아래 있으므로, 그 부모는 미성년자가 타인에게 불법행위를 하지 않고 정상적으로 학교 및 사회생활을 하도록 일반적, 일상적으로 지도와 조언을 할 보호·감독의무를 부담한다. 따라서 그러한 부모는 미성년자의 감독의무자로서 위에서 본 것처럼 미성년자의 불법행위에 대하여 손해배상책임을 질 수 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-174","continued":false,"pageStart":119,"pageEnd":120,"anchor":"source-119-12"},{"type":"p","text":"그런데 이혼으로 인하여 부모 중 1명이 친권자 및 양육자로 지정된 경우 그렇지 않은 부모(이하 ‘비양육친’이라 한다)에게는 자녀에 대한 친권과 양육권이 없어 자녀의 보호·교양에 관한 제913조 등 친권에 관한 규정이 적용될 수 없다. 비양육친은 자녀와 상호 면접교섭할 수 있는 권리가 있지만(제837조의2 제1항), 이러한 면접교섭 제도는 이혼 후에도 자녀가 부모와 친밀한 관계를 유지하여 정서적으로 안정되고 원만한 인격발달을 이룰 수 있도록 함으로써 자녀의 복리를 실현하는 것을 목적으로 하고, 제3자와의 관계에서 손해배상책임의 근거가 되는 감독의무를 부과하는 규정이라고 할 수 없다. 비양육친은 이혼 후에도 자녀의 양육비용을 분담할 의무가 있지만, 이것만으로 비양육친이 일반적, 일상적으로 자녀를 지도하고 조언하는 등 보호·감독할 의무를 진다고 할 수 없다. 이처럼 비양육친이 미성년자의 부모라는 사정만으로 미성년 자녀에 대하여 감독의무를 부담한다고 볼 수 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-174","continued":true,"pageStart":120,"pageEnd":120,"anchor":"source-120-1"},{"type":"p","text":"다만 비양육친도 부모로서 자녀와 면접교섭을 하거나 양육친과의 협의를 통하여 자녀 양육에 관여할 가능성이 있는 점을 고려하면, ① 자녀의 나이와 평소 행실, 불법행위의 성질과 태양, 비양육친과 자녀 사이의 면접교섭의 정도와 빈도, 양육 환경, 비양육친의 양육에 대한 개입 정도 등에 비추어 비양육친이 자녀에 대하여 실질적으로 일반적이고 일상적인 지도, 조언을 함으로써 공동 양육자에 준하여 자녀를 보호·감독하고 있었거나, ② 그러한 정도에는 이르지 않더라도 면접교섭 등을 통해 자녀의 불법행위를 구체적으로 예견할 수 있었던 상황에서 자녀가 불법행위를 하지 않도록 부모로서 직접 지도, 조언을 하거나 양육친에게 알리는 등의 조치를 취하지 않은 경우 등과 같이 비양육친의 감독의무를 인정할 수 있는 특별한 사정이 있는 경우에는, 비양육친도 감독의무 위반으로 인한 손해배상책임을 질 수 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-174","continued":true,"pageStart":120,"pageEnd":120,"anchor":"source-120-2"},{"type":"h3","text":"Ⅲ. 사용자의 책임","emphasis":[[0,10]],"underline":[],"highlight":[],"strike":[],"headingLevel":3,"pageStart":120,"pageEnd":120,"anchor":"source-120-3"},{"type":"p","text":"제756조【사용자의 배상책임】 ① 타인을 사용하여 어느 사무에 종사하게 한 자는 피용자가 그 사무집행에 관하여 제3자에게 가한 손해를 배상할 책임이 있다. 그러나 사용자가 피용자의 선임 및 그 사무감독에 상당한 주의를 한 때 또는 상당한 주의를 하여도 손해가 있을 경우에는 그러하지 아니하다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"statute","group":"민법4_강의자료(불법행위)-175","continued":false,"pageStart":120,"pageEnd":120,"anchor":"source-120-4"},{"type":"p","text":"② 사용자에 갈음하여 그 사무를 감독하는 자도 전항의 책임이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"statute","group":"민법4_강의자료(불법행위)-175","continued":false,"pageStart":120,"pageEnd":120,"anchor":"source-120-5"},{"type":"p","text":"③ 전2항의 경우에 사용자 또는 감독자는 피용자에 대하여 구상권을 행사할 수 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"statute","group":"민법4_강의자료(불법행위)-175","continued":false,"pageStart":120,"pageEnd":120,"anchor":"source-120-6"},{"type":"p","text":"[사례] 식당을 운영하던 甲은 일손이 부족하자 자신의 친구 乙에게 하루 정도 식당일을 도와줄 것을 부탁하였고, 이에 乙은 甲의 식당에서 일하게 되었다. 일을 하던 중 乙은 손님 丙과 다투다 폭행을 가하여 丙에게 상해를 입혔다. 이때 丙은 누구를 상대로 손해배상을 청구할 수 있는가?","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-176","continued":false,"pageStart":120,"pageEnd":120,"anchor":"source-120-7"},{"type":"p","text":"《解說》 사안에서 丙은 우선 직접가해자인 乙에 대하여 불법행위(제750조)의 책임을 물을 수 있다. 그리고 甲에게 손해배상을 청구할 수 있는지가 문제 되는데, 丙이 甲에게 손해배상을 청구할 수 있기 위해서는 사용자책임의 성립요건, 즉 ㈀ 피용자의 가해행위, ㈁ 사용관계, ㈂ 가해행위의 사무집행관련성, ㈃ 선임·감독상의 주의의무의 결여라는 요건을 갖추어야 한다. 사안에서 특히 문제가 되는 것은 甲-乙 간에 사용관계가 존재하는지가 문제 되는데, 비록 호의로 일을 해주기는 하였으나 업무와 관련해서 甲이 乙을 지휘·감독하는 관계에 있다고 보여지므로 甲은 丙에게 사용자책임을 부담하는 것으로 보아야 한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-176","continued":false,"pageStart":120,"pageEnd":120,"anchor":"source-120-8"},{"type":"h3","text":"1. 사용자책임 일반","emphasis":[[0,11]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":120,"pageEnd":120,"anchor":"source-120-9"},{"type":"h3","text":"(1) 의의","emphasis":[[0,6]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":120,"pageEnd":120,"anchor":"source-120-10"},{"type":"p","text":"타인을 사용하여 어느 사무에 종사하게 한 자와 그 자에 갈음하여 그 사무를 감독하는 자는 피용자가 사무집행에 관하여 제3자에게 행한 가해행위와 그로 인한 손해에 대하여 배상책임을 부담한다(제756조 제1항). 이를 사용자책임이라고 한다. 타인을 사용하여 자신의 활동범위를 넓히고, 이로 인해 이익을 얻은 자는 바로 그 사유로 인한 불이익에 대해서도 책임을 져야 하기 때문이다(보상책임의 원리). 다만, 사용자가 피용자의 선임 및 감독에 상당한 주의를 한 경우, 또는 상당한 주의를 하여도 손해가 있을 경우에는 그 책임을 지지 않는다(제756조 제1항 제2문).","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":120,"pageEnd":120,"anchor":"source-120-11"},{"type":"p","text":"F 민법 제756조는 가사노동적 사용관계뿐만 아니라 널리 기업에 있어서의 사용관계에도 적용된다. 오늘날의 기업은 다수의 피용자를 유기적으로 조직하여 거대한 수익을 올리고 있으며, 한편으로는 그러한 기업활동을 위하여 피할 수 없는 위험이 따르는 기계나 시설을 가지고 있다. 따라서 기업의 개개의 피용자가 외부 제3자에게 준 손해는 이를 기업으로 하여금 배상케 하는 것이 공평할 뿐만 아니라, 피해자에게도 충분한 구제를 얻을 수 있는 방법이 된다. 기업책임 일반에 대하여 특별한 규정을 두고 있지 않은 우리나라의 경우 따라서 민법 제756조는 중요한 역할을 한다. 그러나 민법 제756조는 사용자에게 면책사유를 인정하고, 피용자에 대한 사용자의 구상권을 인정하고 있어서 기업책임 규정으로는 불충분하다. 따라서 판례는 ‘사무집행에 관하여’라는 요건을 완화하여 해석하고, 사용자의 면책을 쉽게 인정하지 않는 등 사용자의 책임을 널리 인정하려고 노력하고 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"comment","group":"민법4_강의자료(불법행위)-177","continued":false,"pageStart":120,"pageEnd":121,"anchor":"source-120-12"},{"type":"p","text":"v 대법원 2009. 6. 11. 선고 2008다79500 판결: 피용자가 권한 없이 사용자를 대리하여 한 법률행위가 상대방에 대한 관계에서 기망에 의한 불법행위에 해당하여 사용자가 손해배상책임을 지는 경우에, 사용자가 피용자의 무권대리행위를 추인하였다고 하더라도 그것만으로는 이미 성립된 사용자책임이 소멸되는 것이라고 볼 수 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-178","continued":false,"pageStart":121,"pageEnd":121,"anchor":"source-121-1"},{"type":"h3","text":"(2) 본질","emphasis":[[0,6]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":121,"pageEnd":121,"anchor":"source-121-2"},{"type":"p","text":"사용자책임의 본질에 대해서는 사용자책임의 목적이 피해자의 피용자에 대한 손해배상청구권을 사용자책임을 통해 보장해 주는 데 있다고 보는 「대위책임설」과 사용자책임이 피해자에 대한 관계에서 응당 사용자 자신이 부담해야 할 배상책임이라고 보는 「고유책임설」이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":121,"pageEnd":121,"anchor":"source-121-3"},{"type":"p","text":"㈀ 대위책임설(多)에 의하면 사용자책임은 피용자가 불법행위책임을 지는 경우에만 발생하고, 피용자가 궁극적으로 부담하여야 할 배상의무를 마치 연대보증인처럼 사용자가 대신 변제해 주는 기능을 한다. 따라서 피해자에게 배상해 준 사용자는 언제나 피용자에게 전액 구상할 수 있다고 본다. 다만, 경우에 따라서 신의칙에 의하여 구상범위를 제한할 수 있을 뿐이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":121,"pageEnd":121,"anchor":"source-121-4"},{"type":"p","text":"㈁ 고유책임설에 의하면 사용자는 피용자의 선임·감독을 제대로 하지 못하였다는 사용자 자신의 고유한 부주의에 대하여 책임을 지는 것이기 때문에, 자신의 과책이 인정되는 범위에서 피용자의 과실이나 책임능력이 없는 경우에도 손해배상책임을 지게 된다. 또한 피용자에 대한 대내적 관계에서도 사용자는 자신의 부주의에 해당하는 고유한 부담부분을 갖게 되며, 따라서 피용자에 대한 구상권은 그 범위에서 제한된다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":121,"pageEnd":121,"anchor":"source-121-5"},{"type":"p","text":"㈂ 판례는 대위책임설의 입장을 취하고 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":121,"pageEnd":121,"anchor":"source-121-6"},{"type":"table","html":"<table><caption>강의자료 121쪽 · 비교표</caption><tbody><tr><th rowspan=\"1\" colspan=\"1\"></th><th rowspan=\"1\" colspan=\"1\"><strong>대위책임설(배상보장설)</strong></th><th rowspan=\"1\" colspan=\"1\"><strong>고유책임설(자기책임설)</strong></th></tr><tr><td rowspan=\"1\" colspan=\"1\">개념</td><td rowspan=\"1\" colspan=\"1\">피해자구제를 위해 사용자가 피용자를 대신하여(代位) 배상</td><td rowspan=\"1\" colspan=\"1\">사용자 자신의 선임·감독상 과실에 대한 책임</td></tr><tr><td rowspan=\"1\" colspan=\"1\">피용자의 행위</td><td rowspan=\"1\" colspan=\"1\">피용자의 행위가 불법행위에 해당될 것을 요함</td><td rowspan=\"1\" colspan=\"1\">피용자의 과실이나 책임능력과는 무관함</td></tr><tr><td rowspan=\"2\" colspan=\"1\">면책가능성</td><td rowspan=\"1\" colspan=\"1\">없음</td><td rowspan=\"1\" colspan=\"1\">있음</td></tr><tr><td rowspan=\"1\" colspan=\"2\">우리 민법은 면책가능성을 인정하고 있으나, 실제로는 대부분의 경우 면책이 인정되지 않는다는 점에서 대위책임설과 고유책임설의 중간형태를 취하고 있음</td></tr><tr><td rowspan=\"1\" colspan=\"1\">구상권</td><td rowspan=\"1\" colspan=\"1\">인정(신의칙상 일부 제한)</td><td rowspan=\"1\" colspan=\"1\">불인정(단, 부담부분이 있을 뿐)</td></tr></tbody></table>","text":"대위책임설(배상보장설) 고유책임설(자기책임설) 개념 피해자구제를 위해 사용자가 피용자를 대신하여(代位) 배상 사용자 자신의 선임·감독상 과실에 대한 책임 피용자의 행위 피용자의 행위가 불법행위에 해당될 것을 요함 피용자의 과실이나 책임능력과는 무관함 면책가능성 없음 있음 우리 민법은 면책가능성을 인정하고 있으나, 실제로는 대부분의 경우 면책이 인정되지 않는다는 점에서 대위책임설과 고유책임설의 중간형태를 취하고 있음 구상권 인정(신의칙상 일부 제한) 불인정(단, 부담부분이 있을 뿐)","pageStart":121,"pageEnd":121,"anchor":"source-121-7"},{"type":"p","text":"v 대법원 2017. 4. 27. 선고 2016다271226 판결 : 일반적으로 사용자가 피용자의 업무수행과 관련하여 행하여진 불법행위로 인하여 직접 손해를 입었거나 피해자인 제3자에게 사용자로서의 손해배상책임을 부담한 결과로 손해를 입게 된 경우에 사용자는 사업의 성격과 규모, 시설의 현황, 피용자의 업무내용과 근로조건 및 근무태도, 가해행위의 발생원인과 성격, 가해행위의 예방이나 손실의 분산에 관한 사용자의 배려의 정도, 기타 제반 사정에 비추어 손해의 공평한 분담이라는 견지에서 신의칙상 상당하다고 인정되는 한도 내에서만 피용자에 대하여 손해배상을 청구하거나 구상권을 행사할 수 있고, 이러한 구상권 제한의 법리는 사용자의 보험자가 피용자에 대하여 구상권을 행사하는 경우에도 다를 바 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-179","continued":false,"pageStart":121,"pageEnd":121,"anchor":"source-121-8"},{"type":"h3","text":"(3) 제391조의 이행보조자의 책임과의 구별","emphasis":[[0,25]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":121,"pageEnd":121,"anchor":"source-121-9"},{"type":"p","text":"사용자책임은 자신을 위해서 일하는 자(이행보조자, 피용자)의 행위에 대한 책임이라는 점에서 이행보조자의 책임과 공통점을 갖고 있다. 그러나 이행보조자책임과 달리 사용자책임은 ① 채권관계가 전제되지 않으며, ② 독립적 청구권의 기초가 되고, ③ 면책가능성이 있다는 점에서 구별된다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":121,"pageEnd":121,"anchor":"source-121-10"},{"type":"p","text":"v 대법원 2005. 1. 27. 선고 2004다12394 판결 : 영업용 보세창고업자가 수입화물의 실수입자와의 임치계약에 의하여 수입화물을 보관하게 되는 경우, 운송인 또는 그 국내 선박대리점의 입장에서는 수입화물이 자신들의 지배를 떠나 수하인에게 인도된 것은 아니고 보세창고업자를 통하여 수입화물에 대한 지배를 계속하고 있다고 볼 수 있으므로, 보세창고업자는 수입화물에 대한 통관절차가 끝날 때까지 수입화물을 보관하고 적법한 수령인에게 수입화물을 인도하여야 하는 운송인 또는 그 국내 선박대리점의 의무이행을 보조하는 지위에 있다고 할 수 있으나, 영업용 보세창고업자는 일반적으로 독립된 사업자로서 자신의 책임과 판단에 따라 화물을 보관하고 인도하는 업무를 수행하고 운송인 또는 그 국내 선박대리점의 지휘·감독을 받아 수입화물의 보관 및 인도업무를 수행하는 것이라고는 할 수 없으므로 특별한 사정이 없는 한 운송인 및 그 국내선박대리점이 영업용 보세창고업자에 대하여 민법상 사용자의 지위에 있다고 볼 수는 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-180","continued":false,"pageStart":122,"pageEnd":122,"anchor":"source-122-0"},{"type":"h3","text":"2. 사용자책임의 요건","emphasis":[[0,12]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":122,"pageEnd":122,"anchor":"source-122-1"},{"type":"h3","text":"(1) 피용자의 가해행위로 제3자에게 손해가 발생할 것","emphasis":[[0,30]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":122,"pageEnd":122,"anchor":"source-122-2"},{"type":"p","text":"피용자가 제3자에게 위법한 가해행위를 하고 제3자에게 손해를 준 경우여야 한다. 여기서 제3자는 가해행위를 한 피용자 및 사용자책임을 지는 사용자를 제외한 그 밖의 자를 말한다. 가해 피용자의 동료 피용자도 해당함은 물론이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":122,"pageEnd":122,"anchor":"source-122-3"},{"type":"p","text":"그런데 피용자의 가해행위는 반드시 제750조의 요건을 충족해야 하는가에 대하여 의문이 제기된다. 즉, 피용자가 위법한 가해행위를 하였으나, 피용자의 과실이 없는 경우에도 사용자책임은 성립할 수 있는가?","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":122,"pageEnd":122,"anchor":"source-122-4"},{"type":"p","text":"㈀ 대위책임설(피용자 과실요건설) : 피용자의 과실 및 책임능력도 사용자책임의 요건이라고 한다. 사용자가 피용자의 과실이 없는 행위까지 책임을 지는 것은 가혹하기 때문이며, 민법 제756조 제3항의 구상권 행사규정은 간접적으로 피용자의 불법행위성립을 전제한 것으로 해석되기 때문이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":122,"pageEnd":122,"anchor":"source-122-5"},{"type":"p","text":"v 대법원 1981. 8. 11. 선고 81다298 판결 : 책임무능력자(국민학교 1학년생)의 대리감독자(담임교사)에게 민법 제755조 제2항에 의한 배상책임이 있다고 하여 위 대리감독자의 사용자 또는 사용자에 갈음한 감독자(위 학교를 설립 경영하는 지방자치단체)에게 당연히 민법 제756조에 의한 사용자책임이 있다고 볼 수는 없으며, 책임무능력자의 가해행위에 관하여 그 대리감독자에게 고의 또는 과실이 인정됨으로써 별도로 불법행위의 일반 요건을 충족한 때에만 위 대리감독자의 사용자 또는 사용자에 갈음한 감독자는 민법 제756조의 사용자책임을 지게 된다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-181","continued":false,"pageStart":122,"pageEnd":122,"anchor":"source-122-6"},{"type":"p","text":"㈁ 고유책임설 : 고유책임설은 사용자책임의 성립에 피용자의 과실 및 책임능력은 필요하지 않다고 본다(고유책임설 중 무과실책임설). 그 근거로 다음 네 가지를 든다. ① 사용자책임은 사용자가 피용자를 사용하여 그 자신의 활동을 확대하고 그로 인하여 발생된 피용자의 침해행위도 사용자의 행위범주 내의 행위로 평가되어야 한다. ② 사용자의 불충분한 작업지시 또는 부적격한 기구제공 때문에 피용자의 가해행위가 야기된 경우라면 피용자 자신의 과실 및 불법행위책임은 부정될 수 있지만, 사용자책임은 부인되어서는 안 되기 때문이다. 이 경우 대위책임설(피용자과실요건설)에 의하면 사용자책임이 부인되는 부당한 결과가 발생한다. ③ 민법에는 사용자책임의 요건으로서 피용자의 과실을 요구하지 않고 있다. 대위책임설(피용자과실요건설)은 제756조 제3항이 법적 근거가 된다고 주장하나 제756조 제3항은 사용자책임의 대내관계에 관한 구상권조항으로서 대외관계에서 인정되는 사용자책임의 발생요건과는 무관하다. ④ 사용자책임에 관한 소송에서 피해자로 하여금 피용자에 관한 불법행위성립의 모든 요건과 그에 추가하여 사용자책임의 성립요건을 입증하도록 하는 것은 가혹하기 때문이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":122,"pageEnd":122,"anchor":"source-122-7"},{"type":"h3","text":"(2) 사용관계의 존재","emphasis":[[0,12]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":122,"pageEnd":122,"anchor":"source-122-8"},{"type":"p","text":"사용자와 피용자 사이에 사용관계 또는 사무감독관계가 있어야 한다. 사용관계는 고용계약에 기초한 고용관계나 근로계약관계보다 넓은 개념으로 사용관계가 실질적으로 존재하면 족하고 그 원인관계의 유무와 유효 여부, 보수의 유무나 기간의 장단에 관계없이 인정된다. 즉, 법률적인 사용관계가 아니어도 실질적으로 사용관계에 있으면 인정된다(실질적 지휘 감독관계). 결국 사용관계의 존부는 실질적으로 지휘·감독의 관계에 있는가에 따라 판단된다. 그 외에도 실제로 사용지시를 하지 않았다 하더라도 외부적으로 사용관계를 표시하고 있는 경우에도 사용관계의 존재가 인정된다(명의대여자의 사용자책임).","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":122,"pageEnd":123,"anchor":"source-122-9"},{"type":"p","text":"v 대법원 1998. 8. 21. 선고 97다13702 판결 : [1] 민법 제756조 소정의 사용자와 피용자의 관계는 반드시 유효한 고용관계가 있는 경우에 한하는 것이 아니고, 사실상 어떤 사람이 다른 사람을 위하여 그 지휘·감독 아래 그 의사에 따라 사무를 집행하는 관계에 있으면 족한 것이며, 타인에게 위탁하여 계속적으로 사무를 처리하여 온 경우 객관적으로 보아 그 타인의 행위가 위탁자의 지휘·감독의 범위 내에 속한다고 보이는 경우 그 타인은 민법 제756조에 규정한 피용자에 해당한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-182","continued":false,"pageStart":123,"pageEnd":123,"anchor":"source-123-1"},{"type":"p","text":"[2] 여객선안전관리요강 제6조 제4항에 의하여 여객선의 선장으로서 운항관리자의 업무를 처리해 온 자는 그가 고용된 운송회사에 대해서뿐만 아니라 한국해운조합과의 관계에서도 피용자의 지위에 있으므로, 그 선장의 과실로 발생한 여객선의 침몰사고에 대하여 한국해운조합이 사용자책임을 부담한다고 본 사례.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-182","continued":false,"pageStart":123,"pageEnd":123,"anchor":"source-123-2"},{"type":"p","text":"[3] 지방해운항만청 해무과 직원들에게 침몰된 사고 여객선 선장의 선박운항 상태에 관한 감독의무를 게을리한 과실이 있다는 이유로 국가배상책임을 인정한 사례.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-182","continued":false,"pageStart":123,"pageEnd":123,"anchor":"source-123-3"},{"type":"p","text":"v 대법원 2003. 12. 26. 선고 2003다49542 판결: 제756조의 사용자와 피용자의 관계는 반드시 유효한 고용관계가 있는 경우에 한하는 것이 아니고, 사실상 어떤 사람이 다른 사람을 위하여 그 지휘·감독 아래 그 의사에 따라 사업을 집행하는 관계에 있을 때에도 그 두 사람 사이에 사용자, 피용자의 관계가 있다고 할 수 있으며, 피용자의 불법행위가 외형상 객관적으로 사용자의 사업활동 내지 사무집행행위 또는 그와 관련된 것이라고 보일 때에는 행위자의 주관적 사정을 고려함이 없이 이를 사무집행에 관하여 한 행위로 볼 것이고, 외형상 객관적으로 사용자의 사무집행에 관련된 것인지의 여부는 피용자의 본래 직무와 불법행위와의 관련 정도 및 사용자에게 손해발생에 대한 위험 창출과 방지조치 결여의 책임이 어느 정도 있는지를 고려하여 판단하여야 한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-183","continued":false,"pageStart":123,"pageEnd":123,"anchor":"source-123-4"},{"type":"h3","text":"1) 실질적 사용지시관계","emphasis":[[0,13]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":123,"pageEnd":123,"anchor":"source-123-5"},{"type":"h3","text":"가. 의의","emphasis":[],"underline":[],"highlight":[],"strike":[],"headingLevel":6,"pageStart":123,"pageEnd":123,"anchor":"source-123-6"},{"type":"p","text":"사용관계는 반드시 유효한 고용관계에 한하지 않으며, 고용계약에 기초한 고용관계 또는 근로계약관계보다 넓은 개념이다. 유효한 고용계약이 없더라도 사실상 어떤 사람이 다른 사람을 위하여 그 지휘·감독 아래 그의 의사에 따라 사무를 집행하는 관계(실질적 지휘·감독관계)에 있으면 족하다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":123,"pageEnd":123,"anchor":"source-123-7"},{"type":"p","text":"v 대법원 1996. 10. 11. 선고 96다30182 판결 : 민법 제756조의 사용자와 피용자의 관계는 반드시 유효한 고용관계가 있는 경우에 한하는 것이 아니고, 사실상 어떤 사람이 다른 사람을 위하여 그 지휘·감독 아래 그 의사에 따라 사업을 집행하는 관계에 있을 때에도 그 두 사람 사이에 사용자, 피용자의 관계가 있는 것이라고 할 것이다.","emphasis":[],"underline":[[94,139],[140,194]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-184","continued":false,"pageStart":123,"pageEnd":123,"anchor":"source-123-8"},{"type":"p","text":"피고가 경영하는 이삿짐센터에서는 오랫동안 이삿짐 운반에 종사해 온 이른바 '고정직'이라고 불리는 작업원들의 이름표를 이삿짐센터 내에 걸어두고 대부분의 화물운반 작업을 위 작업원들에게 담당시키고 있었고, 위 작업원들이 이삿짐센터에 항상 대기하면서 화물운반 의뢰가 들어오면 피고의 지시로 화물운반 작업에 나가고 있었던 점 및 소외 김선진은 고정직이라고 불리는 작업원이었던 점 등에 비추어, 김선진은 피고의 피용자라고 판단하였음은 옳다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-184","continued":false,"pageStart":123,"pageEnd":123,"anchor":"source-123-9"},{"type":"p","text":"[정리] 이삿짐센터와 고용관계에 있지는 않았으나, 오랫동안 그 이삿짐센터의 이삿짐 운반에 종사해 온 작업원들을 사용자의 손해배상책임에 있어서 피용자라고 본 사례.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-184","continued":false,"pageStart":123,"pageEnd":123,"anchor":"source-123-10"},{"type":"p","text":"v 대법원 1999. 10. 12. 선고 98다62671 판결 : [1] 사용자책임은 타인을 사용하여 어느 사무에 종사하게 한 자로 하여금 피용자가 그 사무집행에 관하여 제3자에게 가한 손해를 배상하게 하는 것으로서, 사용자책임이 성립하려면 사용자와 불법행위자 사이에 사용관계, 즉 사용자가 불법행위자를 실질적으로 지휘·감독하는 관계에 있어야 한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-185","continued":false,"pageStart":123,"pageEnd":123,"anchor":"source-123-11"},{"type":"p","text":"[2] 국립대학교 소속 체조코치가 시체육회로부터 전국체전에 출전할 체조대표선수들에 대한 코치로 선발, 위촉되어 시체육회가 시행한 합동강화훈련을 지도하다가 대표선수로 선발된 같은 대학교 소속 학생이 훈련 중 사고를 당한 경우, 그 사고는 코치가 시체육회로부터 위촉받은 직무를 집행하는 과정에서 발생한 것이고, 대학교 측은 비록 위 체조코치가 합동강화훈련 기간 중에도 대학교의 체조코치로서의 신분을 그대로 보유하고 있었고, 사고를 입은 자가 같은 대학교 학생이었다고 하더라도, 적어도 위 체조코치가 시체육회로부터 위촉받은 체조대표선수들을 지도하는 코치의 직무를 집행함에 있어서는 그를 지휘·감독할 어떠한 권한이 있다거나 그러한 지위에 있다고 보기는 어려우므로 그 사고에서 국가는 위 체조코치의 사용자라고 볼 수 없다고 한 사례.","emphasis":[],"underline":[[126,189],[190,251],[252,311],[312,366]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-185","continued":false,"pageStart":123,"pageEnd":123,"anchor":"source-123-12"},{"type":"p","text":"v 대법원 2003. 10. 9. 선고 2001다24655 판결 : 파견근로자보호등에관한법률에 의한 근로자 파견은 파견사업주가 근로자를 고용한 후 그 고용관계를 유지하면서 사용사업주와 사이에 체결한 근로자 파견계약에 따라 사용사업주에게 근로자를 파견하여 근로를 제공하게 하는 것으로서, 파견근로자는 사용사업주의 사업장에서 그의 지시·감독을 받아 근로를 제공하기는 하지만 사용사업주와의 사이에는 고용관계가 존재하지 아니하는 반면, 파견사업주는 파견근로자의 근로계약상의 사용자로서 파견근로자에게 임금지급의무를 부담할 뿐만 아니라, 파견근로자가 사용사업자에게 근로를 제공함에 있어서 사용사업자가 행사하는 구체적인 업무상의 지휘·명령권을 제외한 파견근로자에 대한 파견명령권과 징계권 등 근로계약에 기한 모든 권한을 행사할 수 있으므로 파견근로자를 일반적으로 지휘·감독해야 할 지위에 있게 되고, 따라서 파견사업주와 파견근로자 사이에는 민법 제756조의 사용관계가 인정되어 파견사업주는 파견근로자의 파견업무에 관련한 불법행위에 대하여 파견근로자의 사용자로서의 책임을 져야 하지만, 파견근로자가 사용사업주의 구체적인 지시·감독을 받아 사용사업주의 업무를 행하던 중에 불법행위를 한 경우에 파견사업주가 파견근로자의 선발 및 일반적 지휘·감독권의 행사에 있어서 주의를 다하였다고 인정되는 때에는 면책된다고 할 것이다.","emphasis":[],"underline":[[544,572],[573,633],[634,672]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-186","continued":false,"pageStart":123,"pageEnd":124,"anchor":"source-123-13"},{"type":"p","text":"[사실관계] 경남은행에서 근무하던 직원(소위 1)이 교통사고를 냈고, 경남은행이 가입한 보험회사(원고)가 손해배상을 한 후, 직원의 파견사업주(피고)에 대해 구상권을 행사했다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-186","continued":true,"pageStart":124,"pageEnd":124,"anchor":"source-124-1"},{"type":"p","text":"피고는 경남은행과의 근로자 파견계약에 따라 소외 1을 고용한 후 그를 경남은행에 파견하여 파견업무를 하도록 한 파견사업주이고, 또 경남은행과 근로자 파견계약을 체결함에 있어 피고측의 업무지휘·명령 및 관리책임자를 선임하여 파견근로자를 관리하기로 약정하였다는 것이니, 피고는 소외 1을 일반적으로 지휘·감독하여야 할 사용자의 지위에 있다고 볼 수 있어서 외형상 소외 1의 파견업무인 자동차의 운전업무와 관련하여 발생한 이 사건 사고에 대하여는 소외 1에 대한 일반적 지휘·감독권을 갖는 피고로서도 그 사고의 위험이 생길 원인을 제공한 데 또는 그 위험 방지조치를 다하지 못한 데에 책임이 있다고 할 것이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-186","continued":true,"pageStart":124,"pageEnd":124,"anchor":"source-124-2"},{"type":"h3","text":"나. 위임관계","emphasis":[],"underline":[],"highlight":[],"strike":[],"headingLevel":6,"pageStart":124,"pageEnd":124,"anchor":"source-124-3"},{"type":"p","text":"수임인의 행위에 대한 위임인의 사용자책임에 관해서는 논란이 있다. 변호사, 의사 등은 사무처리를 위탁하는 자의 직접적인 지휘·감독을 받지 않기 때문에 자유재량에 따라 독립적으로 사무를 행하는 것이 원칙이다. 따라서 일부 견해는 사용자책임을 부정하고 있다. 그러나 판례는 제756조의 요건을 갖추면 위임인도 사용자책임을 질 수 있다고 한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":124,"pageEnd":124,"anchor":"source-124-4"},{"type":"p","text":"v 대법원 1998. 4. 28. 선고 96다25500 판결 : 불법행위에 있어 사용자책임이 성립하려면 사용자와 불법행위자 사이에 사용관계 즉 사용자가 불법행위자를 실질적으로 지휘·감독하는 관계가 있어야 하는 것으로, 위임의 경우에도 위임인과 수임인 사이에 지휘·감독관계가 있고 수임인의 불법행위가 외형상 객관적으로 위임인의 사무집행에 관련된 경우 위임인은 수임인의 불법행위에 대하여 사용자책임을 진다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-187","continued":false,"pageStart":124,"pageEnd":124,"anchor":"source-124-5"},{"type":"p","text":"소외 7(변호사)은 피고들로부터 교부받은 위 위임장, 백지매도증서, 상속재산분할심판서정본, 상속재산분할협의서원본, 등기권리증 등을 소지하고 있음을 이용하여 자신이 피고들로부터 이 사건 부동산을 처분할 권한을 위임받은 것처럼 가장, 원고에게 이를 금 175,000,000원에 매도하고 원고로부터 계약 당일 계약금 20,000,000원, 같은 해 2. 27. 1차 중도금 40,000,000원, 같은 해 3. 21. 2차 중도금 30,000,000원 합계 금 90,000,000원을 지급받아 편취하였다. 소외 7은 피고들의 위임에 따라 장기간 동안 소송사건 외에도 피고들이 상속받은 부동산을 매각하고 상속재산을 분할하는 사무 등을 처리하여 왔고, 그 사무에 관하여는 피고들이 소외 7을 지휘·감독하는 관계에 있었다고 봄이 상당하다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-187","continued":false,"pageStart":124,"pageEnd":124,"anchor":"source-124-6"},{"type":"p","text":"[정리] 변호사가 의뢰인이 맡겨 놓은 증서들을 이용해 부동산을 매도한 사례에서, 매수인이 의뢰인에게 사용자 책임을 물은 사례. (검토사항: 표현대리의 인정 가능성은?)","emphasis":[[0,5]],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-187","continued":false,"pageStart":124,"pageEnd":124,"anchor":"source-124-7"},{"type":"p","text":"v 대법원 2001. 9. 4. 선고 2000다26128 판결 : 민법 제756조의 사용자책임이 성립하려면 사용자가 불법행위자인 피용자를 실질적으로 지휘․감독하는 관계에 있어야 하므로, 피용자가 퇴직한 뒤에는 퇴직에도 불구하고 사용자의 실질적인 지휘․감독 아래에 있었다고 볼 수 있는 특별한 사정이 없다면 그의 행위에 대하여 원칙적으로 종전의 사용자에게 사용자책임을 물을 수 없다.","emphasis":[],"underline":[[104,204],[205,212]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-188","continued":false,"pageStart":124,"pageEnd":124,"anchor":"source-124-8"},{"type":"h3","text":"다. 도급관계","emphasis":[],"underline":[],"highlight":[],"strike":[],"headingLevel":6,"pageStart":124,"pageEnd":124,"anchor":"source-124-9"},{"type":"p","text":"제757조【도급인의 책임】도급인은 수급인이 그 일에 관하여 제삼자에게 가한 손해를 배상할 책임이 없다. 그러나 도급 또는 지시에 관하여 도급인에게 중대한 과실이 있는 때에는 그러하지 아니하다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"statute","group":"민법4_강의자료(불법행위)-189","continued":false,"pageStart":124,"pageEnd":124,"anchor":"source-124-10"},{"type":"p","text":"도급인이 자신의 지시에 좇아 행위한 수급인의 행위에 대하여 책임을 지는 것(제757조 제2문 참고)도 이에 해당한다. 원래 수급인은 도급인으로부터 독립하여 사무를 처리한다. 따라서 수급인은 도급인의 피용자라고 할 수 없다. 즉, 제757조 제1문은 도급인에게 제756조의 책임이 없음을 규정한 것에 지나지 않는다. 그러나 도급 또는 지시에 관하여 도급인에게 \"중대한 과실\"이 있으면, 도급인은 수급인의 행위에 대하여 사용자로서 책임을 진다(제757조 제2문).","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":124,"pageEnd":124,"anchor":"source-124-11"},{"type":"p","text":"v 대법원 2005. 11. 10. 선고 2004다37676 판결: 일반적으로 도급인과 수급인 사이에는 지휘·감독의 관계가 없으므로 도급인은 수급인이나 수급인의 피용자의 불법행위에 대하여 사용자로서의 배상책임이 없는 것이지만, 도급인이 수급인에 대하여 특정한 행위를 지휘하거나 특정한 사업을 도급시키는 경우와 같은 이른바 노무도급의 경우에는 비록 도급인이라고 하더라도 사용자로서의 배상책임이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-190","continued":false,"pageStart":124,"pageEnd":124,"anchor":"source-124-12"},{"type":"h3","text":"2) 외부적 사용관계","emphasis":[[0,11]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":124,"pageEnd":124,"anchor":"source-124-13"},{"type":"p","text":"외부적으로 ‘사용관계’가 존재하는 것으로 보이는 경우에도 사용관계가 인정된다. 특히 판례는 명의대여자에 대해서도 사용자책임을 인정하고 있다. 이 경우 내부적으로는 사용관계가 없다는 점에서 외부적으로 표현된 사용관계가 책임인정의 근거가 된다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":125,"pageEnd":125,"anchor":"source-125-0"},{"type":"p","text":"v 대법원 2001. 3. 9. 선고 2000다66119 판결(공 2001, 844) : 증권회사의 전 지점장이 회사를 퇴직한 후 같은 지점에서 투자상담사로 근무하다가 그 직을 그만두었음에도 불구하고 이를 숨기고 고객들을 상대로 투자상담사로서의 업무를 계속하였고, 증권회사에서도 그의 업무수행을 묵인하고 회사의 투자상담사로서 업무를 수행하는 것처럼 외관을 갖게 하였다면, 그가 고객들의 증권카드와 인감을 사용하여 금원을 인출한 행위에 대하여 증권회사는 사용자책임을 면할 수 없다고 한 사례.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-191","continued":false,"pageStart":125,"pageEnd":125,"anchor":"source-125-1"},{"type":"p","text":"v 대법원 2007. 6. 28. 선고 2007다26929 판결(미간행) : 타인에게 어떤 사업에 관하여 자기의 명의를 사용할 것을 허용한 경우에 그 사업이 내부관계에 있어서는 타인의 사업이고 명의자의 고용인이 아니라 하더라도 외부에 대한 관계에 있어서는 그 사업이 명의자의 사업이고 또 그 타인은 명의자의 종업원임을 표명한 것과 다름이 없으므로, 명의사용을 허용받은 사람이 업무수행을 함에 있어 고의 또는 과실로 다른 사람에게 손해를 끼쳤다면 명의사용을 허용한 사람은 민법 제756조에 의하여 그 손해를 배상할 책임이 있고, 명의대여관계의 경우 민법 제756조가 규정하고 있는 사용자책임의 요건으로서의 사용관계가 있느냐 여부는 실제적으로 지휘·감독을 하였느냐의 여부에 관계없이 객관적·규범적으로 보아 사용자가 그 불법행위자를 지휘·감독해야 할 지위에 있었느냐의 여부를 기준으로 결정하여야 할 것이다(대법원 2001. 8. 21. 선고 2001다3658 판결 등 참조).","emphasis":[],"underline":[[295,397],[398,447]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-192","continued":false,"pageStart":125,"pageEnd":125,"anchor":"source-125-2"},{"type":"p","text":"v 대판 2006. 3. 10, 2005다65562 : 동업관계에 있는 자들이 공동으로 처리하여야 할 업무를 동업자 중 1인에게 맡겨 그로 하여금 처리하도록 한 경우 다른 동업자는 그 업무집행자의 동업자인 동시에 사용자의 지위에 있다 할 것이므로, 업무집행과정에서 발생한 사고에 대하여 사용자로서 손해배상책임이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-193","continued":false,"pageStart":125,"pageEnd":125,"anchor":"source-125-3"},{"type":"p","text":"v 대판 2001. 8. 21, 2001다3658 : 타인에게 어떤 사업에 관하여 자기의 명의를 사용할 것을 허용한 경우에 그 사업이 내부관계에 있어서는 타인의 사업이고 명의자의 고용인이 아니라 하더라도 외부에 대한 관계에 있어서는 그 사업이 명의자의 사업이고 또 그 타인은 명의자의 종업원임을 표명한 것과 다름이 없으므로, 명의사용을 허용받은 사람이 업무수행을 함에 있어 고의 또는 과실로 다른 사람에게 손해를 끼쳤다면 명의사용을 허용한 사람은 민법 제756조에 의하여 그 손해를 배상할 책임이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-194","continued":false,"pageStart":125,"pageEnd":125,"anchor":"source-125-4"},{"type":"h3","text":"(3) 가해행위의 사무집행관련성","emphasis":[[0,17]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":125,"pageEnd":125,"anchor":"source-125-5"},{"type":"p","text":"사용자는 피용자가 그 \"사무집행에 관하여\" 제3자에게 가한 손해를 배상할 책임이 있다. 사용자책임의 전형적인 경우는 피용자가 사용자로부터 지시받은 일을 하다가 실수로 타인에게 손해를 끼치는 경우이다. 이 경우 당연히 사무집행관련성은 인정된다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":125,"pageEnd":125,"anchor":"source-125-6"},{"type":"p","text":"그러나 사무집행관련성은 두 가지 방향으로 확대될 수 있다. 하나는 지시받은 일을 하는 중에 ‘고의로’ 타인에게 손해를 끼치는 경우이고, 다른 하나는 지시받지 않은 일을 하다가 고의 또는 과실로 타인에게 손해를 끼치는 경우이다. 이러한 경우에 통설과 판례는 가해행위가 사무집행과 관련되는가를 판단하기 위하여 외형이론을 적용한다. 즉, “피용자의 행위가 사무집행의 외형을 갖는\"지의 여부로 판단한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":125,"pageEnd":125,"anchor":"source-125-7"},{"type":"p","text":"\"사무집행에 관하여\"라는 요건은 사용자책임의 적용과 관련하여 가장 중요한 요건으로서 본래의 사무집행 자체 또는 그 목적달성을 위해 일체불가분의 관계를 갖고 있는 행위만으로 제한되지 않는다. 즉, 사무집행과 관련성을 갖는 것으로 보이기만 하면 족하다(외형이론). 다시 말해 사무집행 관련성은 피용자의 행위가 외형상 객관적으로 사용자의 사업활동, 사무집행행위 또는 그와 관련된 것이라고 보여지면 충분하고, 행위자의 주관적 사정은 고려되지 않는다. 또한 피용자의 행위가 사용자의 명령이나 금지에 반하여 부당한 것이더라도, 외형상 사무에 속하는 것이라면 사무집행관련성이 인정된다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":125,"pageEnd":125,"anchor":"source-125-8"},{"type":"p","text":"가령, 피용자가 ‘고의로’ 타인에게 손해를 끼치는 것은 사용자가 지시한 업무에는 속하지 않는다. 하지만 피용자의 불법행위가 외형상 객관적으로 사용자의 사업활동이나 사무집행행위 또는 그와 관련된 것이라고 보일 때에는 행위자의 주관적 사정(가해의 고의)을 고려하지 않고, 이를 사무집행에 관한 행위로 보게 된다(대법원 1998. 2. 10. 선고, 95다39533 판결 등 참고).","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":125,"pageEnd":125,"anchor":"source-125-9"},{"type":"p","text":"v 대법원 1998. 2. 10. 선고, 95다39533 판결 : [4] 민법 제756조에 규정된 사용자 책임의 요건인 '사무집행에 관하여'라는 뜻은 피용자의 불법행위가 외형상 객관적으로 사용자의 사업활동 내지 사무집행 행위 또는 그와 관련된 것이라고 보여질 때에는 행위자의 주관적 사정을 고려함이 없이 이를 사무집행에 관하여 한 행위로 본다는 것이고, 외형상 객관적으로 사용자의 사무집행에 관련된 것인지의 여부는 피용자의 본래 직무와 불법행위와의 관련 정도 및 사용자에게 손해 발생에 대한 위험 창출과 방지조치 결여의 책임이 어느 정도 있는지를 고려하여 판단하여야 한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-195","continued":false,"pageStart":125,"pageEnd":126,"anchor":"source-125-10"},{"type":"p","text":"[5] 고용관계 또는 근로관계는 이른바 계속적 채권관계로서 인적 신뢰관계를 기초로 하는 것이므로, 고용계약에 있어 피용자가 신의칙상 성실하게 노무를 제공할 의무를 부담함에 대하여, 사용자로서는 피용자에 대한 보수지급의무 외에도 피용자의 인격을 존중하고 보호하며 피용자가 그 의무를 이행하는 데 있어서 손해를 받지 아니하도록 필요한 조치를 강구하고 피용자의 생명, 건강, 풍기 등에 관한 보호시설을 하는 등 쾌적한 근로환경을 제공함으로써 피용자를 보호하고 부조할 의무를 부담하는 것은 당연한 것이지만, 어느 피용자의 다른 피용자에 대한 성희롱 행위가 그의 사무집행과는 아무런 관련이 없을 뿐만 아니라, 가해자의 성희롱 행위가 은밀하고 개인적으로 이루어지고 피해자로서도 이를 공개하지 아니하여 사용자로서는 이를 알거나 알 수 있었다고 보여지지도 아니하다면, 이러한 경우에서까지 사용자가 피해자에 대하여 고용계약상의 보호의무를 다하지 아니하였다고 할 수는 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-195","continued":true,"pageStart":126,"pageEnd":126,"anchor":"source-126-1"},{"type":"p","text":"다만 외형이론에 따른 사무집행 관련성에 대해서는 그 적용이 제한되는 경우가 있음에 주의해야 한다. 즉, 대법원에 따르면 피용자의 불법행위가 외관상 사용자의 사무집행의 범위 내에 속하는 것으로 보이는 경우라도 피용자의 행위가 사용자의 사무집행행위에 해당하지 않음을 피해자 자신이 ‘알았거나 중대한 과실로 알지 못하는 경우’에는 사용자책임이 부정된다고 판시하고 있다(대법원 2003. 2. 11. 선고 2002다62029 판결). 외형이론이 피해자의 정당한 신뢰만을 보호하고자 하는 이론이라는 점에서 보호할 필요가 없는 피해자에 대해 그 적용을 배제하는 판례의 입장은 타당하다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":126,"pageEnd":126,"anchor":"source-126-2"},{"type":"p","text":"v 대법원 2003. 2. 11. 선고, 2002다62029 판결 : [3] 피용자의 불법행위가 외관상 사무집행의 범위 내에 속하는 것으로 보이는 경우에 있어서도, 피용자의 행위가 사용자나 사용자에 갈음하여 그 사무를 감독하는 자의 사무집행 행위에 해당하지 않음을 피해자 자신이 알았거나 또는 중대한 과실로 인하여 알지 못한 경우에는 사용자책임을 물을 수 없고, 사용자책임이 면책되는 피해자의 중대한 과실이라 함은 거래의 상대방이 조금만 주의를 기울였더라면 피용자의 행위가 그 직무권한 내에서 적법하게 행하여진 것이 아니라는 사정을 알 수 있었음에도 만연히 이를 직무권한 내의 행위라고 믿음으로써 일반인에게 요구되는 주의의무에 현저히 위반하는 것으로 거의 고의에 가까운 정도의 주의를 결여하고, 공평의 관점에서 상대방을 구태여 보호할 필요가 없다고 봄이 상당하다고 인정되는 상태를 말한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-196","continued":false,"pageStart":126,"pageEnd":126,"anchor":"source-126-3"},{"type":"p","text":"v 대법원 1995. 2. 3. 선고 94다43115 판결 : 세무사 甲의 세무회계사무소 사무장인 乙이 丙으로부터 토지 양도로 인한 양도소득세 신고. 납부와 관련한 상담을 받고 세액과 비용이 금 30,000,000원 정도가 되니 그 금액이면 양도소득세 및 수수료 등 모든 것을 책임지고 종결시켜 주겠다고 하여 양도소득세 신고 및 납부대행을 위임받아 처리하기로 하고 丙으로부터 그 금원을 지급받은 후, 甲에게 그 사실을 알리지 아니한 채 관할세무서에 丙 명의로 양도소득세 과세표준확정신고를 하면서 양도소득세 및 방위세로 일부만을 납부하고 나머지 금액을 임의로 소비하였고, 그 이후 위 세액이 과소하게 신고 납부되었음이 밝혀져 丙이 가산세를 합하여 양도소득세, 방위세 및 가산금을 추가로 납부하게 되었다면, 乙의 행위는 외형상 객관적으로 사용자인 甲의 사무집행과 밀접하게 관련된 것이므로 甲은 乙의 사용자로서 위 불법행위로 인하여 丙이 입은 손해를 배상할 책임이 있다고 한 사례.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-197","continued":false,"pageStart":126,"pageEnd":126,"anchor":"source-126-4"},{"type":"p","text":"v 대법원 2021. 3. 11. 선고 2018다285106 판결: 제756조에 규정된 사용자책임의 요건인 ‘사무집행에 관하여’라 함은 피용자의 불법행위가 외형상 객관적으로 사용자의 사업활동, 사무집행행위 또는 그와 관련된 것이라고 보일 때에는 행위자의 주관적 사정을 고려하지 않고 사무집행에 관하여 한 행위로 본다는 것이다. 피용자가 다른 사람에게 가해행위를 한 경우 그 행위가 피용자의 사무집행 그 자체는 아니더라도 사용자의 사업과 시간적·장소적으로 근접하고 피용자의 사무의 전부 또는 일부를 수행하는 과정에서 이루어지거나 가해행위의 동기가 업무처리와 관련된 것이라면 외형적·객관적으로 사용자의 사무집행행위와 관련된 것이라고 보아 사용자책임이 성립한다. 이때 사용자가 위험발생을 방지하기 위한 조치를 취하였는지 여부도 손해의 공평한 부담을 위하여 부가적으로 고려할 수 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-198","continued":false,"pageStart":126,"pageEnd":126,"anchor":"source-126-5"},{"type":"p","text":"v 대법원 1993. 5. 27. 선고 92다48109 판결: 도급인은 도급 또는 지시에 관하여 중대한 과실이 없는 한 수급인이 그 일에 관하여 제3자에게 가한 손해를 배상할 책임이 없으나 도급인이 수급인의 일의 진행 및 방법에 관하여 구체적인 지휘 감독권을 유보한 경우에는 도급인과 수급인의 관계는 실질적으로 사용자 및 피용자의 관계와 다를 바 없으므로 수급인이 고용한 제3자의 불법행위로 인한 손해에 대하여 도급인은 제756조에 의한 사용자책임을 면할 수 없고, 이러한 이치는 하도급의 경우에도 마찬가지이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-199","continued":false,"pageStart":126,"pageEnd":126,"anchor":"source-126-6"},{"type":"p","text":"또한, 피용자가 지시받지 않은 일을 하는 중에 타인에게 손해를 가하였다면, 이는 엄격한 의미에서는 사무집행이라고 할 수 없다. 그러나 판례와 통설은 업무수행에 시간적․장소적으로 근접하고 업무수행의 外觀을 가지고 있는 경우에는 사무집행관련성을 인정한다. 이와 같이 엄격한 의미에서 사무집행관련성이 인정되지 않는 경우에도 외형이론은 외형을 기준으로 사무집행관련성을 인정한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":126,"pageEnd":126,"anchor":"source-126-7"},{"type":"p","text":"v 대법원 2000. 2. 11. 선고 99다47297 판결 : [사실관계] 甲은 乙이 운영하는 호텔의 종업원으로서 1996. 11. 11. 04:30경 호텔 프론트에서 근무하던 중, 호텔에 목욕을 하기 위하여 찾아온 丙로부터 사우나의 영업시간에 관한 질문을 받고 05:00부터 시작하니 조금 기다리라는 대답을 하였다. 그러나 이에 丙이 심하고 상스러운 욕을 하면서 때리려고 하자 이를 피하였다가 같은 날 04:40경 다음 근무자를 불러 근무교대를 하였는데, 그 후에도 丙이 호텔 지하의 종업원 숙소까지 따라오면서 계속 상스러운 욕을 하기도 하고, 근무교대 후 프론트에서 근무하던 다음 근무자에게도 甲을 불러오라면서 소란을 피우자, 05:00경 분을 참지 못하고 숙소에서 등산용 칼을 꺼내어 이를 소지한 채 丙을 따라 현관 앞 주차장으로 가서 丙이 다시 갑을 손으로 때리려고 하자 갖고 있던 칼로 丙의 얼굴과 등 부위를 찔러 丙에게 상해를 가하였다. [법원의 판단] 민법 제756조에 규정된 사용자책임의 요건인 '사무집행에 관하여'라는 뜻은 피용자의 불법행위가 외형상 객관적으로 사용자의 사업활동 내지 사무집행행위 또는 그와 관련된 것이라고 보여질 때에는 행위자의 주관적 사정을 고려함이 없이 이를 사무집행에 관하여 한 행위로 본다는 것으로, 피용자가 고의에 기하여 다른 사람에게 가해행위를 한 경우 그 행위가 피용자의 사무집행 그 자체는 아니라 하더라도 사용자의 사업과 시간적, 장소적으로 근접하고, 피용자의 사무의 전부 또는 일부를 수행하는 과정에서 이루어지거나 가해행위의 동기가 업무처리와 관련된 것일 경우에는 외형적, 객관적으로 사용자의 사무집행행위와 관련된 것이라고 보아 사용자책임이 성립한다고 할 것이고, 이 경우 사용자가 위험발생 및 방지조치를 결여하였는지 여부도 손해의 공평한 부담을 위하여 부가적으로 고려할 수 있다 할 것이다. 甲의 丙에 대한 상해행위는 乙의 업무처리를 하던 중 丙이 그 업무처리와 관련하여 甲의 감정을 해하는 언동을 하자 이에 대항하여 자신의 감정을 회복하기 위하여 저지른 것으로서, 그 가해행위는 근무교대 직후에 乙의 사업장소 내에서 이루어진 것이어서 시간적으로나 장소적으로 乙의 사무와 밀접하게 관련되어 있을 뿐만 아니라 그 행위의 동기가 甲의 업무처리와 관련된 것이라고 보여지며, 더욱이 접객업소 경영자인 乙로서는 불특정 다수의 고객을 대하는 피용자들에 대한 교육, 감독을 철저히 함으로써 그의 사업범위 내에서 발생할 수 있는 위와 같은 위험을 방지하여야 한다는 점도 아울러 고려하여 보면, 甲의 상해행위로 인하여 丙이 입은 손해는 甲이 乙의 피고의 사무집행에 관하여 丙에게 가한 손해에 해당한다고 보아야 할 것이다.","emphasis":[],"underline":[[538,541],[542,603],[604,636]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-200","continued":false,"pageStart":126,"pageEnd":127,"anchor":"source-126-8"},{"type":"p","text":"v 대법원 1997. 10. 10. 선고 97다16572 판결 : C 회사의 생산 현장 청소 등의 업무로서 파지와 고철의 수집·정리를 담당하던 피용자 A가 고철 수집 작업 중에 마실 물을 달라고 하는 피해자 B에게 음료수를 권하면서 접대한 행위는 A의 본래의 사무 집행 행위는 아니라고 할지라도 외형상 객관적으로 그 사무 집행 행위와 밀접하게 관련된 행위라고 할 것이어서, A가 농약을 음료수로 오인하고 건네주어 B가 이를 마시고 사망함으로써 입은 손해는, A가 C 회사의 사무 집행을 계기로 하여 이것과 밀접한 관련을 가진다고 인정할 수 있는 행위에 의하여 초래된 것으로서 C 회사의 사무의 집행에 관하여 가한 손해에 해당한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-201","continued":false,"pageStart":127,"pageEnd":127,"anchor":"source-127-1"},{"type":"p","text":"그러나 외형이론이 인정되는 경우에도 피용자가 지시받지 않은 일을 하던 중에 타인에게 고의로 손해를 가한 것이 명백한 경우에는 사무집행관련성을 부정하기도 한다. 이 경우는 피용자의 행위가 사용자의 사무집행행위에 속하지 않음을 피해자 자신이 알았거나 중대한 과실로 알지 못한 경우가 될 수 있기 때문이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":127,"pageEnd":127,"anchor":"source-127-2"},{"type":"p","text":"v 대법원 1994. 11. 18. 선고, 94다34272 판결 : 가. 민법 제756조에 규정된 사용자책임의 요건인 ‘사무집행에 관하여’라는 뜻은 피용자의 불법행위가 외형상 객관적으로 사용자의 사업활동 내지 사무집행행위 또는 그와 관련된 것이라고 보일 때에는 행위자의 주관적 사정을 고려함이 없이 이를 사무집행에 관하여 한 행위로 본다는 것이다.","emphasis":[],"underline":[[146,193]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-202","continued":false,"pageStart":127,"pageEnd":127,"anchor":"source-127-3"},{"type":"p","text":"나. 사적인 전화를 받던 레스토랑 종업원이 지배인으로부터 욕설과 구타를 당한 후 레스토랑을 나가 약 8시간 동안 배회하다가 과도를 사 가지고 레스토랑에 들어왔는데 다시 지배인으로부터 욕설과 구타를 당하자 이에 대항하여 지배인을 과도로 찔러 사망에 이르게 한 경우, 종업원의 위 불법행위가 레스토랑의 영업시간 중에 사용자의 사업장소에서 이루어진 것이기는 하나, 그 종업원은 사용자에게 고용되어 담당하게 된 사무의 집행과는 관련이 없이 자기 개인의 인격과 신체에 대한 침해행위에 대항하여 살해행위를 저질렀다고 봄이 상당하고, 종업원의 위 불법행위를 외형적, 객관적으로 보아도 이를 사용자의 사무집행과 관련된 행위로 볼 수는 없다고 한 사례.","emphasis":[],"underline":[[148,186],[187,248],[249,290],[292,349]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-202","continued":false,"pageStart":127,"pageEnd":127,"anchor":"source-127-4"},{"type":"p","text":"v 대법원 2005. 12. 23. 선고 2003다30159 판결: 사용자로부터 위임을 받은 바 없이 행한 피용자의 금원차용행위 및 예금인출행위에 대하여 피해자인 은행의 지점장이 위 피용자의 행위가 사용자의 사무집행행위에 해당하지 않음을 알고도 이에 응한 경우에 위 은행은 그로 인한 손해에 대하여 사용자책임을 물을 수 없다고 볼 수 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-203","continued":false,"pageStart":127,"pageEnd":127,"anchor":"source-127-5"},{"type":"h3","text":"(4) 선임·감독상의 주의의무 결여(면책사유 있음을 입증하지 못할 것)","emphasis":[[0,39]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":127,"pageEnd":127,"anchor":"source-127-6"},{"type":"p","text":"사용자는 ‘피용자의 선임 및 그 사무 감독에 상당한 주의를 한 때’ 또는 ‘상당한 주의를 하여도 손해가 있을 경우’에는 그 책임을 면할 수 있다(제756조 제1항 단서). 이러한 면책사유로 인하여 사용자책임은 이론적으로 사용자의 선임·감독상 주의의무위반의 과실책임으로서 성격을 갖는다고 설명되기도 한다(고유책임설). 그러나 입증책임을 전환하면서 면책사유의 인정을 엄격하게 제한하여 실질적으로 무과실책임에 가깝게 운영되고 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":127,"pageEnd":127,"anchor":"source-127-7"},{"type":"h3","text":"3. 사용자책임의 효과","emphasis":[[0,12]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":128,"pageEnd":128,"anchor":"source-128-0"},{"type":"p","text":"사용자책임의 구성요건이 충족되면 사용자 또는 사용자에 갈음하여 그 사무를 감독하는 자는 손해배상책임을 진다(제756조 제1항, 제2항). 피용자는 제750조에 의해 불법행위책임을 지며, 사용자와 피용자는 부진정연대채무 관계가 된다. 따라서 각각의 손해배상채무는 별개의 것이고, 각자의 독자적 책임이며 피해자가 어느 한쪽으로부터 배상을 일부 또는 전부 받으면, 그 범위에서 다른 쪽의 배상책임은 소멸한다. 사용자가 다수인 경우에도 그들의 책임은 부진정연대책임이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":128,"pageEnd":128,"anchor":"source-128-1"},{"type":"p","text":"사용자 또는 대리감독자가 손해배상을 하게 되면, 피용자에 대하여 구상권을 행사할 수 있다(제756조 제3항). 뿐만 아니라 사용자와 피용자 사이의 계약관계에 근거하여, 사용자는 피용자의 계약상 의무위반으로 발생한 손해에 대한 배상을 청구할 수도 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":128,"pageEnd":128,"anchor":"source-128-2"},{"type":"p","text":"v 대법원 1992. 3. 31. 선고, 91다39849 판결 : 가. 회사 명의로 등록된 차량을 그 지입차주로부터 운전수와 함께 일시 임차하여 화물운송에 사용한 경우에 특별한 사정이 없는 한 회사의 그 소속 운전수에 대한 사용자의 지위는 위와 같은 일시대여 상태에서도 유지된다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-204","continued":false,"pageStart":128,"pageEnd":128,"anchor":"source-128-3"},{"type":"p","text":"나. 위 \"가\"항의 경우 차량을 임차한 자로서는 그 임차기간 중 운전수를 지휘․감독하여 화물운송에 종사케 한 이상 비록 일시차용이라고 하여도 피해자에 대한 관계에서는 사용자로서의 배상책임을 면할 수 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-204","continued":false,"pageStart":128,"pageEnd":128,"anchor":"source-128-4"},{"type":"p","text":"다. 위 \"가\"항의 경우 차량의 임대인과 그 임차인의 각 배상책임은 서로 부진정연대관계에 있다고 할 것이므로, 어느 한 쪽이 피해자에 대한 손해를 배상하여 공동면책이 되었다면 그 구상권의 범위는 각자의 부담부분, 즉 손해발생에 기여한 과실의 정도에 의하여 결정하여야 할 것이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-204","continued":false,"pageStart":128,"pageEnd":128,"anchor":"source-128-5"},{"type":"p","text":"사용자는 피용자가 부담한 배상액을 대외적으로 부진정연대채무로서 부담하는 것에 불과하므로, 자신이 피해자에게 보상한 경우 이를 피용자에게 구상할 수 있다(通說). 그러나 피용자는 근로조건·작업시설·안전장치 등 사고방지를 위한 조건을 스스로 만들 수 없고 사용자는 위험성 있는 노동을 피용자에게 시키고 있기 때문에 손해배상금을 피용자에게 전부 부담시키는 것은 사업위험을 근로자에게 전가하는 결과가 되어 부당하다는 지적이 있다. 또한, 사용자는 사업위험을 줄이도록 적절한 조치를 취하거나 보험가입 또는 상품가격의 조정 등을 통하여 위험을 분산시킬 수 있으므로 피용자의 책임은 제한될 필요가 있다. 판례는 ‘信義則’에 따라 사용자의 구상권을 제한하고 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":128,"pageEnd":128,"anchor":"source-128-6"},{"type":"p","text":"v 대법원 1994. 12. 13. 선고 94다17246 판결 : [사실관계] A는 이사를 하기 위해 아파트관리사무소에 곤돌라를 이용하고 싶다고 의뢰를 하였고, 이에 A의 이삿날 한국주택관리 주식회사(甲)는 소속 직원인 관리소장 乙과 전기주임 丙에게 곤돌라를 운행할 것을 지시하였다. 한국주택관리 주식회사의 지시에 따라 丙은 곤돌라를 조작하여 A의 이사를 다 마친 뒤, 곤돌라의 버턴을 조작하여 곤돌라 줄을 원래의 위치인 옥상 위로 감아올리던 중, 곤돌라 줄 끝에 매달려 있던 쇠고리가 바람에 흔들리면서 15층 베란다 바깥쪽에 설치된 화분대를 치는 바람에 화분대가 지면으로 떨어지면서 곤돌라 아래 지면에 서 있던 B의 머리에 부딪치게 되었고, 이에 B는 사망하게 되었다. 이후 B의 유족은 乙과 丙의 사용자인 甲으로부터 금 1억 2천만 원의 손해배상을 받았다. 이에 갑은 乙과 丙에 대하여 1억 2천만 원에 대한 구상을 요구하였다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-205","continued":false,"pageStart":128,"pageEnd":128,"anchor":"source-128-7"},{"type":"p","text":"법원의 판결: 일반적으로 사용자가 피용자의 업무수행과 관련하여 행해진 불법행위로 인하여 직접 손해를 입었거나 그 피해자에게 사용자로서의 손해배상책임을 부담한 결과로 손해를 입게 된 경우에 있어서 사용자는 그 사업의 성격과 규모, 시설의 현황, 피용자의 업무내용, 근로조건이나 근무태도, 가해행위의 상황, 가해행위의 예방이나 손실의 분산에 관한 사용자의 배려정도, 기타 제반 사정에 비추어 손해의 공평한 분산이라는 견지에서 신의칙상 상당하다고 인정되는 한도 내에서만 피용자에 대하여 그 구상권을 행사할 수 있다고 보아야 할 것이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-205","continued":false,"pageStart":128,"pageEnd":128,"anchor":"source-128-8"},{"type":"p","text":"이러한 쌍방(갑(원고)과 을·병(피고))의 과실의 경중, 곤돌라 기사인 위 피고의 근무조건과 그러한 근무조건이 위 사고발생에 미친 영향의 정도, 위 피해자가 사고를 당하게 된 경위, 원고의 노무자에 대한 인력관리상황, 위 사고 후 위 피고가 실형을 복역한 후 현재 면직되어 있음에 반하여, 원고는 국내 유수의 공동주택관리업체로서의 지위를 그대로 유지하고 있는 점 등 제반 사정을 참작하여 보면, 피고 1에게 앞에서 본 바와 같은 과실이 있었다는 것만으로 원고가 위 피고에 대하여 피해자에게 배상한 데 대한 구상이나 손해배상을 구하는 것은 신의칙상 허용되지 아니한다 [정리] 피해자인 B에 대하여 사용자로서 손해배상을 한 甲은 피용자에 대하여 제756조 3항에 따라서 구상할 수 있다. 그러나 이 구상권규정을 그대로 관철하게 되면 결과적으로 모든 책임을 피용자가 지게 되는 결과가 되는 반면, 사업상 이익을 얻는 사용자는 아무런 부담도 지지 않는 것이 되어 부당하다. 따라서 판례는 사용자의 피용자에 대한 구상권을 ‘신의칙’에 따라서 제한하고자 하는데, 위 사안에서 비록 乙과 丙이 안전조치를 게을리한 과실이 있긴 하나, 한국주택관리 주식회사인 甲의 업무지시로 인한 것인 점, 곤돌라의 경우 이에 대한 면허가 없다는 점, 인원부족으로 혼자서 곤돌라를 조작하다 사고가 난 점, 곤돌라의 구조상 줄이 바람에 흔들리는 것을 막기가 쉽지 않았다는 점 등을 고려하여, 갑은 乙과 병에게 구상할 수 없다고 보았다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-205","continued":false,"pageStart":128,"pageEnd":129,"anchor":"source-128-9"},{"type":"p","text":"v 대법원 1991. 5. 10. 선고 91다7255 판결 : 일반적으로 사용자가 피용자의 업무수행과 관련하여 행해진 불법행위로 인하여 직접 손해를 입었거나 그 피해자에게 사용자로서의 손해배상책임을 부담한 결과로 손해를 입게 된 경우에 있어 사용자는 그 사업의 성격과 규모, 시설의 현황, 피용자의 업무내용, 근로조건이나 근무태도, 가해행위의 상황, 가해행위의 예방이나 손실의 분산에 관한 사용자의 배려정도, 기타 제반사정에 비추어 손해의 공평한 분산이라는 견지에서 신의칙상 상당하다고 인정되는 한도 내에서만 피용자에 대하여 그 구상권을 행사할 수 있다고 보아야 할 것이다( 당원 1987. 9. 8. 선고 86다카1045 판결 참조).","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-206","continued":false,"pageStart":129,"pageEnd":129,"anchor":"source-129-1"},{"type":"p","text":"원고는 렌트카 30대를 보유하고 그 차량의 대여를 영업목적으로 하고 있어서 이용고객의 희망에 따라 수시로 차량운전을 위한 인원이 필요한 관계로 주간 근무자로서 운전기사 3명을 두는 한편, 야간에는 별도로 경비원인 위 망 김영식으로 하여금 사무실 차량의 경비관리와 차량의 대여 및 반차인수 업무 등과 함께 고객의 요청에 따른 대여차량의 운전 등 일체의 야간업무에 종사하게 하여온 사실, 원고가 위 망인을 채용할 당시 동인이 자동차운전면허가 없는 자임을 알면서도 회사 경영상 노무부족 때문에 동인에게 위와 같은 업무를 담당하게 하였을 뿐만 아니라 동인에 대한 근무감독이나 위험사고발생의 예방을 위한 아무런 조치를 강구하지 아니한 사실, 위 망인은 입사 이래 계속하여 매일 19:00부터 08:30까지 혼자 근무하면서 월 금 200,000원의 비교적 적은 보수를 받고 아무런 사고 없이 성실하게 근무하여 온 사실, 한편 원고는 위 김영식이 사고 당시 렌트카를 무단 사용 운전하였다는 이유를 내세워 동인의 유족에 대하여 근로기준법 또는 산업재해보상보험법에 따른 보상 내지 보험처리를 하지 않고 있는 사실들을 인정하고 나서 이 사건 사고의 발생원인에 있어 피용자인 위 망 김영식의 가해행위가 지니는 책임성에 비하여 사용자인 원고의 가해행위에 대한 기여도 내지 가공도가 지나치게 크다고 보여지는 점 등을 참작하면, 원고가 사용자로서의 위 망인의 상속인과 그 신원보증인들인 피고들에게 구상권을 행사한다는 것은 신의칙상 도저히 받아들일 수 없다고 판시하고 원고의 청구를 기각하였는바, 원심의 위와 같은 조치는 위에서 본 법리에 따른 것으로 정당하다고 수긍이 되고 거기에 소론과 같은 법리오해의 위법이 있다고 할 수 없다. 논지는 이유 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-206","continued":false,"pageStart":129,"pageEnd":129,"anchor":"source-129-2"},{"type":"h3","text":"Ⅳ. 공작물 등의 점유자와 소유자의 책임","emphasis":[[0,22]],"underline":[],"highlight":[],"strike":[],"headingLevel":3,"pageStart":129,"pageEnd":129,"anchor":"source-129-3"},{"type":"p","text":"제758조(공작물 등의 점유자, 소유자의 책임) ①공작물의 설치 또는 보존의 하자로 인하여 타인에게 손해를 가한 때에는 공작물점유자가 손해를 배상할 책임이 있다. 그러나 점유자가 손해의 방지에 필요한 주의를 해태하지 아니한 때에는 그 소유자가 손해를 배상할 책임이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"statute","group":"민법4_강의자료(불법행위)-207","continued":false,"pageStart":129,"pageEnd":129,"anchor":"source-129-4"},{"type":"p","text":"②전항의 규정은 수목의 재식 또는 보존에 하자 있는 경우에 준용한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"statute","group":"민법4_강의자료(불법행위)-207","continued":false,"pageStart":129,"pageEnd":129,"anchor":"source-129-5"},{"type":"p","text":"③전2항의 경우 점유자 또는 소유자는 그 손해의 원인에 대한 책임 있는 자에 대하여 구상권을 행사할 수 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"statute","group":"민법4_강의자료(불법행위)-207","continued":false,"pageStart":129,"pageEnd":129,"anchor":"source-129-6"},{"type":"h3","text":"1. 의의","emphasis":[[0,5]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":129,"pageEnd":129,"anchor":"source-129-7"},{"type":"p","text":"공작물의 설치 또는 보존의 하자로 인하여 타인에게 손해를 가한 경우 공작물의 점유자와 소유자가 손해배상 책임을 지는 것을 공작물 등의 점유자와 소유자 책임이라고 한다(제758조 제1항 제1문). 공작물의 점유자가 1차적으로 배상책임을 지고, 점유자가 손해의 방지에 필요한 주의를 다한 경우 점유자의 책임을 배제하고 있다. 이 경우 2차적으로 공작물의 소유자가 배상책임을 진다(제758조 제1항 제2문). 소유자는 면책이 불가능하다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":129,"pageEnd":129,"anchor":"source-129-8"},{"type":"p","text":"예를 들면, 갈라진 돌축대가 장마로 무너져서 통행인이 다친 경우 점유자인 임차인이 1차적으로 책임을 지게 된다. 그러나 임차인이 통행인의 접근을 막고 위험을 알리는 등 충분한 조치를 하였다면 소유자인 집주인이 손해배상책임을 부담하게 된다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":129,"pageEnd":129,"anchor":"source-129-9"},{"type":"h3","text":"2. 공작물책임의 성질","emphasis":[[0,12]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":129,"pageEnd":129,"anchor":"source-129-10"},{"type":"p","text":"공작물의 점유자는 손해의 발생을 막는 데 필요한 주의를 다한 경우 면책되기 때문에 점유자의 책임은 이미 설명한 사용자의 책임과 같이 과실의 입증책임을 전환한 중간책임(추정과실책임)이 된다. 그러나 소유자는 면책이 인정되지 않는다는 점에서 무과실책임이라고 할 수 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":129,"pageEnd":129,"anchor":"source-129-11"},{"type":"p","text":"점유자의 책임과 소유자의 책임은 원칙적으로 위험책임의 원리에서 출발한다. 즉, 위험성이 많은 공작물을 관리·소유하는 자는 위험의 방지에 충분한 주의를 하여야 하며, 만일 이러한 위험이 현실화하여 손해가 발생한 경우 그 손해를 배상할 책임을 지는 것이 사회적으로 타당하기 때문이다. 다만, 공작물 소유자 책임은 엄격한 의미의 위험책임으로 보기는 어렵다고 평가된다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":129,"pageEnd":130,"anchor":"source-129-12"},{"type":"p","text":"v 대법원 1996. 11. 22. 선고 96다39219 판결: 제758조는 공작물의 설치·보존의 하자로 인하여 타인에게 손해를 가한 경우 그 점유자 또는 소유자에게 일반 불법행위와 달리 이른바 위험책임의 법리에 따라 책임을 가중시킨 규정일 뿐이고, 그 공작물 시공자가 그 시공상의 고의·과실로 인하여 피해자에게 가한 손해를 제750조에 의하여 직접 책임을 부담하게 되는 것을 배제하는 취지의 규정은 아니다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-208","continued":false,"pageStart":130,"pageEnd":130,"anchor":"source-130-1"},{"type":"h3","text":"3. 공작물책임의 요건","emphasis":[[0,12]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":130,"pageEnd":130,"anchor":"source-130-2"},{"type":"h3","text":"(1) 공작물","emphasis":[[0,7]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":130,"pageEnd":130,"anchor":"source-130-3"},{"type":"p","text":"공작물책임은 공작물로부터 손해가 생겼을 것을 요건으로 한다. 공작물이란 인공적 작업에 의하여 만들어진 물건을 의미하며, 토지의 상하에 존재하는 공작물이나 건물의 일부를 이루는 내부설비, 기업설비 등이 이에 해당한다. 자동차나 항공기와 같은 동산도 공작물에 포함된다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":130,"pageEnd":130,"anchor":"source-130-4"},{"type":"p","text":"v 대법원 2026. 1. 8. 선고 2022다233713 판결: 민법 제758조 제1항은 위험책임 법리에 근거하여 공작물 소유자에게 무과실책임을 부과함으로써 그 책임을 가중하고, 구 민법 제717조 제1항과 달리 공작물책임의 원칙적인 적용 대상을 “토지의 공작물”로 한정하지 않고 “공작물”, 즉 인공적 작업에 의하여 제작된 물건으로 확대하였다. 이와 같이 공작물 소유자에게 무과실책임을 부과하고 공작물책임의 적용 범위를 확대한 것은 과학기술의 발전 등으로 인해 위험원이 복잡·다양화되고 있는 현대 사회에서 피해자 보호를 도모하는 데 그 취지가 있다. 그러나 위와 같은 입법 취지를 고려하더라도, 공작물 소유자에게 예외 없이 모든 손해를 배상할 무과실책임을 지운다면 손해의 공평 부담을 지도원리로 하는 손해배상제도의 근본 취지에 어긋나는 경우가 있을 수 있다. 특히 복잡다기한 기술이 집약되어 만들어진 공작물의 경우, 그 소유자가 해당 공작물의 구조 및 작동원리와 그로 인한 위험성, 위험성이 현실화하여 발생할 수 있는 손해의 범위 등을 구체적으로 파악하기 어렵다는 점에서 더욱 그러하다. 불법행위에 있어 손해액을 정함에 참작하는 피해자의 과실, 즉 과실상계에서의 과실은 가해자의 과실과 달리 사회통념이나 신의성실의 원칙에 따라 공동생활에 있어 요구되는 약한 의미의 부주의를 가리키는데, 그 취지 또한 불법행위로 인한 손해를 가해자와 피해자 사이에 공평하게 분담시키고자 함에 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-209","continued":false,"pageStart":130,"pageEnd":130,"anchor":"source-130-5"},{"type":"h3","text":"(2) 공작물의 설치·보존상 하자로 인한 손해","emphasis":[[0,25]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":130,"pageEnd":130,"anchor":"source-130-6"},{"type":"p","text":"공작물의 설치 또는 보존의 하자로 인하여 손해가 발생하여야 한다. 우선, ① 여기서 하자(瑕疵)란 물건이 그 용도에 따라 통상 갖추고 있어야 할 완전성을 갖추고 있지 않은 경우를 의미한다(객관적 관점). 하자의 존부는 객관적으로 판단되며, 점유자나 소유자의 고의·과실에 의하여 발생할 것을 요하지 않는다. 또한, ② 하자로 손해가 발생해야 한다. 만약 공작물이 강풍이나 폭우와 같은 불가항력으로 파괴되고, 이로 인하여 손해가 발생한 경우 이러한 손해가 공작물에 하자가 없는 경우에도 일어날 수 있다면 공작물에 존재하는 하자와 손해 간의 인과관계는 부정될 수 있다. 즉, 공작물에 의한 책임이 점유자는 물론 소유자에게도 발생하지 않는다. 이 경우는 불행한 사건에 불과할 뿐이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":130,"pageEnd":130,"anchor":"source-130-7"},{"type":"p","text":"v 대법원 1993. 3. 9. 선고 92다54715 판결 : 경기장 앞 광장 입구의 도로 위에 차량통행을 막기 위하여 바리케이드 2개를 설치하고, 그 사이의 2m 공간에 윗부분끼리 한 줄의 쇠사슬로 연결해 놓았는데 피해자가 오토바이를 타고 그 사이를 통과하려다가 쇠사슬에 목부분이 걸려 넘어지면서 사망한 사고에서 경기장 진입로 차단시설의 설치보존상의 하자가 있다고 한 사례.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-210","continued":false,"pageStart":130,"pageEnd":130,"anchor":"source-130-8"},{"type":"p","text":"v 대법원 1998. 1. 23. 선고 97다25118 판결 : 가. 민법 제758조 제1항에 규정된 공작물의 설치․보존상의 하자라 함은 공작물이 그 용도에 따라 통상 갖추어야 할 안전성을 갖추지 못한 상태에 있음을 말하는 것으로서, 이와 같은 안전성의 구비 여부를 판단함에 있어서는 당해 공작물의 설치․보존자가 그 공작물의 위험성에 비례하여 사회통념상 일반적으로 요구되는 정도의 방호조치 의무를 다하였는지의 여부를 기준으로 삼아야 할 것이고, 따라서 공작물에서 발생한 사고라도 그것이 공작물의 통상의 용법에 따르지 아니한 이례적인 행동의 결과 발생한 사고라면, 특별한 사정이 없는 한 공작물의 설치․보존자에게 그러한 사고에까지 대비하여야 할 방호조치 의무가 있다고 할 수는 없다.","emphasis":[],"underline":[[39,76],[77,126],[175,203],[204,245]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-211","continued":false,"pageStart":130,"pageEnd":130,"anchor":"source-130-9"},{"type":"p","text":"나. 배수관이 설치된 여관 앞 골목길은 평소에 여관 내부를 엿보려고 하는 행인들이 있었고 그러한 사람들이 배수관을 잡고 올라가는 경우가 있어 배수관이 자주 훼손되므로 여관 주인이 이를 방지하기 위하여 보호벽을 설치하게 되었으며, 보호벽을 설치하면서 보호벽의 맨 윗부분에 여러 개의 못까지 박아 두었는데, 행인이 음주를 한 상태에서 여관의 내부를 들여다 보기 위하여 그 보호벽을 타고 올라가다가 보호벽이 무너지는 바람에 사고를 당하게 된 경우, 그 보호벽의 본래의 용도는 어디까지나 배수관이 훼손되는 것을 방지하기 위한 것이므로, 보호벽이 스스로 넘어지지 않을 만큼의 견고성을 갖도록 설치하였다면 이로써 보호벽은 일단 본래의 용도에 따른 통상적인 안전성을 갖추었다고 할 것이고, 그와 같이 보호벽 윗부분에 못을 박아 사람들이 보호벽 위로 올라가서 여관방을 들여다 보는 것을 방지하는 조치까지 취하였음에도 불구하고 행인들이 윗부분에 꽂혀 있는 못에 찔려 다칠 위험을 무릅쓰고 보호벽에 올라가 여관 내부를 들여다 보는 부정한 행위를 저지를 것까지 예상하여 보호벽을 설치․관리하는 여관 주인에게 이러한 경우까지 대비한 방호조치를 취할 의무는 없다는 이유로 그 보호벽의 설치․보존상의 하자를 부인한 사례.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-211","continued":false,"pageStart":130,"pageEnd":131,"anchor":"source-130-10"},{"type":"p","text":"v 대법원 1994. 10. 28. 선고 94다16328 판결 : 나. 도시가스의 공급시설 내지 그 사용시설 등과 같은 고도의 위험을 수반하는 공작물의 경우에는 그 시설이 관계법령의 정한 바에 따른 시설기준 등에 부적합한 것이라면 특별한 사정이 없는 한 이러한 사유는 공작물의 설치․보존상의 하자에 해당한다고 볼 수 있다고 한 사례.","emphasis":[],"underline":[[40,79],[80,125]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-212","continued":false,"pageStart":131,"pageEnd":131,"anchor":"source-131-1"},{"type":"p","text":"[정리] 가스보일러의 폐가스인 일산화탄소에 중독되어 사망한 사건에서 피해자가 환기구를 막아놓은 과실도 있지만, 관계법령의 시설기준에 부합하지 않게 설치한 회사의 책임을 인정한 사례","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-212","continued":false,"pageStart":131,"pageEnd":131,"anchor":"source-131-2"},{"type":"p","text":"v 대법원 2000. 1. 14. 선고 99다39548 판결 : [2] 온풍기의 연통을 가연성 물질인 천막지붕에 근접하여 설치한 경우, 온풍기의 설치․보존상의 하자가 있다고 본 사례.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-213","continued":false,"pageStart":131,"pageEnd":131,"anchor":"source-131-3"},{"type":"p","text":"v 대법원 1988. 11. 8. 선고 86다카775 판결 : 가. 민법 제758조 제1항에 규정된 공작물의 설치 또는 보존의 하자라 함은 그 공작물이 본래 갖추어야 할 안전성을 갖추지 못한 상태를 말하는 것인 바, 경부고속도로는 시속 100킬로미터의 속도로 차량이 빈번히 통행하는 도로로서 도로상에 통행에 방해가 되는 어떠한 장애물의 존재도 허용될 수 없는 것이기 때문에 그 도로의 추월선상에 가로 약 30내지 40센티미터, 세로 약 40내지 50센티미터, 높이 약 20센티미터 크기의 차단 블록이 밀려나와 있었다면 그 사실자체가 일단은 고속도로가 본래 갖추어야 할 안전성을 갖추지 못한 상태에 있는 것이어서 이는 고속도로의 보존상의 하자가 있는 경우에 해당한다.","emphasis":[],"underline":[[121,140],[141,204],[205,272],[273,333],[334,338]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-214","continued":false,"pageStart":131,"pageEnd":131,"anchor":"source-131-4"},{"type":"p","text":"나. 고속도로의 보존상의 하자의 존재에 관한 입증책임은 피해자에게 있으나 일단 그 하자있음이 인정되는 이상 고속도로의 점유관리자는 그 하자가 불가항력에 인한 것이거나 손해의 방지에 필요한 주의를 해태하지 아니하였다는 점을 주장입증하여야 비로소 그 책임을 면할 수가 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-214","continued":false,"pageStart":131,"pageEnd":131,"anchor":"source-131-5"},{"type":"p","text":"v [하자의 개념에 관한 객관적 관점을 따르지 않은 판결] 대법원 1992. 9. 14. 선고 92다3243 판결 : 가. 공작물인 도로의 설치보존상의 하자는 도로의 위치 등 장소적인 조건,도로의 구조, 교통량, 사고 시에 있어서의 교통사정 등 도로의 이용상황과 그본래의 이용목적 등 제반 사정과 물적 결함의 위치, 형상 등을 종합적으로 고려하여 사회통념에 따라 구체적으로 판단하여야 할 것인바, 도로의 설치 후 제3자의 행위에 의하여 그 본래의 목적인 통행상의 안전에 결함이 발생된 경우에는 도로에 그와 같은 결함이 있다는 것만으로 성급하게 도로의 보존상 하자를 인정하여서는 안되고, 당해 도로의 구조, 장소적 환경과 이용상황 등 제반 사정을 종합하여 그와 같은 결함을 제거하여 원상으로 복구할 수 있는데도 이를 방치한 것인지 여부를 개별적, 구체적으로 심리하여 하자의 유무를 판단하여야 할 것이다.","emphasis":[],"underline":[[194,208],[209,211],[354,403],[404,447]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-214","continued":false,"pageStart":131,"pageEnd":131,"anchor":"source-131-6"},{"type":"p","text":"나. 트럭 앞바퀴가 고속도로상에 떨어져 있는 자동차 타이어에 걸려 중앙분리대를 넘어가 사고가 발생한 경우에 있어서 한국도로공사에게 도로의 보존상하자로 인한 손해배상책임을 인정하기 위하여는 도로에 타이어가 떨어져 있어 고속으로 주행하는 차량의 통행에 안전상의 결함이 있다는 것만으로 족하지 않고, 위 공사의 고속도로 안전성에 대한 순찰 등 감시체제, 타이어의 낙하시점, 위 공사가 타이어의 낙하사실을 신고받거나 직접 이를 발견하여 그로 인한 고속도로상의 안전성 결함을 알았음에도 사고방지조치를 취하지 아니하고 방치하였는지 여부, 혹은 이를 발견할 수 있었음에도 발견하지 못하였는지 여부 등 제반 사정을 심리하여 고속도로의 하자 유무를 판단하였어야 함에도 이에 이르지 않은 채 위 공사의 손해배상책임을 인정한 원심판결을 파기한 사례.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-214","continued":false,"pageStart":131,"pageEnd":131,"anchor":"source-131-7"},{"type":"p","text":"v 대법원 1993. 6. 29. 선고 93다11913 판결 : 가. 전력수급계약 해제 이후에도 전선을 절단하는 등의 방법으로 단전조치를 위하지 않은 한전에 과실이 있다 할지라도 높이 8m의 고압전선에 앉은 새를 잡으려고 철근으로 맞추려다 감전당한 피해자의 손해와의 사이에 상당인과 관계가 없다 한 사례.","emphasis":[],"underline":[[100,138],[139,164]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-215","continued":false,"pageStart":131,"pageEnd":131,"anchor":"source-131-8"},{"type":"p","text":"나. 민법 제758조에서 말하는 공작물이라 함은 인공적 작업에 의하여 제작된 물건을 말하는 것으로서 전기 그 자체는 여기에서 말하는 공작물에 해당되지 않는다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-215","continued":false,"pageStart":131,"pageEnd":131,"anchor":"source-131-9"},{"type":"p","text":"v 대법원 2019. 11. 28. 선고 2017다14895 판결: 제758조 제1항은 “공작물의 설치 또는 보존상의 하자로 인하여 타인에게 손해를 가한 때에는 공작물점유자가 손해를 배상할 책임이 있다. 그러나 점유자가 손해의 방지에 필요한 주의를 해태하지 아니한 때에는 그 소유자가 손해를 배상할 책임이 있다.”라고 규정하고 있다. 위 규정의 입법 취지는 공작물의 관리자는 위험의 방지에 필요한 주의를 다하여야 하고, 만일에 위험이 현실화하여 손해가 발생한 경우에는 그들에게 배상책임을 부담시키는 것이 공평하다는 데 있다. 따라서 ‘공작물의 설치·보존상의 하자’란 공작물이 그 용도에 따라 통상 갖추어야 할 안전성을 갖추지 못한 상태에 있음을 말하고, 위와 같은 안전성의 구비 여부를 판단할 때에는 공작물을 설치·보존하는 자가 그 공작물의 위험성에 비례하여 사회통념상 일반적으로 요구되는 정도로 위험방지조치를 다하였는지 여부를 기준으로 판단하여야 한다. 하자의 존재에 관한 증명책임은 피해자에게 있으나, 일단 하자가 있음이 인정되고 그 하자가 사고의 공동원인이 되는 이상, 그 사고가 위와 같은 하자가 없었더라도 불가피한 것이었다는 점이 공작물의 소유자나 점유자에 의하여 증명되지 않는다면 그 손해는 공작물의 설치 또는 보존의 하자에 의하여 발생한 것으로 해석함이 타당하다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-216","continued":false,"pageStart":131,"pageEnd":131,"anchor":"source-131-10"},{"type":"p","text":"이 경우 하자 여부를 판단할 때에는 위험의 현실화 가능성의 정도, 위험이 현실화하여 사고가 발생하였을 때 침해되는 법익의 중대성과 피해의 정도, 사고 방지를 위한 사전조치에 드는 비용이나 위험방지조치를 함으로써 희생되는 이익 등을 종합적으로 고려하여야 한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-216","continued":true,"pageStart":132,"pageEnd":132,"anchor":"source-132-0"},{"type":"h3","text":"(3) 면책사유의 부존재","emphasis":[[0,13]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":132,"pageEnd":132,"anchor":"source-132-1"},{"type":"p","text":"점유자에 대해서는 면책사유를 인정하고 있으나 소유자에게는 면책사유를 인정하고 있지 않다. 점유자는 손해의 방지에 필요한 주의를 해태하지 않았다면 그 손해를 배상할 책임이 없다(손해방지의무 위반의 관점).","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":132,"pageEnd":132,"anchor":"source-132-2"},{"type":"h3","text":"(4) 기타 면책 가능성 : 무단침입자에 대한 책임","emphasis":[[0,28]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":132,"pageEnd":132,"anchor":"source-132-3"},{"type":"p","text":"목적물에 하자가 있으나 무단침입자에게 손해가 발생한 경우, 무단침입자에게 공작물의 소유자가 책임을 져야 하는지 의문이 제기되고 있다. 위법하게 타인의 위험영역에 침입한 자에게는 위험책임을 부담하지 않는다는 것이 학설의 일반적인 견해이다. 예컨대, 도둑이 타인의 주거에 침입하여 미끄러운 계단에서 추락한 경우, 엔진 결함이 있는 자동차를 훔친 도둑이 달아나다가 사고가 난 경우가 이에 해당한다. 판례 역시 책임을 부정하고 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":132,"pageEnd":132,"anchor":"source-132-4"},{"type":"p","text":"v 대법원 1977. 11. 8. 선고 77다1486 판결 : 일반인의 무단출입이 금지되어 있는 철도역 구내의 횡단로는 일반 통행인을 위한 소위 건널목이라고 볼 수는 없으므로 함부로 내왕하던 주민에게 사고가 발생한 경우 건널목의 설치와 보존의 하자책임을 물을 수 없다.","emphasis":[],"underline":[[40,65],[98,135],[136,149]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-217","continued":false,"pageStart":132,"pageEnd":132,"anchor":"source-132-5"},{"type":"p","text":"v 대법원 1992. 4. 24. 선고 91다37652 판결 : [1] 공작물의 설치보존상의 하자라 함은 공작물이 그 용도에 따라 통상 갖추어야 할 안전성을 갖추지 못한 상태에 있음을 말하는 것이고, 공작물의 설치 및 보존에 있어서 항상 완전무결한 상태를 유지할 정도의 고도의 안전성을 갖추지 아니하였다 하여 그 공작물의 설치보존에 하자가 있는 것이라고는 할 수 없으므로, 공작물의 설치보존자에게 부과되는 방호조치의무의 정도는 그 공작물의 위험성에 비례하여 사회통념상 일반적으로 요구되는 정도의 것을 말한다.","emphasis":[],"underline":[[209,261],[262,283]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-218","continued":false,"pageStart":132,"pageEnd":132,"anchor":"source-132-6"},{"type":"p","text":"나. 대학 5층 건물 옥상에서 그 대학 학생이 후배들에게 얼굴을 하늘로 향하게 하여 바닥에 눕게 한 다음, 구령에 맞추어 몸통을 좌우로 뒹굴게 하는 방법으로 기합을 주던 중, 그중 1인이 몸을 구르다가 약 15미터 아래로 떨어져 사망한 경우 위 옥상은 그 설치용도와 관계 있는 사람 이외에는 올라가지 않는 곳이고, 위 망인을 비롯한 학생들도 평소 그와 같은 사정을 잘 알고 있었다고 할 것이며, 나아가 위험성에 대한 지각능력이 있는 학생들이 출입이 제한되어 있는 그 옥상에서 추락 등의 사고를 일으킬 수 있는 행위를 하리라고 기대하기는 어려우므로, 학교측에게 그러한 사고가 있을 것까지 예상하여 항상 그 곳에 관리인을 두어서 출입을 통제한다거나 추락을 방지하기 위하여 난간을 설치하는 등의 조치를 취할 것까지 요구할 수는 없고 따라서 위 건물의 설치보존상의 하자가 인정되지 않는다고 한 사례.","emphasis":[],"underline":[[135,174]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-218","continued":false,"pageStart":132,"pageEnd":132,"anchor":"source-132-7"},{"type":"p","text":"v 대법원 1981. 6. 23. 선고 80다2993 판결 : 사실관계가 그렇다면 비록 위 표시판은 그 자체가 아이들의 놀이에 제공되는 것은 아니라 할지라도 그 판시와 같은 사정 아래에서는 아이들이 올라타고 놀면서 충격을 주는 것이 예상되는 이상 이에 따르는 상당한 관리를 하여야 할 터인데 피고는 위 표시판이 갖추어야 할 안전성을 유지 관리하지 못하였다 할 것이니 이와 같은 취지에서 원심이 공작물인 위 표시판의 관리소홀로 인해서 발생한 손해에 대하여 피고에게 소유자 겸 점유자로서의 배상책임을 인정한 조처는 정당하고, 원심판결에 소론과 같이 공작물의 하자에 관한 법리를 오해한 위법이 있다 할 수 없고...","emphasis":[],"underline":[[49,75],[76,87]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-219","continued":false,"pageStart":132,"pageEnd":132,"anchor":"source-132-8"},{"type":"h3","text":"4. 공작물책임의 효과","emphasis":[[0,12]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":132,"pageEnd":132,"anchor":"source-132-9"},{"type":"p","text":"공작물책임의 1차적 책임자는 공작물의 점유자이고 2차적 책임자는 소유자이다. 이러한 책임자의 순위와 지위차이는 다음과 같은 이유에 근거한다. 공작물에 대하여 가장 밀접한 지위에 있는 자에게 먼저 책임을 부담시키고, 위험한 설비를 이용하는 자보다 소유한 자에게 최종적으로 책임을 귀속시키는 것이 타당하기 때문이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":132,"pageEnd":132,"anchor":"source-132-10"},{"type":"h3","text":"1) 공작물 점유자","emphasis":[[0,10]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":132,"pageEnd":132,"anchor":"source-132-11"},{"type":"p","text":"공작물의 점유자는 공작물을 사실상 지배하여 설치 또는 보존상의 하자로 발생할 사고를 방지하기 위하여 공작물을 보수·관리할 권한과 책임이 있는 자를 의미한다. 따라서 간접점유자가 있는 경우 직접점유자가 책임을 지게 되고, 그 후에 간접점유자가 책임을 진다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":132,"pageEnd":133,"anchor":"source-132-12"},{"type":"p","text":"v 대법원 2000. 4. 21. 선고 2000다386 판결 : [1] 민법 제758조 제1항 소정의 공작물점유자라 함은 공작물을 사실상 지배하면서 그 설치 또는 보존상의 하자로 인하여 발생할 수 있는 각종 사고를 방지하기 위하여 공작물을 보수․관리할 권한 및 책임이 있는 자를 말한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-220","continued":false,"pageStart":133,"pageEnd":133,"anchor":"source-133-1"},{"type":"p","text":"[2] 공장근저당권자가 공장의 부도로 대표이사 등이 도피한 상태에서 담보물의 가치를 보전하기 위하여 경비용역업체를 통하여 공장을 경비한 사실만으로 민법 제758조 제1항 소정의 공작물점유자에 해당한다고 볼 수 없다고 한 사례.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-220","continued":false,"pageStart":133,"pageEnd":133,"anchor":"source-133-2"},{"type":"p","text":"v 대법원 2003. 2. 28. 선고 2002다65516 판결 : 건물 일부의 임차인이 건물 외벽에 설치한 간판이 추락하여 행인이 부상한 경우 건물소유자는 건물 외벽의 직접점유자로서 민법 제758조 제1항 소정의 손해배상책임을 부담한다고 판단한 사례.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-221","continued":false,"pageStart":133,"pageEnd":133,"anchor":"source-133-3"},{"type":"p","text":"v 대법원 1994. 7. 29. 선고 93다32453 판결 : 나. ... 구 액화석유가스의안전및사업관리법 제29조 소정의 액화 석유가스 (L.P.G) 사용신고자는 일반수요자와는 달리 다른 특별한 사정이 없는 한 액화석유가스의 사용시설을 사실상 지배하고 점유. 관리하는 자라 할 것이므로 그 사용시설에 대한 민법 제758조 소정의 점유자로 보아야 할 것이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-222","continued":false,"pageStart":133,"pageEnd":133,"anchor":"source-133-4"},{"type":"p","text":"v 대법원 1994. 6. 28. 선고 94다2787 판결 : 가. 계량기에 대하여 가스 사용자의 점유를 전혀 부정할 수는 없다고 하더라도, 가스 공급업자도 또한 가스 사용자와 함께 계량기에 대하여 직접 지배하면서 이를 점유 관리하고 있었다 할 것이고, 오히려 계량기의 보수, 관리에 관련하는 한에 있어서는 가스 사용자보다도 가스 공급업자가 보다 직접적, 구체적인 지배를 하였다고 할 것이므로, 가스 공급업자는 민법 제758조 제1항 소정의 점유자에 해당한다고 할 것이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-223","continued":false,"pageStart":133,"pageEnd":133,"anchor":"source-133-5"},{"type":"p","text":"점유자는 손해의 방지에 필요한 주의를 해태하지 아니한 때에는 책임을 지지 않는다. 상당한 주의를 하였더라도 손해가 생겼으리라고 생각되는 경우 점유자는 면책되는 것으로 해석하는 것이 보통이다(제756조 제1항 단서 유추). 주의의무 위반과 손해 사이의 인과관계를 인정하기 어렵기 때문이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":133,"pageEnd":133,"anchor":"source-133-6"},{"type":"p","text":"v 대법원 2024. 2. 15. 선고 2019다208724 판결: 물건에 대한 점유란 사회관념상 어떤 사람의 사실적 지배에 있다고 보이는 객관적 관계를 말하는 것으로서, 사실상의 지배가 있다고 하기 위하여는 반드시 물건을 물리적, 현실적으로 지배하여야만 하는 것이 아니고, 물건과 사람 사이의 시간적, 공간적 관계와 본권관계, 타인지배의 배제 가능성 등을 고려하여 사회통념에 따라 합목적적으로 판단하여야 한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-224","continued":false,"pageStart":133,"pageEnd":133,"anchor":"source-133-7"},{"type":"p","text":"민법 제758조 제1항 소정의 공작물 점유자란 공작물을 사실상 지배하면서 그 설치 또는 보존상의 하자로 인하여 발생할 수 있는 각종 사고를 방지하기 위하여 공작물을 보수? 관리할 권한 및 책임이 있는 자를 말한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-224","continued":false,"pageStart":133,"pageEnd":133,"anchor":"source-133-8"},{"type":"p","text":"가사상, 영업상 기타 유사한 관계에 의하여 타인의 지시를 받아서 공작물에 대한 사실상의 지배를 하는 자가 있는 경우에 그 타인의 지시를 받는 자는 민법 제195조에 따른 점유보조자에 불과하므로 민법 제758조 제1항에 의한 공작물 점유자의 책임을 부담하는 자에 해당하지 않는다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-224","continued":false,"pageStart":133,"pageEnd":133,"anchor":"source-133-9"},{"type":"h3","text":"2) 공작물소유자의 책임","emphasis":[[0,13]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":133,"pageEnd":133,"anchor":"source-133-10"},{"type":"p","text":"점유자가 피해자인 경우나, 점유자가 손해방지에 필요한 주의를 해태하지 아니한 경우 소유자가 손해배상책임을 진다(제758조 제1항 제2문). 면책이 인정되지 않는 무과실책임에 해당한다. 그러나 구상권이 인정된다는 점에서 특색이 있다(제758조 제3항).","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":133,"pageEnd":133,"anchor":"source-133-11"},{"type":"p","text":"v 대법원 1993. 2. 9. 선고 92다31668 판결 : 가. 공작물의 설치 또는 보존의 하자로 인하여 타인에게 손해를 가한 때에는 1차적으로 공작물의 점유자가 손해를 배상할 책임이 있고 공작물의 소유자는 점유자가 손해의 방지에 필요한 주의를 해태하지 아니한 때에 비로소 2차적으로 손해를 배상할 책임이 있는 것이나, 공작물의 임차인인 직접점유자나 그와 같은 지위에 있는 것으로 볼 수 있는 자가 공작물의 설치 또는 보존의 하자로 인하여 피해를 입은 경우에는 그 가옥의 소유자는 민법 제758조 제1항 소정의 책임자로서 이에 대하여 손해를 배상할 책임이 있는 것이고 그 피해자에게 보존상의 과실이 있더라도 과실상계의 사유가 될 뿐이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-225","continued":false,"pageStart":133,"pageEnd":133,"anchor":"source-133-12"},{"type":"p","text":"나. 임차인과 함께 임차방실에 기거하던 직장동료가 연통에서 새어나온 연탄가스에 중독 사망한 사고에 대하여 가옥소유자의 손해배상책임을 인정한 사례.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-225","continued":false,"pageStart":133,"pageEnd":133,"anchor":"source-133-13"},{"type":"p","text":"v 대법원 1987. 4. 14. 선고 86다카1705 판결 : 가옥임대차에 있어서 임대인은 임차인으로 하여금 그 목적물을 사용․수익하게 할 의무가 있고 그 의무내용에는 목적물의 수선의무도 포함되는 것인바, 가옥임차인이 건물의 부엌벽의 균열을 발견하고 임대인에게 보수를 요구하고 임대인도 그 위험을 인식하여 곧 보수하여 주겠다고 약속하고서 그 이행을 지체하고 있던 중 위 벽이 무너짐으로 말미암아 인명사고 가 발생하였다면, 공작물의 직접 점유자인 위 임차인으로서는 손해의 방지에 필요한 주의를 해태하지 아니하였다고 볼 것이므로 결국 그 소유자인 임대인이 위 사고에 대한 손해배상책임을 질 수밖에 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-226","continued":false,"pageStart":133,"pageEnd":133,"anchor":"source-133-14"},{"type":"h3","text":"3) 점유자 및 소유자의 구상권","emphasis":[[0,17]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":133,"pageEnd":133,"anchor":"source-133-15"},{"type":"p","text":"점유자 또는 소유자로서 책임을 지고 피해자에게 배상을 한 자는 그 손해의 원인에 대하여 책임이 있는 자에게 구상할 수 있다. 예를 들면, 공작물을 만든 수급인이나 공작물의 前소유자 또는 前점유자 등이 이에 해당한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":133,"pageEnd":134,"anchor":"source-133-16"},{"type":"h3","text":"4) 수목에 관한 책임","emphasis":[[0,12]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":134,"pageEnd":134,"anchor":"source-134-1"},{"type":"p","text":"수목 식재나 보존상 하자가 있는 경우에도 점유자 또는 소유자는 공작물책임이 있다(제758조 제2항). 이 경우 구상권에 관하여도 공작물책임의 경우와 같다(제758조 제3항).","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":134,"pageEnd":134,"anchor":"source-134-2"},{"type":"h3","text":"Ⅴ. 동물의 점유자의 책임","emphasis":[[0,14]],"underline":[],"highlight":[],"strike":[],"headingLevel":3,"pageStart":134,"pageEnd":134,"anchor":"source-134-3"},{"type":"p","text":"제759조【동물의 점유자의 책임】 ① 동물의 점유자는 그 동물이 타인에게 가한 손해를 배상할 책임이 있다. 그러나 동물의 종류와 성질에 따라 그 보관에 상당한 주의를 해태하지 아니한 때에는 그러하지 아니하다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"statute","group":"민법4_강의자료(불법행위)-227","continued":false,"pageStart":134,"pageEnd":134,"anchor":"source-134-4"},{"type":"p","text":"② 점유자에 갈음하여 동물을 보관한 자도 전항의 책임이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"statute","group":"민법4_강의자료(불법행위)-227","continued":false,"pageStart":134,"pageEnd":134,"anchor":"source-134-5"},{"type":"h3","text":"1. 책임의 성질","emphasis":[[0,9]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":134,"pageEnd":134,"anchor":"source-134-6"},{"type":"p","text":"민법 제759조는 동물이 타인에게 손해를 준 경우 점유자 또는 보관자가 원칙적으로 배상책임을 지도록 하고 있다(제1항 제1문). 다만, 상당한 주의를 게을리하지 않은 경우 면책을 인정하고 있다(제1항 제2문). 민법 제759조의 동물점유자책임 역시 과실의 입증책임을 전환한 중간책임(추정과실책임)에 해당한다. 동물점유자책임 역시 위험책임의 법리에서 출발하고 있다. 점유자에 갈음하여 동물을 보관하는 자도 동일한 책임을 진다(제759조 제2항).","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":134,"pageEnd":134,"anchor":"source-134-7"},{"type":"h3","text":"2. 책임의 요건","emphasis":[[0,9]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":134,"pageEnd":134,"anchor":"source-134-8"},{"type":"h3","text":"(1) 동물로 인한 손해","emphasis":[[0,13]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":134,"pageEnd":134,"anchor":"source-134-9"},{"type":"p","text":"동물이 손해를 야기해야 한다. 동물의 종류는 불문한다. 따라서 가축도 포함된다. 그러나 동물의 종류에 따라서 점유자에게 요구되는 주의의 정도가 달라진다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":134,"pageEnd":134,"anchor":"source-134-10"},{"type":"p","text":"v 대판 1981. 2. 10, 선고 80다2966 판결 : 도사견은 성질이 난폭하여 사람에게 피해를 입힐 위험이 크므로 그 소유자가 이를 타인에게 빌려주는 경우에는 그가 도사견을 안전하게 보관 관리할 수 있는 시설을 갖추고 있는지 여부를 확인하여야 할 주의의무가 있다. *동물의 간접점유자에 대한 책임을 인정한 사건","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-228","continued":false,"pageStart":134,"pageEnd":134,"anchor":"source-134-11"},{"type":"h3","text":"(2) 타인에게 손해를 야기할 것","emphasis":[[0,18]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":134,"pageEnd":134,"anchor":"source-134-12"},{"type":"p","text":"동물이 타인에게 가한 손해가 배상의 대상이 된다. 여기서 손해에는 인적 손해 외에도 물적 손해가 포함된다. 즉, 가축이 타인의 물건을 부서뜨린 경우도 그 손해를 배상해야 한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":134,"pageEnd":134,"anchor":"source-134-13"},{"type":"h3","text":"(3) 면책사유가 없을 것","emphasis":[[0,14]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":134,"pageEnd":134,"anchor":"source-134-14"},{"type":"p","text":"동물의 종류와 성질에 따라 그 보관에 상당한 주의를 해태하지 않은 경우 동물의 점유자 또는 보관자는 배상책임을 면한다(제759조 제1항 제2문). 상당한 주의를 한 경우에도 손해가 발생하였을 경우라면 면책된다고 할 수 있다(제756조 제1항 단서 유추). 주의의무 위반과 손해 간의 인과관계를 인정할 수 없기 때문이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":134,"pageEnd":134,"anchor":"source-134-15"},{"type":"h3","text":"3. 효과","emphasis":[[0,5]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":134,"pageEnd":134,"anchor":"source-134-16"},{"type":"p","text":"동물의 「점유자」와 「점유자에 갈음하여 동물을 보관한 자」는 손해배상책임을 진다. 여기서 점유자에 갈음하여 동물을 보관한 자는 동물의 직접점유자를 의미하고, 따라서 점유자에 갈음하여 동물을 보관한 자는 독립적인 동물의 점유자가 된다. 즉, 제759조 제2항의 규정은 주의적 규정에 불과하다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":134,"pageEnd":135,"anchor":"source-134-17"},{"type":"p","text":"제759조는 동물소유자의 책임을 언급하고 있지 않다. 즉, 동물소유자는 별도의 책임을 부담하지 않는다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":135,"pageEnd":135,"anchor":"source-135-1"},{"type":"p","text":"또한, 제759조는 구상권에 대하여 언급하고 있지 않다. 민법이 별도의 규정을 두고 있지 않으나, 계약책임의 일반이론에 따라서 당연히 인정된다. 예를 들어 점유보조자인 피용자의 과실로 사용자가 동물점유자로서의 책임을 부담한 경우 쇠사슬이나 동물우리의 하자로 동물점유자가 책임을 부담한 경우 사용자 또는 쇠사슬이나 동물우리의 매수인은 점유보조자인 피용자 또는 매도인에게 그 책임을 물을 수 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":135,"pageEnd":135,"anchor":"source-135-2"},{"type":"h3","text":"Ⅵ. 공동불법행위자의 책임","emphasis":[[0,14]],"underline":[],"highlight":[],"strike":[],"headingLevel":3,"pageStart":135,"pageEnd":135,"anchor":"source-135-3"},{"type":"h3","text":"1. 서설","emphasis":[[0,5]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":135,"pageEnd":135,"anchor":"source-135-4"},{"type":"p","text":"[사례] 친구 사이인 甲, 乙, 丙은 평소 자신들에게 고분고분하지 않다는 이유로 혼을 내주려고 같은 반 급우인 丁을 학교 근처 골목으로 데려갔다. 그곳에서 甲과 乙은 丁을 폭행하여 상해를 가하였고, 丙은 사람들이 오는지 망을 보았다. 이때 丁은 누구를 상대로 어떤 책임을 물을 수 있는가?","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-229","continued":false,"pageStart":135,"pageEnd":135,"anchor":"source-135-5"},{"type":"p","text":"《解說》 甲, 乙, 丙이 공동으로 丁에게 불법행위를 하였으므로 甲, 乙, 丙은 丁의 손해에 대하여 연대하여 책임을 부담한다. 그리고 甲, 乙, 丙 사이의 가해행위에 대한 공모가 있으므로, 어느 학설에 따르더라도 공동불법행위가 성립한다. 그리고 丙의 경우 실제 폭행에는 가담하지 않았으나 丁에 대한 폭행과 상해라는 공동의 행위를 수행한 것으로 판단되므로, 망을 본 것만으로도 행위관련공동성이 인정된다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-229","continued":false,"pageStart":135,"pageEnd":135,"anchor":"source-135-6"},{"type":"p","text":"제760조【공동불법행위자의 책임】 ① 수인이 공동의 불법행위로 타인에게 손해를 가한 때에는 연대하여 그 손해를 배상할 책임이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"statute","group":"민법4_강의자료(불법행위)-230","continued":false,"pageStart":135,"pageEnd":135,"anchor":"source-135-7"},{"type":"p","text":"② 공동 아닌 수인의 행위중 어느 자의 행위가 그 손해를 가한 것인지를 알 수 없는 때에도 전항과 같다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"statute","group":"민법4_강의자료(불법행위)-230","continued":false,"pageStart":135,"pageEnd":135,"anchor":"source-135-8"},{"type":"p","text":"③ 교사자나 방조자는 공동행위자로 본다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"statute","group":"민법4_강의자료(불법행위)-230","continued":false,"pageStart":135,"pageEnd":135,"anchor":"source-135-9"},{"type":"p","text":"여러 명이 가해행위를 하여 하나의 손해를 발생시키는 형태의 불법행위를 공동불법행위라고 한다. 우리 민법상 불법행위의 유형은 원칙적으로 한 명의 행위자가 하나의 손해를 일으키는 단독의 불법행위를 예정하고 있으며, 행위자가 여러 명인 공동불법행위는 제760조에서 예외로 규정하고 있다. 민법 제760조는 수인이 관여된 불법행위를 세 가지 유형으로 나누어 규정하고 있다. ㈀ 수인이 공동으로 불법행위를 한 경우(협의의 공동불법행위), ㈁ 공동 아닌 수인의 행위로 손해가 발생하였으나 그 손해를 가한 자를 알 수 없는 경우(가해자 불명의 공동불법행위), ㈂ 교사자 또는 방조자의 경우(교사 또는 방조에 의한 공동불법행위)로 나누고 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":135,"pageEnd":135,"anchor":"source-135-10"},{"type":"h3","text":"2. 공동불법행위의 유형별 요건","emphasis":[[0,17]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":135,"pageEnd":135,"anchor":"source-135-11"},{"type":"h3","text":"(1) 협의의 공동불법행위","emphasis":[[0,14]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":135,"pageEnd":135,"anchor":"source-135-12"},{"type":"p","text":"[사례] 甲과 乙은 丁 소유의 부동산에 근저당을 설정하여 금원을 대출받기로 공모한 뒤, 근저당권설정을 위한 인감증명서를 발급받기 위해서 丁의 주민등록표를 위조하여 관할 동사무소에 제출하였다. 그런데 동사무소 인감발급 담당직원인 丙은 甲․乙이 제출한 주민등록표가 그 작성일자나 날인된 인장들이 적합한 것이 아니어서 정상적으로 작성된 것으로 보기 어려운 사정이 있음에도 불구하고 이를 간과하고 인감을 발급해주었다. 발급받은 인감을 이용하여 甲․乙은 丁 소유의 부동산에 戊명의의 채권최고액 1억 5천만 원의 근저당권을 설정하였다. 이후 이 사실을 알게 된 丁은 위 부동산에 대한 근저당권설정등기의 말소등기소송에서 승소하였다. 이때 戊는 누구를 상대로 어떤 청구를 할 수 있는가?","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-231","continued":false,"pageStart":135,"pageEnd":136,"anchor":"source-135-13"},{"type":"p","text":"<解說> 피해자 戊는 자신의 손해에 대하여 행위관련공동성이 있는 자에 대하여 공동불법행위책임을 물을 수 있는데, 사안에서 戊의 손해와 甲․乙․丙 간에 행위관련공동성이 인정되므로 공동불법행위가 성립한다(대판 1991. 11. 22., 91다26980)","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-231","continued":true,"pageStart":136,"pageEnd":136,"anchor":"source-136-1"},{"type":"p","text":"협의의 공동불법행위는 수인이 공동으로 불법행위를 한 경우를 의미한다. 이를 위해서는 ① 가해자 각자가 독립하여 일반불법행위의 요건(제750조)을 갖추어야 하며, ② 그 행위에 공동성이 인정되어야 한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":136,"pageEnd":136,"anchor":"source-136-2"},{"type":"p","text":"일반불법행위의 요건과 관련하여 우선 인과관계가 문제 된다. 공동불법행위자들의 각각의 가해행위와 손해 간의 인과관계가 존재하여야 하는지, 아니면 공동의 행위와 손해 간의 인과관계가 존재하는 것만으로 충분한지에 대해서 견해대립이 있다. 공동불법행위의 경우 자신의 행위와 인과관계가 없는 손해에 대해서도 손해배상책임을 진다는 점에서 자기책임의 원칙에 대한 예외라고 할 수 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":136,"pageEnd":136,"anchor":"source-136-3"},{"type":"p","text":"수인이 “共同”으로 가해행위를 하여야 협의의 공동불법행위가 성립한다(제760조 제1항). 따라서 공동불법행위자 간에 행위의 공동성이 존재하지 않는 경우라면 제760조 제2항에 따른 가해자불명의 공동불법행위가 되거나, 여러 명의 불법행위자는 각각 일반불법행위책임(제750조)을 질 뿐이다. 행위의 공동성에 대해서는 수인이 공모의 합의 또는 의사의 공통이 있어야 한다는 주관적 공동설도 있지만, 이러한 공동의 모의나 인식은 필요 없으며 객관적으로 보아 피해자에 대한 권리침해가 공동으로 이루어졌고 그 행위가 손해발생에 대해 공통의 원인이 되었다고 인정되는 경우라면 충분하다는 객관적 공동설이 통설·판례의 태도이다. 이에 따르면 과실에 의한 공동불법행위도 성립할 수 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":136,"pageEnd":136,"anchor":"source-136-4"},{"type":"p","text":"F 主觀的 共同說 : 공동의 의미에 대해서는 가해자 간의 공모나 공동의 인식과 같은 의사의 공동성이 존재하여야 한다는 견해.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"comment","group":"민법4_강의자료(불법행위)-232","continued":false,"pageStart":136,"pageEnd":136,"anchor":"source-136-5"},{"type":"p","text":"客觀的 共同說 : 가해자 간의 주관적 공동성은 필요 없고 가해자의 각 행위 간의 관련공동성만 있으면 공동불법행위가 성립한다는 견해로서 通說․判例의 입장이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"comment","group":"민법4_강의자료(불법행위)-232","continued":false,"pageStart":136,"pageEnd":136,"anchor":"source-136-6"},{"type":"p","text":"v 대법원 1997. 8. 29. 선고 96다46903 판결: 공동불법행위의 성립에는 공동불법행위자 상호 간에 의사의 공통이나 공동의 인식이 필요하지 아니하고 객관적으로 각 행위에 관련공동성이 있으면 족하므로, 관련공동성 있는 행위에 의하여 손해가 발생하였다면 그 손해배상책임을 면할 수 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-233","continued":false,"pageStart":136,"pageEnd":136,"anchor":"source-136-7"},{"type":"p","text":"v 대법원 1998. 11. 24. 선고 98다32045 판결: 교통사고로 인하여 상해를 입은 피해자가 치료를 받던 중 치료를 하던 의사의 과실로 인한 의료사고로 증상이 악화되거나 새로운 증상이 생겨 손해가 확대된 경우, 의사에게 중대한 과실이 있다는 등의 특별한 사정이 없는 한 확대된 손해와 교통사고 사이에도 상당인과관계가 있고, 이 경우 교통사고와 의료사고가 각기 독립하여 불법행위의 요건을 갖추고 있으면서 객관적으로 관련되고 공동하여 위법하게 피해자에게 손해를 가한 것으로 인정되면 공동불법행위가 성립한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-234","continued":false,"pageStart":136,"pageEnd":136,"anchor":"source-136-8"},{"type":"p","text":"v 대법원 1968. 2. 27. 선고 67다1975 판결 : 피고들이 모두 공작물의 설치보존에 하자있음을 이유로 본조에 의하여 손해배상책임이 있다면 그들의 각 불법행위는 그들 간에 주관적 공동관계가 없어도 객관적인 공동관계가 있으므로 민법 제760조 소정 공동불법행위자로서 손해를 배상할 책임이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-235","continued":false,"pageStart":136,"pageEnd":136,"anchor":"source-136-9"},{"type":"p","text":"v 대법원 1994. 11. 25. 선고, 94다35671, 판결 : 교통사고로 인하여 상해를 입은 피해자가 치료를 받던 중 의사의 과실 등으로 인한 의료사고로 증상이 악화되거나 새로운 증상이 생겨 사망에 이르는 등 손해가 확대된 경우, 특별한 사정이 없는 한 그와 같은 손해와 교통사고 사이에도 상당인과관계가 있다고 보아야 하므로, 교통사고와 의료사고가 각기 독립하여 불법행위의 요건을 갖추고 있으면서 객관적으로 관련되고 공동하여 위법하게 피해자에게 손해를 가한 것으로 인정된다면 공동불법행위가 성립되므로 이들은 연대하여 손해를 배상할 책임이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-236","continued":false,"pageStart":136,"pageEnd":136,"anchor":"source-136-10"},{"type":"p","text":"v 대법원 1997. 11. 28. 선고, 97다18448 : <사실관계> 甲은 부산시 소재 노래연습장에서 동네 선배인 丙이 술에 취해 성명불상의 손님과 말다툼을 하고는 것을 보고 이를 말리다가 丙과 시비가 되어 서로 상대방의 뺨을 수회씩 때리기에 이르렀는데, 이때 乙이 가세하여 발과 주먹으로 丙의 얼굴과 가슴 다리 등을 수회 구타하여 丙은 오른쪽 눈에 상해를 입혀 실명에 이르게 되었다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-237","continued":false,"pageStart":136,"pageEnd":136,"anchor":"source-136-11"},{"type":"p","text":"[판결요지] 공동불법행위의 성립에는 공동불법행위자 상호 간에 의사의 공통이나 공동의 인식이 필요하지 아니하고 객관적으로 각 그 행위에 관련공동성이 있으면 족하고 그 관련공동성 있는 행위에 의하여 손해가 발생하였다면 그 손해배상책임을 면할 수 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-237","continued":false,"pageStart":136,"pageEnd":136,"anchor":"source-136-12"},{"type":"p","text":"v 대법원 1993. 1. 26. 선고, 92다4871 판결 : <사실관계> 차량운전자 甲은 과실로 보행자 丙을 치어 좌측대퇴골 분쇄골절 등의 상해를 입혔다. 이에 丙은 乙이 운영하던 정형외과에 입원하여 치료를 받던 중, 乙의 무리한 물리치료시술로 인하여 좌측대퇴골이 소실이 되는 등 증세가 악화되었다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-238","continued":false,"pageStart":136,"pageEnd":137,"anchor":"source-136-13"},{"type":"p","text":"<판결요지> 교통사고로 인하여 상해를 입은 피해자가 치료를 받던 중 의사의 과실 등으로 인한 의료사고로 증상이 악화되거나 새로운 증상이 생겨 손해가 확대된 경우 특별한 다른 사정이 없는 한 그와 같은 손해와 교통사고 사이에도 상당인과관계가 있다고 보아야 하므로, 교통사고와 의료사고가 각기 독립하여 불법행위의 요건을 갖추고 있으면서 객관적으로 관련되고 공동하여 위법하게 피해자에게 손해를 가한 것으로 인정된다면, 공동불법행위가 성립되어 공동불법행위자들이 연대하여 손해를 배상할 책임이 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-238","continued":true,"pageStart":137,"pageEnd":137,"anchor":"source-137-1"},{"type":"p","text":"그러나 행위와 결과를 각각 구분할 수 있는 경우에는 공동불법행위가 성립하지 않는다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":137,"pageEnd":137,"anchor":"source-137-2"},{"type":"p","text":"v 대법원 1989. 5. 23. 선고 87다카2723 판결 : 공동불법행위가 성립하려면 행위자 사이에 의사의 공통이나 행위공동의 인식이 필요한 것은 아니지만 객관적으로 보아 피해자에 대한 권리침해가 공동으로 행하여졌다고 보여지고 그 행위가 손해발생에 대하여 공통의 원인이 되었다고 인정되는 경우라야 할 것인바, 이 사건에서 피고 일신중기주식 회사 운전수의 불법행위는 1984. 8. 8. 11:30에 피해자를 차로 치어 그 결과 뇌좌상중등중, 뇌기절부골절우칙, 두피하혈종 등의 상해가 발생한 것이며 피고 대한민국 산하 전남의대부속병원의 시설하자 및 그 직원의 불법행위는 1984. 9. 10에 발생하여 환자가 비상계단에서 추락한 결과를 발생케 한 것이므로 양 행위가 시간과 장소에 괴리가 있고 결과 발생에 있어서도 양 행위가 경합하여 단일한 결과를 발생시킨 것이 아니고 각 행위의 결과 발생을 구별할 수 있으므로 그러한 경우에는 공동불법행위가 성립한다고 하기 어렵다. 원심으로서는 피해자의 추락사를 개의치 아니하고 동인이 교통사고로 부상한 결과 입게 된 손해를 심리하여 그 배상을 명하여야 할 것이고 피고 대한민국의 배상책임을 정함에 있어서는 피해자가 병원에서 추락하므로 인하여 발생된 손해를 산정(이때에 교통사고로 인한 손해액과 중첩되지 아니하도록 유의하여야 할 것이다)하여 각기 그 배상을 명하여야 할 것이고 전손해액에 대하여 연대배상을 명한 것은 잘못이라 할 것이다.","emphasis":[],"underline":[[89,134],[135,173],[432,455]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-239","continued":false,"pageStart":137,"pageEnd":137,"anchor":"source-137-3"},{"type":"p","text":"v 대법원 1998. 2. 13선고 96다7854 판결 : [1] 수인이 공동하여 타인에게 손해를 가하는 민법 제760조 제1항의 공동불법행위가 성립하려면 각 행위가 독립하여 불법행위의 요건을 갖추고 있으면서 객관적으로 관련되고 공동하여 위법하게 피해자에게 손해를 가한 것으로 인정되어야 한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-240","continued":false,"pageStart":137,"pageEnd":137,"anchor":"source-137-4"},{"type":"p","text":"[2] 에이즈 바이러스에 감염된 혈액을 환자가 수혈받음으로써 에이즈에 감염될 위험을 배제할 의무 및 그와 같은 결과를 회피할 의무를 다하지 아니하여 감염된 혈액을 수혈받은 환자로 하여금 에이즈 바이러스 감염이라는 치명적인 건강 침해를 입게 한 대한적십자사의 과실 및 위법행위는 신체상해 자체에 대한 것인 데 비하여, 수혈로 인한 에이즈 바이러스 감염 위험 등의 설명의무를 다하지 아니한 의사들의 과실 및 위법행위는 신체상해의 결과 발생 여부를 묻지 아니하는 수혈 여부와 수혈 혈액에 대한 환자의 자기결정권이라는 인격권의 침해에 대한 것이므로, 대한적십자사와 의사의 양 행위가 경합하여 단일한 결과를 발생시킨 것이 아니고 각 행위의 결과 발생을 구별할 수 있으니, 이와 같은 경우에는 공동불법행위가 성립한다고 할 수 없다.","emphasis":[],"underline":[[304,317],[318,369]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-240","continued":false,"pageStart":137,"pageEnd":137,"anchor":"source-137-5"},{"type":"h3","text":"(2) 가해자 불명의 공동불법행위","emphasis":[[0,18]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":137,"pageEnd":137,"anchor":"source-137-6"},{"type":"p","text":"공동 아닌 수인의 행위 중 누구의 행위가 그 손해를 가한 것인지 알 수 없는 경우에도 공동불법행위책임이 발생한다. 시간적, 공간적 관련 및 행위의 동질성이 없어도 인정된다. 가령 두 사람이 각각 창문에 돌을 던졌는데 누구의 돌 때문에 창문이 깨졌는지는 알 수 없는 경우, 하나의 돌에 의해 창문이 깨졌음이 분명하다면 두 사람 모두의 공동불법행위책임이 성립한다. 실제로 책임이 있는 자 외의 자의 행위는 결과와 인과관계가 없지만, 인과관계를 추정하여 이에 관한 증명부담을 전환하고 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":137,"pageEnd":137,"anchor":"source-137-7"},{"type":"p","text":"이처럼 가해자불명의 경우를 공동불법행위로 보는 것은 무엇보다도 여러 사람의 행위가 경합하여 손해가 발생하였으나 공동불법행위로 보기 어려운 경우에 인과관계의 증명책임을 덜어 줌으로써 피해자를 보호하려는 데 그 취지가 있다. 다만, 이 경우 가해자 중의 1인은 자신의 행위와 손해 간에 인과관계가 없다는 사실을 증명하여 공동불법행위에 대한 책임을 지지 않을 수 있다는 점에서 다른 공동불법행위의 유형과 차이가 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":137,"pageEnd":137,"anchor":"source-137-8"},{"type":"p","text":"의료행위에 관여한 다수의 의사 중 누구의 과실에 의하여 의료사고가 발생한 것인지 분명하게 특정할 수 없는 경우 이들 모두에 대하여 공동불법행위책임을 물을 수 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":137,"pageEnd":137,"anchor":"source-137-9"},{"type":"p","text":"v 대법원 2005. 9. 30. 선고 2004다52576 판결 : 다수의 의사가 의료행위에 관여한 경우 그 중 누구의 과실에 의하여 의료사고가 발생한 것인지 분명하게 특정할 수 없는 때에는 일련의 의료행위에 관여한 의사들 모두에 대하여 민법 제760조 제2항에 따라 공동불법행위책임을 물을 수 있다고 봄이 상당하다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-241","continued":false,"pageStart":137,"pageEnd":137,"anchor":"source-137-10"},{"type":"p","text":"망인은 소외 회사 내 작업장에서 프레스 기계를 이용하여 작업을 하던 중 양손이 위 기계에 압착되어 좌, 우측 각 제1, 2 수지가 절단되는 사고를 당한 사실(이하 '1차 산재사고'라고 한다), 망인은 피고 1이 운영하는 병원으로 후송되어 피고 병원 소속 의사들인 피고 2, 3으로부터 수지절단 및 접합수술을 받은 사실, 피고 병원의 의료진은 수술을 전후하여 전신기능이 저하된 망인에게 적정수액량을 훨씬 초과하여 수액을 과다투여하였음에도 망인의 소변배출 여부와 소변량 등 환자의 동태를 제대로 살피지 아니하였고, 망인은 수술 이후 심장을 둘러싸고 있는 심낭에 400㏄ 가량의 삼출물이 차서 심장을 압박하는 바람에 심폐기능에 갑작스런 장애를 일으켜 심장 탐포나데로 사망에 이르게 된 사실(이하 '2차 의료사고'라고 한다), ... 이 사건 2차 의료사고는 전신기능이 저하된 망인에게 수액을 투여함에 있어 그 용량을 철저히 지키고 투여 후에도 망인의 소변배출 여부와 배출량 등을 제대로 관찰하며 신체상태를 세심하게 살펴보아 수액 투여로 인한 부작용의 기미가 보이면 즉시 이를 중단하거나 적절한 대응조치를 취하여야 할 주의의무가 있음에도, 이러한 조치를 제대로 취하지 아니한 채 수액을 계속 투여하고 망인의 신체상태를 제대로 살펴보지 아니한 피고 2, 3의 잘못으로 인하여 발생한 것으로 봄이 상당하다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-241","continued":false,"pageStart":137,"pageEnd":138,"anchor":"source-137-11"},{"type":"h3","text":"(3) 교사 또는 방조","emphasis":[[0,12]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":138,"pageEnd":138,"anchor":"source-138-1"},{"type":"p","text":"[사례] 상호신용금고업무를 총괄하던 부회장 甲, 상무 乙은 대출신청자의 명의를 차용․도용하여 실제 차주가 아닌 자 명의로 대출신청서나 어음할인신청서를 작성하는 방법으로 동일인여신한도초과금지 및 출자여신금지 규정을 위반하였을 뿐만 아니라 물적․인적 담보를 충분히 확보하지 않은 채 대출을 하여 채권회수를 곤란하게 함으로써 배임행위를 저질렀다. 이들의 배임행위를 알면서 위 상호신용금고가 속한 그룹회장 丙은 이를 방관하였다. 이때 丙은 위 상호신용금고에 대하여 어떤 책임을 지는가?","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-242","continued":false,"pageStart":138,"pageEnd":138,"anchor":"source-138-2"},{"type":"p","text":"<解說> 방조는 작위는 물론이고 부작위로도 가능하다. 따라서 사안에서 丙은 그룹회장으로서 甲․乙의 배임행위를 알고도 과실로 방조한 것으로 판단되므로, 상호신용금고에 대하여 甲․乙․丙은 공동불법행위책임을 진다(대판 2003. 1. 10, 2002다35850 참조).","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-242","continued":false,"pageStart":138,"pageEnd":138,"anchor":"source-138-3"},{"type":"p","text":"㈀ 불법행위에 대한 책임은 직접적인 가해행위를 한 행위자가 지는 것이 원칙이나 가해행위를 교사하거나 방조한 자도 제760조 제3항에 따라서 직접 행위자와 더불어 공동불법행위책임을 지게 된다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":138,"pageEnd":138,"anchor":"source-138-4"},{"type":"p","text":"㈁ 敎唆란 甲이 乙에게 일정한 금원을 지급하여 평소 원한관계에 있던 丙의 가게에 불을 놓게 하는 경우와 같이 타인으로 하여금 불법행위를 하도록 결의하게 하는 것을 말한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":138,"pageEnd":138,"anchor":"source-138-5"},{"type":"p","text":"㈂ 幇助란 불법행위를 용이하게 하는 직접․간접의 모든 행위를 가리키는 것으로서 고의나 과실로도 가능하며, 또한 작위에 의한 경우뿐만 아니라 작위의무가 있는 자가 그것을 방지하여야 할 제반조치를 하지 않는 부작위에 의해서도 가능하다. 예를 들어 건축업자 甲은 부실시공을 하고 감리자인 乙이 이를 묵과하였는데 건물이 붕괴되어 丙이 사망한 경우, 이때 甲과 이를 방조한 乙도 공동불법행위의 책임을 지게 된다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":138,"pageEnd":138,"anchor":"source-138-6"},{"type":"p","text":"㈃ 물론 교사자나 방조자가 공동불법행위책임을 지기 위해서는 교사·방조와 피교사자 또는 피방조자의 가해행위 간에 상당인과관계가 있어야 한다. 또한 교사·방조와 피해자의 손해 발생 사이에도 상당인과관계가 있어야 한다. 즉, 교사자나 방조자는 불법행위자의 손해를 함께 야기하였다는 점에서 배상책임이 인정된다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":138,"pageEnd":138,"anchor":"source-138-7"},{"type":"p","text":"v 대법원 2014. 3. 27. 선고 2013다91597 판결 : [1] 민법 제760조 제3항은 불법행위의 방조자를 공동행위자로 보아 방조자에게 공동불법행위의 책임을 부담시키고 있는바, 방조는 불법행위를 용이하게 하는 직접, 간접의 모든 행위를 가리키는 것으로서 작위에 의한 경우뿐만 아니라 작위의무 있는 사람이 그것을 방지하여야 할 제반 조치를 취하지 아니하는 부작위로 인하여 불법행위자의 실행행위를 용이하게 하는 경우도 포함하며, 손해의 전보를 목적으로 하여 과실을 원칙적으로 고의와 동일시하는 민사법의 영역에서는 과실에 의한 방조도 가능하다. 그런데 이 경우의 과실의 내용은 불법행위에 도움을 주지 말아야 할 주의의무가 있음을 전제로 하여 그 의무를 위반하는 것을 말하고, 방조자에게 공동불법행위자로서 책임을 지우기 위하여는 방조행위와 피해자의 손해 발생 사이에 상당인과관계가 있어야 한다. 그리고 상당인과관계가 있는지 여부는 과실에 의한 방조가 피해 발생에 끼친 영향, 피해자의 신뢰 형성에 기여한 정도, 피해자 스스로 쉽게 피해 방지를 할 수 있었는지 등을 종합적으로 고려하여 판단하여야 한다.","emphasis":[],"underline":[[319,332],[333,397],[398,446]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-243","continued":false,"pageStart":138,"pageEnd":138,"anchor":"source-138-8"},{"type":"p","text":"v 대법원 2014. 1. 29. 선고 2011다107627 판결 : 민법 제760조 제3항은 교사자나 방조자는 공동행위자로 본다고 규정하여 교사자나 방조자에게 공동불법행위자로서 책임을 부담시키고 있는바, 방조라 함은 불법행위를 용이하게 하는 직접, 간접의 모든 행위를 가리키는 것으로서 작위에 의한 경우뿐만 아니라 작위의무 있는 자가 그것을 방지하여야 할 제반 조치를 취하지 아니하는 부작위로 인하여 불법행위자의 실행행위를 용이하게 하는 경우도 포함하는 것이고, 이러한 불법행위의 방조는 형법과 달리 손해의 전보를 목적으로 하여 과실을 원칙적으로 고의와 동일시하는 민법의 해석으로서는 과실에 의한 방조도 가능하다고 할 것이며, 이 경우의 과실의 내용은 불법행위에 도움을 주지 않아야 할 주의의무가 있음을 전제로 하여 이 의무에 위반하는 것을 말하고, 방조자에게 공동불법행위자로서의 책임을 지우기 위하여는 방조행위와 피방조자의 불법행위 사이에 상당인과관계가 있어야 한다.","emphasis":[],"underline":[[115,139],[140,202],[203,256],[421,486]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-244","continued":false,"pageStart":138,"pageEnd":138,"anchor":"source-138-9"},{"type":"p","text":"v 대판 2001. 5. 8., 2001다2181 : [사실관계] 甲은 乙이 경영하는 회사의 경리직원으로 근무하면서 1년여에 걸쳐 44회에 걸쳐 회사공금 3억 원 가량을 횡령하는 불법행위를 저질렀는데, 甲과 사실혼관계에 있던 丙은 甲에게 회사의 월급 이외에 별다른 소득원이 없다는 사실을 알면서 장기간에 걸쳐 甲이 자신의 월급의 몇 배나 되는 금원을 매월 1회 내지 4회에 걸쳐 계속하여 송금한 금원을 수령하였으며, 사업자금 명목으로 甲에게 송금을 요구하기도 하였다. 그리고 丙은 甲이 이전에 근무하던 직장에서도 횡령으로 형사처벌을 받은 사실까지 알고 있었다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-245","continued":false,"pageStart":139,"pageEnd":139,"anchor":"source-139-0"},{"type":"p","text":"[판결요지] [1] 수인이 공동하여 타인에게 손해를 가하는 민법 제760조의 공동불법행위의 경우 행위자 상호 간의 공모는 물론 공동의 인식을 필요로 하지 아니하고, 다만 객관적으로 그 공동행위가 관련공동되어 있으면 족하고, 그 관련공동성 있는 행위에 의하여 손해가 발생함으로써 그에 대한 배상책임을 지는 공동불법행위가 성립하는 것이며, 공동불법행위에서 방조라 함은 불법행위를 용이하게 하는 직접·간접의 모든 행위를 가리키는 것이다.","emphasis":[],"underline":[[54,67],[68,123],[188,240]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-245","continued":false,"pageStart":139,"pageEnd":139,"anchor":"source-139-1"},{"type":"p","text":"[2] 회사직원의 공금횡령행위에 대하여 구체적인 공모를 하지는 않았지만 그가 정상적이 아닌 부정한 방법으로 금원을 마련하여 송금하는 사정을 미필적으로나마 인식하고 있으면서도 이를 계속하여 묵인한 채 송금을 받은 경우, 횡령행위에 대한 방조 또는 장물취득행위에 해당한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-245","continued":false,"pageStart":139,"pageEnd":139,"anchor":"source-139-2"},{"type":"p","text":"v 대법원 2010. 3. 11. 선고 2009다4343 판결 : [3] 인터넷 포털사이트를 운영하는 온라인서비스제공자가 제공한 인터넷 게시공간에 타인의 저작권을 침해하는 게시물이 게시되었고 그 검색 기능을 통하여 인터넷 이용자들이 위 게시물을 쉽게 찾을 수 있다 하더라도, 위와 같은 사정만으로 곧바로 위 서비스제공자에게 저작권 침해 게시물에 대한 불법행위책임을 지울 수는 없다. 다만 저작권 침해 게시물이 게시된 목적, 내용, 게시기간과 방법, 그로 인한 피해의 정도, 게시자와 피해자의 관계, 삭제 요구의 유무 등 게시에 관련한 쌍방의 대응태도, 관련 인터넷 기술의 발전 수준, 기술적 수단의 도입에 따른 경제적 비용 등에 비추어, 위 서비스제공자가 제공하는 인터넷 게시공간에 게시된 저작권 침해 게시물의 불법성이 명백하고, 위 서비스제공자가 위와 같은 게시물로 인하여 저작권을 침해당한 피해자로부터 구체적·개별적인 게시물의 삭제 및 차단 요구를 받은 경우는 물론, 피해자로부터 직접적인 요구를 받지 않은 경우라 하더라도 그 게시물이 게시된 사정을 구체적으로 인식하고 있었거나 그 게시물의 존재를 인식할 수 있었음이 외관상 명백히 드러나며, 또한 기술적, 경제적으로 그 게시물에 대한 관리·통제가 가능한 경우에는, 위 서비스제공자에게 그 게시물을 삭제하고 향후 같은 인터넷 게시공간에 유사한 내용의 게시물이 게시되지 않도록 차단하는 등의 적절한 조치를 취하여야 할 의무가 있으므로, 이를 위반하여 게시자의 저작권 침해를 용이하게 하는 경우에는 위 게시물을 직접 게시한 자의 행위에 대하여 부작위에 의한 방조자로서 공동불법행위책임이 성립한다.","emphasis":[],"underline":[[217,269],[270,334],[335,397],[398,459],[460,525],[526,588],[589,652],[653,714],[715,719]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-246","continued":false,"pageStart":139,"pageEnd":139,"anchor":"source-139-3"},{"type":"p","text":"v 전주지법 2012. 5. 23. 선고 2011나9771 판결 : 甲이 기존에 전혀 거래관계가 없던 성명불상자에게서 전화로 거액의 거래를 제안받은 후 乙 명의 은행계좌에 송금하였는데, 필리핀 여행가이드업자 乙은 여행객 丙에게서 이른바 환치기의 방법으로 원화를 필리핀 화폐로 바꿔달라는 부탁을 받고 국내에 있는 乙의 예금계좌를 알려준 다음 위와 같이 계좌에 입금된 것을 확인하고 丙에게 환전해 주었는데, 甲이 보이스피싱 사기에 의한 송금이었음을 이유로 乙을 상대로 불법행위에 기한 손해배상을 구한 사안에서, 乙이 성명불상자의 보이스피싱 범죄행위에 적극적으로 가담하지는 않았지만 위와 같은 환전행위가 외국환거래법상 금지되고, 乙이 신원을 잘 알지 못하는 자에게서 환전요청을 받아 환치기의 방법으로 환전해 주는 것이 국내의 범죄행위에 악용될 수도 있음을 예견할 수 있었을 것이라는 이유로, 적어도 과실로 성명불상자의 불법행위를 방조한 것이므로 공동불법행위자로서 甲에게 손해배상책임이 있다고 한 사례(다만 전화를 이용한 보이스피싱 피해가 사회적 문제로 부각되고 있는 상황에서 甲이 별다른 신원확인절차 없이 고액을 송금한 점 등 제반 사정에 비추어 乙의 책임을 전체 손해의 30%로 제한함)","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-246","continued":false,"pageStart":139,"pageEnd":139,"anchor":"source-139-4"},{"type":"h3","text":"3. 공동불법행위자의 책임","emphasis":[[0,14]],"underline":[],"highlight":[],"strike":[],"headingLevel":4,"pageStart":139,"pageEnd":139,"anchor":"source-139-5"},{"type":"p","text":"[사례] 아파트신축공사 감리자 甲은 어스앵커공법 시행으로 인하여 공사현장에 연접한 인근 기존아파트 옹벽에 위험이 생길 가능성을 예상하고도 토목전문건설회사 乙로 하여금 토목공사를 시공하도록 지시만 하였을 뿐 그 지시가 제대로 이행되는지를 확인하지 아니하고, 나아가 시공자 丙이 아무런 조치도 취하지 아니한 채 어스앵커공법을 시행하는 것을 방치하고 어스앵커 시공일 당일 인근 아파트 균열이 발생한 것을 확인하고도 공사중단명령을 내리지 아니하고 오히려 조속히 공사를 완료할 것을 지시하였다. 이후 공사현장의 인근 아파트 옹벽에 균열이 생겨 이에 아파트주민들이 甲․乙․丙에 대하여 공동불법행위책임을 묻자, 감리자인 甲은 다른 불법행위자인 乙․丙보다 불법행위에 기여한 정도가 경미하므로 자신의 손해배상의무가 제한되어야 한다고 주장한다. 이러한 甲의 주장은 타당한가? <解說> 아파트 옹벽의 균열로 인한 아파트주민들의 손해에 대하여 시공자인 丙은 물론이고, 수급인인 乙이 공동불법행위책임을 지는 것에는 의문이 없다. 다만 이때 감리자인 甲의 경우 손해에 대한 기여도가 작으므로 자신의 기여도만큼 손해배상의무가 제한될 수 있는지 문제가 되나, 판례는 공동불법행위제도의 취지를 고려하여 이를 부정한다(대판 2001. 9. 7, 99다70365).","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-247","continued":false,"pageStart":139,"pageEnd":139,"anchor":"source-139-6"},{"type":"p","text":"공동불법행위자는 연대해서 손해배상책임을 진다. 이때 ‘연대’의 의미에 대해서는 통설·판례가 부진정연대채무로 해석한다. 따라서 채무자 간에 주관적 공동관계가 없으므로 부담부분이 없고 원칙적으로 구상관계가 인정되지 않지만, 판례는 일관되게 공평한 손해분담을 실현하기 위하여 과실 비율에 따라 부담부분이 있는 것으로 보고 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":139,"pageEnd":140,"anchor":"source-139-7"},{"type":"p","text":"v 대법원 2006. 2. 9. 선고 2005다28426 판결 : 공동불법행위자는 채권자에 대한 관계에서는 부진정연대채무를 지되, 공동불법행위자들 내부관계에서는 일정한 부담 부분이 있고, 공동불법행위자 중 1인이 자기의 부담 부분 이상을 변제하여 공동의 면책을 얻게 하였을 때에는 다른 공동불법행위자에게 그 부담 부분의 비율에 따라 구상권을 행사할 수 있으므로 공동불법행위자가 구상권을 갖기 위하여는 반드시 피해자의 손해 전부를 배상하여야 할 필요는 없으나, 자기의 부담 부분을 초과하여 배상을 하여야 할 것이고, 피용자와 제3자가 공동불법행위로 피해자에게 손해를 가하여 그 손해배상채무를 부담하는 경우에 피용자와 제3자는 공동불법행위자로서 서로 부진정연대관계에 있고, 한편 사용자의 손해배상책임은 피용자의 배상책임에 대한 대체적 책임이어서 사용자도 제3자와 부진정연대관계에 있다고 보아야 할 것이므로, 사용자가 피용자와 제3자의 책임비율에 의하여 정해진 피용자의 부담 부분을 초과하여 피해자에게 손해를 배상한 경우에는 사용자는 제3자에 대하여도 구상권을 행사할 수 있다.","emphasis":[],"underline":[[224,263],[264,286],[378,445],[450,514],[515,543]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-248","continued":false,"pageStart":140,"pageEnd":140,"anchor":"source-140-1"},{"type":"h3","text":"(1) 공동불법행위자 간의 연대책임","emphasis":[[0,19]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":140,"pageEnd":140,"anchor":"source-140-2"},{"type":"p","text":"공동불법행위가 성립하게 되면 각 불법행위자들은 가해행위와 인과관계가 있는 손해에 대한 배상책임을 민법 제760조에 따라서 연대하여 지게 된다. 이때 “連帶하여”를 통설․판례는 각 행위자들이 손해 전부에 대한 배상의무를 부담한다고 이해하면서 손해배상채무를 ‘부진정연대채무’로 이해한다. 따라서 피해자는 공동불법행위자 중 누구에게라도 손해배상액 전부를 청구할 수 있고 공동불법행위자는 자신의 부담부분을 가지고 피해자에게 대항할 수 없다(연대채무의 대외관계). 그러나 공동불법행위자들 간에는 각자의 과실비율대로 부담부분이 인정된다(연대채무의 대내관계).","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":140,"pageEnd":140,"anchor":"source-140-3"},{"type":"p","text":"공동불법행위책임에 따른 채무를 부진정연대채무로 이해하게 되면 연대채무자 1인에게 생긴 사유는 채권을 만족시키는 사유를 제외하고는 다른 채무자에게 영향을 주지 않는다. 즉 채무자 1인에게 생긴 사유 중에서 변제, 대물변제, 공탁, 상계만이 다른 채무자에게 영향을 미치며(소위 절대적 효력), 채무면제, 경개, 혼동, 소멸시효, 청구권 포기 등과 같은 사유들은 다른 채무자에게 영향을 미치지 않는다 (소위 상대적 효력).","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":140,"pageEnd":140,"anchor":"source-140-4"},{"type":"p","text":"F 상계에 관해서 기존 판례는 절대적 효력을 부정했으나 2010년 전원합의체 판결에서 절대적 효력을 인정했다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"comment","group":"민법4_강의자료(불법행위)-249","continued":false,"pageStart":140,"pageEnd":140,"anchor":"source-140-5"},{"type":"p","text":"v 대법원 2010. 9. 16. 선고 2008다97218 전원합의체 판결 : 부진정연대채무자 중 1인이 자신의 채권자에 대한 반대채권으로 상계를 한 경우에도 채권은 변제, 대물변제, 또는 공탁이 행하여진 경우와 동일하게 현실적으로 만족을 얻어 그 목적을 달성하는 것이므로, 그 상계로 인한 채무소멸의 효력은 소멸한 채무 전액에 관하여 다른 부진정연대채무자에 대하여도 미친다고 보아야 한다. 이는 부진정연대채무자 중 1인이 채권자와 상계계약을 체결한 경우에도 마찬가지이다. 나아가 이러한 법리는 채권자가 상계 내지 상계계약이 이루어질 당시 다른 부진정연대채무자의 존재를 알았는지 여부에 의하여 좌우되지 아니한다.","emphasis":[],"underline":[[154,205],[206,217]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-250","continued":false,"pageStart":140,"pageEnd":140,"anchor":"source-140-6"},{"type":"h3","text":"(2) 공동불법행위에 있어서 손해배상범위","emphasis":[[0,22]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":140,"pageEnd":140,"anchor":"source-140-7"},{"type":"p","text":"공동불법행위자들 간에는 손해에 가공하는 정도가 다를 수 있다. 그러나 공동불법행위는 공동의 가해행위에 대해 연대책임을 지우는 것이므로 그로 인한 손해배상책임은 피해자에 대한 관계에서 공동불법행위자들 모두의 행위를 전체적으로 평가하여 정하게 된다. 따라서 가해자 중 1인이나 일부가 다른 가해자에 대하여 가담의 정도가 미약하다고 하더라도 피해자에 대한 관계에서 가담의 정도를 고려하여 그의 책임범위를 제한할 수 없다(불법행위에 있어서 각자의 기여도는 상호 간의 대내적 구상관계에서만 고려될 수 있다). 그러나 공동불법행위자별로 별개의 소를 제기한 경우에는 증명의 차이 등으로 손해액도 달리 인정될 수 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":140,"pageEnd":140,"anchor":"source-140-8"},{"type":"p","text":"v 대법원 2001. 9. 7. 선고 99다70365 판결 : 공동불법행위 책임은 가해자 각 개인의 행위에 대하여 개별적으로 그로 인한 손해를 구하는 것이 아니라 그 가해자들이 공동으로 가한 불법행위에 대하여 그 책임을 추궁하는 것이므로, 공동불법행위로 인한 손해배상책임의 범위는 피해자에 대한 관계에서 가해자들 전원의 행위를 전체적으로 함께 평가하여 정하여야 하고, 그 손해배상액에 대하여는 가해자 각자가 그 금액의 전부에 대한 책임을 부담하는 것이며, 가해자 1인이 다른 가해자에 비하여 불법행위에 가공한 정도가 경미하다고 하더라도 피해자에 대한 관계에서 그 가해자의 책임 범위를 위와 같이 정하여진 손해배상액의 일부로 제한하여 인정할 수는 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-251","continued":false,"pageStart":140,"pageEnd":141,"anchor":"source-140-9"},{"type":"p","text":"v 대법원 2001. 2. 9. 선고 2000다60227 판결 : [사실관계] 소외 1은 새벽 1시경 택시를 운전하고 편도 1차선 도로를 전방주시를 태만히 한 채 진행한 과실로 도로상에 쓰러져 있던 피해자를 택시 우측 앞 바퀴부분으로 역과하였고 그 뒤를 이어 소외 2가 승용차를 운전하고 전방주시를 태만히 한 채 위 도로를 진행하다가 다시 피해자를 역과함으로써 피해자가 사망하였다. 피해자의 유족인 원고가 소외 2의 보험회사를 상대로 손해배상청구의 소를 제기하여 일부 승소판결을 받고 그에 따라 합계 금 76,300,000원을 지급받았다. 그런데 원고가 소외 1의 공제회사인 피고를 상대로 추가로 손해배상소송을 제기하자 피고는 ‘손해배상청구권의 포기’, ‘전체손해의 전보’를 들어 항변하였다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-252","continued":false,"pageStart":141,"pageEnd":141,"anchor":"source-141-1"},{"type":"p","text":"[법원의 판단] 손해배상청구권의 포기주장과 관련해 법원은 원고가 손해배상청구권을 포기했는지도 불명확하고, 설사 원고가 소외 2의 보험회사에 대해 손해배상청구권을 포기했다 하더라도 피고에 대한 청구에는 영향을 미치지 않는다고 하였다. 다음으로 전체손해가 전보되었는지에 관해 법원은 “피해자가 공동불법행위자들을 모두 피고로 삼아 한꺼번에 손해배상청구의 소를 제기한 경우와 달리 공동불법행위자별로 별개의 소를 제기하여 소송을 진행하는 경우에는 각 소송에서 제출된 증거가 서로 다르고 이에 따라 교통사고의 경위와 피해자의 손해액산정의 기초가 되는 사실이 달리 인정됨으로 인하여 과실상계비율과 손해액도 서로 달리 인정될 수 있는 것이므로, 원고들이 엘지화재해상보험 주식회사를 상대로 한 손해배상 소송에서 승소한 금액을 전부 지급받았다고 하더라도 그 금액이 이 사건 손해배상 소송에서 산정된 손해액에 미치지 못한다면 피고는 그 차액을 원고들에게 지급할 의무가 있는 것이다.”라고 판시했다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-252","continued":false,"pageStart":141,"pageEnd":141,"anchor":"source-141-2"},{"type":"h3","text":"(3) 과실상계","emphasis":[[0,8]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":141,"pageEnd":141,"anchor":"source-141-3"},{"type":"p","text":"불법행위에 있어서와 마찬가지로 공동불법행위에 있어서도 과실상계가 인정되는데, 이때 다수인 가해자에 대한 피해자의 과실을 어떻게 상계할 것인지가 문제 된다. 이에 대하여 판례는 원칙적으로 공동불법행위에 있어서 과실상계는 공동불법행위자 전원의 과실과 피해자의 공동불법행위자 전원에 대한 과실을 전체적으로 평가해야 한다고 본다(전체평가설). 다만, 고의가해자와 과실가해자가 있는 경우 고의가해자는 피해자에게 과실상계를 주장할 수 없지만 과실가해자는 피해자에게 과실상계를 주장할 수 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":141,"pageEnd":141,"anchor":"source-141-4"},{"type":"p","text":"v 대법원 1997. 4. 11. 선고 97다3118 판결 : [사실관계] 소외 1은 그 소유의 승용차로 경부고속도로 하행선을 운전하여 가던 중 조향장치를 제대로 조작하지 못하고 중앙분리대를 들이받아 그 곳에 설치된 철제 방현망(가로 3.68m, 세로 0.6m) 5개를 파손시켜 그 중 1개를 상행선인 반대차선 2차선 상으로 떨어뜨렸는데, 약 10분 후 소외 망인이 승용차를 운전하고 상행선을 주행하다 위 방현망에 걸려 좌측 앞바퀴 등이 파손된 채 차량이 우측으로 쏠리면서 약 25m를 진행하다가 전방 차량들이 정체된 틈을 타 그 승용차에서 내려 이상 유무를 살피고자 동 승용차의 뒷쪽으로 걸어 오고 있던 중, 때마침 소외 2가 고속버스를 운전하고 상행선 2차선 상을 시속 약 95km로 망인 승용차 뒤를 따라 진행하다가 약 3m 전방에서 위 방현망을 발견하고 이를 피하고자 1차선으로 급히 차선을 변경하다가 1차선 상에서 차량 정체로 서행하고 있는 소외 르망 승용차와의 충돌 위험을 느껴 이를 피하고자 다시 조향장치를 우측으로 조작하였으나 미치지 못하고 위 르망 승용차 우측 뒷부분을 위 고속버스 좌측 앞부분으로 충격한 후 2차선 상으로 급진입하면서 위와 같이 걸어 나오고 있던 소외 망인을 위 고속버스의 앞부분으로 충격하여 동인으로 하여금 뇌좌상 등으로 즉시 그 자리에서 사망하게 하였다. 망인의 유족인 원고는 소외 1과 소외 2의 보험회사인 피고들을 상대로 손해배상소송을 제기하였다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-253","continued":false,"pageStart":141,"pageEnd":141,"anchor":"source-141-5"},{"type":"p","text":"[법원의 판단] 소외 1에게 사망사고의 책임이 있는가에 관해 법원은 상당인과관계를 인정하여 책임을 긍정하였다. 다음으로 과실상계를 함에 있어서 소외 1과 소외 2의 과실비율이 다르지만 전체적으로 평가하여 망인 : 소외 1, 2의 과실비율을 40:60으로 인정하였다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-253","continued":false,"pageStart":141,"pageEnd":141,"anchor":"source-141-6"},{"type":"p","text":"[판결요지] 공동불법행위 책임은 가해자 각 개인의 행위에 대하여 개별적으로 그로 인한 손해를 구하는 것이 아니라 그 가해자들이 공동으로 가한 불법행위에 대하여 그 책임을 추궁하는 것으로, 법원이 피해자의 과실을 들어 과실상계를 함에 있어서는 피해자의 공동불법행위자 각인에 대한 과실비율이 서로 다르더라도 피해자의 과실을 공동불법행위자 각인에 대한 과실로 개별적으로 평가할 것이 아니고 그들 전원에 대한 과실로 전체적으로 평가하여야 할 것이다.(이하 판결에서 공통)","emphasis":[],"underline":[[7,62],[63,103],[105,126],[127,186],[187,247]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-253","continued":false,"pageStart":141,"pageEnd":141,"anchor":"source-141-7"},{"type":"p","text":"v 대법원 1998. 6. 12, 선고 96다55631 판결 : [사안정리] 丙의 자동차가 중앙선을 침범하여 甲의 승용차를 충돌하였고, 이 사고로 멈춰서있던 甲의 승용차를 뒤따라오던 乙의 자동차가 추돌하였다. 丙은 중앙선을 침범하여 과실이 크지만, 乙은 전방주시의무위반과 과속으로 그 정도가 약하였다. 甲 또한 전방주시의무를 게을리하여 丙과 충돌하는 사고를 당하였다. 甲이 乙에게 손해배상을 청구한 사안에서 원심은 과실상계를 하여 乙의 책임을 30%로 제한했지만, 대법원은 전체적 평가설에 비추어 과실상계를 너무 많이 했다고 하여 원심을 파기환송했다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-254","continued":false,"pageStart":141,"pageEnd":141,"anchor":"source-141-8"},{"type":"p","text":"[1] 공동불법행위의 성립에는 공동불법행위자 상호 간에 의사의 공통이나 공동의 인식이 필요하지 아니하고 객관적으로 각 행위에 관련공동성이 있으면 족하므로, 관련공동성 있는 행위에 의하여 손해가 발생하였다면 그 손해배상책임을 면할 수 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-254","continued":false,"pageStart":141,"pageEnd":141,"anchor":"source-141-9"},{"type":"p","text":"[2] 공동불법행위책임은 가해자 각 개인의 행위에 대하여 개별적으로 그로 인한 손해를 구하는 것이 아니라 가해자들이 공동으로 가한 불법행위에 대하여 그 책임을 추궁하는 것으로, 법원이 피해자의 과실을 들어 과실상계를 함에 있어서는 피해자의 공동불법행위자 각인에 대한 과실비율이 서로 다르더라도 피해자의 과실을 공동불법행위자 각인에 대한 과실로 개별적으로 평가할 것이 아니고 그들 전원에 대한 과실로 전체적으로 평가하여야 한다.","emphasis":[],"underline":[[4,64],[65,128],[129,237]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-254","continued":false,"pageStart":141,"pageEnd":142,"anchor":"source-141-10"},{"type":"p","text":"v 대법원 2000. 9. 8. 선고 99다48245 판결 : [사안정리] 축구골대의 하자로 인한 장파열과 전원상의 과실로 인한 사망 사건에서 법원은 “망인의 사망에 대한 피고 1(관광농원 경영자)의 과실과 피고 3(의사)의 과실(피고 2는 병원)이 동일하지 않더라도 ... 원고측의 과실을 피고들 전원의 과실과 전체적으로 평가”하여 원고 : 피고전체의 과실비율을 40 : 60으로 정하였다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-255","continued":false,"pageStart":142,"pageEnd":142,"anchor":"source-142-1"},{"type":"p","text":"v 대법원 2007. 6. 14. 선고 2005다32999 판결 : [사실관계] 피고는 자산관리주식회사(이하 소외 회사)의 영업부장이다. 피고는 원고에게 소외 회사 경영진으로부터 교육받은 내용을 그대로 들려주며 투자를 권유하고 소외 회사의 투자설명회에 참가하도록 적극 유도하였는데, 소외 회사 경영진은 원고가 투자한 금원을 불법적으로 수신하여 편취하였다. 원고도 경영진의 투자금 편취사실을 모른 채 9억 원을 투자하여 현재 약 6억 원의 손해를 입고 있다. 원고는 피고에 대하여 공동불법행위에 따른 손해배상책임을 물었다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-256","continued":false,"pageStart":142,"pageEnd":142,"anchor":"source-142-2"},{"type":"p","text":"[법원의 판단] 원심법원은 고의의 방조를 인정하였다. 대법원은 고의는 부정하였지만 과실에 의한 방조를 인정하였고, 결국 손해배상책임은 인정되었다. 문제는 과실상계가 어떻게 되는가이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-256","continued":false,"pageStart":142,"pageEnd":142,"anchor":"source-142-3"},{"type":"p","text":"원심은 피고의 고의를 인정하여 과실상계를 인정하지 않았다. 그러나 대법원은 피고에게 과실만이 있다고 하여 과실상계를 인정하였다. 그 근거는 다음과 같다: “공동불법행위의 경우 ... 과실상계를 함에 있어서는 피해자의 공동불법행위자 각인에 대한 과실비율이 서로 다르더라도 피해자의 과실을 공동불법행위자 각인에 대한 과실로 개별적으로 평가할 것이 아니고 그들 전원에 대한 과실로 전체적으로 평가하여야 할 것이며, 이 경우 피해자의 부주의를 이용하여 고의로 불법행위를 저지른 자가 바로 그 피해자의 부주의를 이유로 자신의 책임을 감하여 달라고 주장하는 것은 허용될 수 없는 것이나, 불법행위자 중의 일부에게 그러한 사유가 있다고 하여 그러한 사유가 없는 다른 불법행위자까지도 과실상계의 주장을 할 수 없다고 해석할 것은 아니다. 그렇다면 피고가 과실로써 방조행위를 하여 공동불법행위책임을 부담하게 된 이 사건에서 다른 공동불법행위자인 소외인 등이 원고의 부주의를 이용하여 고의로 불법행위를 저질렀다는 사유만으로 피고의 과실상계 주장이 허용되지 않는 것으로 볼 수는 없[다.]”","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-256","continued":false,"pageStart":142,"pageEnd":142,"anchor":"source-142-4"},{"type":"p","text":"v 대법원 2010. 2. 11. 선고 2009다68408 판결: 공동불법행위책임은 가해자 각 개인의 행위에 대하여 개별적으로 그로 인한 손해를 구하는 것이 아니라 가해자들이 공동으로 가한 불법행위에 대하여 그 책임을 추궁하는 것이므로, 법원이 피해자의 과실을 들어 과실상계를 함에 있어서는 피해자의 공동불법행위자 각인에 대한 과실비율이 서로 다르더라도 피해자의 과실을 공동불법행위자 각인에 대한 과실로 개별적으로 평가할 것이 아니고 그들 전원에 대한 과실로 전체적으로 평가하여야 하나, 이는 과실상계를 위한 피해자의 과실을 평가함에 있어서 공동불법행위자 전원에 대한 과실로 전체적으로 평가하여야 한다는 것이지, 공동불법행위자 중에 고의로 불법행위를 행한 자가 있는 경우에는 피해자에게 과실이 없는 것으로 보아야 한다거나 모든 불법행위자가 과실상계의 주장을 할 수 없게 된다는 의미는 아니다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-257","continued":false,"pageStart":142,"pageEnd":142,"anchor":"source-142-5"},{"type":"p","text":"v 대법원 2018. 3. 22. 선고 2012다74236 전원합의체 판결: 금액이 다른 채무가 서로 부진정연대 관계에 있을 때 다액채무자가 일부 변제를 하는 경우 변제로 인하여 먼저 소멸하는 부분은 당사자의 의사와 채무 전액의 지급을 확실히 확보하려는 부진정연대채무 제도의 취지에 비추어 볼 때 다액채무자가 단독으로 채무를 부담하는 부분으로 보아야 한다. 이러한 법리는 사용자의 손해배상액이 피해자의 과실을 참작하여 과실상계를 한 결과 타인에게 직접 손해를 가한 피용자 자신의 손해배상액과 달라졌는데 다액채무자인 피용자가 손해배상액의 일부를 변제한 경우에 적용되고, 공동불법행위자들의 피해자에 대한 과실비율이 달라 손해배상액이 달라졌는데 다액채무자인 공동불법행위자가 손해배상액의 일부를 변제한 경우에도 적용된다. 또한 중개보조원을 고용한 개업공인중개사의 공인중개사법 제30조 제1항에 따른 손해배상액이 과실상계를 한 결과 거래당사자에게 직접 손해를 가한 중개보조원 자신의 손해배상액과 달라졌는데 다액채무자인 중개보조원이 손해배상액의 일부를 변제한 경우에도 마찬가지이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-258","continued":false,"pageStart":142,"pageEnd":142,"anchor":"source-142-6"},{"type":"h3","text":"(4) 공동불법행위에 있어서 구상관계","emphasis":[[0,20]],"underline":[],"highlight":[],"strike":[],"headingLevel":5,"pageStart":142,"pageEnd":142,"anchor":"source-142-7"},{"type":"p","text":"[사례] 甲․乙․丙은 丁에게 상해를 가하여 丁에게 치료비, 위자료를 포함하여 총 9천만 원의 손해가 발생하였다. 이때 손해배상과 관련한 법률관계는?","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-259","continued":false,"pageStart":142,"pageEnd":142,"anchor":"source-142-8"},{"type":"p","text":"<解說> 공동불법행위자 甲․乙․丙이 丁에게 상해를 가하여 치료비를 포함한 9천만 원의 손해가 발생한 경우, 피해자 丁과의 관계에서 甲․乙․丙은 손해배상액 전부인 9천만 원에 대한 책임을 각각 지게 되므로 자신의 부담부분을 가지고 丁의 청구에 대항할 수 없으며, 피해자 丁은 甲․乙․丙 중 아무에게나 손해배상액 전부를 청구할 수 있다. 그러나 丁의 손해에 대하여 甲․乙․丙 간의 기여도가 다르므로 공동불법행위자인 이들 간에는 내부적으로 부담부분이 달리 정해질 수 있다. 따라서 만약 피해자 丁이 공동불법행위자 중 1인인 乙에게 손해배상액 전부인 9천만 원을 청구한 경우, 乙은 丁에 대하여 전액을 배상하여야 한다. 만약 손해에 대한 甲․乙․丙의 기여도가 각각 5:3:1이라면 이 경우 乙은 3천만 원(3/9)은 자신의 채무를 변제한 것이 되나, 나머지 6천만 원에 대해서는 다른 공동불법행위자인 甲과 丙에게 5:1의 비율로 구상할 수 있게 된다. 그리고 공동불법행위자들 간의 내부적인 부담부분은 각자의 고의나 과실, 위법성, 변제능력 및 그 밖에도 신의칙에 따라서 결정하게 된다. 그러나 부담부분을 결정할 수 없는 경우에 각 행위자의 부담부분은 균등한 것으로 추정된다(제424조).","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"example","group":"민법4_강의자료(불법행위)-259","continued":false,"pageStart":142,"pageEnd":143,"anchor":"source-142-9"},{"type":"p","text":"공동불법행위자들은 부진정연대채무를 부담하게 된다. 따라서 이들 사이에는 주관적 공동관계가 존재하지 않으며 상호 간에 구상관계가 발생하지 않는 것이 원칙이다. 그러나 통설과 판례는 손해의 공평한 분담의 차원에서 공동불법행위자들 간에 과실비율에 따른 부담부분을 인정하여 자신의 부담부분을 넘는 배상의무를 이행한 자에게 구상권을 인정한다. 이때 구상채무는 원칙적으로 분할채무이다. 그러나 내부 부담비율이 0인 자가 다른 공동불법행위자에게 책임을 추궁할 때라면 부진정연대채무가 된다. 이는 내부 부담비율이 0인 공동불법행위자를 내부관계에서는 피해자와 유사하게 보기 때문이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"pageStart":143,"pageEnd":143,"anchor":"source-143-1"},{"type":"p","text":"v 대법원 1997. 12. 12. 선고 96다50896 판결 : [1] 공동불법행위자는 채권자에 대한 관계에서는 연대책임(부진정연대채무)을 지되, 공동불법행위자들 내부관계에서는 일정한 부담 부분이 있고, 이 부담 부분은 공동불법행위자의 과실의 정도에 따라 정하여지는 것으로서 공동불법행위자 중 1인이 자기의 부담 부분 이상을 변제하여 공동의 면책을 얻게 하였을 때에는 다른 공동불법행위자에게 그 부담 부분의 비율에 따라 구상권을 행사할 수 있다.","emphasis":[],"underline":[[41,140],[141,202],[203,249]],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-260","continued":false,"pageStart":143,"pageEnd":143,"anchor":"source-143-2"},{"type":"p","text":"[2] 공동불법행위자 중 1인이 다른 공동불법행위자에 대하여 구상권을 행사하기 위하여는 자기의 부담 부분 이상을 변제하여 공동의 면책을 얻었음을 주장·입증하여야 하며, 위와 같은 법리는 피해자의 다른 공동불법행위자에 대한 손해배상청구권이 시효소멸한 후에 구상권을 행사하는 경우라고 하여 달리 볼 것이 아니다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-260","continued":false,"pageStart":143,"pageEnd":143,"anchor":"source-143-3"},{"type":"p","text":"[3] 피해자가 부진정연대채무자 중 1인에 대하여 손해배상에 관한 권리를 포기하거나 채무를 면제하는 의사표시를 하였다 하더라도 다른 채무자에 대하여 그 효력이 미친다고 볼 수는 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-260","continued":false,"pageStart":143,"pageEnd":143,"anchor":"source-143-4"},{"type":"p","text":"[4] 공동불법행위자 간 구상권의 발생 시점은 구상권자가 현실로 피해자에게 손해배상금을 지급한 때이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-260","continued":false,"pageStart":143,"pageEnd":143,"anchor":"source-143-5"},{"type":"p","text":"v 구상권을 행사하는 공동불법행위자 측에 과실이 없는 경우 구상채무가 부진정연대관계에 있는지 여부(대판 2005. 10. 13, 2003다24147) : [사실관계] 운전자 甲은 빗길에 미끄러지는 바람에 중앙선을 침범하여 마주오던 택시 乙과 충돌하였고, 乙의 택시와 안전거리를 확보하지 않은 채 뒤따라오던 丙은 甲의 자동차의 사고로 정지해 있던 乙의 택시를 충돌하였다. 이 사고로 乙의 택시의 승객인 丁이 상해를 입었다. 이에 乙의 택시회사가 속한 전국택시운송사업조합연합회 X는 승객 丁에게 손해배상액 전부를 배상하고 난 뒤, 보험자대위(상법 제682조)에 따라 乙 소속 택시회사의 구상권을 대위행사하였다. 이때 X는 甲․丙 중 1인에게 손해배상액의 전부를 구상할 있는지 여부.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-260","continued":false,"pageStart":143,"pageEnd":143,"anchor":"source-143-6"},{"type":"p","text":"[판결요지] 공동불법행위자 중 1인에 대하여 구상의무를 부담하는 다른 공동불법행위자가 수인인 경우에는 특별한 사정이 없는 이상 그들의 구상권자에 대한 채무는 각자의 부담 부분에 따른 분할채무로 봄이 상당하지만, 구상권자인 공동불법행위자측에 과실이 없는 경우, 즉 내부적인 부담 부분이 전혀 없는 경우에는 이와 달리 그에 대한 수인의 구상의무 사이의 관계를 부진정연대관계로 봄이 상당하다. (乙 택시의 기사에게는 과실이 없음)","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-260","continued":false,"pageStart":143,"pageEnd":143,"anchor":"source-143-7"},{"type":"p","text":"v 공동불법행위에 대하여 민법 제426조의 적용여부(대판 1998. 6. 26, 98다5777) : [사실관계] 甲은 乙과 공사계약을 체결하였고, 이에 甲이 운영하는 회사소속 직원인 丙이 乙 소유 공장에서 작업을 하던 중 甲의 피용자 X와 乙의 피용자 Y의 과실로 화재가 발생하여 丙이 화상을 입어 사망하였다. 이에 甲은 丙에게 손해전액을 배상하고 乙에게 구상권을 행사하였으나, 乙은 甲이 손해배상을 하면서 자신에게 사전이나 사후에도 아무런 통지를 하지 않았으며 자신은 丙에게 손해배상채무의 면제를 받았던 사실을 들어 구상의무에 응할 수 없다고 한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-260","continued":false,"pageStart":143,"pageEnd":143,"anchor":"source-143-8"},{"type":"p","text":"[판결요지] 민법 제426조가 연대채무에 있어서의 변제에 관하여 채무자 상호 간에 통지의무를 인정하고 있는 취지는, 연대채무에 있어서는 채무자들 상호 간에 공동목적을 위한 주관적인 연관관계가 있고 이와 같은 주관적인 연관관계의 발생 근거가 된 대내적 관계에 터잡아 채무자 상호 간에 출연분담에 관한 관련관계가 있게 되므로, 구상관계에 있어서도 상호 밀접한 주관적인 관련관계를 인정하고 변제에 관하여 상호 통지의무를 인정함으로써 과실 없는 변제자를 보다 보호하려는 데 있으므로, 이와 같이 출연분담에 관한 주관적인 밀접한 연관관계가 없고 단지 채권만족이라는 목적만을 공통으로 하고 있는 부진정 연대채무에 있어서는 그 변제에 관하여 채무자 상호 간에 통지의무 관계를 인정할 수 없고, 변제로 인한 공동면책이 있는 경우에 있어서는 채무자 상호 간에 어떤 대내적인 특별관계에서 또는 형평의 관점에서 손해를 분담하는 관계가 있게 되는데 불과하다고 할 것이므로, 부진정 연대채무에 해당하는 공동불법행위로 인한 손해배상채무에 있어서도 채무자 상호 간에 구상요건으로서의 통지에 관한 민법의 위 규정을 유추 적용할 수는 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-260","continued":false,"pageStart":143,"pageEnd":143,"anchor":"source-143-9"},{"type":"p","text":"v 공동불법행위자 중 1인에 대한 채무면제의 효력(대판 1969. 8. 26, 69다962) : [사실관계] 광업권자인 甲(대한석탄공사)는 채굴업자인 乙에게 채굴에 관한 도급계약을 체결하면서, 채굴작업 중 갱내사고에 대해서는 수급인인 乙이 일체의 책임을 지기로 하였다. 그런데 작업 도중 乙의 피용자인 丙이 갱내 낙반사고로 중상을 입게 되었다. 이 낙반사고에 대하여 甲은 광산보안법상 갱내 낙반사고주의의무를 위반하였고, 乙은 丙의 사용자로서 갱내안전시설을 제대로 설치․관리하지 못한 데에 과실이 있음이 증명되었다. 그리고 피해자 丙은 乙에 대하여 손해배상청구권을 포기하기로 약정하였다. 이때 丙이 甲에 대하여 손해배상을 청구하는 경우, 甲이 丙의 乙에 대한 손해배상청구권의 포기로서 대항할 수 있는지 여부. [판결요지] 광업권자가 그 갱내의 광물 채굴작업을 제3자에게 도급시켜 그 수급자가 그 작업에 있어서의 모든 감독책임을 지기로 하고 그 갱내의 보안상의 의무와그 작업 중의 사고로 인한 재해보상의 책임을 부담하기로 한 도급계약이 있다고 하여 광업권자의 광산보안법상의 보안의무에 아무런 영향이 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-260","continued":false,"pageStart":143,"pageEnd":143,"anchor":"source-143-10"},{"type":"p","text":"v 구상권의 소멸시효(대판 1996. 3. 26, 96다3791) : [사실관계] 甲 합자회사의 피용자인 乙의 과실로 발생한 교통사고로 丙이 손해를 입었고(2001. 10. 30), 이에 甲 회사와 공제계약을 체결한 공제조합 丁이 공제계약에 따라서 피해자 丙에게 손해배상채무를 이행하였다(2002. 5. 15). 이에 丁은 보험자대위에 따라 甲회사가 乙에 대하여 가지는 구상권을 행사하였으나(2005. 3. 20), 乙은 공동불법행위자인 자신에 대한 피해자의 손해배상채권이 3년의 소멸시효로 소멸하였음을 들어 丁이 보험자대위로 취득한 자신에 대한 구상권도 소멸하였다고 주장한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-260","continued":true,"pageStart":144,"pageEnd":144,"anchor":"source-144-0"},{"type":"p","text":"[판결요지] [1] 피해자에게 손해배상을 한 공동불법행위자의 다른 공동불법행위자에 대한 구상권은 피해자의 다른 공동불법행위자에 대한 손해배상채권과는 그 발생 원인과 법적 성질을 달리하는 별개의 독립한 권리이므로, 공동불법행위자가 다른 공동불법행위자에 대한 구상권을 취득한 이후에 피해자의 그 다른 공동불법행위자에 대한 손해배상채권이 시효로 소멸되었다고 하여 그러한 사정만으로 이미 취득한 구상권이 소멸된다고 할 수 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-260","continued":true,"pageStart":144,"pageEnd":144,"anchor":"source-144-1"},{"type":"p","text":"[2] 공동불법행위자의 다른 공동불법행위자에 대한 구상권의 소멸시효는 그 구상권이 발생한 시점, 즉 구상권자가 공동면책행위를 한 때로부터 기산하여야 할 것이고, 그 기간도 일반 채권과 같이 10년으로 보아야 한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-260","continued":true,"pageStart":144,"pageEnd":144,"anchor":"source-144-2"},{"type":"p","text":"[3] 공제조합이 공동불법행위자 중의 1인과 체결한 공제계약에 따라 그 공동불법행위자를 위하여 직접 피해자에게 배상함으로써 그 공동불법행위자의 다른 공동불법행위자에 대한 구상권을 보험자대위의 법리에 따라 취득한 경우, 공제계약이 상행위에 해당한다고 하여 그로 인하여 취득한 구상권 자체가 상사채권으로 변한다고 할 수 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-260","continued":true,"pageStart":144,"pageEnd":144,"anchor":"source-144-3"},{"type":"p","text":"v 대판 2001. 2. 15, 96다42420 : [사실관계] 민간인인 소외 甲은 1990. 3. 7. 소외회사 소유의 트럭을 운전하던 중, 피고 대한민국 산하 경찰청 소속 의경인 소외 乙이 운전하는 공무용 오토바이와 충돌하여, 위 오토바이 뒷좌석에 타고 있던 의경인 소외 丙이 상해를 입었다. 소외회사의 보험자인 원고 전국화물자동차운송사업조합연합회는 피해자 丙에게 치료비 및 합의금으로 4,733만 원을 지급한 후, 피고 대한민국에 대하여 피고의 부담부분이 50%라고 주장하면서 구상금을 구하는 소송을 제기하였다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-261","continued":false,"pageStart":144,"pageEnd":144,"anchor":"source-144-4"},{"type":"p","text":"[관련조문] 헌법 제29조(국가·공공단체의 배상책임) ① 공무원의 직무상 불법행위로 손해를 받은 국민은 법률이 정하는 바에 의하여 국가 또는 공공단체에 정당한 배상을 청구할 수 있다. 이 경우 공무원 자신의 책임은 면제되지 아니한다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-261","continued":false,"pageStart":144,"pageEnd":144,"anchor":"source-144-5"},{"type":"p","text":"② 군인·군무원·경찰공무원 기타 법률이 정하는 자가 전투·훈련 등 직무집행과 관련하여 받은 손해에 대하여는 법률이 정하는 보상 외에 국가 또는 공공단체에 공무원의 직무상 불법행위로 인한 배상은 청구할 수 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-261","continued":false,"pageStart":144,"pageEnd":144,"anchor":"source-144-6"},{"type":"p","text":"국가배상법 제2조(배상책임) ① 국가 또는 지방자치단체는 공무원이 그 직무를 집행함에 당하여 고의 또는 과실로 법령에 위반하여 타인에게 손해를 가하거나, 자동차손해배상보장법의 규정에 의하여 손해배상의 책임이 있는 때에는 이 법에 의하여 그 손해를 배상하여야 한다. 다만, 군인·군무원·경찰공무원 또는 향토예비군대원이 전투·훈련·기타 직무집행과 관련하거나 국방 또는 치안유지의 목적상 사용하는 시설 및 자동차·함선·항공기·기타 운반기구 안에서 전사·순직 또는 공상을 입은 경우에 본인 또는 그 유족이 다른 법령의 규정에 의하여 재해보상금·유족연금·상이연금 등의 보상을 지급받을 수 있을 때 에는 이 법 및 민법의 규정에 의한 손해배상을 청구할 수 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-261","continued":false,"pageStart":144,"pageEnd":144,"anchor":"source-144-7"},{"type":"p","text":"[판결요지] [다수의견] 헌법 제29조 제2항, 국가배상법 제2조 제1항 단서의 입법 취지를 관철하기 위하여는, 국가배상법 제2조 제1항 단서가 적용되는 공무원의 직무상 불법행위로 인하여 직무집행과 관련하여 피해를 입은 군인 등에 대하여 위 불법행위에 관련된 일반국민(법인을 포함한다. 이하 '민간인'이라 한다)이 공동불법행위책임, 사용자책임, 자동차운행자책임 등에 의하여 그 손해를 자신의 귀책부분을 넘어서 배상한 경우에도, 국가 등은 피해 군인 등에 대한 국가배상책임을 면할 뿐만 아니라, 나아가 민간인에 대한 국가의 귀책비율에 따른 구상의무도 부담하지 않는다고 하여야 할 것이다. 그러나 위와 같은 경우, 민간인은 여전히 공동불법행위자 등이라는 이유로 피해 군인 등의 손해 전부를 배상할 책임을 부담하도록 하면서 국가 등에 대하여는 귀책비율에 따른 구상을 청구할 수 없도록 한다면, 공무원의 직무활동으로 빚어지는 이익의 귀속주체인 국가 등과 민간인과의 관계에서 원래는 국가 등이 부담하여야 할 손해까지 민간인이 부담하는 부당한 결과가 될 것이고(가해 공무원에게 경과실이 있는 경우에는 그 공무원은 손해배상책임을 부담하지 아니하므로 민간인으로서는 자신이 손해발생에 기여한 귀책부분을 넘는 손해까지 종국적으로 부담하는 불이익을 받게 될 것이고, 가해 공무원에게 고의 또는 중과실이 있는 경우에도 그 무자력 위험을 사용관계에 있는 국가 등이 부담하는 것이 아니라 오히려 민간인이 감수하게 되는 결과가 된다.), 이는 위 헌법과 국가배상법의 규정에 의하여도 정당화될 수 없다고 할 것이다. 이러한 부당한 결과를 방지하면서 위 헌법 및 국가배상법 규정의 입법 취지를 관철하기 위하여는, 피해 군인 등은 위 헌법 및 국가배상법 규정에 의하여 국가 등에 대한 배상청구권을 상실한 대신에 자신의 과실 유무나 그 정도와 관계없이 무자력의 위험부담이 없는 확실한 국가보상의 혜택을 받을 수 있는 지위에 있게 되는 특별한 이익을 누리고 있음에 반하여 민간인으로서는 손해 전부를 배상할 의무를 부담하면서도 국가 등에 대한 구상권을 행사할 수 없다고 한다면 부당하게 권리침해를 당하게 되는 결과가 되는 것과 같은 각 당사자의 이해관계의 실질을 고려하여, 위와 같은 경우에는 공동불법행위자 등이 부진정연대채무자로서 각자 피해자의 손해 전부를 배상할 의무를 부담하는 공동불법행위의 일반적인 경우와 달리 예외적으로 민간인은 피해 군인 등에 대하여 그 손해 중 국가 등이 민간인에 대한 구상의무를 부담한다면 그 내부적인 관계에서 부담하여야 할 부분을 제외한 나머지 자신의 부담부분에 한하여 손해배상의무를 부담하고, 한편 국가 등에 대하여는 그 귀책부분의 구상을 청구할 수 없다고 해석함이 상당하다 할 것이고, 이러한 해석이 손해의 공평·타당한 부담을 그 지도원리로 하는 손해배상제도의 이상에도 맞는다 할 것이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-261","continued":false,"pageStart":144,"pageEnd":144,"anchor":"source-144-8"},{"type":"p","text":"[반대의견] 불법행위법은 피해자의 구제와 손해의 공평·타당한 부담·분배를 그 목적으로 하는바, 이러한 목적에 입각한 불법행위법의 일반원칙에 따르면 직접 불법행위를 한 자뿐만 아니라 그 사용자, 자동차운행자 등 손해의 발생에 대하여 일정한 책임이 있는 자들로 하여금 각자 피해자의 손해 전부를 배상할 의무를 부담하게 함으로써 피해자를 두텁게 보호하고, 한편 불법행위로 인한 손해발생에 관한 복수의 책임주체 중 일방이 피해자에게 그 손해를 자신의 귀책부분을 넘어서 배상한 때에는 다른 책임주체에 대하여 그들 사이에서 손해발생에 기여한 정도 등 실질관계에 따라 정하여지는 부담부분을 구상할 수 있도록 함으로써 손해의 공평·타당한 부담·분배를 도모하게 되는 것이다. 이러한 불법행위법의 목적과 일반원칙에 비추어 볼 때, 가해 공무원의 사용자로서의 지위에서 피해 군인 등의 손해발생에 책임이 있는 국가 등의 손해배상의무가 위 헌법 및 국가배상법의 규정에 의하여 배제 또는 면제되었다고 하더라도, 피해자를 보호하기 위해서는 그 손해발생의 다른 책임주체인 민간인의 손해배상의무까지 감축된다고 할 수 없고 그 민간인은 여전히 피해 군인 등의 손해 전부를 배상할 의무가 있는 것이다. 한편, 손해의 공평·타당한 부담·배분을 위해서는 군인 등의 손해를 배상한 민간인이 국가 등에 대하여 구상권을 행사할 수 있다고 해석하여야 한다. 만약 국가 등이 군인 등의 손해 전부를 배상한 민간인에 대한 구상의무까지 부담하지 않는다면, 국가 등은 공무원의 직무행위로 빚어지는 이익의 귀속주체로서 그 손해의 발생에 책임이 있는 경우에도 그 손해 중 민간인과의 관계에서 원래는 자신이 부담함이 마땅한 부분을 민간인에게 전가시킴으로써 재산상 불이익을 주게 될 것인데, 이러한 결과는 공평과 재산권 보장의 정신에 반하고, 그것은 다수의견도 지적하는 바와 같이 위 헌법 및 국가배상법의 규정에 의하여 정당화될 수는 없기 때문이다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-261","continued":false,"pageStart":144,"pageEnd":145,"anchor":"source-144-9"},{"type":"p","text":"[보충의견] 다수의견은 공동불법행위자의 책임에 관하여 피해자를 두텁게 보호하기 위하여 그동안 우리의 지배적 학설과 판례가 취하여 온, 공동불법행위자는 각자 손해 전부에 대한 배상의무를 부담한다는 원칙은 여전히 타당하다고 보지만, 법률에 의하여 보장되는 국가보상청구권제도에 의하여 피해자의 구제가 확실해 보이는 이 사건과 같은 경우에 민간인이 국가에 대하여 구상권을 행사할 수 없다고 봄으로 인하여 민간인이 부당한 손해를 입을 수 있는 위험을 방지하기 위하여 앞에서 본 바와 같은 특별한 사정을 기초로 예외적으로 공동불법행위자인 민간인의 손해배상의무를 제한하려는 것이므로, 이로 인하여 불법행위제도에 의한 피해자 보호의 취지가 특별히 훼손된다거나 불법행위로 인한 피해자의 구제에 관하여 일관성 없는 차별적 처리를 초래할 위험이 있다고 볼 수는 없으며, 민간인의 손해배상의무가 제한된다고 보는 것은 피해자가 누구로부터 먼저 배상이나 보상을 받느냐에 따라 민간인이 최종적으로 부담할 손해배상액에 차이가 생기고, 경우에 따라서는 민간인의 부담 아래 피해자가 과잉배상을 받게 되는 부당한 결과를 방지하기 위한 것으로서, 민간인은 그 손해배상의무의 제한으로 인하여 부당한 이득을 얻는 것이 아니라, 그 반대의 경우에 발생할 수 있는 부당한 손해를 입을 위험이 없게 될 뿐이므로 다수의견이 피해자보다 민간인을 부당하게 더 두텁게 보호하려는 것으로 볼 수도 없다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-261","continued":true,"pageStart":145,"pageEnd":145,"anchor":"source-145-1"},{"type":"p","text":"v 대법원 2001. 1. 19. 선고 2000다33607 판결: 불법행위에 있어서 부진정연대채무의 관계에 있는 복수의 책임주체 중 1인이 자기 부담 부분 이상을 변제하여 공동의 면책을 얻게 하고 다른 부진정연대채무자에 대하여 그 부담 부분의 비율에 따라 구상권을 행사하는 경우 부담 부분의 비율을 판단함에 있어서는, 불법행위 및 손해와 관련하여 그 발생 내지 확대에 대한 각 부진정연대채무자의 주의의무의 정도에 상응한 과실의 정도를 비롯한 기여도 등 사고 내지 손해와 직접적으로 관련된 대외적 요소를 고려하여야 함은 물론, 나아가 부진정연대채무자 사이에 특별한 내부적 법률관계가 있어 그 실질적 관계를 기초로 한 요소를 참작하지 않으면 현저하게 형평에 어긋난다고 인정되는 경우에는 그 대내적 요소도 참작하여야 하며, 일정한 경우에는 그와 같은 제반 사정에 비추어 손해의 공평한 분담이라는 견지에서 신의칙상 상당하다고 인정되는 한도 내에서만 구상권을 행사하도록 제한할 수도 있다.","emphasis":[],"underline":[],"highlight":[],"strike":[],"role":"precedent","group":"민법4_강의자료(불법행위)-262","continued":false,"pageStart":145,"pageEnd":145,"anchor":"source-145-2"}],"updated":false});
window.LECTURE.pages.push(...[{"n":112,"text":"제4절 특수불법행위\nⅠ. 특수불법행위의 유형\n1. 특수불법행위의 유형\n불법행위에 대하여 민법 제750조는 불법행위의 기본적인 구성요건이 된다. 이와 달리 불법행위에 대한 개별적인 특칙은 제755조부터 제759조까지, 그리고 제760조에서 정하고 있다. 특수한 불법행위는 일반불법행위와 달리 직접적인 가해행위를 하지 않은 자가 일정한 지위(감독자, 사용자, 도급인) 때문에 또는 관리·감독에 대하여 책임을 지도록 규정하고 있다. 따라서 특수불법행위를 “타인행위에 대한 책임” 또는 “물건의 관리․감독에 대한 책임”으로 부르기도 한다.\n불법행위법 규정 일반불법행위 불법행위의 기본적인 책임구성요건 제750조 재산이외의 손해의 배상 제751조 생명침해로 인한 위자료 제752조 책임무능력자(미성년자, 심신상실자) 제753조․제754조 특수불법행위 (타인행위에 대한 책임) 책임무능력자의 감독자책임 제755조 사용자책임 제756조 도급인의 책임 제757조 공작물 등의 점유자․소유자의 책임 제758조 동물의 점유자의 책임 제759조 공동불법행위 제760조\n2. 일반불법행위와 특수불법행위의 적용순서\n일반불법행위에 대한 제750조 규정에 대하여 특수한 불법행위에 대한 규정은 특칙이므로, 불법행위의 사안을 검토할 때 언제나 특수불법행위에 해당하는지를 먼저 검토하여야 한다. 그러나 주의하여야 할 점은 같은 사안에 특수불법행위규정과 일반불법행위규정(제750조)이 동시에 적용될 수 있다(예: 사용자의 제756조에 따른 사용자책임과 피용자의 제750조 책임)는 점이다.\nⅡ. 책임무능력자의 감독자의 책임\n제755조【감독자의 책임】 ① 다른 자에게 손해를 가한 사람이 제753조 또는 제754조에 따라 책임이 없는 경우에는 그를 감독할 법정의무가 있는 자가 그 손해를 배상할 책임이 있다. 다만, 감독의무를 게을리하지 아니한 경우에는 그러하지 아니하다.\n② 감독의무자를 갈음하여 제753조 또는 제754조에 따라 책임이 없는 사람을 감독하는 자도 제1항의 책임"},{"n":113,"text":"이 있다.\n[사례] 초등생 '5억 람보르기니 테러', 수리비가…헉!, 온라인 중앙일보, 2012. 07. 26.\n악동 초등학생들이 장난으로 5억 원짜리 람보르기니를 엉망으로 만들었다는 소식. 수리비가 1억 5000만 원이나 나왔다. 한 달이 넘도록 배상문제가 해결되지 않고 있다. 무슨 문제가 있는 것일까? 지난달 18일 광주광역시의 아파트. 초등학생 남자 아이들이 승용차에 소화기를 마구 뿌려댄다. 놀이터 미끄럼틀에 오르듯 차 위를 오르락내리락, 신이 났다. 아이들이 장난감처럼 갖고 놀다 파손한 차량은 람보르기니 무르시엘라고 LP640. 새 차 가격이 5억 원에 이른다. 아이들은 차량 파손 혐의로 경찰 조사를 받았고 부모가 수리비를 물어주기로 약속했다.\n[람보르기니 차주 : 확실히 되는 건 없고 진행되고 있어요. 합의도 몇 명은 안 되고 있고…]\n문제는 1억 5000만 원에 이르는 엄청난 수리비. 앞뒤 범퍼를 교환하는 비용은 웬만한 풀옵션 중형차 가격인 3000만 원. 엔진룸 후드와 라이트를 바꾸는 데도 2000만 원이 들어간다. 소화기 분말로 엉망이 된 차체를 도색하는 데 1000만 원. 외부 부품을 교환하는 데 1000만 원, 엔진을 청소하고 다시 세팅하는 데 4000만 원. 썬루프는 4000만 원 가량이다.\n[수입차 정비업체 : 모든 걸 다 한다면 견적은 1억2000만 원에서 1억5000만 원쯤 할 거고요. 차주분이 손상된 부분에 대해 저희가 낸 건 그 정도 나와요.]\n수리비가 많은 데다 학생들의 가담 정도를 가리지 못해 한 달이 지났지만 배상이 이뤄지지 않고 있다. 현재 람보르기니는 정비를 위해 대기하고 있다.\n[김덕은/변호사 : 합의가 되지 않으면 법원에서 법정의 판단을 받을 수밖에 없을 것 같습니다]\n초등학생 악동들의 철부지 장난이 민사소송으로 번질 처지에 놓였다.\n온라인 중앙일보, 정진명 기자.\n[사례] 고등학교 2학년에 재학 중이던 甲․乙․丙은 술에 취해, 평소 甲과 사귀던 중학교 3학년에 재학 중인 여학생 丁이 가출을 했다는 이유로 혼을 내주겠다며 丙의 자취방으로 데려갔다. 자취방에서 乙이 주먹으로 丁의 얼굴을 가격한 다음, 丙은 병에 든 석유를 丁의 머리에 붓고 甲은 버너용 플라스틱 알코올병에 있던 알코올을 丁의 목 부위에 붓고 불을 붙였다. 이로 인해 丁은 2개월의 치료를 요하는 전신 3도의 화상을 입게 되었다. 이때 丁은 누구를 상대로 손해배상을 청구할 수 있는가?\n≪해설≫ 丁에 대해서 가해행위를 한 자는 甲․乙․丙이므로 이들은 제750조에 따라 불법행위책임을 진다. 다음으로 甲․乙․丙이 책임능력 있는 미성년자이므로 이들 외에 그들의 부모들이 책임을 지는지가 문제 된다. 판례의 경우 책임능력 있는 미성년자의 친권자도 감독의무소홀에 따른 일반불법행위책임(제750조)을 진다고 보므로, 사안에서 甲․乙․丙과 더불어 그들의 친권자들도 책임을 진다. 그리고 이들 간에는 공동불법행위가 성립하므로, 丁의 손해에 대하여 모두 연대하여 책임을 지게 될 것이다.\n1. 의의\n책임무능력자가 제3자에게 손해를 가한 경우에, 그 책임무능력자를 감독할 법정의무 있는 자(친권자·후견인) 또는 그에 갈음하여 책임무능력자를 감독하는 자(예, 보모·유치원장·초등학교장·정신병원장 등)가 그 손해에 대하여 배상책임을 지는 것을 말한다(제755조).\nF 책임무능력자의 감독자 책임은 일반 불법행위에 있어서의 책임이론과 다른 성질을 갖고 있다. ㈀ 이 책임은 책임무능력자의 가해의 결과에 대한 책임이다. 즉, 감독채무자 스스로 가해행위를 하여 발생한 책임이 아니다. ㈁ 이 책임에 있어서 감독의무자의 과실은 책임무능력자의 행위에 대한 감독을 게을리한 것에 있다. 책임무능력자가 가해행위를 한 것 자체에 대한 과실은 아니다. ㈂ 감독의무자의 과실에 관한 입증책임이 전환되어 있다. 따라서 감독의무자가 감독을 게을리하지 않았음을 입증하지 않는 한 책임을 면하지 못한다.\n2. 감독자책임의 요건\n(1) 책임무능력자의 고의·과실에 의한 위법한 가해행위\n제753조【미성년자의 책임능력】 미성년자가 타인에게 손해를 가한 경우에 그 행위의 책임을 변식할 지능이 없는 때에는 배상의 책임이 없다."},{"n":114,"text":"제754조【심신상실자의 책임능력】 심신상실중에 타인에게 손해를 가한 자는 배상의 책임이 없다. 그러나 고의 또는 과실로 인하여 심신상실을 초래한 때에는 그러하지 아니하다.\n제755조【감독자의 책임】 ① 다른 자에게 손해를 가한 사람이 제753조 또는 제754조에 따라 책임이 없는 경우에는 그를 감독할 법정의무가 있는 자가 그 손해를 배상할 책임이 있다. 다만, 감독의무를 게을리하지 아니한 경우에는 그러하지 아니하다.\n② 감독의무자를 갈음하여 제753조 또는 제754조에 따라 책임이 없는 사람을 감독하는 자도 제1항의 책임이 있다.\n피감독자인 책임무능력자가 고의 또는 과실에 의한 위법행위로 타인에게 손해를 가하여야 한다. 즉, 책임무능력자의 불법행위가 있어야 한다. 따라서 미성년자 등에게 책임능력이 있어서 스스로 불법행위책임을 지는 경우라면 비록 감독의무자의 감독에 과실이 있다고 하여도 감독자가 본조에 의한 책임을 지지 않는다.\n그러나 피감독자로 인한 손해를 감독의무자가 제755조에 따라 보충적으로만 부담한다는 결론은 때에 따라 부당한 결과를 가져온다. 현재 대법원은 미성년자 등이 가해행위 당시에 책임능력을 가지고 있었다고 하여도 그 가해행위로 발생한 손해와 감독의무자의 감독의무위반 사이에 상당인과관계가 있으면 감독의무자는 일반 불법행위자로서 손해배상책임을 부담하는 것으로 보고 있다(구체적인 것은 아래 관련 부분 참고).\n피감독자의 고의 또는 과실에 대한 입증책임은 불법행위의 일반원칙에 따라서 손해배상청구권자(피해자)가 부담한다. 가해자가 행위 시에 책임능력이 없었다는 점에 대해서도 제755조의 손해배상을 청구하는 피해자가 주장·입증해야 한다. 피해자가 가해자의 책임무능력을 이유로 감독자에게 손해배상을 청구하고 있기 때문이다.\nv 대법원 1978. 11. 28. 선고 78다1805 판결 : [사실관계] 가해자인 소외 최00(가해자, 피고의 아들)는 사고 당시에 만 14세 2개월 된 소년으로서 중학교 3학년에 재학중이었는데 동네 콘크리트로 된 다리 위에서 원고(피해자)는 정00과 1조가 되고 최00(가해자)는 조00와 다른 1조가 되어 각기 한사람씩 대결하는 소위 태그매치 방식의 레스링 놀이를 하게 되었고 그 레스링 놀이에서 원고와 조00가 어울려 레스링을 하던 중 조00이 원고의 밑에 깔리게 되자 교량 난간에서 이를 보고 있던 최00(가해자)가 조00를 구원하기 위하여 오른발로 원고의 등을 예고 없이 갑자기 밀어버림으로써 원고가 콘크리트 교량 바닥에 얼굴을 부딪혀 치아 5개가 탈락되는 상해를 입게 되었다.\n[법원의 판단] 가해자가 14년 2개월 된 중학생이라고는 하나 사고 당시가 야간이고 동 레스링을 한 장소가 다치기 쉬운 콘크리트로 된 다리의 맨바닥이었으며 그러한 맨바닥 위에서 얼굴을 지면으로 향하여 엎드려 있는 피해자를 갑자기 아무런 예고 없이 발로 밀어버린 최00(가해자)의 소위는 다른 사정이 없는 한 불법행위의 책임을 변식할 수 있는 지능을 가진 사람의 행위라고 볼 수는 없는 것이므로 결국 가해자의 아버지인 피고는 그 보호감독자로서의 주의의무를 해태하지 아니하였음을 주장입증하지 못한 본건에 있어서 가해자의 과실행위로 인하여 원고에게 가한 모든 손해를 배상할 책임이 있다.\n(2) 감독의무자의 감독의무 위반\n감독자책임은 자기의 직접적인 행위가 아닌 타인의 위법행위에 대한 책임이다. 책임무능력자의 감독자책임은 가족단체의 통솔자로서의 가장의 책임에서 유래하였다. 이것이 과실책임과 절충하여, 감독의무의 태만을 요건으로 하여 감독자책임이 인정되었다. 따라서 감독상의 주의를 다했다는 점을 증명하면 면책되는 중간책임(= 추정과실책임, vermutete Verschuldenshaftung)에 해당한다. 현재 법정감독의무자(제755조 제1항)에는 미성년자의 친권자, 양육자, 후견인 등이 있고, 감독의무자에 갈음하여 책임무능력자를 감독하는 자(제755조 제2항)에는 교사, 소년원 직원 등이 있다.\n감독상의 의무란 구체적 가해행위에 대한 감독이 아니라, 일반적인 생활에 대한 감독이다. 단, 법정감독의무자의 책임범위와 대리감독의무자의 책임범위는 서로 차이가 있다. 법정감독의무자는 전생활관계에 대하여 일반적인 감독의무가 있으므로 구체적인 가해행위에 대한 감독의무위반과 상관없이 책임을 진다. 제755조의 법문상으로는 법정감독자와 대리감독자 사이에 책임의 차이가 없는 것으로 규정되어"},{"n":115,"text":"있지만, 법원은 양자 간 차이를 두고 있다. 가령 대리감독자인 교사의 경우 가해행위가 교육활동과 관련되어 있고, 예측가능성(구체적 위험성)이 있는 경우에만 감독자책임을 진다. 따라서 이 경우 제755조보다는 제750조에 의한 책임에 가깝다고도 할 수 있다. 책임능력 있는 미성년자의 부모가 제750조에 기초해서 지는 책임과 판단기준이 유사하기 때문이다.\n감독자는 자신이 감독의무를 해태하지 않았다는 것을 입증한 경우에만 면책될 수 있다(제755조 제1항 단서). 따라서 감독의무자가 자신의 의무를 게을리하였음을 피해자가 입증할 필요는 없다. 제755조 제1항의 조문 구조상 감독의무의 해태는 추정되며 면책사유의 증명은 현실적으로 쉽지 않다.\nv 대법원 2007. 4. 26. 선고 2005다24318 판결 등 다수의 판결 : 지방자치단체가 설치·경영하는 학교의 교장이나 교사는 학생을 보호·감독할 의무를 지는데, 이러한 보호·감독의무는 교육법에 따라 학생들을 친권자 등 법정감독의무자에 대신하여 감독을 하여야 하는 의무로서 학교 내에서의 학생의 모든 생활관계에 미치는 것은 아니지만, 학교에서의 교육활동 및 이와 밀접 불가분의 관계에 있는 생활관계에 속하고, 교육활동의 때와 장소, 가해자의 분별능력, 가해자의 성행, 가해자와 피해자의 관계, 기타 여러 사정을 고려하여 사고가 학교생활에서 통상 발생할 수 있다고 하는 것이 예측되거나 또는 예측가능성(사고발생의 구체적 위험성)이 있는 경우에는 교장이나 교사는 보호·감독의무 위반에 대한 책임을 진다. [대리감독자의 감독의무의 내용] 교육활동과의 밀접성, 예측가능성(구체적 위험성)을 기준으로 하여 감독의무 위반을 판단함\nv 대법원 2007. 4. 26. 선고 2005다24318 판결 : [사실관계] 초등학교 6학년인 가해학생들의 집단따돌림으로 인해 피해자가 자살.\n[법원의 판단] 가해학생들은 12세 남짓된 초등학교 6학년 학생들로서 비록 책임을 변식할 지능을 갖추지 못하고 있다고 하더라도 상당한 정도의 자율능력, 분별능력은 가지고 있다고 보아야 할 것이고, 당시 학교에서의 집단 괴롭힘이 사회문제화 되어 학교에서 이에 대한 예방교육이 실시되고 있었으며, 가해학생들 역시 그와 같은 교육을 받아 그 폐해를 잘 알고 있었다 할 것인바, 이러한 사정들을 종합하여 보면, 가해학생들의 폭행 등 괴롭힘과 망인의 자살 사이에는 상당인과관계가 있다 할 것이다.\n민법 제755조에 의하여 책임능력 없는 미성년자를 감독할 친권자 등 법정감독의무자의 보호감독책임은 미성년자의 생활 전반에 미치는 것이고, 법정감독의무자에 대신하여 보호감독의무를 부담하는 교사 등의 보호감독책임은 학교 내에서의 학생의 모든 생활관계에 미치는 것이 아니라, 학교에서의 교육활동 및 이와 밀접 불가분의 관계에 있는 생활관계에 한하며, 이와 같은 대리감독자가 있다는 사실만 가지고서 곧 친권자의 법정감독책임이 면탈된다고는 볼 수 없다 할 것이다.\n망인은 가해학생들로부터 수개월에 걸쳐 이유 없이 폭행 등 괴롭힘을 당한 결과 충격 후 스트레스 장애 등의 증상에 시달리다 결국 자살에까지 이르게 되었음을 알 수 있고, 가해학생들의 망인에 대한 폭행 등은 거의 대부분 학교 내에서 휴식시간 중에 이루어졌고, 또한 수개월에 걸쳐 지속되었으며 당시 학교 내 집단 괴롭힘이 심각한 사회문제로 대두되어 있었으므로, 망인의 담임교사인 소외 1로서는 학생들의 동향 등을 보다 면밀히 파악하였더라면 망인에 대한 폭행 등을 적발하여 망인의 자살이라는 결과를 사전에 예방할 수 있었던 것으로 보이며, 나아가 망인에 대한 폭행사실이 적발된 후에도 소외 1, 2는 망인의 정신적 피해상태를 과소 평가한 나머지 망인의 부모로부터 가해학생들과 망인을 격리해 줄 것을 요청받고도 이를 거절하면서 가해학생들로부터 반성문을 제출받고 가해학생들의 부모들로부터 치료비에 대한 부담과 재발방지 약속을 받는 데 그치는 등 미온적으로 대처하였고, 또한 그 이후의 수학여행 중에도 망인에 대하여 보다 특별한 주의를 기울였어야 함에도 불구하고, 특별교우관계에 있는 학생을 붙여주는 이외에 별다른 조치를 취하지 아니함으로써 결과적으로 망인이 자살에 이르게 하도록 한 원인을 제공한 과실이 있다고 할 것이므로, 피고 경기도는 국가배상법 제2조 제1항에 의하여 그 소속 공무원인 소외 1, 2의 위와 같은 공무수행상의 과실로 인하여 망인 및 원고들이 입은 손해를 배상할 책임이 있다.\n[정리] 대리감독자의 과실이 가해행위와 구체적인 인과관계에 있다는 점을 설시한 후, 국가배상법 제2조를 적용하여 경기도의 책임을 인정하였음.\nv 대법원 1997. 6. 27. 선고 97다15258 판결 : [1] 초등학교의 교장이나 교사는 학생을 보호․감독할 의무를 지는 것이나 이러한 학생에 대한 보호․감독의무는 학교 내에서의 학생의 모든 생활관계에 미치는 것은 아니고 학교에서의 교육활동 및 이에 밀접불가분의 관계에 있는 생활관계에 한하며, 그 의무의 범위 내의 생활관계라고 하더라도 사고가 학교생활에서 통상 발생할 수 있다고 하는 것이 예측되거나 또는 예측가능성(사고발생의 구체적 위험성)이 있는 경우에만 교장이나 교사는 보호․감독의무위반에 대한 책임을 진다고 할 것이고, 그 예측가능성에 대하여는 교육활동의 때, 장소, 가해자의 분별능력, 가해자의 성행, 가해자와 피해자의 관계, 기타 여러 사정을 고려하여 판단할 필요가 있다.\n가해자와 피해자가 초등학교 6학년생들로서 비록 책임을 변식할 지능을 갖추지 못하고 있다고 하더라도 초등학교 6학년 정도라면, 대체로 학교생활에 적응하여 상당한 정도의 자율능력, 분별능력을 가지고 있다고 보아야 할 것이고, 가해자의 성격도 친구들과 잘 사귀고, 책임감이 강한 학생이었으며 피해자와도 원만한 사이였고, 이전에는 교실에서 학생들 사이에 아크릴판을 던지는 등의 장난 등은 없었던 경우, 호기심이 많은 학생들이 장난 등 돌발적인 행동을 할 가능성이 많다고 하여 자율학습이 시작되기 전에 교실에서 주인을 찾아주려는 마음에서 실과수업교재인 아크릴판을 던지는 등으로 인하"},{"n":116,"text":"여 잘못되면, 신체에 커다란 충격을 줄 수 있는 위험한 행위를 하리라는 구체적인 위험성이 있다거나 담임교사 등이 이를 예측하였거나 예측가능하였다고 보여지지는 아니하다면, 특별한 사정이 없는 한 돌발적이거나 우연한 사고에 대해서까지 교사 등에게 보호·감독의무위반의 책임을 지울 수는 없다. (정규 학습 시작시간 전에 교실에서 주인을 찾아주기 위해 아크릴판을 던져 중간에 앉아 있던 급우의 눈을 다치게 한 경우, 교사 등에게 보호·감독의무위반의 책임을 지울 수 없다고 했다).\nv 대법원 2008. 1. 17. 선고 2007다40437 판결: 유치원이나 학교의 원장·교장 및 교사는 교육기본법 등 관련 법령에 따라 그들로부터 교육을 받는 유치원생과 학생들을 친권자 등 법정감독의무자에 대신하여 보호·감독할 의무를 진다. 그런데 유치원생이나 학생들을 대상으로 한 교육활동이 유치원이나 학교에서만 이루어지는 것은 아니고, 특히 우리의 교육현실을 보면 학원의 설립·운영 및 과외교습에 관한 법률에 따라 설립·운영되는 학원이나 교습소에서 학교교육의 보충 또는 특기·적성교육을 위하여 지식·기술·예능을 교습하는 형태의 사교육이 광범위하게 이루어지고 있으며, 이러한 사교육은 학교 안에서 이루어지는 공교육 못지않은 중요한 역할을 수행하고 있는바, 공교육을 담당하는 교사 등과 마찬가지로 위와 같은 형태의 사교육을 담당하는 학원의 설립·운영자나 교습자에게도 당해 학원에서 교습을 받는 수강생을 보호·감독할 의무가 있다고 봄이 상당하다.\nv 대법원 2002. 12. 10. 선고 2000다55126 판결 : 국립 전남대학교에서 한총련 산하 남총련의 간부들이 엉뚱한 사람을 경찰프락치라고 속단하여 감금폭행하여 사망에 이르게 한 경우, 그 사망사고가 전남대학교의 불법행위자들에 대한 교육활동이나 이에 밀접한 생활관계와 연관성이 있다고 보기 어려울 뿐만 아니라 전남대학교에 학교생활에서 위와 같은 사망사고가 발생하리라는 점에 대한 예견가능성이 있었다고 보기 어렵다는 이유로 전남대학교(국가)측의 손해배상책임을 부정한 사례.\nv 대법원 2000. 4. 11. 선고 99다44205 판결 : [사실관계] 원고 2(피해학생)는 피고(인천시)에 소속된 하도진중학교 2학년 8반에 재학중이던 1996. 12. 14. 10:00경 체육시간이 끝나고 교실로 들어와 쉬는 시간에 같은 반 학생인 제1심 공동피고로부터 폭행을 당하여 좌측 안와골절상을 입게 되었는데, 폭행을 당한 이유는 원고 2등이 체육시간에 학교 담을 넘어 나갔다 오다가 들키는 바람에 체육교사인 소외 유00으로부터 같은 반 학생들이 단체로 벌을 받아 화가 났기 때문이다. (원고는 감독자책임을 물어 손해배상청구를 했고, 피고는 감독상의 과실이 없으며, 이 사건 사고가 우발적인 것이어서 예상할 수 없었다고 주장했다.)\n[원심의 판단] 유00 등 교사들은 원고 2등의 잘못으로 같은 반 학생들 모두에게 벌을 주었으면 혹시라도 다른 학생들이 이에 불만을 품고 원고 2등에게 앙갚음을 할 가능성이 있으므로 이를 방지하기 위하여 특별히 지도를 하였어야 할 의무가 있음에도 이를 게을리 한 잘못이 있으므로 피고는 위 유00 등의 사용자로서 원고들이 입은 손해를 배상할 책임이 있다.\n학교 교사로서는 어느 학생의 잘못으로 같은 반 학생 전체에게 벌을 주는 등의 특별한 경우에는 아직 성숙하지 아니한 중학생들이 이에 대한 앙갚음을 하는 등의 갑작스러운 행동을 할 수 있음을 충분히 예상하여야 한다.\n[대법원의 판단] 체육시간 수업 직후의 휴식시간은 다음 수업을 위하여 잠시 쉬거나 수업의 정리·준비 등을 하는 시간으로서 교육활동과 질적, 시간적으로 밀접 불가분의 관계에 있어, 그 시간 중의 교실 내에서의 학생의 행위에 대하여는 교사의 일반적 보호·감독의무가 미친다고 할 수 있다.\n그러나 이 사건 사고 당시 가해자인 제1심 공동피고(1982. 8. 12. 생)는 만 14세 4개월 정도로서 충분한 분별능력이 있고, 비록 공부를 못하고 성격이 급하나 본성이 착하여 평소 친구들을 때리거나 괴롭힌 일이 없으며, 피해자인 원고 2와 같은 급우로서 별문제 없이 지내왔고, 원고 2도 비록 공부는 못하나 심성이 고운 학생으로 친구들 사이에서 별다른 문제가 없는 학생이었으며, 유00이 단체기합을 주게 된 동기와 약 5분 정도에 걸쳐 쪼그려뛰기 20회, 엎드렸다 일어나기 20회, 팔벌려뛰기 20회를 실시한 체벌의 방법과 정도로 보아 교육적 차원에서 정당하고, 그 단체기합으로 인하여 같은 반 학생들이 원고 2등에게 반감을 가질 정도의 것은 아니라고 보이므로 이러한 가해자의 성행, 피해자와의 관계, 사고발생의 때와 장소 등을 고려할 때 체육교사인 유00이나 담임교사 등이 이 사건 사고를 예측하였거나 예측할 수 있었다고 보기 어렵고, 사고에 앞서 유00이 위와 같은 단체기합을 주었다는 사정만으로 사고의 발생에 대한 구체적 위험성이 있다고도 할 수 없다. 따라서 이 사건 사고는 돌발적이거나 우연한 사고로서 유00 등 교사에게 보호·감독의무 위반의 책임을 물을 수 없다고 보아야 할 것이다.\nv 대법원 1997. 6. 13. 선고 96다44433 판결 : 중학교 1학년생이 휴식시간에 먹고 있던 도시락에 급우가 오물을 떨어지게 했다는 이유로 그 급우를 구타하여 상해를 입힌 사안에서, 사고가 일어난 3교시 수업 직후의 휴식시간은 다음 수업을 위하여 잠시 쉬거나 수업의 정리, 준비 등을 하는 시간으로서 교육활동과 질적, 시간적으로 밀접 불가분의 관계에 있어, 그 시간 중의 교실 내에서의 학생의 행위에 대하여는 교사의 일반적 보호·감독의무가 미친다고 할 수 있으나, 가해자가 성격이 거칠어서 평소 자기보다 약한 급우를 괴롭히다가 담임교사로부터 꾸중을 듣기도 하였다고 하더라도 가해자는 중학교 1학년 학급의 반장으로서 학업성적이 우수하고 매사에 적극적이었으며 피해자와는 같은 반 친구로서 지내던 사이였으므로, 이러한 가해자의 성행, 피해자와의 관계, 사고발생의 때와 장소 등을 고려할 때 사고가 담임교사가 이를 예측하였거나 예측할 수 있었다고 보기 어려운 돌발적이거나 우연한 사고로서 담임교사에게 보호·감독의무 위반의 책임을 물을 수 없다.\nv 대법원 2007. 6. 15. 선고 2004다48775 판결 : [사실관계] 평소 망인과 그의 친구들은 학생들을 상대로 폭력을 행사하고 금품을 빼앗는 등의 행동을 해왔는데, 소외 1도 망인으로부터 피해를 당했다. 소외 1은 중학교 1학년 때부터 수시로"},{"n":117,"text":"보건실을 드나들면서 복통, 두통을 호소하고, 간혹 분노를 조절하지 못하는 모습을 보였다. 사고 당일 망인과 그의 친구들이 소외 1을 비롯한 여러 학생들을 폭행했고, 소외 1은 수업 중인 교실에 칼을 들고 들어가 망인을 찔러 사망에 이르게 했다.\n[법원의 판단] 이 사건 사고는 수업시간 중에 발생한 것으로 학교에서의 교육활동 중에 발생한 것이므로 교장이나 교사의 일반적 보호감독의무가 미친다고 할 수 있다.\n또한, 학교폭력이 상당히 사회문제화되고 있는 현실 속에서 학교를 설립하여 운영하는 지방자치단체인 피고 및 그 소속 교사들은 어느 특정 개인의 폭력성 여부를 떠나 폭력행위가 학교 내에서 발생하지 않도록 함으로써 학생들을 보호할 일반적 주의의무가 있다고 할 것인데, 이 사건을 살펴보면, 평소 망인과 그의 친구들은 학생들을 상대로 폭력을 행사하고 금품을 빼앗는 등의 행동을 해옴으로써 많은 학생들이 피해의식을 느껴왔고 교사들도 이를 알고 있었으므로 실효성 있는 대책을 강구하지 않으면 또 다른 폭력이 행해지리라는 것은 예견이 가능한 상태였다는 점, 이러한 와중에 망인과 그 친구들이 사고 당일 휴식시간 및 점심시간에 여러 학생들에 대한 폭행을 한 것이 결국 이 사건 사고의 직접적인 원인이 되었다는 점, 이러한 위 학교의 상황에 비추어 볼 때, 폭력성 있는 학생들로 인하여 시작된 폭력이 또 다른 폭력을 야기할 위험성을 내포하고 있었고 소외 1의 이 사건 가해행위는 이러한 위험성이 구체화되어 나타난 것으로 볼 수 있다는 점, 이 사건 사고는 학교 수업시간 중에 담당교사가 수업을 진행하는 면전에서 일어났다는 점 등을 종합하여 보면, 이 사건 사고가 피고나 그 소속교사들의 예견가능성의 범위를 벗어난 영역에서 발생하였다고 보기는 어렵다. [정리] 가해행위가 수업시간에 발생했다는 점과, 구체적 위험성이 실현되었다는 점에서 감독자책임을 인정했다.\nv 대법원 2002. 5. 10. 선고 2002다10585,10592 판결 : 유치원 운영자의 원아에 대한 단 1회의 성추행을 방지하지 못한 유치원 교사의 손해배상책임을 부정한 사례.\nv 대법원 2021. 7. 29. 선고 2018다228486 판결: [1] 구 정신보건법(2016. 5. 29. 법률 제14224호 정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률로 전부 개정되기 전의 것, 이하 같다) 제3조 제1호는 ‘정신질환자’란 ‘정신병(기질적 정신병을 포함한다)·인격장애·알코올 및 약물중독 기타 비정신병적정신장애를 가진 자’라고 정의하고 있고, 제21조 제1항 본문은 “정신질환자의 민법상의 부양의무자 또는 후견인(이하 ‘부양의무자 등’이라 한다)은 정신질환자의 보호의무자가 된다.”라고 정하고 있다. 또한 제22조 제2항은 “보호의무자는 보호하고 있는 정신질환자가 자신 또는 타인을 해치지 아니하도록 유의하여야 한다.”라고 정하여 부양의무자 등에게 피보호자인 정신질환자에 대한 감독의무를 부과하고 있다.\n정신질환자가 심신상실 중에 타인에게 손해를 가하여 배상의 책임이 없는 경우에는 제755조 제1항에 따라 그를 감독할 법정의무 있는 자가 손해를 배상할 책임이 있다. 정신질환자가 책임능력이 있는 경우에도 그 손해가 감독의무자의 감독의무 위반과 인과관계가 있으면 감독의무자는 일반불법행위자로서 제750조에 따라 손해를 배상할 책임이 있다.\n위와 같은 법규정의 문언과 체계 등에 비추어 보면, 부양의무자 등은 피보호자인 정신질환자에 대한 법률상 감독의무를 부담하므로 그 의무 위반으로 타인에게 손해를 가하는 경우에 이를 배상할 책임이 있으나, 이러한 감독의무는 정신질환자의 행동을 전적으로 통제하고 그 행동으로 인한 모든 결과를 방지해야 하는 일반적인 의무가 아니라 구 정신보건법 등 관련 법령의 취지, 신의성실의 원칙, 형평의 원칙 등을 종합적으로 고려하여 합리적으로 제한된 범위에서의 의무라고 해석함이 타당하다.\n구체적인 사안에서 부양의무자 등이 피보호자인 정신질환자에 관한 감독의무를 위반하였는지는 정신질환자의 생활이나 심신의 상태 등과 함께 친족 관계와 동거 여부, 일상적인 접촉 정도, 정신질환자의 재산관리 관여 상황 등 정신질환자와의 관계, 정신질환자가 과거에도 타인에게 위해를 가하는 행동을 한 적이 있는지 여부와 그 내용, 정신질환자의 상태에 대응하는 보호와 치료 상황 등 모든 사정을 종합적으로 고려하여, 피보호자인 정신질환자가 타인을 위해할 가능성이 있다는 구체적인 위험을 인지하였는데도 대비를 하지 않은 경우와 같이 부양의무자 등에게 정신질환자의 행위에 관해서 책임을 묻는 것이 타당한 객관적 상황이 인정되는지 여부에 따라 개별적으로 판단해야 한다.\n[2] 양극성 정동장애를 앓고 있는 정신질환자인 甲이 아파트 방에서 불을 질렀다가 甲의 아버지인 乙이 불을 껐는데, 약 4시간 후 甲이 방 안에서 다시 불을 질러 인접 호수의 아파트로 불이 옮겨붙어 丙 등에게 손해가 발생한 사안에서, 乙에게는 甲이 타인을 위해할 가능성이 있다는 구체적인 위험을 인지하였는데도 대비를 하지 않아 甲의 행위에 관해서 책임을 묻는 것이 타당한 객관적 상황이 인정되므로, 乙이 甲의 직계존속으로서 甲의 방화 등 우발적인 행동을 미리 방지하고 이와 같은 우발적인 행동이 있더라도 손해가 발생하거나 확대되지 않도록 할 주의의무가 있었는데도 이를 위반한 과실로 丙 등에게 손해가 발생하였다는 이유로 乙의 손해배상책임을 인정한 원심판단이 정당하다고 한 사례\n(3) 인과관계의 존재\n감독의무 해태와 책임무능력자의 가해행위 사이에 인과관계가 존재해야 한다. 즉, 감독의무자가 감독을 게을리하지 않았더라도 손해가 생겼으리라는 것이 입증되면 감독의무자는 그 책임을 면할 수 있다. 이와 같이 감독의무자 등이 인과관계의 부존재를 증명함으로써 면책될 수 있는가에 대하여 ① 다수설은 제756조 제1항 단서를 유추하여 면책을 긍정하는 반면, ② 소수설은 피감독자의 위법행위로 발생한 손해를 감독의무자 등이 대신 배상하는 것이 책임무능력자의 감독자책임의 기본취지이므로 인과관계의 존부와 관계없이 감독의무자 등은 책임을 진다고 본다. 현실적으로는 감독의무자가 감독을 게을"},{"n":118,"text":"리하지 않았더라도 손해가 생겼으리라는 것을 입증하는 것은 거의 불가능하다.\n3. 효과\n책임무능력자에 갈음하여 배상책임을 부담하는 것은 법정감독의무자 및 감독의무자에 갈음하여 책임무능력자를 감독하는 대리감독자이다. 책임무능력자의 법정감독의무자는 미성년자의 경우 친권자(제913조)와 후견인(제945조)이고, 금치산자에 있어서는 후견인(제947조)이다. 금치산선고를 받지 않은 심신상실자의 경우 관습법 또는 조리에 의하여 적당한 지위에 있는 자가 그 감독의무자가 된다. 판례는 조리상 妻, 부모 등의 순서로 감독의무자가 된다고 한다(대판 1957. 7. 25. 4290민상302). 대리감독자가 법정감독의무자에 갈음하여 감독하게 된 이유는 계약에 의하든 또는 법률에 의하든 이를 묻지 않는다. 손해배상범위(제393조)에서 ‘특별한 사정’에 대한 인식은 감독자를 기준으로 결정한다.\n만일 이들의 책임이 모두 발생한 경우에 ① 대리감독자가 감독의무를 다하였음에도 피감독자의 가해행위가 있었던 경우라면 최종적으로 법정감독의무자에게 배상책임이 있다고 할 것이며, 대리감독자를 두었다는 사실만 가지고서 곧 법정감독의무자의 감독책임이 면책될 수는 없다. ② 대리감독자도 감독의무를 다하지 않고 법정감독의무자도 대리감독자에게 감독케 한 것에 과실이 없었음을 증명하지 못하여 책임을 지게 되는 경우 양자의 책임은 부진정연대채무의 관계에 있게 된다. 따라서 피해자는 전부의 배상을 받을 때까지 어느 쪽에 대해서도 책임을 물을 수 있다.\nv 대법원 2007. 4. 26. 선고 2005다24318 판결 : [1] 민법 제755조에 의하여 책임능력 없는 미성년자를 감독할 친권자 등 법정감독의무자의 보호·감독책임은 미성년자의 생활 전반에 미치는 것이고, 법정감독의무자에 대신하여 보호·감독의무를 부담하는 교사 등의 보호·감독책임은 학교 내에서의 학생의 모든 생활관계에 미치는 것이 아니라 학교에서의 교육활동 및 이와 밀접 불가분의 관계에 있는 생활관계에 한하며, 이와 같은 대리감독자가 있다는 사실만 가지고 곧 친권자의 법정감독책임이 면탈된다고는 볼 수 없다.\n[2] 지방자치단체가 설치·경영하는 학교의 교장이나 교사는 학생을 보호·감독할 의무를 지는데, 이러한 보호·감독의무는 교육법에 따라 학생들을 친권자 등 법정감독의무자에 대신하여 감독을 하여야 하는 의무로서 학교 내에서의 학생의 모든 생활관계에 미치는 것은 아니지만, 학교에서의 교육활동 및 이와 밀접 불가분의 관계에 있는 생활관계에 속하고, 교육활동의 때와 장소, 가해자의 분별능력, 가해자의 성행, 가해자와 피해자의 관계, 기타 여러 사정을 고려하여 사고가 학교생활에서 통상 발생할 수 있다고 하는 것이 예측되거나 또는 예측가능성(사고발생의 구체적 위험성)이 있는 경우에는 교장이나 교사는 보호·감독의무 위반에 대한 책임을 진다.\n[3] 학교폭력 가해학생들의 부모의 과실과 담임교사, 교장의 과실이 경합하여 피해학생의 자살 사건이 발생하였다는 이유로, 부모들과 지방자치단체에게 공동불법행위자로서의 손해배상책임을 인정한 사례.\n4. 책임능력 있는 미성년자의 감독자책임\n(1) 문제점\n책임능력 있는 미성년자가 가해행위를 한 경우, 제755조의 문언에 따르면 친권자나 감독자들은 손해배상책임을 지지 않는다. 그러나 미성년자들은 일반적으로 변제자력이 없기 때문에 이 경우 피해자 구제가 사실상 불가능해지는 불합리한 결과가 초래된다. 따라서 책임능력 있는 미성년자의 불법행위로 발생한 피해자의 손해를 구제하기 위하여 제755조의 문언을 피할 수 있는 이론이 필요하게 된다.\nv 대법원 1989. 1. 24. 선고 87다카2118 판결 : [사실관계] 소외 1은 만 18세로 고등학교 3학년 재학 중에 운전면허 없이 친구인 소외 최00을 무등록의 90씨씨 오토바이 뒷좌석에 태우고 운행하다 소외회사의 차량과 충돌하여 위 최00으로 하여금 뇌좌상 등의 상해를 입게 하였다. 위 소외회사와 자동차종합보험계약을 체결한 원고는 소외회사를 대위하여 위 최00과 그 부모 등에게 손해배상금을 지급하였다. 원고는 가해자인 소외 1의 부모에게 구상금을 청구하였다.\n[원고의 주장] 피고들은 미성년자인 소외 1의 감독의무자로서 위 사고로 인한 최00등의 손해를 위 소외회사와 연대하여 배상할 의무가 있는데 원고가 위 소외회사를 대위하여 그 손해전부를 배상하였으므로 위 소외 회사의 피고들에 대한 구상금채권을 구한다.\n[법원의 판단] 소외1은 사회통념상 자기행위에 대한 책임을 변식할 지능이 있었다고 볼 수 있으므로 그 친권자인 피고들에"},{"n":119,"text":"게는 아들의 불법행위에 대한 아무런 책임이 없다.\n(2) 학설 및 판례\n㈀ 제755조 확대적용설 : 제755조가 정하는 감독자책임은 미성년자에게 책임능력이 없는 경우 발생하는 보충적 책임이 아니라, 미성년자의 책임과 감독자의 책임이 병존한다는 사실을 표현한 것이라고 이해하는 견해이다. 즉, 감독자의 책임은 위험책임과 같은 성질을 갖는다고 이해하는 견해이다. 그러나 이 견해는 법문에 정면으로 배치되어 해석의 한계를 벗어난다는 비판을 받는다.\n㈁ 제750조 적용설 : 친권자는 子를 보호하고 교양할 권리·의무가 있으므로(제913조), 친권자의 子에 대한 교양의무위반과 손해발생 사이에 상당인과관계가 있으면 친권자는 민법 제750조의 일반불법행위책임을 부담한다는 견해이다. 이 경우 의무위반은 일반적으로 子에 대한 교양의무 등 감독의무 위반을 의미하는 것이며, 문제가 된 불법행위 자체와 관련된 감독의무 위반을 의미하는 것은 아니다.\n㈂ 판례 : 판례는 우여곡절을 겪은 끝에 1994년의 전원합의체판결 이후 책임능력 있는 미성년자의 감독의무자 책임을 제750조에 따른 책임으로 인정하고 있다. 감독의무자가 제750조에 의해 배상책임을 지는 경우, 감독의무위반 및 의무위반과 손해발생 간의 상당인과관계의 존부는 이를 주장하여 손해배상을 청구하는 피해자 측에서 입증해야 한다.\nv 대법원 1994. 2. 8. 선고 93다13605 판결 전원합의체 판결 : 책임능력 없는 미성년자를 감독할 법정의 의무 있는 자가 지는 손해배상책임은 그 미성년자에게 책임이 없음을 전제로 하여 이를 보충하는 책임이고, 그 경우에 감독의무자 자신이 감독의무를 해태하지 아니하였음을 입증하지 아니하는 한 책임을 면할 수 없는 것이나, 반면에 미성년자가 책임 능력이 있어 그 스스로 불법행위책임을 지는 경우에는 그 손해가 당해 미성년자의 감독의무자의 의무위반과 상당인과관계가 있으면 감독의무자는 일반 불법행위자로서 손해배상 책임이 있다 할 것이므로, 이 경우에 그러한 감독의무위반사실 및 손해발생과의 상당인과관계의 존재는 이를 주장하는 자가 입증하여야 할 것이다. 당원 1984. 7. 10. 선고,84다카474 판결의 해석은 위와 같은 견해와 저촉되는 것이므로 이를 변경하기로 한다.\n소외 김00(미성년자)은 그가 오토바이를 운전하던 중 일으킨 교통사고 당시 만 17세 9개월 남짓된 고등학교 3학년생으로서 자기 행위에 대한 책임을 변식할 지능이 있었으므로 그 부모인 피고들은 피해자(원고들)에 대하여 민법 제755조 제1항에 의한 손해배상책임이 없고, 위 김00은 이 사건 사고를 일으키기 8개월여전에 원동기장치자전거운전면허를 취득하였는데, 그 판시와 같은 원고들의 입증만으로는 피고들이 위 김00에 대한 감독을 게을리한 과실이 있고, 그로 말미암아 위 사고가 발생하였다고 인정하기에 부족하고, 달리 증거가 없으므로 피고들에게는 민법 제750조에 의한 손해배상책임이 없다.\nF 민법초안 제750조(입법되었다면 제756조 다음에 규정되었을 것) : “전 4조의 규정에 의하여 미성년자, 심신상실자, 감독의무자 또는 사용인에게 손해배상의 책임이 없는 경우에도 법원은 당사자의 경제상황 및 기타 사정을 참작하여 그에게 손해의 전부 또는 일부의 배상을 명할 수 있다.” 그러나 무과실책임은 특별법을 통해 인정하는 것이 타당하다는 이유로 삭제됨.\nv 대법원 1997. 3. 28. 선고 96다15374 판결 : [사실관계] 사고 당시 17세 남짓한 피고 2는 부모인 피고 3, 4와 동거하면서 운전면허가 없음에도 가끔 그의 숙부인 피고 서00 소유의 사고 화물차를 운전한 적이 있다.\n황색점멸등이 설치되어 있는 삼거리 교차로상에서 피고 2가 운전하던 피고 1소유의 화물차와 원고 1이 운전하던 오토바이가 충돌하였다. 피고 2가 먼저 교차로에 진입하기는 하였지만 마주오던 오토바이의 동태를 주의깊게 살피지 아니한 채 급하게 교차로를 통과하려고 하다가 오토바이를 충돌한 과실이 있다. 원고 1으로서도 운전면허 없이 주취상태에서 안전모도 착용하지 아니한 채 화물차보다 먼저 교차로를 통과하기 위하여 무리하게 교차로에 진입한 과실이 있다(원고 1의 과실비율 60%)\n[법원의 판단] 피고3, 4는 피고 2의 부모로서 미성년의 아들이 무면허운전을 하지 못하도록 보호감독하여야 할 주의의무를 게을리하여 사고 화물차를 운전하도록 방치한 과실이 있고, 피고 3, 4의 위와 같은 보호감독상의 과실은 사고 발생의 원인이 되었으므로 원고들이 입은 손해를 배상할 책임이 있다.\nv 대법원 2022. 4. 14. 선고 2020다240021 판결: 미성년자가 책임능력이 있어 스스로 불법행위책임을 지는 경우에도 그 손해가 미성년자의 감독의무자의 의무 위반과 상당인과관계가 있으면 감독의무자는 제750조에 따라 일반불법행위자로서 손해배상책임이 있다. 이 경우 그러한 감독의무 위반사실과 손해 발생과의 상당인과관계는 이를 주장하는 자가 증명하여야 한다.\n미성년 자녀를 양육하며 친권을 행사하는 부모는 자녀를 경제적으로 부양하고 보호하며 교양할 법적인 의무가 있다(제913조). 부모와 함께 살면서 경제적으로 부모에게 의존하는 미성년자는 부모의 전면적인 보호·감독 아래 있으므로, 그 부모는 미성년자가 타인에게 불법행위를 하지 않고 정상적으로 학교 및 사회생활을 하도록 일반적, 일상적으로 지도와"},{"n":120,"text":"조언을 할 보호·감독의무를 부담한다. 따라서 그러한 부모는 미성년자의 감독의무자로서 위에서 본 것처럼 미성년자의 불법행위에 대하여 손해배상책임을 질 수 있다.\n그런데 이혼으로 인하여 부모 중 1명이 친권자 및 양육자로 지정된 경우 그렇지 않은 부모(이하 ‘비양육친’이라 한다)에게는 자녀에 대한 친권과 양육권이 없어 자녀의 보호·교양에 관한 제913조 등 친권에 관한 규정이 적용될 수 없다. 비양육친은 자녀와 상호 면접교섭할 수 있는 권리가 있지만(제837조의2 제1항), 이러한 면접교섭 제도는 이혼 후에도 자녀가 부모와 친밀한 관계를 유지하여 정서적으로 안정되고 원만한 인격발달을 이룰 수 있도록 함으로써 자녀의 복리를 실현하는 것을 목적으로 하고, 제3자와의 관계에서 손해배상책임의 근거가 되는 감독의무를 부과하는 규정이라고 할 수 없다. 비양육친은 이혼 후에도 자녀의 양육비용을 분담할 의무가 있지만, 이것만으로 비양육친이 일반적, 일상적으로 자녀를 지도하고 조언하는 등 보호·감독할 의무를 진다고 할 수 없다. 이처럼 비양육친이 미성년자의 부모라는 사정만으로 미성년 자녀에 대하여 감독의무를 부담한다고 볼 수 없다.\n다만 비양육친도 부모로서 자녀와 면접교섭을 하거나 양육친과의 협의를 통하여 자녀 양육에 관여할 가능성이 있는 점을 고려하면, ① 자녀의 나이와 평소 행실, 불법행위의 성질과 태양, 비양육친과 자녀 사이의 면접교섭의 정도와 빈도, 양육 환경, 비양육친의 양육에 대한 개입 정도 등에 비추어 비양육친이 자녀에 대하여 실질적으로 일반적이고 일상적인 지도, 조언을 함으로써 공동 양육자에 준하여 자녀를 보호·감독하고 있었거나, ② 그러한 정도에는 이르지 않더라도 면접교섭 등을 통해 자녀의 불법행위를 구체적으로 예견할 수 있었던 상황에서 자녀가 불법행위를 하지 않도록 부모로서 직접 지도, 조언을 하거나 양육친에게 알리는 등의 조치를 취하지 않은 경우 등과 같이 비양육친의 감독의무를 인정할 수 있는 특별한 사정이 있는 경우에는, 비양육친도 감독의무 위반으로 인한 손해배상책임을 질 수 있다.\nⅢ. 사용자의 책임\n제756조【사용자의 배상책임】 ① 타인을 사용하여 어느 사무에 종사하게 한 자는 피용자가 그 사무집행에 관하여 제3자에게 가한 손해를 배상할 책임이 있다. 그러나 사용자가 피용자의 선임 및 그 사무감독에 상당한 주의를 한 때 또는 상당한 주의를 하여도 손해가 있을 경우에는 그러하지 아니하다.\n② 사용자에 갈음하여 그 사무를 감독하는 자도 전항의 책임이 있다.\n③ 전2항의 경우에 사용자 또는 감독자는 피용자에 대하여 구상권을 행사할 수 있다.\n[사례] 식당을 운영하던 甲은 일손이 부족하자 자신의 친구 乙에게 하루 정도 식당일을 도와줄 것을 부탁하였고, 이에 乙은 甲의 식당에서 일하게 되었다. 일을 하던 중 乙은 손님 丙과 다투다 폭행을 가하여 丙에게 상해를 입혔다. 이때 丙은 누구를 상대로 손해배상을 청구할 수 있는가?\n《解說》 사안에서 丙은 우선 직접가해자인 乙에 대하여 불법행위(제750조)의 책임을 물을 수 있다. 그리고 甲에게 손해배상을 청구할 수 있는지가 문제 되는데, 丙이 甲에게 손해배상을 청구할 수 있기 위해서는 사용자책임의 성립요건, 즉 ㈀ 피용자의 가해행위, ㈁ 사용관계, ㈂ 가해행위의 사무집행관련성, ㈃ 선임·감독상의 주의의무의 결여라는 요건을 갖추어야 한다. 사안에서 특히 문제가 되는 것은 甲-乙 간에 사용관계가 존재하는지가 문제 되는데, 비록 호의로 일을 해주기는 하였으나 업무와 관련해서 甲이 乙을 지휘·감독하는 관계에 있다고 보여지므로 甲은 丙에게 사용자책임을 부담하는 것으로 보아야 한다.\n1. 사용자책임 일반\n(1) 의의\n타인을 사용하여 어느 사무에 종사하게 한 자와 그 자에 갈음하여 그 사무를 감독하는 자는 피용자가 사무집행에 관하여 제3자에게 행한 가해행위와 그로 인한 손해에 대하여 배상책임을 부담한다(제756조 제1항). 이를 사용자책임이라고 한다. 타인을 사용하여 자신의 활동범위를 넓히고, 이로 인해 이익을 얻은 자는 바로 그 사유로 인한 불이익에 대해서도 책임을 져야 하기 때문이다(보상책임의 원리). 다만, 사용자가 피용자의 선임 및 감독에 상당한 주의를 한 경우, 또는 상당한 주의를 하여도 손해가 있을 경우에는 그 책임을 지지 않는다(제756조 제1항 제2문).\nF 민법 제756조는 가사노동적 사용관계뿐만 아니라 널리 기업에 있어서의 사용관계에도 적용된다. 오늘날의 기업은 다수의 피용자를 유기적으로 조직하여 거대한 수익을 올리고 있으며, 한편으로는 그러한 기업활동을 위하여 피할"},{"n":121,"text":"수 없는 위험이 따르는 기계나 시설을 가지고 있다. 따라서 기업의 개개의 피용자가 외부 제3자에게 준 손해는 이를 기업으로 하여금 배상케 하는 것이 공평할 뿐만 아니라, 피해자에게도 충분한 구제를 얻을 수 있는 방법이 된다. 기업책임 일반에 대하여 특별한 규정을 두고 있지 않은 우리나라의 경우 따라서 민법 제756조는 중요한 역할을 한다. 그러나 민법 제756조는 사용자에게 면책사유를 인정하고, 피용자에 대한 사용자의 구상권을 인정하고 있어서 기업책임 규정으로는 불충분하다. 따라서 판례는 ‘사무집행에 관하여’라는 요건을 완화하여 해석하고, 사용자의 면책을 쉽게 인정하지 않는 등 사용자의 책임을 널리 인정하려고 노력하고 있다.\nv 대법원 2009. 6. 11. 선고 2008다79500 판결: 피용자가 권한 없이 사용자를 대리하여 한 법률행위가 상대방에 대한 관계에서 기망에 의한 불법행위에 해당하여 사용자가 손해배상책임을 지는 경우에, 사용자가 피용자의 무권대리행위를 추인하였다고 하더라도 그것만으로는 이미 성립된 사용자책임이 소멸되는 것이라고 볼 수 없다.\n(2) 본질\n사용자책임의 본질에 대해서는 사용자책임의 목적이 피해자의 피용자에 대한 손해배상청구권을 사용자책임을 통해 보장해 주는 데 있다고 보는 「대위책임설」과 사용자책임이 피해자에 대한 관계에서 응당 사용자 자신이 부담해야 할 배상책임이라고 보는 「고유책임설」이 있다.\n㈀ 대위책임설(多)에 의하면 사용자책임은 피용자가 불법행위책임을 지는 경우에만 발생하고, 피용자가 궁극적으로 부담하여야 할 배상의무를 마치 연대보증인처럼 사용자가 대신 변제해 주는 기능을 한다. 따라서 피해자에게 배상해 준 사용자는 언제나 피용자에게 전액 구상할 수 있다고 본다. 다만, 경우에 따라서 신의칙에 의하여 구상범위를 제한할 수 있을 뿐이다.\n㈁ 고유책임설에 의하면 사용자는 피용자의 선임·감독을 제대로 하지 못하였다는 사용자 자신의 고유한 부주의에 대하여 책임을 지는 것이기 때문에, 자신의 과책이 인정되는 범위에서 피용자의 과실이나 책임능력이 없는 경우에도 손해배상책임을 지게 된다. 또한 피용자에 대한 대내적 관계에서도 사용자는 자신의 부주의에 해당하는 고유한 부담부분을 갖게 되며, 따라서 피용자에 대한 구상권은 그 범위에서 제한된다.\n㈂ 판례는 대위책임설의 입장을 취하고 있다.\n대위책임설(배상보장설) 고유책임설(자기책임설) 개념 피해자구제를 위해 사용자가 피용자를 대신하여(代位) 배상 사용자 자신의 선임·감독상 과실에 대한 책임 피용자의 행위 피용자의 행위가 불법행위에 해당될 것을 요함 피용자의 과실이나 책임능력과는 무관함 면책가능성 없음 있음 우리 민법은 면책가능성을 인정하고 있으나, 실제로는 대부분의 경우 면책이 인정되지 않는다는 점에서 대위책임설과 고유책임설의 중간형태를 취하고 있음 구상권 인정(신의칙상 일부 제한) 불인정(단, 부담부분이 있을 뿐)\nv 대법원 2017. 4. 27. 선고 2016다271226 판결 : 일반적으로 사용자가 피용자의 업무수행과 관련하여 행하여진 불법행위로 인하여 직접 손해를 입었거나 피해자인 제3자에게 사용자로서의 손해배상책임을 부담한 결과로 손해를 입게 된 경우에 사용자는 사업의 성격과 규모, 시설의 현황, 피용자의 업무내용과 근로조건 및 근무태도, 가해행위의 발생원인과 성격, 가해행위의 예방이나 손실의 분산에 관한 사용자의 배려의 정도, 기타 제반 사정에 비추어 손해의 공평한 분담이라는 견지에서 신의칙상 상당하다고 인정되는 한도 내에서만 피용자에 대하여 손해배상을 청구하거나 구상권을 행사할 수 있고, 이러한 구상권 제한의 법리는 사용자의 보험자가 피용자에 대하여 구상권을 행사하는 경우에도 다를 바 없다.\n(3) 제391조의 이행보조자의 책임과의 구별\n사용자책임은 자신을 위해서 일하는 자(이행보조자, 피용자)의 행위에 대한 책임이라는 점에서 이행보조자의 책임과 공통점을 갖고 있다. 그러나 이행보조자책임과 달리 사용자책임은 ① 채권관계가 전제되지 않으며, ② 독립적 청구권의 기초가 되고, ③ 면책가능성이 있다는 점에서 구별된다."},{"n":122,"text":"v 대법원 2005. 1. 27. 선고 2004다12394 판결 : 영업용 보세창고업자가 수입화물의 실수입자와의 임치계약에 의하여 수입화물을 보관하게 되는 경우, 운송인 또는 그 국내 선박대리점의 입장에서는 수입화물이 자신들의 지배를 떠나 수하인에게 인도된 것은 아니고 보세창고업자를 통하여 수입화물에 대한 지배를 계속하고 있다고 볼 수 있으므로, 보세창고업자는 수입화물에 대한 통관절차가 끝날 때까지 수입화물을 보관하고 적법한 수령인에게 수입화물을 인도하여야 하는 운송인 또는 그 국내 선박대리점의 의무이행을 보조하는 지위에 있다고 할 수 있으나, 영업용 보세창고업자는 일반적으로 독립된 사업자로서 자신의 책임과 판단에 따라 화물을 보관하고 인도하는 업무를 수행하고 운송인 또는 그 국내 선박대리점의 지휘·감독을 받아 수입화물의 보관 및 인도업무를 수행하는 것이라고는 할 수 없으므로 특별한 사정이 없는 한 운송인 및 그 국내선박대리점이 영업용 보세창고업자에 대하여 민법상 사용자의 지위에 있다고 볼 수는 없다.\n2. 사용자책임의 요건\n(1) 피용자의 가해행위로 제3자에게 손해가 발생할 것\n피용자가 제3자에게 위법한 가해행위를 하고 제3자에게 손해를 준 경우여야 한다. 여기서 제3자는 가해행위를 한 피용자 및 사용자책임을 지는 사용자를 제외한 그 밖의 자를 말한다. 가해 피용자의 동료 피용자도 해당함은 물론이다.\n그런데 피용자의 가해행위는 반드시 제750조의 요건을 충족해야 하는가에 대하여 의문이 제기된다. 즉, 피용자가 위법한 가해행위를 하였으나, 피용자의 과실이 없는 경우에도 사용자책임은 성립할 수 있는가?\n㈀ 대위책임설(피용자 과실요건설) : 피용자의 과실 및 책임능력도 사용자책임의 요건이라고 한다. 사용자가 피용자의 과실이 없는 행위까지 책임을 지는 것은 가혹하기 때문이며, 민법 제756조 제3항의 구상권 행사규정은 간접적으로 피용자의 불법행위성립을 전제한 것으로 해석되기 때문이다.\nv 대법원 1981. 8. 11. 선고 81다298 판결 : 책임무능력자(국민학교 1학년생)의 대리감독자(담임교사)에게 민법 제755조 제2항에 의한 배상책임이 있다고 하여 위 대리감독자의 사용자 또는 사용자에 갈음한 감독자(위 학교를 설립 경영하는 지방자치단체)에게 당연히 민법 제756조에 의한 사용자책임이 있다고 볼 수는 없으며, 책임무능력자의 가해행위에 관하여 그 대리감독자에게 고의 또는 과실이 인정됨으로써 별도로 불법행위의 일반 요건을 충족한 때에만 위 대리감독자의 사용자 또는 사용자에 갈음한 감독자는 민법 제756조의 사용자책임을 지게 된다.\n㈁ 고유책임설 : 고유책임설은 사용자책임의 성립에 피용자의 과실 및 책임능력은 필요하지 않다고 본다(고유책임설 중 무과실책임설). 그 근거로 다음 네 가지를 든다. ① 사용자책임은 사용자가 피용자를 사용하여 그 자신의 활동을 확대하고 그로 인하여 발생된 피용자의 침해행위도 사용자의 행위범주 내의 행위로 평가되어야 한다. ② 사용자의 불충분한 작업지시 또는 부적격한 기구제공 때문에 피용자의 가해행위가 야기된 경우라면 피용자 자신의 과실 및 불법행위책임은 부정될 수 있지만, 사용자책임은 부인되어서는 안 되기 때문이다. 이 경우 대위책임설(피용자과실요건설)에 의하면 사용자책임이 부인되는 부당한 결과가 발생한다. ③ 민법에는 사용자책임의 요건으로서 피용자의 과실을 요구하지 않고 있다. 대위책임설(피용자과실요건설)은 제756조 제3항이 법적 근거가 된다고 주장하나 제756조 제3항은 사용자책임의 대내관계에 관한 구상권조항으로서 대외관계에서 인정되는 사용자책임의 발생요건과는 무관하다. ④ 사용자책임에 관한 소송에서 피해자로 하여금 피용자에 관한 불법행위성립의 모든 요건과 그에 추가하여 사용자책임의 성립요건을 입증하도록 하는 것은 가혹하기 때문이다.\n(2) 사용관계의 존재\n사용자와 피용자 사이에 사용관계 또는 사무감독관계가 있어야 한다. 사용관계는 고용계약에 기초한 고용관계나 근로계약관계보다 넓은 개념으로 사용관계가 실질적으로 존재하면 족하고 그 원인관계의 유무와 유효 여부, 보수의 유무나 기간의 장단에 관계없이 인정된다. 즉, 법률적인 사용관계가 아니어도 실질적으로 사용관계에 있으면 인정된다(실질적 지휘 감독관계). 결국 사용관계의 존부는 실질적으"},{"n":123,"text":"로 지휘·감독의 관계에 있는가에 따라 판단된다. 그 외에도 실제로 사용지시를 하지 않았다 하더라도 외부적으로 사용관계를 표시하고 있는 경우에도 사용관계의 존재가 인정된다(명의대여자의 사용자책임).\nv 대법원 1998. 8. 21. 선고 97다13702 판결 : [1] 민법 제756조 소정의 사용자와 피용자의 관계는 반드시 유효한 고용관계가 있는 경우에 한하는 것이 아니고, 사실상 어떤 사람이 다른 사람을 위하여 그 지휘·감독 아래 그 의사에 따라 사무를 집행하는 관계에 있으면 족한 것이며, 타인에게 위탁하여 계속적으로 사무를 처리하여 온 경우 객관적으로 보아 그 타인의 행위가 위탁자의 지휘·감독의 범위 내에 속한다고 보이는 경우 그 타인은 민법 제756조에 규정한 피용자에 해당한다.\n[2] 여객선안전관리요강 제6조 제4항에 의하여 여객선의 선장으로서 운항관리자의 업무를 처리해 온 자는 그가 고용된 운송회사에 대해서뿐만 아니라 한국해운조합과의 관계에서도 피용자의 지위에 있으므로, 그 선장의 과실로 발생한 여객선의 침몰사고에 대하여 한국해운조합이 사용자책임을 부담한다고 본 사례.\n[3] 지방해운항만청 해무과 직원들에게 침몰된 사고 여객선 선장의 선박운항 상태에 관한 감독의무를 게을리한 과실이 있다는 이유로 국가배상책임을 인정한 사례.\nv 대법원 2003. 12. 26. 선고 2003다49542 판결: 제756조의 사용자와 피용자의 관계는 반드시 유효한 고용관계가 있는 경우에 한하는 것이 아니고, 사실상 어떤 사람이 다른 사람을 위하여 그 지휘·감독 아래 그 의사에 따라 사업을 집행하는 관계에 있을 때에도 그 두 사람 사이에 사용자, 피용자의 관계가 있다고 할 수 있으며, 피용자의 불법행위가 외형상 객관적으로 사용자의 사업활동 내지 사무집행행위 또는 그와 관련된 것이라고 보일 때에는 행위자의 주관적 사정을 고려함이 없이 이를 사무집행에 관하여 한 행위로 볼 것이고, 외형상 객관적으로 사용자의 사무집행에 관련된 것인지의 여부는 피용자의 본래 직무와 불법행위와의 관련 정도 및 사용자에게 손해발생에 대한 위험 창출과 방지조치 결여의 책임이 어느 정도 있는지를 고려하여 판단하여야 한다.\n1) 실질적 사용지시관계\n가. 의의\n사용관계는 반드시 유효한 고용관계에 한하지 않으며, 고용계약에 기초한 고용관계 또는 근로계약관계보다 넓은 개념이다. 유효한 고용계약이 없더라도 사실상 어떤 사람이 다른 사람을 위하여 그 지휘·감독 아래 그의 의사에 따라 사무를 집행하는 관계(실질적 지휘·감독관계)에 있으면 족하다.\nv 대법원 1996. 10. 11. 선고 96다30182 판결 : 민법 제756조의 사용자와 피용자의 관계는 반드시 유효한 고용관계가 있는 경우에 한하는 것이 아니고, 사실상 어떤 사람이 다른 사람을 위하여 그 지휘·감독 아래 그 의사에 따라 사업을 집행하는 관계에 있을 때에도 그 두 사람 사이에 사용자, 피용자의 관계가 있는 것이라고 할 것이다.\n피고가 경영하는 이삿짐센터에서는 오랫동안 이삿짐 운반에 종사해 온 이른바 '고정직'이라고 불리는 작업원들의 이름표를 이삿짐센터 내에 걸어두고 대부분의 화물운반 작업을 위 작업원들에게 담당시키고 있었고, 위 작업원들이 이삿짐센터에 항상 대기하면서 화물운반 의뢰가 들어오면 피고의 지시로 화물운반 작업에 나가고 있었던 점 및 소외 김선진은 고정직이라고 불리는 작업원이었던 점 등에 비추어, 김선진은 피고의 피용자라고 판단하였음은 옳다.\n[정리] 이삿짐센터와 고용관계에 있지는 않았으나, 오랫동안 그 이삿짐센터의 이삿짐 운반에 종사해 온 작업원들을 사용자의 손해배상책임에 있어서 피용자라고 본 사례.\nv 대법원 1999. 10. 12. 선고 98다62671 판결 : [1] 사용자책임은 타인을 사용하여 어느 사무에 종사하게 한 자로 하여금 피용자가 그 사무집행에 관하여 제3자에게 가한 손해를 배상하게 하는 것으로서, 사용자책임이 성립하려면 사용자와 불법행위자 사이에 사용관계, 즉 사용자가 불법행위자를 실질적으로 지휘·감독하는 관계에 있어야 한다.\n[2] 국립대학교 소속 체조코치가 시체육회로부터 전국체전에 출전할 체조대표선수들에 대한 코치로 선발, 위촉되어 시체육회가 시행한 합동강화훈련을 지도하다가 대표선수로 선발된 같은 대학교 소속 학생이 훈련 중 사고를 당한 경우, 그 사고는 코치가 시체육회로부터 위촉받은 직무를 집행하는 과정에서 발생한 것이고, 대학교 측은 비록 위 체조코치가 합동강화훈련 기간 중에도 대학교의 체조코치로서의 신분을 그대로 보유하고 있었고, 사고를 입은 자가 같은 대학교 학생이었다고 하더라도, 적어도 위 체조코치가 시체육회로부터 위촉받은 체조대표선수들을 지도하는 코치의 직무를 집행함에 있어서는 그를 지휘·감독할 어떠한 권한이 있다거나 그러한 지위에 있다고 보기는 어려우므로 그 사고에서 국가는 위 체조코치의 사용자라고 볼 수 없다고 한 사례.\nv 대법원 2003. 10. 9. 선고 2001다24655 판결 : 파견근로자보호등에관한법률에 의한 근로자 파견은 파견사업주가 근로자를 고용한 후 그 고용관계를 유지하면서 사용사업주와 사이에 체결한 근로자 파견계약에 따라 사용사업주에게 근로자를 파견하여 근로를 제공하게 하는 것으로서, 파견근로자는 사용사업주의 사업장에서 그의 지시·감독을 받아 근로를 제공하기는 하지만 사용사업주와의 사이에는 고용관계가 존재하지 아니하는 반면, 파견사업주는 파견근로자의 근로계약상의 사용자로서 파견근로자에게 임금지급의무를 부담할 뿐만 아니라, 파견근로자가 사용사업자에게 근로를 제공함에 있어서 사용사업자가 행사하는 구체적인 업무상의 지휘·명령권을 제외한 파견근로자에 대한 파견명령권과 징계권 등 근로계약"},{"n":124,"text":"에 기한 모든 권한을 행사할 수 있으므로 파견근로자를 일반적으로 지휘·감독해야 할 지위에 있게 되고, 따라서 파견사업주와 파견근로자 사이에는 민법 제756조의 사용관계가 인정되어 파견사업주는 파견근로자의 파견업무에 관련한 불법행위에 대하여 파견근로자의 사용자로서의 책임을 져야 하지만, 파견근로자가 사용사업주의 구체적인 지시·감독을 받아 사용사업주의 업무를 행하던 중에 불법행위를 한 경우에 파견사업주가 파견근로자의 선발 및 일반적 지휘·감독권의 행사에 있어서 주의를 다하였다고 인정되는 때에는 면책된다고 할 것이다.\n[사실관계] 경남은행에서 근무하던 직원(소위 1)이 교통사고를 냈고, 경남은행이 가입한 보험회사(원고)가 손해배상을 한 후, 직원의 파견사업주(피고)에 대해 구상권을 행사했다.\n피고는 경남은행과의 근로자 파견계약에 따라 소외 1을 고용한 후 그를 경남은행에 파견하여 파견업무를 하도록 한 파견사업주이고, 또 경남은행과 근로자 파견계약을 체결함에 있어 피고측의 업무지휘·명령 및 관리책임자를 선임하여 파견근로자를 관리하기로 약정하였다는 것이니, 피고는 소외 1을 일반적으로 지휘·감독하여야 할 사용자의 지위에 있다고 볼 수 있어서 외형상 소외 1의 파견업무인 자동차의 운전업무와 관련하여 발생한 이 사건 사고에 대하여는 소외 1에 대한 일반적 지휘·감독권을 갖는 피고로서도 그 사고의 위험이 생길 원인을 제공한 데 또는 그 위험 방지조치를 다하지 못한 데에 책임이 있다고 할 것이다.\n나. 위임관계\n수임인의 행위에 대한 위임인의 사용자책임에 관해서는 논란이 있다. 변호사, 의사 등은 사무처리를 위탁하는 자의 직접적인 지휘·감독을 받지 않기 때문에 자유재량에 따라 독립적으로 사무를 행하는 것이 원칙이다. 따라서 일부 견해는 사용자책임을 부정하고 있다. 그러나 판례는 제756조의 요건을 갖추면 위임인도 사용자책임을 질 수 있다고 한다.\nv 대법원 1998. 4. 28. 선고 96다25500 판결 : 불법행위에 있어 사용자책임이 성립하려면 사용자와 불법행위자 사이에 사용관계 즉 사용자가 불법행위자를 실질적으로 지휘·감독하는 관계가 있어야 하는 것으로, 위임의 경우에도 위임인과 수임인 사이에 지휘·감독관계가 있고 수임인의 불법행위가 외형상 객관적으로 위임인의 사무집행에 관련된 경우 위임인은 수임인의 불법행위에 대하여 사용자책임을 진다.\n소외 7(변호사)은 피고들로부터 교부받은 위 위임장, 백지매도증서, 상속재산분할심판서정본, 상속재산분할협의서원본, 등기권리증 등을 소지하고 있음을 이용하여 자신이 피고들로부터 이 사건 부동산을 처분할 권한을 위임받은 것처럼 가장, 원고에게 이를 금 175,000,000원에 매도하고 원고로부터 계약 당일 계약금 20,000,000원, 같은 해 2. 27. 1차 중도금 40,000,000원, 같은 해 3. 21. 2차 중도금 30,000,000원 합계 금 90,000,000원을 지급받아 편취하였다. 소외 7은 피고들의 위임에 따라 장기간 동안 소송사건 외에도 피고들이 상속받은 부동산을 매각하고 상속재산을 분할하는 사무 등을 처리하여 왔고, 그 사무에 관하여는 피고들이 소외 7을 지휘·감독하는 관계에 있었다고 봄이 상당하다.\n[정리] 변호사가 의뢰인이 맡겨 놓은 증서들을 이용해 부동산을 매도한 사례에서, 매수인이 의뢰인에게 사용자 책임을 물은 사례. (검토사항: 표현대리의 인정 가능성은?)\nv 대법원 2001. 9. 4. 선고 2000다26128 판결 : 민법 제756조의 사용자책임이 성립하려면 사용자가 불법행위자인 피용자를 실질적으로 지휘․감독하는 관계에 있어야 하므로, 피용자가 퇴직한 뒤에는 퇴직에도 불구하고 사용자의 실질적인 지휘․감독 아래에 있었다고 볼 수 있는 특별한 사정이 없다면 그의 행위에 대하여 원칙적으로 종전의 사용자에게 사용자책임을 물을 수 없다.\n다. 도급관계\n제757조【도급인의 책임】도급인은 수급인이 그 일에 관하여 제삼자에게 가한 손해를 배상할 책임이 없다. 그러나 도급 또는 지시에 관하여 도급인에게 중대한 과실이 있는 때에는 그러하지 아니하다.\n도급인이 자신의 지시에 좇아 행위한 수급인의 행위에 대하여 책임을 지는 것(제757조 제2문 참고)도 이에 해당한다. 원래 수급인은 도급인으로부터 독립하여 사무를 처리한다. 따라서 수급인은 도급인의 피용자라고 할 수 없다. 즉, 제757조 제1문은 도급인에게 제756조의 책임이 없음을 규정한 것에 지나지 않는다. 그러나 도급 또는 지시에 관하여 도급인에게 \"중대한 과실\"이 있으면, 도급인은 수급인의 행위에 대하여 사용자로서 책임을 진다(제757조 제2문).\nv 대법원 2005. 11. 10. 선고 2004다37676 판결: 일반적으로 도급인과 수급인 사이에는 지휘·감독의 관계가 없으므로 도급인은 수급인이나 수급인의 피용자의 불법행위에 대하여 사용자로서의 배상책임이 없는 것이지만, 도급인이 수급인에 대하여 특정한 행위를 지휘하거나 특정한 사업을 도급시키는 경우와 같은 이른바 노무도급의 경우에는 비록 도급인이라고 하더라도 사용자로서의 배상책임이 있다.\n2) 외부적 사용관계"},{"n":125,"text":"외부적으로 ‘사용관계’가 존재하는 것으로 보이는 경우에도 사용관계가 인정된다. 특히 판례는 명의대여자에 대해서도 사용자책임을 인정하고 있다. 이 경우 내부적으로는 사용관계가 없다는 점에서 외부적으로 표현된 사용관계가 책임인정의 근거가 된다.\nv 대법원 2001. 3. 9. 선고 2000다66119 판결(공 2001, 844) : 증권회사의 전 지점장이 회사를 퇴직한 후 같은 지점에서 투자상담사로 근무하다가 그 직을 그만두었음에도 불구하고 이를 숨기고 고객들을 상대로 투자상담사로서의 업무를 계속하였고, 증권회사에서도 그의 업무수행을 묵인하고 회사의 투자상담사로서 업무를 수행하는 것처럼 외관을 갖게 하였다면, 그가 고객들의 증권카드와 인감을 사용하여 금원을 인출한 행위에 대하여 증권회사는 사용자책임을 면할 수 없다고 한 사례.\nv 대법원 2007. 6. 28. 선고 2007다26929 판결(미간행) : 타인에게 어떤 사업에 관하여 자기의 명의를 사용할 것을 허용한 경우에 그 사업이 내부관계에 있어서는 타인의 사업이고 명의자의 고용인이 아니라 하더라도 외부에 대한 관계에 있어서는 그 사업이 명의자의 사업이고 또 그 타인은 명의자의 종업원임을 표명한 것과 다름이 없으므로, 명의사용을 허용받은 사람이 업무수행을 함에 있어 고의 또는 과실로 다른 사람에게 손해를 끼쳤다면 명의사용을 허용한 사람은 민법 제756조에 의하여 그 손해를 배상할 책임이 있고, 명의대여관계의 경우 민법 제756조가 규정하고 있는 사용자책임의 요건으로서의 사용관계가 있느냐 여부는 실제적으로 지휘·감독을 하였느냐의 여부에 관계없이 객관적·규범적으로 보아 사용자가 그 불법행위자를 지휘·감독해야 할 지위에 있었느냐의 여부를 기준으로 결정하여야 할 것이다(대법원 2001. 8. 21. 선고 2001다3658 판결 등 참조).\nv 대판 2006. 3. 10, 2005다65562 : 동업관계에 있는 자들이 공동으로 처리하여야 할 업무를 동업자 중 1인에게 맡겨 그로 하여금 처리하도록 한 경우 다른 동업자는 그 업무집행자의 동업자인 동시에 사용자의 지위에 있다 할 것이므로, 업무집행과정에서 발생한 사고에 대하여 사용자로서 손해배상책임이 있다.\nv 대판 2001. 8. 21, 2001다3658 : 타인에게 어떤 사업에 관하여 자기의 명의를 사용할 것을 허용한 경우에 그 사업이 내부관계에 있어서는 타인의 사업이고 명의자의 고용인이 아니라 하더라도 외부에 대한 관계에 있어서는 그 사업이 명의자의 사업이고 또 그 타인은 명의자의 종업원임을 표명한 것과 다름이 없으므로, 명의사용을 허용받은 사람이 업무수행을 함에 있어 고의 또는 과실로 다른 사람에게 손해를 끼쳤다면 명의사용을 허용한 사람은 민법 제756조에 의하여 그 손해를 배상할 책임이 있다.\n(3) 가해행위의 사무집행관련성\n사용자는 피용자가 그 \"사무집행에 관하여\" 제3자에게 가한 손해를 배상할 책임이 있다. 사용자책임의 전형적인 경우는 피용자가 사용자로부터 지시받은 일을 하다가 실수로 타인에게 손해를 끼치는 경우이다. 이 경우 당연히 사무집행관련성은 인정된다.\n그러나 사무집행관련성은 두 가지 방향으로 확대될 수 있다. 하나는 지시받은 일을 하는 중에 ‘고의로’ 타인에게 손해를 끼치는 경우이고, 다른 하나는 지시받지 않은 일을 하다가 고의 또는 과실로 타인에게 손해를 끼치는 경우이다. 이러한 경우에 통설과 판례는 가해행위가 사무집행과 관련되는가를 판단하기 위하여 외형이론을 적용한다. 즉, “피용자의 행위가 사무집행의 외형을 갖는\"지의 여부로 판단한다.\n\"사무집행에 관하여\"라는 요건은 사용자책임의 적용과 관련하여 가장 중요한 요건으로서 본래의 사무집행 자체 또는 그 목적달성을 위해 일체불가분의 관계를 갖고 있는 행위만으로 제한되지 않는다. 즉, 사무집행과 관련성을 갖는 것으로 보이기만 하면 족하다(외형이론). 다시 말해 사무집행 관련성은 피용자의 행위가 외형상 객관적으로 사용자의 사업활동, 사무집행행위 또는 그와 관련된 것이라고 보여지면 충분하고, 행위자의 주관적 사정은 고려되지 않는다. 또한 피용자의 행위가 사용자의 명령이나 금지에 반하여 부당한 것이더라도, 외형상 사무에 속하는 것이라면 사무집행관련성이 인정된다.\n가령, 피용자가 ‘고의로’ 타인에게 손해를 끼치는 것은 사용자가 지시한 업무에는 속하지 않는다. 하지만 피용자의 불법행위가 외형상 객관적으로 사용자의 사업활동이나 사무집행행위 또는 그와 관련된 것이라고 보일 때에는 행위자의 주관적 사정(가해의 고의)을 고려하지 않고, 이를 사무집행에 관한 행위로 보게 된다(대법원 1998. 2. 10. 선고, 95다39533 판결 등 참고).\nv 대법원 1998. 2. 10. 선고, 95다39533 판결 : [4] 민법 제756조에 규정된 사용자 책임의 요건인 '사무집행에 관하여'라는"},{"n":126,"text":"뜻은 피용자의 불법행위가 외형상 객관적으로 사용자의 사업활동 내지 사무집행 행위 또는 그와 관련된 것이라고 보여질 때에는 행위자의 주관적 사정을 고려함이 없이 이를 사무집행에 관하여 한 행위로 본다는 것이고, 외형상 객관적으로 사용자의 사무집행에 관련된 것인지의 여부는 피용자의 본래 직무와 불법행위와의 관련 정도 및 사용자에게 손해 발생에 대한 위험 창출과 방지조치 결여의 책임이 어느 정도 있는지를 고려하여 판단하여야 한다.\n[5] 고용관계 또는 근로관계는 이른바 계속적 채권관계로서 인적 신뢰관계를 기초로 하는 것이므로, 고용계약에 있어 피용자가 신의칙상 성실하게 노무를 제공할 의무를 부담함에 대하여, 사용자로서는 피용자에 대한 보수지급의무 외에도 피용자의 인격을 존중하고 보호하며 피용자가 그 의무를 이행하는 데 있어서 손해를 받지 아니하도록 필요한 조치를 강구하고 피용자의 생명, 건강, 풍기 등에 관한 보호시설을 하는 등 쾌적한 근로환경을 제공함으로써 피용자를 보호하고 부조할 의무를 부담하는 것은 당연한 것이지만, 어느 피용자의 다른 피용자에 대한 성희롱 행위가 그의 사무집행과는 아무런 관련이 없을 뿐만 아니라, 가해자의 성희롱 행위가 은밀하고 개인적으로 이루어지고 피해자로서도 이를 공개하지 아니하여 사용자로서는 이를 알거나 알 수 있었다고 보여지지도 아니하다면, 이러한 경우에서까지 사용자가 피해자에 대하여 고용계약상의 보호의무를 다하지 아니하였다고 할 수는 없다.\n다만 외형이론에 따른 사무집행 관련성에 대해서는 그 적용이 제한되는 경우가 있음에 주의해야 한다. 즉, 대법원에 따르면 피용자의 불법행위가 외관상 사용자의 사무집행의 범위 내에 속하는 것으로 보이는 경우라도 피용자의 행위가 사용자의 사무집행행위에 해당하지 않음을 피해자 자신이 ‘알았거나 중대한 과실로 알지 못하는 경우’에는 사용자책임이 부정된다고 판시하고 있다(대법원 2003. 2. 11. 선고 2002다62029 판결). 외형이론이 피해자의 정당한 신뢰만을 보호하고자 하는 이론이라는 점에서 보호할 필요가 없는 피해자에 대해 그 적용을 배제하는 판례의 입장은 타당하다.\nv 대법원 2003. 2. 11. 선고, 2002다62029 판결 : [3] 피용자의 불법행위가 외관상 사무집행의 범위 내에 속하는 것으로 보이는 경우에 있어서도, 피용자의 행위가 사용자나 사용자에 갈음하여 그 사무를 감독하는 자의 사무집행 행위에 해당하지 않음을 피해자 자신이 알았거나 또는 중대한 과실로 인하여 알지 못한 경우에는 사용자책임을 물을 수 없고, 사용자책임이 면책되는 피해자의 중대한 과실이라 함은 거래의 상대방이 조금만 주의를 기울였더라면 피용자의 행위가 그 직무권한 내에서 적법하게 행하여진 것이 아니라는 사정을 알 수 있었음에도 만연히 이를 직무권한 내의 행위라고 믿음으로써 일반인에게 요구되는 주의의무에 현저히 위반하는 것으로 거의 고의에 가까운 정도의 주의를 결여하고, 공평의 관점에서 상대방을 구태여 보호할 필요가 없다고 봄이 상당하다고 인정되는 상태를 말한다.\nv 대법원 1995. 2. 3. 선고 94다43115 판결 : 세무사 甲의 세무회계사무소 사무장인 乙이 丙으로부터 토지 양도로 인한 양도소득세 신고. 납부와 관련한 상담을 받고 세액과 비용이 금 30,000,000원 정도가 되니 그 금액이면 양도소득세 및 수수료 등 모든 것을 책임지고 종결시켜 주겠다고 하여 양도소득세 신고 및 납부대행을 위임받아 처리하기로 하고 丙으로부터 그 금원을 지급받은 후, 甲에게 그 사실을 알리지 아니한 채 관할세무서에 丙 명의로 양도소득세 과세표준확정신고를 하면서 양도소득세 및 방위세로 일부만을 납부하고 나머지 금액을 임의로 소비하였고, 그 이후 위 세액이 과소하게 신고 납부되었음이 밝혀져 丙이 가산세를 합하여 양도소득세, 방위세 및 가산금을 추가로 납부하게 되었다면, 乙의 행위는 외형상 객관적으로 사용자인 甲의 사무집행과 밀접하게 관련된 것이므로 甲은 乙의 사용자로서 위 불법행위로 인하여 丙이 입은 손해를 배상할 책임이 있다고 한 사례.\nv 대법원 2021. 3. 11. 선고 2018다285106 판결: 제756조에 규정된 사용자책임의 요건인 ‘사무집행에 관하여’라 함은 피용자의 불법행위가 외형상 객관적으로 사용자의 사업활동, 사무집행행위 또는 그와 관련된 것이라고 보일 때에는 행위자의 주관적 사정을 고려하지 않고 사무집행에 관하여 한 행위로 본다는 것이다. 피용자가 다른 사람에게 가해행위를 한 경우 그 행위가 피용자의 사무집행 그 자체는 아니더라도 사용자의 사업과 시간적·장소적으로 근접하고 피용자의 사무의 전부 또는 일부를 수행하는 과정에서 이루어지거나 가해행위의 동기가 업무처리와 관련된 것이라면 외형적·객관적으로 사용자의 사무집행행위와 관련된 것이라고 보아 사용자책임이 성립한다. 이때 사용자가 위험발생을 방지하기 위한 조치를 취하였는지 여부도 손해의 공평한 부담을 위하여 부가적으로 고려할 수 있다.\nv 대법원 1993. 5. 27. 선고 92다48109 판결: 도급인은 도급 또는 지시에 관하여 중대한 과실이 없는 한 수급인이 그 일에 관하여 제3자에게 가한 손해를 배상할 책임이 없으나 도급인이 수급인의 일의 진행 및 방법에 관하여 구체적인 지휘 감독권을 유보한 경우에는 도급인과 수급인의 관계는 실질적으로 사용자 및 피용자의 관계와 다를 바 없으므로 수급인이 고용한 제3자의 불법행위로 인한 손해에 대하여 도급인은 제756조에 의한 사용자책임을 면할 수 없고, 이러한 이치는 하도급의 경우에도 마찬가지이다.\n또한, 피용자가 지시받지 않은 일을 하는 중에 타인에게 손해를 가하였다면, 이는 엄격한 의미에서는 사무집행이라고 할 수 없다. 그러나 판례와 통설은 업무수행에 시간적․장소적으로 근접하고 업무수행의 外觀을 가지고 있는 경우에는 사무집행관련성을 인정한다. 이와 같이 엄격한 의미에서 사무집행관련성이 인정되지 않는 경우에도 외형이론은 외형을 기준으로 사무집행관련성을 인정한다.\nv 대법원 2000. 2. 11. 선고 99다47297 판결 : [사실관계] 甲은 乙이 운영하는 호텔의 종업원으로서 1996. 11. 11. 04:30경"},{"n":127,"text":"호텔 프론트에서 근무하던 중, 호텔에 목욕을 하기 위하여 찾아온 丙로부터 사우나의 영업시간에 관한 질문을 받고 05:00부터 시작하니 조금 기다리라는 대답을 하였다. 그러나 이에 丙이 심하고 상스러운 욕을 하면서 때리려고 하자 이를 피하였다가 같은 날 04:40경 다음 근무자를 불러 근무교대를 하였는데, 그 후에도 丙이 호텔 지하의 종업원 숙소까지 따라오면서 계속 상스러운 욕을 하기도 하고, 근무교대 후 프론트에서 근무하던 다음 근무자에게도 甲을 불러오라면서 소란을 피우자, 05:00경 분을 참지 못하고 숙소에서 등산용 칼을 꺼내어 이를 소지한 채 丙을 따라 현관 앞 주차장으로 가서 丙이 다시 갑을 손으로 때리려고 하자 갖고 있던 칼로 丙의 얼굴과 등 부위를 찔러 丙에게 상해를 가하였다. [법원의 판단] 민법 제756조에 규정된 사용자책임의 요건인 '사무집행에 관하여'라는 뜻은 피용자의 불법행위가 외형상 객관적으로 사용자의 사업활동 내지 사무집행행위 또는 그와 관련된 것이라고 보여질 때에는 행위자의 주관적 사정을 고려함이 없이 이를 사무집행에 관하여 한 행위로 본다는 것으로, 피용자가 고의에 기하여 다른 사람에게 가해행위를 한 경우 그 행위가 피용자의 사무집행 그 자체는 아니라 하더라도 사용자의 사업과 시간적, 장소적으로 근접하고, 피용자의 사무의 전부 또는 일부를 수행하는 과정에서 이루어지거나 가해행위의 동기가 업무처리와 관련된 것일 경우에는 외형적, 객관적으로 사용자의 사무집행행위와 관련된 것이라고 보아 사용자책임이 성립한다고 할 것이고, 이 경우 사용자가 위험발생 및 방지조치를 결여하였는지 여부도 손해의 공평한 부담을 위하여 부가적으로 고려할 수 있다 할 것이다. 甲의 丙에 대한 상해행위는 乙의 업무처리를 하던 중 丙이 그 업무처리와 관련하여 甲의 감정을 해하는 언동을 하자 이에 대항하여 자신의 감정을 회복하기 위하여 저지른 것으로서, 그 가해행위는 근무교대 직후에 乙의 사업장소 내에서 이루어진 것이어서 시간적으로나 장소적으로 乙의 사무와 밀접하게 관련되어 있을 뿐만 아니라 그 행위의 동기가 甲의 업무처리와 관련된 것이라고 보여지며, 더욱이 접객업소 경영자인 乙로서는 불특정 다수의 고객을 대하는 피용자들에 대한 교육, 감독을 철저히 함으로써 그의 사업범위 내에서 발생할 수 있는 위와 같은 위험을 방지하여야 한다는 점도 아울러 고려하여 보면, 甲의 상해행위로 인하여 丙이 입은 손해는 甲이 乙의 피고의 사무집행에 관하여 丙에게 가한 손해에 해당한다고 보아야 할 것이다.\nv 대법원 1997. 10. 10. 선고 97다16572 판결 : C 회사의 생산 현장 청소 등의 업무로서 파지와 고철의 수집·정리를 담당하던 피용자 A가 고철 수집 작업 중에 마실 물을 달라고 하는 피해자 B에게 음료수를 권하면서 접대한 행위는 A의 본래의 사무 집행 행위는 아니라고 할지라도 외형상 객관적으로 그 사무 집행 행위와 밀접하게 관련된 행위라고 할 것이어서, A가 농약을 음료수로 오인하고 건네주어 B가 이를 마시고 사망함으로써 입은 손해는, A가 C 회사의 사무 집행을 계기로 하여 이것과 밀접한 관련을 가진다고 인정할 수 있는 행위에 의하여 초래된 것으로서 C 회사의 사무의 집행에 관하여 가한 손해에 해당한다.\n그러나 외형이론이 인정되는 경우에도 피용자가 지시받지 않은 일을 하던 중에 타인에게 고의로 손해를 가한 것이 명백한 경우에는 사무집행관련성을 부정하기도 한다. 이 경우는 피용자의 행위가 사용자의 사무집행행위에 속하지 않음을 피해자 자신이 알았거나 중대한 과실로 알지 못한 경우가 될 수 있기 때문이다.\nv 대법원 1994. 11. 18. 선고, 94다34272 판결 : 가. 민법 제756조에 규정된 사용자책임의 요건인 ‘사무집행에 관하여’라는 뜻은 피용자의 불법행위가 외형상 객관적으로 사용자의 사업활동 내지 사무집행행위 또는 그와 관련된 것이라고 보일 때에는 행위자의 주관적 사정을 고려함이 없이 이를 사무집행에 관하여 한 행위로 본다는 것이다.\n나. 사적인 전화를 받던 레스토랑 종업원이 지배인으로부터 욕설과 구타를 당한 후 레스토랑을 나가 약 8시간 동안 배회하다가 과도를 사 가지고 레스토랑에 들어왔는데 다시 지배인으로부터 욕설과 구타를 당하자 이에 대항하여 지배인을 과도로 찔러 사망에 이르게 한 경우, 종업원의 위 불법행위가 레스토랑의 영업시간 중에 사용자의 사업장소에서 이루어진 것이기는 하나, 그 종업원은 사용자에게 고용되어 담당하게 된 사무의 집행과는 관련이 없이 자기 개인의 인격과 신체에 대한 침해행위에 대항하여 살해행위를 저질렀다고 봄이 상당하고, 종업원의 위 불법행위를 외형적, 객관적으로 보아도 이를 사용자의 사무집행과 관련된 행위로 볼 수는 없다고 한 사례.\nv 대법원 2005. 12. 23. 선고 2003다30159 판결: 사용자로부터 위임을 받은 바 없이 행한 피용자의 금원차용행위 및 예금인출행위에 대하여 피해자인 은행의 지점장이 위 피용자의 행위가 사용자의 사무집행행위에 해당하지 않음을 알고도 이에 응한 경우에 위 은행은 그로 인한 손해에 대하여 사용자책임을 물을 수 없다고 볼 수 있다.\n(4) 선임·감독상의 주의의무 결여(면책사유 있음을 입증하지 못할 것)\n사용자는 ‘피용자의 선임 및 그 사무 감독에 상당한 주의를 한 때’ 또는 ‘상당한 주의를 하여도 손해가 있을 경우’에는 그 책임을 면할 수 있다(제756조 제1항 단서). 이러한 면책사유로 인하여 사용자책임은 이론적으로 사용자의 선임·감독상 주의의무위반의 과실책임으로서 성격을 갖는다고 설명되기도 한다(고유책임설). 그러나 입증책임을 전환하면서 면책사유의 인정을 엄격하게 제한하여 실질적으로 무과실책임에 가깝게 운영되고 있다."},{"n":128,"text":"3. 사용자책임의 효과\n사용자책임의 구성요건이 충족되면 사용자 또는 사용자에 갈음하여 그 사무를 감독하는 자는 손해배상책임을 진다(제756조 제1항, 제2항). 피용자는 제750조에 의해 불법행위책임을 지며, 사용자와 피용자는 부진정연대채무 관계가 된다. 따라서 각각의 손해배상채무는 별개의 것이고, 각자의 독자적 책임이며 피해자가 어느 한쪽으로부터 배상을 일부 또는 전부 받으면, 그 범위에서 다른 쪽의 배상책임은 소멸한다. 사용자가 다수인 경우에도 그들의 책임은 부진정연대책임이다.\n사용자 또는 대리감독자가 손해배상을 하게 되면, 피용자에 대하여 구상권을 행사할 수 있다(제756조 제3항). 뿐만 아니라 사용자와 피용자 사이의 계약관계에 근거하여, 사용자는 피용자의 계약상 의무위반으로 발생한 손해에 대한 배상을 청구할 수도 있다.\nv 대법원 1992. 3. 31. 선고, 91다39849 판결 : 가. 회사 명의로 등록된 차량을 그 지입차주로부터 운전수와 함께 일시 임차하여 화물운송에 사용한 경우에 특별한 사정이 없는 한 회사의 그 소속 운전수에 대한 사용자의 지위는 위와 같은 일시대여 상태에서도 유지된다.\n나. 위 \"가\"항의 경우 차량을 임차한 자로서는 그 임차기간 중 운전수를 지휘․감독하여 화물운송에 종사케 한 이상 비록 일시차용이라고 하여도 피해자에 대한 관계에서는 사용자로서의 배상책임을 면할 수 없다.\n다. 위 \"가\"항의 경우 차량의 임대인과 그 임차인의 각 배상책임은 서로 부진정연대관계에 있다고 할 것이므로, 어느 한 쪽이 피해자에 대한 손해를 배상하여 공동면책이 되었다면 그 구상권의 범위는 각자의 부담부분, 즉 손해발생에 기여한 과실의 정도에 의하여 결정하여야 할 것이다.\n사용자는 피용자가 부담한 배상액을 대외적으로 부진정연대채무로서 부담하는 것에 불과하므로, 자신이 피해자에게 보상한 경우 이를 피용자에게 구상할 수 있다(通說). 그러나 피용자는 근로조건·작업시설·안전장치 등 사고방지를 위한 조건을 스스로 만들 수 없고 사용자는 위험성 있는 노동을 피용자에게 시키고 있기 때문에 손해배상금을 피용자에게 전부 부담시키는 것은 사업위험을 근로자에게 전가하는 결과가 되어 부당하다는 지적이 있다. 또한, 사용자는 사업위험을 줄이도록 적절한 조치를 취하거나 보험가입 또는 상품가격의 조정 등을 통하여 위험을 분산시킬 수 있으므로 피용자의 책임은 제한될 필요가 있다. 판례는 ‘信義則’에 따라 사용자의 구상권을 제한하고 있다.\nv 대법원 1994. 12. 13. 선고 94다17246 판결 : [사실관계] A는 이사를 하기 위해 아파트관리사무소에 곤돌라를 이용하고 싶다고 의뢰를 하였고, 이에 A의 이삿날 한국주택관리 주식회사(甲)는 소속 직원인 관리소장 乙과 전기주임 丙에게 곤돌라를 운행할 것을 지시하였다. 한국주택관리 주식회사의 지시에 따라 丙은 곤돌라를 조작하여 A의 이사를 다 마친 뒤, 곤돌라의 버턴을 조작하여 곤돌라 줄을 원래의 위치인 옥상 위로 감아올리던 중, 곤돌라 줄 끝에 매달려 있던 쇠고리가 바람에 흔들리면서 15층 베란다 바깥쪽에 설치된 화분대를 치는 바람에 화분대가 지면으로 떨어지면서 곤돌라 아래 지면에 서 있던 B의 머리에 부딪치게 되었고, 이에 B는 사망하게 되었다. 이후 B의 유족은 乙과 丙의 사용자인 甲으로부터 금 1억 2천만 원의 손해배상을 받았다. 이에 갑은 乙과 丙에 대하여 1억 2천만 원에 대한 구상을 요구하였다.\n법원의 판결: 일반적으로 사용자가 피용자의 업무수행과 관련하여 행해진 불법행위로 인하여 직접 손해를 입었거나 그 피해자에게 사용자로서의 손해배상책임을 부담한 결과로 손해를 입게 된 경우에 있어서 사용자는 그 사업의 성격과 규모, 시설의 현황, 피용자의 업무내용, 근로조건이나 근무태도, 가해행위의 상황, 가해행위의 예방이나 손실의 분산에 관한 사용자의 배려정도, 기타 제반 사정에 비추어 손해의 공평한 분산이라는 견지에서 신의칙상 상당하다고 인정되는 한도 내에서만 피용자에 대하여 그 구상권을 행사할 수 있다고 보아야 할 것이다.\n이러한 쌍방(갑(원고)과 을·병(피고))의 과실의 경중, 곤돌라 기사인 위 피고의 근무조건과 그러한 근무조건이 위 사고발생에 미친 영향의 정도, 위 피해자가 사고를 당하게 된 경위, 원고의 노무자에 대한 인력관리상황, 위 사고 후 위 피고가 실형을 복역한 후 현재 면직되어 있음에 반하여, 원고는 국내 유수의 공동주택관리업체로서의 지위를 그대로 유지하고 있는 점 등 제반 사정을 참작하여 보면, 피고 1에게 앞에서 본 바와 같은 과실이 있었다는 것만으로 원고가 위 피고에 대하여 피해자에게 배상한 데 대한 구상이나 손해배상을 구하는 것은 신의칙상 허용되지 아니한다 [정리] 피해자인 B에 대하여 사용자로서 손해배상을 한 甲은 피용자에 대하여 제756조 3항에 따라서 구상할 수 있다. 그러나 이 구상권규정을 그대로 관철하게 되면 결과적으로 모든 책임을 피용자가 지게 되는 결과가 되는 반면, 사업상 이익을 얻는 사용자는 아무런 부담도 지지 않는 것이 되어 부당하다. 따라서 판례는 사용자의 피용자에 대한 구상권을 ‘신의칙’에 따라서 제한하고자 하는데, 위 사안에서 비록 乙과 丙이 안전조치를 게을리한 과실이 있긴 하나, 한국주택관리 주식회사인 甲의 업무지시로 인한 것인 점, 곤돌라의 경우 이에 대한 면허가 없다는 점, 인원부족으로 혼자서 곤돌라를 조작하다 사고가 난 점, 곤돌라의 구조상 줄이 바람에 흔들리는 것을 막기가 쉽지 않았다는 점 등을 고려하여, 갑은"},{"n":129,"text":"乙과 병에게 구상할 수 없다고 보았다.\nv 대법원 1991. 5. 10. 선고 91다7255 판결 : 일반적으로 사용자가 피용자의 업무수행과 관련하여 행해진 불법행위로 인하여 직접 손해를 입었거나 그 피해자에게 사용자로서의 손해배상책임을 부담한 결과로 손해를 입게 된 경우에 있어 사용자는 그 사업의 성격과 규모, 시설의 현황, 피용자의 업무내용, 근로조건이나 근무태도, 가해행위의 상황, 가해행위의 예방이나 손실의 분산에 관한 사용자의 배려정도, 기타 제반사정에 비추어 손해의 공평한 분산이라는 견지에서 신의칙상 상당하다고 인정되는 한도 내에서만 피용자에 대하여 그 구상권을 행사할 수 있다고 보아야 할 것이다( 당원 1987. 9. 8. 선고 86다카1045 판결 참조).\n원고는 렌트카 30대를 보유하고 그 차량의 대여를 영업목적으로 하고 있어서 이용고객의 희망에 따라 수시로 차량운전을 위한 인원이 필요한 관계로 주간 근무자로서 운전기사 3명을 두는 한편, 야간에는 별도로 경비원인 위 망 김영식으로 하여금 사무실 차량의 경비관리와 차량의 대여 및 반차인수 업무 등과 함께 고객의 요청에 따른 대여차량의 운전 등 일체의 야간업무에 종사하게 하여온 사실, 원고가 위 망인을 채용할 당시 동인이 자동차운전면허가 없는 자임을 알면서도 회사 경영상 노무부족 때문에 동인에게 위와 같은 업무를 담당하게 하였을 뿐만 아니라 동인에 대한 근무감독이나 위험사고발생의 예방을 위한 아무런 조치를 강구하지 아니한 사실, 위 망인은 입사 이래 계속하여 매일 19:00부터 08:30까지 혼자 근무하면서 월 금 200,000원의 비교적 적은 보수를 받고 아무런 사고 없이 성실하게 근무하여 온 사실, 한편 원고는 위 김영식이 사고 당시 렌트카를 무단 사용 운전하였다는 이유를 내세워 동인의 유족에 대하여 근로기준법 또는 산업재해보상보험법에 따른 보상 내지 보험처리를 하지 않고 있는 사실들을 인정하고 나서 이 사건 사고의 발생원인에 있어 피용자인 위 망 김영식의 가해행위가 지니는 책임성에 비하여 사용자인 원고의 가해행위에 대한 기여도 내지 가공도가 지나치게 크다고 보여지는 점 등을 참작하면, 원고가 사용자로서의 위 망인의 상속인과 그 신원보증인들인 피고들에게 구상권을 행사한다는 것은 신의칙상 도저히 받아들일 수 없다고 판시하고 원고의 청구를 기각하였는바, 원심의 위와 같은 조치는 위에서 본 법리에 따른 것으로 정당하다고 수긍이 되고 거기에 소론과 같은 법리오해의 위법이 있다고 할 수 없다. 논지는 이유 없다.\nⅣ. 공작물 등의 점유자와 소유자의 책임\n제758조(공작물 등의 점유자, 소유자의 책임) ①공작물의 설치 또는 보존의 하자로 인하여 타인에게 손해를 가한 때에는 공작물점유자가 손해를 배상할 책임이 있다. 그러나 점유자가 손해의 방지에 필요한 주의를 해태하지 아니한 때에는 그 소유자가 손해를 배상할 책임이 있다.\n②전항의 규정은 수목의 재식 또는 보존에 하자 있는 경우에 준용한다.\n③전2항의 경우 점유자 또는 소유자는 그 손해의 원인에 대한 책임 있는 자에 대하여 구상권을 행사할 수 있다.\n1. 의의\n공작물의 설치 또는 보존의 하자로 인하여 타인에게 손해를 가한 경우 공작물의 점유자와 소유자가 손해배상 책임을 지는 것을 공작물 등의 점유자와 소유자 책임이라고 한다(제758조 제1항 제1문). 공작물의 점유자가 1차적으로 배상책임을 지고, 점유자가 손해의 방지에 필요한 주의를 다한 경우 점유자의 책임을 배제하고 있다. 이 경우 2차적으로 공작물의 소유자가 배상책임을 진다(제758조 제1항 제2문). 소유자는 면책이 불가능하다.\n예를 들면, 갈라진 돌축대가 장마로 무너져서 통행인이 다친 경우 점유자인 임차인이 1차적으로 책임을 지게 된다. 그러나 임차인이 통행인의 접근을 막고 위험을 알리는 등 충분한 조치를 하였다면 소유자인 집주인이 손해배상책임을 부담하게 된다.\n2. 공작물책임의 성질\n공작물의 점유자는 손해의 발생을 막는 데 필요한 주의를 다한 경우 면책되기 때문에 점유자의 책임은 이미 설명한 사용자의 책임과 같이 과실의 입증책임을 전환한 중간책임(추정과실책임)이 된다. 그러나 소유자는 면책이 인정되지 않는다는 점에서 무과실책임이라고 할 수 있다.\n점유자의 책임과 소유자의 책임은 원칙적으로 위험책임의 원리에서 출발한다. 즉, 위험성이 많은 공작"},{"n":130,"text":"물을 관리·소유하는 자는 위험의 방지에 충분한 주의를 하여야 하며, 만일 이러한 위험이 현실화하여 손해가 발생한 경우 그 손해를 배상할 책임을 지는 것이 사회적으로 타당하기 때문이다. 다만, 공작물 소유자 책임은 엄격한 의미의 위험책임으로 보기는 어렵다고 평가된다.\nv 대법원 1996. 11. 22. 선고 96다39219 판결: 제758조는 공작물의 설치·보존의 하자로 인하여 타인에게 손해를 가한 경우 그 점유자 또는 소유자에게 일반 불법행위와 달리 이른바 위험책임의 법리에 따라 책임을 가중시킨 규정일 뿐이고, 그 공작물 시공자가 그 시공상의 고의·과실로 인하여 피해자에게 가한 손해를 제750조에 의하여 직접 책임을 부담하게 되는 것을 배제하는 취지의 규정은 아니다.\n3. 공작물책임의 요건\n(1) 공작물\n공작물책임은 공작물로부터 손해가 생겼을 것을 요건으로 한다. 공작물이란 인공적 작업에 의하여 만들어진 물건을 의미하며, 토지의 상하에 존재하는 공작물이나 건물의 일부를 이루는 내부설비, 기업설비 등이 이에 해당한다. 자동차나 항공기와 같은 동산도 공작물에 포함된다.\nv 대법원 2026. 1. 8. 선고 2022다233713 판결: 민법 제758조 제1항은 위험책임 법리에 근거하여 공작물 소유자에게 무과실책임을 부과함으로써 그 책임을 가중하고, 구 민법 제717조 제1항과 달리 공작물책임의 원칙적인 적용 대상을 “토지의 공작물”로 한정하지 않고 “공작물”, 즉 인공적 작업에 의하여 제작된 물건으로 확대하였다. 이와 같이 공작물 소유자에게 무과실책임을 부과하고 공작물책임의 적용 범위를 확대한 것은 과학기술의 발전 등으로 인해 위험원이 복잡·다양화되고 있는 현대 사회에서 피해자 보호를 도모하는 데 그 취지가 있다. 그러나 위와 같은 입법 취지를 고려하더라도, 공작물 소유자에게 예외 없이 모든 손해를 배상할 무과실책임을 지운다면 손해의 공평 부담을 지도원리로 하는 손해배상제도의 근본 취지에 어긋나는 경우가 있을 수 있다. 특히 복잡다기한 기술이 집약되어 만들어진 공작물의 경우, 그 소유자가 해당 공작물의 구조 및 작동원리와 그로 인한 위험성, 위험성이 현실화하여 발생할 수 있는 손해의 범위 등을 구체적으로 파악하기 어렵다는 점에서 더욱 그러하다. 불법행위에 있어 손해액을 정함에 참작하는 피해자의 과실, 즉 과실상계에서의 과실은 가해자의 과실과 달리 사회통념이나 신의성실의 원칙에 따라 공동생활에 있어 요구되는 약한 의미의 부주의를 가리키는데, 그 취지 또한 불법행위로 인한 손해를 가해자와 피해자 사이에 공평하게 분담시키고자 함에 있다.\n(2) 공작물의 설치·보존상 하자로 인한 손해\n공작물의 설치 또는 보존의 하자로 인하여 손해가 발생하여야 한다. 우선, ① 여기서 하자(瑕疵)란 물건이 그 용도에 따라 통상 갖추고 있어야 할 완전성을 갖추고 있지 않은 경우를 의미한다(객관적 관점). 하자의 존부는 객관적으로 판단되며, 점유자나 소유자의 고의·과실에 의하여 발생할 것을 요하지 않는다. 또한, ② 하자로 손해가 발생해야 한다. 만약 공작물이 강풍이나 폭우와 같은 불가항력으로 파괴되고, 이로 인하여 손해가 발생한 경우 이러한 손해가 공작물에 하자가 없는 경우에도 일어날 수 있다면 공작물에 존재하는 하자와 손해 간의 인과관계는 부정될 수 있다. 즉, 공작물에 의한 책임이 점유자는 물론 소유자에게도 발생하지 않는다. 이 경우는 불행한 사건에 불과할 뿐이다.\nv 대법원 1993. 3. 9. 선고 92다54715 판결 : 경기장 앞 광장 입구의 도로 위에 차량통행을 막기 위하여 바리케이드 2개를 설치하고, 그 사이의 2m 공간에 윗부분끼리 한 줄의 쇠사슬로 연결해 놓았는데 피해자가 오토바이를 타고 그 사이를 통과하려다가 쇠사슬에 목부분이 걸려 넘어지면서 사망한 사고에서 경기장 진입로 차단시설의 설치보존상의 하자가 있다고 한 사례.\nv 대법원 1998. 1. 23. 선고 97다25118 판결 : 가. 민법 제758조 제1항에 규정된 공작물의 설치․보존상의 하자라 함은 공작물이 그 용도에 따라 통상 갖추어야 할 안전성을 갖추지 못한 상태에 있음을 말하는 것으로서, 이와 같은 안전성의 구비 여부를 판단함에 있어서는 당해 공작물의 설치․보존자가 그 공작물의 위험성에 비례하여 사회통념상 일반적으로 요구되는 정도의 방호조치 의무를 다하였는지의 여부를 기준으로 삼아야 할 것이고, 따라서 공작물에서 발생한 사고라도 그것이 공작물의 통상의 용법에 따르지 아니한 이례적인 행동의 결과 발생한 사고라면, 특별한 사정이 없는 한 공작물의 설치․보존자에게 그러한 사고에까지 대비하여야 할 방호조치 의무가 있다고 할 수는 없다.\n나. 배수관이 설치된 여관 앞 골목길은 평소에 여관 내부를 엿보려고 하는 행인들이 있었고 그러한 사람들이 배수관을 잡고 올라가는 경우가 있어 배수관이 자주 훼손되므로 여관 주인이 이를 방지하기 위하여 보호벽을 설치하게 되었으며,"},{"n":131,"text":"보호벽을 설치하면서 보호벽의 맨 윗부분에 여러 개의 못까지 박아 두었는데, 행인이 음주를 한 상태에서 여관의 내부를 들여다 보기 위하여 그 보호벽을 타고 올라가다가 보호벽이 무너지는 바람에 사고를 당하게 된 경우, 그 보호벽의 본래의 용도는 어디까지나 배수관이 훼손되는 것을 방지하기 위한 것이므로, 보호벽이 스스로 넘어지지 않을 만큼의 견고성을 갖도록 설치하였다면 이로써 보호벽은 일단 본래의 용도에 따른 통상적인 안전성을 갖추었다고 할 것이고, 그와 같이 보호벽 윗부분에 못을 박아 사람들이 보호벽 위로 올라가서 여관방을 들여다 보는 것을 방지하는 조치까지 취하였음에도 불구하고 행인들이 윗부분에 꽂혀 있는 못에 찔려 다칠 위험을 무릅쓰고 보호벽에 올라가 여관 내부를 들여다 보는 부정한 행위를 저지를 것까지 예상하여 보호벽을 설치․관리하는 여관 주인에게 이러한 경우까지 대비한 방호조치를 취할 의무는 없다는 이유로 그 보호벽의 설치․보존상의 하자를 부인한 사례.\nv 대법원 1994. 10. 28. 선고 94다16328 판결 : 나. 도시가스의 공급시설 내지 그 사용시설 등과 같은 고도의 위험을 수반하는 공작물의 경우에는 그 시설이 관계법령의 정한 바에 따른 시설기준 등에 부적합한 것이라면 특별한 사정이 없는 한 이러한 사유는 공작물의 설치․보존상의 하자에 해당한다고 볼 수 있다고 한 사례.\n[정리] 가스보일러의 폐가스인 일산화탄소에 중독되어 사망한 사건에서 피해자가 환기구를 막아놓은 과실도 있지만, 관계법령의 시설기준에 부합하지 않게 설치한 회사의 책임을 인정한 사례\nv 대법원 2000. 1. 14. 선고 99다39548 판결 : [2] 온풍기의 연통을 가연성 물질인 천막지붕에 근접하여 설치한 경우, 온풍기의 설치․보존상의 하자가 있다고 본 사례.\nv 대법원 1988. 11. 8. 선고 86다카775 판결 : 가. 민법 제758조 제1항에 규정된 공작물의 설치 또는 보존의 하자라 함은 그 공작물이 본래 갖추어야 할 안전성을 갖추지 못한 상태를 말하는 것인 바, 경부고속도로는 시속 100킬로미터의 속도로 차량이 빈번히 통행하는 도로로서 도로상에 통행에 방해가 되는 어떠한 장애물의 존재도 허용될 수 없는 것이기 때문에 그 도로의 추월선상에 가로 약 30내지 40센티미터, 세로 약 40내지 50센티미터, 높이 약 20센티미터 크기의 차단 블록이 밀려나와 있었다면 그 사실자체가 일단은 고속도로가 본래 갖추어야 할 안전성을 갖추지 못한 상태에 있는 것이어서 이는 고속도로의 보존상의 하자가 있는 경우에 해당한다.\n나. 고속도로의 보존상의 하자의 존재에 관한 입증책임은 피해자에게 있으나 일단 그 하자있음이 인정되는 이상 고속도로의 점유관리자는 그 하자가 불가항력에 인한 것이거나 손해의 방지에 필요한 주의를 해태하지 아니하였다는 점을 주장입증하여야 비로소 그 책임을 면할 수가 있다.\nv [하자의 개념에 관한 객관적 관점을 따르지 않은 판결] 대법원 1992. 9. 14. 선고 92다3243 판결 : 가. 공작물인 도로의 설치보존상의 하자는 도로의 위치 등 장소적인 조건,도로의 구조, 교통량, 사고 시에 있어서의 교통사정 등 도로의 이용상황과 그본래의 이용목적 등 제반 사정과 물적 결함의 위치, 형상 등을 종합적으로 고려하여 사회통념에 따라 구체적으로 판단하여야 할 것인바, 도로의 설치 후 제3자의 행위에 의하여 그 본래의 목적인 통행상의 안전에 결함이 발생된 경우에는 도로에 그와 같은 결함이 있다는 것만으로 성급하게 도로의 보존상 하자를 인정하여서는 안되고, 당해 도로의 구조, 장소적 환경과 이용상황 등 제반 사정을 종합하여 그와 같은 결함을 제거하여 원상으로 복구할 수 있는데도 이를 방치한 것인지 여부를 개별적, 구체적으로 심리하여 하자의 유무를 판단하여야 할 것이다.\n나. 트럭 앞바퀴가 고속도로상에 떨어져 있는 자동차 타이어에 걸려 중앙분리대를 넘어가 사고가 발생한 경우에 있어서 한국도로공사에게 도로의 보존상하자로 인한 손해배상책임을 인정하기 위하여는 도로에 타이어가 떨어져 있어 고속으로 주행하는 차량의 통행에 안전상의 결함이 있다는 것만으로 족하지 않고, 위 공사의 고속도로 안전성에 대한 순찰 등 감시체제, 타이어의 낙하시점, 위 공사가 타이어의 낙하사실을 신고받거나 직접 이를 발견하여 그로 인한 고속도로상의 안전성 결함을 알았음에도 사고방지조치를 취하지 아니하고 방치하였는지 여부, 혹은 이를 발견할 수 있었음에도 발견하지 못하였는지 여부 등 제반 사정을 심리하여 고속도로의 하자 유무를 판단하였어야 함에도 이에 이르지 않은 채 위 공사의 손해배상책임을 인정한 원심판결을 파기한 사례.\nv 대법원 1993. 6. 29. 선고 93다11913 판결 : 가. 전력수급계약 해제 이후에도 전선을 절단하는 등의 방법으로 단전조치를 위하지 않은 한전에 과실이 있다 할지라도 높이 8m의 고압전선에 앉은 새를 잡으려고 철근으로 맞추려다 감전당한 피해자의 손해와의 사이에 상당인과 관계가 없다 한 사례.\n나. 민법 제758조에서 말하는 공작물이라 함은 인공적 작업에 의하여 제작된 물건을 말하는 것으로서 전기 그 자체는 여기에서 말하는 공작물에 해당되지 않는다.\nv 대법원 2019. 11. 28. 선고 2017다14895 판결: 제758조 제1항은 “공작물의 설치 또는 보존상의 하자로 인하여 타인에게 손해를 가한 때에는 공작물점유자가 손해를 배상할 책임이 있다. 그러나 점유자가 손해의 방지에 필요한 주의를 해태하지 아니한 때에는 그 소유자가 손해를 배상할 책임이 있다.”라고 규정하고 있다. 위 규정의 입법 취지는 공작물의 관리자는 위험의 방지에 필요한 주의를 다하여야 하고, 만일에 위험이 현실화하여 손해가 발생한 경우에는 그들에게 배상책임을 부담시키는 것이 공평하다는 데 있다. 따라서 ‘공작물의 설치·보존상의 하자’란 공작물이 그 용도에 따라 통상 갖추어야 할 안전성을 갖추지 못한 상태에 있음을 말하고, 위와 같은 안전성의 구비 여부를 판단할 때에는 공작물을 설치·보존하는 자가 그 공작물의 위험성에 비례하여 사회통념상 일반적으로 요구되는 정도로 위험방지조치를 다하였는지 여부를 기준으로 판단하여야 한다. 하자의 존재에 관한 증명책임은 피해자에게 있으나, 일단 하자가 있음이 인정되고 그 하자가 사고의 공동원인이 되는 이상, 그 사고가 위와 같은 하자가 없었더라도 불가피한 것이었다는 점이 공작물의 소유자나 점유자에 의하여 증명되지 않는다면 그 손해는 공작물의 설치 또는 보존의 하자에 의하여 발생한 것으로 해석함이 타당하다."},{"n":132,"text":"이 경우 하자 여부를 판단할 때에는 위험의 현실화 가능성의 정도, 위험이 현실화하여 사고가 발생하였을 때 침해되는 법익의 중대성과 피해의 정도, 사고 방지를 위한 사전조치에 드는 비용이나 위험방지조치를 함으로써 희생되는 이익 등을 종합적으로 고려하여야 한다.\n(3) 면책사유의 부존재\n점유자에 대해서는 면책사유를 인정하고 있으나 소유자에게는 면책사유를 인정하고 있지 않다. 점유자는 손해의 방지에 필요한 주의를 해태하지 않았다면 그 손해를 배상할 책임이 없다(손해방지의무 위반의 관점).\n(4) 기타 면책 가능성 : 무단침입자에 대한 책임\n목적물에 하자가 있으나 무단침입자에게 손해가 발생한 경우, 무단침입자에게 공작물의 소유자가 책임을 져야 하는지 의문이 제기되고 있다. 위법하게 타인의 위험영역에 침입한 자에게는 위험책임을 부담하지 않는다는 것이 학설의 일반적인 견해이다. 예컨대, 도둑이 타인의 주거에 침입하여 미끄러운 계단에서 추락한 경우, 엔진 결함이 있는 자동차를 훔친 도둑이 달아나다가 사고가 난 경우가 이에 해당한다. 판례 역시 책임을 부정하고 있다.\nv 대법원 1977. 11. 8. 선고 77다1486 판결 : 일반인의 무단출입이 금지되어 있는 철도역 구내의 횡단로는 일반 통행인을 위한 소위 건널목이라고 볼 수는 없으므로 함부로 내왕하던 주민에게 사고가 발생한 경우 건널목의 설치와 보존의 하자책임을 물을 수 없다.\nv 대법원 1992. 4. 24. 선고 91다37652 판결 : [1] 공작물의 설치보존상의 하자라 함은 공작물이 그 용도에 따라 통상 갖추어야 할 안전성을 갖추지 못한 상태에 있음을 말하는 것이고, 공작물의 설치 및 보존에 있어서 항상 완전무결한 상태를 유지할 정도의 고도의 안전성을 갖추지 아니하였다 하여 그 공작물의 설치보존에 하자가 있는 것이라고는 할 수 없으므로, 공작물의 설치보존자에게 부과되는 방호조치의무의 정도는 그 공작물의 위험성에 비례하여 사회통념상 일반적으로 요구되는 정도의 것을 말한다.\n나. 대학 5층 건물 옥상에서 그 대학 학생이 후배들에게 얼굴을 하늘로 향하게 하여 바닥에 눕게 한 다음, 구령에 맞추어 몸통을 좌우로 뒹굴게 하는 방법으로 기합을 주던 중, 그중 1인이 몸을 구르다가 약 15미터 아래로 떨어져 사망한 경우 위 옥상은 그 설치용도와 관계 있는 사람 이외에는 올라가지 않는 곳이고, 위 망인을 비롯한 학생들도 평소 그와 같은 사정을 잘 알고 있었다고 할 것이며, 나아가 위험성에 대한 지각능력이 있는 학생들이 출입이 제한되어 있는 그 옥상에서 추락 등의 사고를 일으킬 수 있는 행위를 하리라고 기대하기는 어려우므로, 학교측에게 그러한 사고가 있을 것까지 예상하여 항상 그 곳에 관리인을 두어서 출입을 통제한다거나 추락을 방지하기 위하여 난간을 설치하는 등의 조치를 취할 것까지 요구할 수는 없고 따라서 위 건물의 설치보존상의 하자가 인정되지 않는다고 한 사례.\nv 대법원 1981. 6. 23. 선고 80다2993 판결 : 사실관계가 그렇다면 비록 위 표시판은 그 자체가 아이들의 놀이에 제공되는 것은 아니라 할지라도 그 판시와 같은 사정 아래에서는 아이들이 올라타고 놀면서 충격을 주는 것이 예상되는 이상 이에 따르는 상당한 관리를 하여야 할 터인데 피고는 위 표시판이 갖추어야 할 안전성을 유지 관리하지 못하였다 할 것이니 이와 같은 취지에서 원심이 공작물인 위 표시판의 관리소홀로 인해서 발생한 손해에 대하여 피고에게 소유자 겸 점유자로서의 배상책임을 인정한 조처는 정당하고, 원심판결에 소론과 같이 공작물의 하자에 관한 법리를 오해한 위법이 있다 할 수 없고...\n4. 공작물책임의 효과\n공작물책임의 1차적 책임자는 공작물의 점유자이고 2차적 책임자는 소유자이다. 이러한 책임자의 순위와 지위차이는 다음과 같은 이유에 근거한다. 공작물에 대하여 가장 밀접한 지위에 있는 자에게 먼저 책임을 부담시키고, 위험한 설비를 이용하는 자보다 소유한 자에게 최종적으로 책임을 귀속시키는 것이 타당하기 때문이다.\n1) 공작물 점유자\n공작물의 점유자는 공작물을 사실상 지배하여 설치 또는 보존상의 하자로 발생할 사고를 방지하기 위하여 공작물을 보수·관리할 권한과 책임이 있는 자를 의미한다. 따라서 간접점유자가 있는 경우 직접"},{"n":133,"text":"점유자가 책임을 지게 되고, 그 후에 간접점유자가 책임을 진다.\nv 대법원 2000. 4. 21. 선고 2000다386 판결 : [1] 민법 제758조 제1항 소정의 공작물점유자라 함은 공작물을 사실상 지배하면서 그 설치 또는 보존상의 하자로 인하여 발생할 수 있는 각종 사고를 방지하기 위하여 공작물을 보수․관리할 권한 및 책임이 있는 자를 말한다.\n[2] 공장근저당권자가 공장의 부도로 대표이사 등이 도피한 상태에서 담보물의 가치를 보전하기 위하여 경비용역업체를 통하여 공장을 경비한 사실만으로 민법 제758조 제1항 소정의 공작물점유자에 해당한다고 볼 수 없다고 한 사례.\nv 대법원 2003. 2. 28. 선고 2002다65516 판결 : 건물 일부의 임차인이 건물 외벽에 설치한 간판이 추락하여 행인이 부상한 경우 건물소유자는 건물 외벽의 직접점유자로서 민법 제758조 제1항 소정의 손해배상책임을 부담한다고 판단한 사례.\nv 대법원 1994. 7. 29. 선고 93다32453 판결 : 나. ... 구 액화석유가스의안전및사업관리법 제29조 소정의 액화 석유가스 (L.P.G) 사용신고자는 일반수요자와는 달리 다른 특별한 사정이 없는 한 액화석유가스의 사용시설을 사실상 지배하고 점유. 관리하는 자라 할 것이므로 그 사용시설에 대한 민법 제758조 소정의 점유자로 보아야 할 것이다.\nv 대법원 1994. 6. 28. 선고 94다2787 판결 : 가. 계량기에 대하여 가스 사용자의 점유를 전혀 부정할 수는 없다고 하더라도, 가스 공급업자도 또한 가스 사용자와 함께 계량기에 대하여 직접 지배하면서 이를 점유 관리하고 있었다 할 것이고, 오히려 계량기의 보수, 관리에 관련하는 한에 있어서는 가스 사용자보다도 가스 공급업자가 보다 직접적, 구체적인 지배를 하였다고 할 것이므로, 가스 공급업자는 민법 제758조 제1항 소정의 점유자에 해당한다고 할 것이다.\n점유자는 손해의 방지에 필요한 주의를 해태하지 아니한 때에는 책임을 지지 않는다. 상당한 주의를 하였더라도 손해가 생겼으리라고 생각되는 경우 점유자는 면책되는 것으로 해석하는 것이 보통이다(제756조 제1항 단서 유추). 주의의무 위반과 손해 사이의 인과관계를 인정하기 어렵기 때문이다.\nv 대법원 2024. 2. 15. 선고 2019다208724 판결: 물건에 대한 점유란 사회관념상 어떤 사람의 사실적 지배에 있다고 보이는 객관적 관계를 말하는 것으로서, 사실상의 지배가 있다고 하기 위하여는 반드시 물건을 물리적, 현실적으로 지배하여야만 하는 것이 아니고, 물건과 사람 사이의 시간적, 공간적 관계와 본권관계, 타인지배의 배제 가능성 등을 고려하여 사회통념에 따라 합목적적으로 판단하여야 한다.\n민법 제758조 제1항 소정의 공작물 점유자란 공작물을 사실상 지배하면서 그 설치 또는 보존상의 하자로 인하여 발생할 수 있는 각종 사고를 방지하기 위하여 공작물을 보수? 관리할 권한 및 책임이 있는 자를 말한다.\n가사상, 영업상 기타 유사한 관계에 의하여 타인의 지시를 받아서 공작물에 대한 사실상의 지배를 하는 자가 있는 경우에 그 타인의 지시를 받는 자는 민법 제195조에 따른 점유보조자에 불과하므로 민법 제758조 제1항에 의한 공작물 점유자의 책임을 부담하는 자에 해당하지 않는다.\n2) 공작물소유자의 책임\n점유자가 피해자인 경우나, 점유자가 손해방지에 필요한 주의를 해태하지 아니한 경우 소유자가 손해배상책임을 진다(제758조 제1항 제2문). 면책이 인정되지 않는 무과실책임에 해당한다. 그러나 구상권이 인정된다는 점에서 특색이 있다(제758조 제3항).\nv 대법원 1993. 2. 9. 선고 92다31668 판결 : 가. 공작물의 설치 또는 보존의 하자로 인하여 타인에게 손해를 가한 때에는 1차적으로 공작물의 점유자가 손해를 배상할 책임이 있고 공작물의 소유자는 점유자가 손해의 방지에 필요한 주의를 해태하지 아니한 때에 비로소 2차적으로 손해를 배상할 책임이 있는 것이나, 공작물의 임차인인 직접점유자나 그와 같은 지위에 있는 것으로 볼 수 있는 자가 공작물의 설치 또는 보존의 하자로 인하여 피해를 입은 경우에는 그 가옥의 소유자는 민법 제758조 제1항 소정의 책임자로서 이에 대하여 손해를 배상할 책임이 있는 것이고 그 피해자에게 보존상의 과실이 있더라도 과실상계의 사유가 될 뿐이다.\n나. 임차인과 함께 임차방실에 기거하던 직장동료가 연통에서 새어나온 연탄가스에 중독 사망한 사고에 대하여 가옥소유자의 손해배상책임을 인정한 사례.\nv 대법원 1987. 4. 14. 선고 86다카1705 판결 : 가옥임대차에 있어서 임대인은 임차인으로 하여금 그 목적물을 사용․수익하게 할 의무가 있고 그 의무내용에는 목적물의 수선의무도 포함되는 것인바, 가옥임차인이 건물의 부엌벽의 균열을 발견하고 임대인에게 보수를 요구하고 임대인도 그 위험을 인식하여 곧 보수하여 주겠다고 약속하고서 그 이행을 지체하고 있던 중 위 벽이 무너짐으로 말미암아 인명사고 가 발생하였다면, 공작물의 직접 점유자인 위 임차인으로서는 손해의 방지에 필요한 주의를 해태하지 아니하였다고 볼 것이므로 결국 그 소유자인 임대인이 위 사고에 대한 손해배상책임을 질 수밖에 없다.\n3) 점유자 및 소유자의 구상권\n점유자 또는 소유자로서 책임을 지고 피해자에게 배상을 한 자는 그 손해의 원인에 대하여 책임이 있는 자에게 구상할 수 있다. 예를 들면, 공작물을 만든 수급인이나 공작물의 前소유자 또는 前점유자"},{"n":134,"text":"등이 이에 해당한다.\n4) 수목에 관한 책임\n수목 식재나 보존상 하자가 있는 경우에도 점유자 또는 소유자는 공작물책임이 있다(제758조 제2항). 이 경우 구상권에 관하여도 공작물책임의 경우와 같다(제758조 제3항).\nⅤ. 동물의 점유자의 책임\n제759조【동물의 점유자의 책임】 ① 동물의 점유자는 그 동물이 타인에게 가한 손해를 배상할 책임이 있다. 그러나 동물의 종류와 성질에 따라 그 보관에 상당한 주의를 해태하지 아니한 때에는 그러하지 아니하다.\n② 점유자에 갈음하여 동물을 보관한 자도 전항의 책임이 있다.\n1. 책임의 성질\n민법 제759조는 동물이 타인에게 손해를 준 경우 점유자 또는 보관자가 원칙적으로 배상책임을 지도록 하고 있다(제1항 제1문). 다만, 상당한 주의를 게을리하지 않은 경우 면책을 인정하고 있다(제1항 제2문). 민법 제759조의 동물점유자책임 역시 과실의 입증책임을 전환한 중간책임(추정과실책임)에 해당한다. 동물점유자책임 역시 위험책임의 법리에서 출발하고 있다. 점유자에 갈음하여 동물을 보관하는 자도 동일한 책임을 진다(제759조 제2항).\n2. 책임의 요건\n(1) 동물로 인한 손해\n동물이 손해를 야기해야 한다. 동물의 종류는 불문한다. 따라서 가축도 포함된다. 그러나 동물의 종류에 따라서 점유자에게 요구되는 주의의 정도가 달라진다.\nv 대판 1981. 2. 10, 선고 80다2966 판결 : 도사견은 성질이 난폭하여 사람에게 피해를 입힐 위험이 크므로 그 소유자가 이를 타인에게 빌려주는 경우에는 그가 도사견을 안전하게 보관 관리할 수 있는 시설을 갖추고 있는지 여부를 확인하여야 할 주의의무가 있다. *동물의 간접점유자에 대한 책임을 인정한 사건\n(2) 타인에게 손해를 야기할 것\n동물이 타인에게 가한 손해가 배상의 대상이 된다. 여기서 손해에는 인적 손해 외에도 물적 손해가 포함된다. 즉, 가축이 타인의 물건을 부서뜨린 경우도 그 손해를 배상해야 한다.\n(3) 면책사유가 없을 것\n동물의 종류와 성질에 따라 그 보관에 상당한 주의를 해태하지 않은 경우 동물의 점유자 또는 보관자는 배상책임을 면한다(제759조 제1항 제2문). 상당한 주의를 한 경우에도 손해가 발생하였을 경우라면 면책된다고 할 수 있다(제756조 제1항 단서 유추). 주의의무 위반과 손해 간의 인과관계를 인정할 수 없기 때문이다.\n3. 효과\n동물의 「점유자」와 「점유자에 갈음하여 동물을 보관한 자」는 손해배상책임을 진다. 여기서 점유자에 갈음하여 동물을 보관한 자는 동물의 직접점유자를 의미하고, 따라서 점유자에 갈음하여 동물을 보관"},{"n":135,"text":"한 자는 독립적인 동물의 점유자가 된다. 즉, 제759조 제2항의 규정은 주의적 규정에 불과하다.\n제759조는 동물소유자의 책임을 언급하고 있지 않다. 즉, 동물소유자는 별도의 책임을 부담하지 않는다.\n또한, 제759조는 구상권에 대하여 언급하고 있지 않다. 민법이 별도의 규정을 두고 있지 않으나, 계약책임의 일반이론에 따라서 당연히 인정된다. 예를 들어 점유보조자인 피용자의 과실로 사용자가 동물점유자로서의 책임을 부담한 경우 쇠사슬이나 동물우리의 하자로 동물점유자가 책임을 부담한 경우 사용자 또는 쇠사슬이나 동물우리의 매수인은 점유보조자인 피용자 또는 매도인에게 그 책임을 물을 수 있다.\nⅥ. 공동불법행위자의 책임\n1. 서설\n[사례] 친구 사이인 甲, 乙, 丙은 평소 자신들에게 고분고분하지 않다는 이유로 혼을 내주려고 같은 반 급우인 丁을 학교 근처 골목으로 데려갔다. 그곳에서 甲과 乙은 丁을 폭행하여 상해를 가하였고, 丙은 사람들이 오는지 망을 보았다. 이때 丁은 누구를 상대로 어떤 책임을 물을 수 있는가?\n《解說》 甲, 乙, 丙이 공동으로 丁에게 불법행위를 하였으므로 甲, 乙, 丙은 丁의 손해에 대하여 연대하여 책임을 부담한다. 그리고 甲, 乙, 丙 사이의 가해행위에 대한 공모가 있으므로, 어느 학설에 따르더라도 공동불법행위가 성립한다. 그리고 丙의 경우 실제 폭행에는 가담하지 않았으나 丁에 대한 폭행과 상해라는 공동의 행위를 수행한 것으로 판단되므로, 망을 본 것만으로도 행위관련공동성이 인정된다.\n제760조【공동불법행위자의 책임】 ① 수인이 공동의 불법행위로 타인에게 손해를 가한 때에는 연대하여 그 손해를 배상할 책임이 있다.\n② 공동 아닌 수인의 행위중 어느 자의 행위가 그 손해를 가한 것인지를 알 수 없는 때에도 전항과 같다.\n③ 교사자나 방조자는 공동행위자로 본다.\n여러 명이 가해행위를 하여 하나의 손해를 발생시키는 형태의 불법행위를 공동불법행위라고 한다. 우리 민법상 불법행위의 유형은 원칙적으로 한 명의 행위자가 하나의 손해를 일으키는 단독의 불법행위를 예정하고 있으며, 행위자가 여러 명인 공동불법행위는 제760조에서 예외로 규정하고 있다. 민법 제760조는 수인이 관여된 불법행위를 세 가지 유형으로 나누어 규정하고 있다. ㈀ 수인이 공동으로 불법행위를 한 경우(협의의 공동불법행위), ㈁ 공동 아닌 수인의 행위로 손해가 발생하였으나 그 손해를 가한 자를 알 수 없는 경우(가해자 불명의 공동불법행위), ㈂ 교사자 또는 방조자의 경우(교사 또는 방조에 의한 공동불법행위)로 나누고 있다.\n2. 공동불법행위의 유형별 요건\n(1) 협의의 공동불법행위\n[사례] 甲과 乙은 丁 소유의 부동산에 근저당을 설정하여 금원을 대출받기로 공모한 뒤, 근저당권설정을 위한 인감증명서를 발급받기 위해서 丁의 주민등록표를 위조하여 관할 동사무소에 제출하였다. 그런데 동사무소 인감발급 담당직원인 丙은 甲․乙이 제출한 주민등록표가 그 작성일자나 날인된 인장들이 적합한 것이 아니어서 정상적으로 작성된 것으로 보기 어려운 사정이 있음에도 불구하고 이를 간과하고 인감을 발급해주었다. 발급받은 인감을 이용하여 甲․乙은 丁 소유의 부동산에 戊명의의 채권최고액 1억 5천만 원의 근저당권을 설정하였다. 이후 이 사실을 알게 된 丁은 위 부동산에 대한 근저당권설정등기의 말소등기소송에서 승소하였다. 이때 戊는 누구를 상대로 어떤 청구를 할 수"},{"n":136,"text":"있는가?\n<解說> 피해자 戊는 자신의 손해에 대하여 행위관련공동성이 있는 자에 대하여 공동불법행위책임을 물을 수 있는데, 사안에서 戊의 손해와 甲․乙․丙 간에 행위관련공동성이 인정되므로 공동불법행위가 성립한다(대판 1991. 11. 22., 91다26980)\n협의의 공동불법행위는 수인이 공동으로 불법행위를 한 경우를 의미한다. 이를 위해서는 ① 가해자 각자가 독립하여 일반불법행위의 요건(제750조)을 갖추어야 하며, ② 그 행위에 공동성이 인정되어야 한다.\n일반불법행위의 요건과 관련하여 우선 인과관계가 문제 된다. 공동불법행위자들의 각각의 가해행위와 손해 간의 인과관계가 존재하여야 하는지, 아니면 공동의 행위와 손해 간의 인과관계가 존재하는 것만으로 충분한지에 대해서 견해대립이 있다. 공동불법행위의 경우 자신의 행위와 인과관계가 없는 손해에 대해서도 손해배상책임을 진다는 점에서 자기책임의 원칙에 대한 예외라고 할 수 있다.\n수인이 “共同”으로 가해행위를 하여야 협의의 공동불법행위가 성립한다(제760조 제1항). 따라서 공동불법행위자 간에 행위의 공동성이 존재하지 않는 경우라면 제760조 제2항에 따른 가해자불명의 공동불법행위가 되거나, 여러 명의 불법행위자는 각각 일반불법행위책임(제750조)을 질 뿐이다. 행위의 공동성에 대해서는 수인이 공모의 합의 또는 의사의 공통이 있어야 한다는 주관적 공동설도 있지만, 이러한 공동의 모의나 인식은 필요 없으며 객관적으로 보아 피해자에 대한 권리침해가 공동으로 이루어졌고 그 행위가 손해발생에 대해 공통의 원인이 되었다고 인정되는 경우라면 충분하다는 객관적 공동설이 통설·판례의 태도이다. 이에 따르면 과실에 의한 공동불법행위도 성립할 수 있다.\nF 主觀的 共同說 : 공동의 의미에 대해서는 가해자 간의 공모나 공동의 인식과 같은 의사의 공동성이 존재하여야 한다는 견해.\n客觀的 共同說 : 가해자 간의 주관적 공동성은 필요 없고 가해자의 각 행위 간의 관련공동성만 있으면 공동불법행위가 성립한다는 견해로서 通說․判例의 입장이다.\nv 대법원 1997. 8. 29. 선고 96다46903 판결: 공동불법행위의 성립에는 공동불법행위자 상호 간에 의사의 공통이나 공동의 인식이 필요하지 아니하고 객관적으로 각 행위에 관련공동성이 있으면 족하므로, 관련공동성 있는 행위에 의하여 손해가 발생하였다면 그 손해배상책임을 면할 수 없다.\nv 대법원 1998. 11. 24. 선고 98다32045 판결: 교통사고로 인하여 상해를 입은 피해자가 치료를 받던 중 치료를 하던 의사의 과실로 인한 의료사고로 증상이 악화되거나 새로운 증상이 생겨 손해가 확대된 경우, 의사에게 중대한 과실이 있다는 등의 특별한 사정이 없는 한 확대된 손해와 교통사고 사이에도 상당인과관계가 있고, 이 경우 교통사고와 의료사고가 각기 독립하여 불법행위의 요건을 갖추고 있으면서 객관적으로 관련되고 공동하여 위법하게 피해자에게 손해를 가한 것으로 인정되면 공동불법행위가 성립한다.\nv 대법원 1968. 2. 27. 선고 67다1975 판결 : 피고들이 모두 공작물의 설치보존에 하자있음을 이유로 본조에 의하여 손해배상책임이 있다면 그들의 각 불법행위는 그들 간에 주관적 공동관계가 없어도 객관적인 공동관계가 있으므로 민법 제760조 소정 공동불법행위자로서 손해를 배상할 책임이 있다.\nv 대법원 1994. 11. 25. 선고, 94다35671, 판결 : 교통사고로 인하여 상해를 입은 피해자가 치료를 받던 중 의사의 과실 등으로 인한 의료사고로 증상이 악화되거나 새로운 증상이 생겨 사망에 이르는 등 손해가 확대된 경우, 특별한 사정이 없는 한 그와 같은 손해와 교통사고 사이에도 상당인과관계가 있다고 보아야 하므로, 교통사고와 의료사고가 각기 독립하여 불법행위의 요건을 갖추고 있으면서 객관적으로 관련되고 공동하여 위법하게 피해자에게 손해를 가한 것으로 인정된다면 공동불법행위가 성립되므로 이들은 연대하여 손해를 배상할 책임이 있다.\nv 대법원 1997. 11. 28. 선고, 97다18448 : <사실관계> 甲은 부산시 소재 노래연습장에서 동네 선배인 丙이 술에 취해 성명불상의 손님과 말다툼을 하고는 것을 보고 이를 말리다가 丙과 시비가 되어 서로 상대방의 뺨을 수회씩 때리기에 이르렀는데, 이때 乙이 가세하여 발과 주먹으로 丙의 얼굴과 가슴 다리 등을 수회 구타하여 丙은 오른쪽 눈에 상해를 입혀 실명에 이르게 되었다.\n[판결요지] 공동불법행위의 성립에는 공동불법행위자 상호 간에 의사의 공통이나 공동의 인식이 필요하지 아니하고 객관적으로 각 그 행위에 관련공동성이 있으면 족하고 그 관련공동성 있는 행위에 의하여 손해가 발생하였다면 그 손해배상책임을 면할 수 없다.\nv 대법원 1993. 1. 26. 선고, 92다4871 판결 : <사실관계> 차량운전자 甲은 과실로 보행자 丙을 치어 좌측대퇴골 분쇄골절 등의 상해를 입혔다. 이에 丙은 乙이 운영하던 정형외과에 입원하여 치료를 받던 중, 乙의 무리한 물리치료시술로 인하여"},{"n":137,"text":"좌측대퇴골이 소실이 되는 등 증세가 악화되었다.\n<판결요지> 교통사고로 인하여 상해를 입은 피해자가 치료를 받던 중 의사의 과실 등으로 인한 의료사고로 증상이 악화되거나 새로운 증상이 생겨 손해가 확대된 경우 특별한 다른 사정이 없는 한 그와 같은 손해와 교통사고 사이에도 상당인과관계가 있다고 보아야 하므로, 교통사고와 의료사고가 각기 독립하여 불법행위의 요건을 갖추고 있으면서 객관적으로 관련되고 공동하여 위법하게 피해자에게 손해를 가한 것으로 인정된다면, 공동불법행위가 성립되어 공동불법행위자들이 연대하여 손해를 배상할 책임이 있다.\n그러나 행위와 결과를 각각 구분할 수 있는 경우에는 공동불법행위가 성립하지 않는다.\nv 대법원 1989. 5. 23. 선고 87다카2723 판결 : 공동불법행위가 성립하려면 행위자 사이에 의사의 공통이나 행위공동의 인식이 필요한 것은 아니지만 객관적으로 보아 피해자에 대한 권리침해가 공동으로 행하여졌다고 보여지고 그 행위가 손해발생에 대하여 공통의 원인이 되었다고 인정되는 경우라야 할 것인바, 이 사건에서 피고 일신중기주식 회사 운전수의 불법행위는 1984. 8. 8. 11:30에 피해자를 차로 치어 그 결과 뇌좌상중등중, 뇌기절부골절우칙, 두피하혈종 등의 상해가 발생한 것이며 피고 대한민국 산하 전남의대부속병원의 시설하자 및 그 직원의 불법행위는 1984. 9. 10에 발생하여 환자가 비상계단에서 추락한 결과를 발생케 한 것이므로 양 행위가 시간과 장소에 괴리가 있고 결과 발생에 있어서도 양 행위가 경합하여 단일한 결과를 발생시킨 것이 아니고 각 행위의 결과 발생을 구별할 수 있으므로 그러한 경우에는 공동불법행위가 성립한다고 하기 어렵다. 원심으로서는 피해자의 추락사를 개의치 아니하고 동인이 교통사고로 부상한 결과 입게 된 손해를 심리하여 그 배상을 명하여야 할 것이고 피고 대한민국의 배상책임을 정함에 있어서는 피해자가 병원에서 추락하므로 인하여 발생된 손해를 산정(이때에 교통사고로 인한 손해액과 중첩되지 아니하도록 유의하여야 할 것이다)하여 각기 그 배상을 명하여야 할 것이고 전손해액에 대하여 연대배상을 명한 것은 잘못이라 할 것이다.\nv 대법원 1998. 2. 13선고 96다7854 판결 : [1] 수인이 공동하여 타인에게 손해를 가하는 민법 제760조 제1항의 공동불법행위가 성립하려면 각 행위가 독립하여 불법행위의 요건을 갖추고 있으면서 객관적으로 관련되고 공동하여 위법하게 피해자에게 손해를 가한 것으로 인정되어야 한다.\n[2] 에이즈 바이러스에 감염된 혈액을 환자가 수혈받음으로써 에이즈에 감염될 위험을 배제할 의무 및 그와 같은 결과를 회피할 의무를 다하지 아니하여 감염된 혈액을 수혈받은 환자로 하여금 에이즈 바이러스 감염이라는 치명적인 건강 침해를 입게 한 대한적십자사의 과실 및 위법행위는 신체상해 자체에 대한 것인 데 비하여, 수혈로 인한 에이즈 바이러스 감염 위험 등의 설명의무를 다하지 아니한 의사들의 과실 및 위법행위는 신체상해의 결과 발생 여부를 묻지 아니하는 수혈 여부와 수혈 혈액에 대한 환자의 자기결정권이라는 인격권의 침해에 대한 것이므로, 대한적십자사와 의사의 양 행위가 경합하여 단일한 결과를 발생시킨 것이 아니고 각 행위의 결과 발생을 구별할 수 있으니, 이와 같은 경우에는 공동불법행위가 성립한다고 할 수 없다.\n(2) 가해자 불명의 공동불법행위\n공동 아닌 수인의 행위 중 누구의 행위가 그 손해를 가한 것인지 알 수 없는 경우에도 공동불법행위책임이 발생한다. 시간적, 공간적 관련 및 행위의 동질성이 없어도 인정된다. 가령 두 사람이 각각 창문에 돌을 던졌는데 누구의 돌 때문에 창문이 깨졌는지는 알 수 없는 경우, 하나의 돌에 의해 창문이 깨졌음이 분명하다면 두 사람 모두의 공동불법행위책임이 성립한다. 실제로 책임이 있는 자 외의 자의 행위는 결과와 인과관계가 없지만, 인과관계를 추정하여 이에 관한 증명부담을 전환하고 있다.\n이처럼 가해자불명의 경우를 공동불법행위로 보는 것은 무엇보다도 여러 사람의 행위가 경합하여 손해가 발생하였으나 공동불법행위로 보기 어려운 경우에 인과관계의 증명책임을 덜어 줌으로써 피해자를 보호하려는 데 그 취지가 있다. 다만, 이 경우 가해자 중의 1인은 자신의 행위와 손해 간에 인과관계가 없다는 사실을 증명하여 공동불법행위에 대한 책임을 지지 않을 수 있다는 점에서 다른 공동불법행위의 유형과 차이가 있다.\n의료행위에 관여한 다수의 의사 중 누구의 과실에 의하여 의료사고가 발생한 것인지 분명하게 특정할 수 없는 경우 이들 모두에 대하여 공동불법행위책임을 물을 수 있다.\nv 대법원 2005. 9. 30. 선고 2004다52576 판결 : 다수의 의사가 의료행위에 관여한 경우 그 중 누구의 과실에 의하여 의료사고가 발생한 것인지 분명하게 특정할 수 없는 때에는 일련의 의료행위에 관여한 의사들 모두에 대하여 민법 제760조 제2항에 따라 공동불법행위책임을 물을 수 있다고 봄이 상당하다.\n망인은 소외 회사 내 작업장에서 프레스 기계를 이용하여 작업을 하던 중 양손이 위 기계에 압착되어 좌, 우측 각 제1, 2 수지가 절단되는 사고를 당한 사실(이하 '1차 산재사고'라고 한다), 망인은 피고 1이 운영하는 병원으로 후송되어 피고 병원 소속 의사들인 피고 2, 3으로부터 수지절단 및 접합수술을 받은 사실, 피고 병원의 의료진은 수술을 전후하여 전신기능이 저하된 망인에게 적정수액량을 훨씬 초과하여 수액을 과다투여하였음에도 망인의 소변배출 여부와 소변량"},{"n":138,"text":"등 환자의 동태를 제대로 살피지 아니하였고, 망인은 수술 이후 심장을 둘러싸고 있는 심낭에 400㏄ 가량의 삼출물이 차서 심장을 압박하는 바람에 심폐기능에 갑작스런 장애를 일으켜 심장 탐포나데로 사망에 이르게 된 사실(이하 '2차 의료사고'라고 한다), ... 이 사건 2차 의료사고는 전신기능이 저하된 망인에게 수액을 투여함에 있어 그 용량을 철저히 지키고 투여 후에도 망인의 소변배출 여부와 배출량 등을 제대로 관찰하며 신체상태를 세심하게 살펴보아 수액 투여로 인한 부작용의 기미가 보이면 즉시 이를 중단하거나 적절한 대응조치를 취하여야 할 주의의무가 있음에도, 이러한 조치를 제대로 취하지 아니한 채 수액을 계속 투여하고 망인의 신체상태를 제대로 살펴보지 아니한 피고 2, 3의 잘못으로 인하여 발생한 것으로 봄이 상당하다.\n(3) 교사 또는 방조\n[사례] 상호신용금고업무를 총괄하던 부회장 甲, 상무 乙은 대출신청자의 명의를 차용․도용하여 실제 차주가 아닌 자 명의로 대출신청서나 어음할인신청서를 작성하는 방법으로 동일인여신한도초과금지 및 출자여신금지 규정을 위반하였을 뿐만 아니라 물적․인적 담보를 충분히 확보하지 않은 채 대출을 하여 채권회수를 곤란하게 함으로써 배임행위를 저질렀다. 이들의 배임행위를 알면서 위 상호신용금고가 속한 그룹회장 丙은 이를 방관하였다. 이때 丙은 위 상호신용금고에 대하여 어떤 책임을 지는가?\n<解說> 방조는 작위는 물론이고 부작위로도 가능하다. 따라서 사안에서 丙은 그룹회장으로서 甲․乙의 배임행위를 알고도 과실로 방조한 것으로 판단되므로, 상호신용금고에 대하여 甲․乙․丙은 공동불법행위책임을 진다(대판 2003. 1. 10, 2002다35850 참조).\n㈀ 불법행위에 대한 책임은 직접적인 가해행위를 한 행위자가 지는 것이 원칙이나 가해행위를 교사하거나 방조한 자도 제760조 제3항에 따라서 직접 행위자와 더불어 공동불법행위책임을 지게 된다.\n㈁ 敎唆란 甲이 乙에게 일정한 금원을 지급하여 평소 원한관계에 있던 丙의 가게에 불을 놓게 하는 경우와 같이 타인으로 하여금 불법행위를 하도록 결의하게 하는 것을 말한다.\n㈂ 幇助란 불법행위를 용이하게 하는 직접․간접의 모든 행위를 가리키는 것으로서 고의나 과실로도 가능하며, 또한 작위에 의한 경우뿐만 아니라 작위의무가 있는 자가 그것을 방지하여야 할 제반조치를 하지 않는 부작위에 의해서도 가능하다. 예를 들어 건축업자 甲은 부실시공을 하고 감리자인 乙이 이를 묵과하였는데 건물이 붕괴되어 丙이 사망한 경우, 이때 甲과 이를 방조한 乙도 공동불법행위의 책임을 지게 된다.\n㈃ 물론 교사자나 방조자가 공동불법행위책임을 지기 위해서는 교사·방조와 피교사자 또는 피방조자의 가해행위 간에 상당인과관계가 있어야 한다. 또한 교사·방조와 피해자의 손해 발생 사이에도 상당인과관계가 있어야 한다. 즉, 교사자나 방조자는 불법행위자의 손해를 함께 야기하였다는 점에서 배상책임이 인정된다.\nv 대법원 2014. 3. 27. 선고 2013다91597 판결 : [1] 민법 제760조 제3항은 불법행위의 방조자를 공동행위자로 보아 방조자에게 공동불법행위의 책임을 부담시키고 있는바, 방조는 불법행위를 용이하게 하는 직접, 간접의 모든 행위를 가리키는 것으로서 작위에 의한 경우뿐만 아니라 작위의무 있는 사람이 그것을 방지하여야 할 제반 조치를 취하지 아니하는 부작위로 인하여 불법행위자의 실행행위를 용이하게 하는 경우도 포함하며, 손해의 전보를 목적으로 하여 과실을 원칙적으로 고의와 동일시하는 민사법의 영역에서는 과실에 의한 방조도 가능하다. 그런데 이 경우의 과실의 내용은 불법행위에 도움을 주지 말아야 할 주의의무가 있음을 전제로 하여 그 의무를 위반하는 것을 말하고, 방조자에게 공동불법행위자로서 책임을 지우기 위하여는 방조행위와 피해자의 손해 발생 사이에 상당인과관계가 있어야 한다. 그리고 상당인과관계가 있는지 여부는 과실에 의한 방조가 피해 발생에 끼친 영향, 피해자의 신뢰 형성에 기여한 정도, 피해자 스스로 쉽게 피해 방지를 할 수 있었는지 등을 종합적으로 고려하여 판단하여야 한다.\nv 대법원 2014. 1. 29. 선고 2011다107627 판결 : 민법 제760조 제3항은 교사자나 방조자는 공동행위자로 본다고 규정하여 교사자나 방조자에게 공동불법행위자로서 책임을 부담시키고 있는바, 방조라 함은 불법행위를 용이하게 하는 직접, 간접의 모든 행위를 가리키는 것으로서 작위에 의한 경우뿐만 아니라 작위의무 있는 자가 그것을 방지하여야 할 제반 조치를 취하지 아니하는 부작위로 인하여 불법행위자의 실행행위를 용이하게 하는 경우도 포함하는 것이고, 이러한 불법행위의 방조는 형법과 달리 손해의 전보를 목적으로 하여 과실을 원칙적으로 고의와 동일시하는 민법의 해석으로서는 과실에 의한 방조도 가능하다고 할 것이며, 이 경우의 과실의 내용은 불법행위에 도움을 주지 않아야 할 주의의무가 있음을 전제로 하여 이 의무에 위반하는 것을 말하고, 방조자에게 공동불법행위자로서의 책임을 지우기 위하여는 방조행위와 피방조자의 불법행위 사이에 상당인과관계가 있어야 한다."},{"n":139,"text":"v 대판 2001. 5. 8., 2001다2181 : [사실관계] 甲은 乙이 경영하는 회사의 경리직원으로 근무하면서 1년여에 걸쳐 44회에 걸쳐 회사공금 3억 원 가량을 횡령하는 불법행위를 저질렀는데, 甲과 사실혼관계에 있던 丙은 甲에게 회사의 월급 이외에 별다른 소득원이 없다는 사실을 알면서 장기간에 걸쳐 甲이 자신의 월급의 몇 배나 되는 금원을 매월 1회 내지 4회에 걸쳐 계속하여 송금한 금원을 수령하였으며, 사업자금 명목으로 甲에게 송금을 요구하기도 하였다. 그리고 丙은 甲이 이전에 근무하던 직장에서도 횡령으로 형사처벌을 받은 사실까지 알고 있었다.\n[판결요지] [1] 수인이 공동하여 타인에게 손해를 가하는 민법 제760조의 공동불법행위의 경우 행위자 상호 간의 공모는 물론 공동의 인식을 필요로 하지 아니하고, 다만 객관적으로 그 공동행위가 관련공동되어 있으면 족하고, 그 관련공동성 있는 행위에 의하여 손해가 발생함으로써 그에 대한 배상책임을 지는 공동불법행위가 성립하는 것이며, 공동불법행위에서 방조라 함은 불법행위를 용이하게 하는 직접·간접의 모든 행위를 가리키는 것이다.\n[2] 회사직원의 공금횡령행위에 대하여 구체적인 공모를 하지는 않았지만 그가 정상적이 아닌 부정한 방법으로 금원을 마련하여 송금하는 사정을 미필적으로나마 인식하고 있으면서도 이를 계속하여 묵인한 채 송금을 받은 경우, 횡령행위에 대한 방조 또는 장물취득행위에 해당한다.\nv 대법원 2010. 3. 11. 선고 2009다4343 판결 : [3] 인터넷 포털사이트를 운영하는 온라인서비스제공자가 제공한 인터넷 게시공간에 타인의 저작권을 침해하는 게시물이 게시되었고 그 검색 기능을 통하여 인터넷 이용자들이 위 게시물을 쉽게 찾을 수 있다 하더라도, 위와 같은 사정만으로 곧바로 위 서비스제공자에게 저작권 침해 게시물에 대한 불법행위책임을 지울 수는 없다. 다만 저작권 침해 게시물이 게시된 목적, 내용, 게시기간과 방법, 그로 인한 피해의 정도, 게시자와 피해자의 관계, 삭제 요구의 유무 등 게시에 관련한 쌍방의 대응태도, 관련 인터넷 기술의 발전 수준, 기술적 수단의 도입에 따른 경제적 비용 등에 비추어, 위 서비스제공자가 제공하는 인터넷 게시공간에 게시된 저작권 침해 게시물의 불법성이 명백하고, 위 서비스제공자가 위와 같은 게시물로 인하여 저작권을 침해당한 피해자로부터 구체적·개별적인 게시물의 삭제 및 차단 요구를 받은 경우는 물론, 피해자로부터 직접적인 요구를 받지 않은 경우라 하더라도 그 게시물이 게시된 사정을 구체적으로 인식하고 있었거나 그 게시물의 존재를 인식할 수 있었음이 외관상 명백히 드러나며, 또한 기술적, 경제적으로 그 게시물에 대한 관리·통제가 가능한 경우에는, 위 서비스제공자에게 그 게시물을 삭제하고 향후 같은 인터넷 게시공간에 유사한 내용의 게시물이 게시되지 않도록 차단하는 등의 적절한 조치를 취하여야 할 의무가 있으므로, 이를 위반하여 게시자의 저작권 침해를 용이하게 하는 경우에는 위 게시물을 직접 게시한 자의 행위에 대하여 부작위에 의한 방조자로서 공동불법행위책임이 성립한다.\nv 전주지법 2012. 5. 23. 선고 2011나9771 판결 : 甲이 기존에 전혀 거래관계가 없던 성명불상자에게서 전화로 거액의 거래를 제안받은 후 乙 명의 은행계좌에 송금하였는데, 필리핀 여행가이드업자 乙은 여행객 丙에게서 이른바 환치기의 방법으로 원화를 필리핀 화폐로 바꿔달라는 부탁을 받고 국내에 있는 乙의 예금계좌를 알려준 다음 위와 같이 계좌에 입금된 것을 확인하고 丙에게 환전해 주었는데, 甲이 보이스피싱 사기에 의한 송금이었음을 이유로 乙을 상대로 불법행위에 기한 손해배상을 구한 사안에서, 乙이 성명불상자의 보이스피싱 범죄행위에 적극적으로 가담하지는 않았지만 위와 같은 환전행위가 외국환거래법상 금지되고, 乙이 신원을 잘 알지 못하는 자에게서 환전요청을 받아 환치기의 방법으로 환전해 주는 것이 국내의 범죄행위에 악용될 수도 있음을 예견할 수 있었을 것이라는 이유로, 적어도 과실로 성명불상자의 불법행위를 방조한 것이므로 공동불법행위자로서 甲에게 손해배상책임이 있다고 한 사례(다만 전화를 이용한 보이스피싱 피해가 사회적 문제로 부각되고 있는 상황에서 甲이 별다른 신원확인절차 없이 고액을 송금한 점 등 제반 사정에 비추어 乙의 책임을 전체 손해의 30%로 제한함)\n3. 공동불법행위자의 책임\n[사례] 아파트신축공사 감리자 甲은 어스앵커공법 시행으로 인하여 공사현장에 연접한 인근 기존아파트 옹벽에 위험이 생길 가능성을 예상하고도 토목전문건설회사 乙로 하여금 토목공사를 시공하도록 지시만 하였을 뿐 그 지시가 제대로 이행되는지를 확인하지 아니하고, 나아가 시공자 丙이 아무런 조치도 취하지 아니한 채 어스앵커공법을 시행하는 것을 방치하고 어스앵커 시공일 당일 인근 아파트 균열이 발생한 것을 확인하고도 공사중단명령을 내리지 아니하고 오히려 조속히 공사를 완료할 것을 지시하였다. 이후 공사현장의 인근 아파트 옹벽에 균열이 생겨 이에 아파트주민들이 甲․乙․丙에 대하여 공동불법행위책임을 묻자, 감리자인 甲은 다른 불법행위자인 乙․丙보다 불법행위에 기여한 정도가 경미하므로 자신의 손해배상의무가 제한되어야 한다고 주장한다. 이러한 甲의 주장은 타당한가? <解說> 아파트 옹벽의 균열로 인한 아파트주민들의 손해에 대하여 시공자인 丙은 물론이고, 수급인인 乙이 공동불법행위책임을 지는 것에는 의문이 없다. 다만 이때 감리자인 甲의 경우 손해에 대한 기여도가 작으므로 자신의 기여도만큼 손해배상의무가 제한될 수 있는지 문제가 되나, 판례는 공동불법행위제도의 취지를 고려하여 이를 부정한다(대판 2001. 9. 7, 99다70365).\n공동불법행위자는 연대해서 손해배상책임을 진다. 이때 ‘연대’의 의미에 대해서는 통설·판례가 부진정연대채무로 해석한다. 따라서 채무자 간에 주관적 공동관계가 없으므로 부담부분이 없고 원칙적으로"},{"n":140,"text":"구상관계가 인정되지 않지만, 판례는 일관되게 공평한 손해분담을 실현하기 위하여 과실 비율에 따라 부담부분이 있는 것으로 보고 있다.\nv 대법원 2006. 2. 9. 선고 2005다28426 판결 : 공동불법행위자는 채권자에 대한 관계에서는 부진정연대채무를 지되, 공동불법행위자들 내부관계에서는 일정한 부담 부분이 있고, 공동불법행위자 중 1인이 자기의 부담 부분 이상을 변제하여 공동의 면책을 얻게 하였을 때에는 다른 공동불법행위자에게 그 부담 부분의 비율에 따라 구상권을 행사할 수 있으므로 공동불법행위자가 구상권을 갖기 위하여는 반드시 피해자의 손해 전부를 배상하여야 할 필요는 없으나, 자기의 부담 부분을 초과하여 배상을 하여야 할 것이고, 피용자와 제3자가 공동불법행위로 피해자에게 손해를 가하여 그 손해배상채무를 부담하는 경우에 피용자와 제3자는 공동불법행위자로서 서로 부진정연대관계에 있고, 한편 사용자의 손해배상책임은 피용자의 배상책임에 대한 대체적 책임이어서 사용자도 제3자와 부진정연대관계에 있다고 보아야 할 것이므로, 사용자가 피용자와 제3자의 책임비율에 의하여 정해진 피용자의 부담 부분을 초과하여 피해자에게 손해를 배상한 경우에는 사용자는 제3자에 대하여도 구상권을 행사할 수 있다.\n(1) 공동불법행위자 간의 연대책임\n공동불법행위가 성립하게 되면 각 불법행위자들은 가해행위와 인과관계가 있는 손해에 대한 배상책임을 민법 제760조에 따라서 연대하여 지게 된다. 이때 “連帶하여”를 통설․판례는 각 행위자들이 손해 전부에 대한 배상의무를 부담한다고 이해하면서 손해배상채무를 ‘부진정연대채무’로 이해한다. 따라서 피해자는 공동불법행위자 중 누구에게라도 손해배상액 전부를 청구할 수 있고 공동불법행위자는 자신의 부담부분을 가지고 피해자에게 대항할 수 없다(연대채무의 대외관계). 그러나 공동불법행위자들 간에는 각자의 과실비율대로 부담부분이 인정된다(연대채무의 대내관계).\n공동불법행위책임에 따른 채무를 부진정연대채무로 이해하게 되면 연대채무자 1인에게 생긴 사유는 채권을 만족시키는 사유를 제외하고는 다른 채무자에게 영향을 주지 않는다. 즉 채무자 1인에게 생긴 사유 중에서 변제, 대물변제, 공탁, 상계만이 다른 채무자에게 영향을 미치며(소위 절대적 효력), 채무면제, 경개, 혼동, 소멸시효, 청구권 포기 등과 같은 사유들은 다른 채무자에게 영향을 미치지 않는다 (소위 상대적 효력).\nF 상계에 관해서 기존 판례는 절대적 효력을 부정했으나 2010년 전원합의체 판결에서 절대적 효력을 인정했다.\nv 대법원 2010. 9. 16. 선고 2008다97218 전원합의체 판결 : 부진정연대채무자 중 1인이 자신의 채권자에 대한 반대채권으로 상계를 한 경우에도 채권은 변제, 대물변제, 또는 공탁이 행하여진 경우와 동일하게 현실적으로 만족을 얻어 그 목적을 달성하는 것이므로, 그 상계로 인한 채무소멸의 효력은 소멸한 채무 전액에 관하여 다른 부진정연대채무자에 대하여도 미친다고 보아야 한다. 이는 부진정연대채무자 중 1인이 채권자와 상계계약을 체결한 경우에도 마찬가지이다. 나아가 이러한 법리는 채권자가 상계 내지 상계계약이 이루어질 당시 다른 부진정연대채무자의 존재를 알았는지 여부에 의하여 좌우되지 아니한다.\n(2) 공동불법행위에 있어서 손해배상범위\n공동불법행위자들 간에는 손해에 가공하는 정도가 다를 수 있다. 그러나 공동불법행위는 공동의 가해행위에 대해 연대책임을 지우는 것이므로 그로 인한 손해배상책임은 피해자에 대한 관계에서 공동불법행위자들 모두의 행위를 전체적으로 평가하여 정하게 된다. 따라서 가해자 중 1인이나 일부가 다른 가해자에 대하여 가담의 정도가 미약하다고 하더라도 피해자에 대한 관계에서 가담의 정도를 고려하여 그의 책임범위를 제한할 수 없다(불법행위에 있어서 각자의 기여도는 상호 간의 대내적 구상관계에서만 고려될 수 있다). 그러나 공동불법행위자별로 별개의 소를 제기한 경우에는 증명의 차이 등으로 손해액도 달리 인정될 수 있다.\nv 대법원 2001. 9. 7. 선고 99다70365 판결 : 공동불법행위 책임은 가해자 각 개인의 행위에 대하여 개별적으로 그로 인한 손해를 구하는 것이 아니라 그 가해자들이 공동으로 가한 불법행위에 대하여 그 책임을 추궁하는 것이므로, 공동불법행위로 인한 손해배상책임의 범위는 피해자에 대한 관계에서 가해자들 전원의 행위를 전체적으로 함께 평가하여 정하여야 하고, 그 손해배상액에 대하여는 가해자 각자가 그 금액의 전부에 대한 책임을 부담하는 것이며, 가해자 1인이 다른 가해자에 비하여 불법행위에 가공한 정도가 경미하다고 하더라도 피해자에 대한 관계에서 그 가해자의 책임 범위를"},{"n":141,"text":"위와 같이 정하여진 손해배상액의 일부로 제한하여 인정할 수는 없다.\nv 대법원 2001. 2. 9. 선고 2000다60227 판결 : [사실관계] 소외 1은 새벽 1시경 택시를 운전하고 편도 1차선 도로를 전방주시를 태만히 한 채 진행한 과실로 도로상에 쓰러져 있던 피해자를 택시 우측 앞 바퀴부분으로 역과하였고 그 뒤를 이어 소외 2가 승용차를 운전하고 전방주시를 태만히 한 채 위 도로를 진행하다가 다시 피해자를 역과함으로써 피해자가 사망하였다. 피해자의 유족인 원고가 소외 2의 보험회사를 상대로 손해배상청구의 소를 제기하여 일부 승소판결을 받고 그에 따라 합계 금 76,300,000원을 지급받았다. 그런데 원고가 소외 1의 공제회사인 피고를 상대로 추가로 손해배상소송을 제기하자 피고는 ‘손해배상청구권의 포기’, ‘전체손해의 전보’를 들어 항변하였다.\n[법원의 판단] 손해배상청구권의 포기주장과 관련해 법원은 원고가 손해배상청구권을 포기했는지도 불명확하고, 설사 원고가 소외 2의 보험회사에 대해 손해배상청구권을 포기했다 하더라도 피고에 대한 청구에는 영향을 미치지 않는다고 하였다. 다음으로 전체손해가 전보되었는지에 관해 법원은 “피해자가 공동불법행위자들을 모두 피고로 삼아 한꺼번에 손해배상청구의 소를 제기한 경우와 달리 공동불법행위자별로 별개의 소를 제기하여 소송을 진행하는 경우에는 각 소송에서 제출된 증거가 서로 다르고 이에 따라 교통사고의 경위와 피해자의 손해액산정의 기초가 되는 사실이 달리 인정됨으로 인하여 과실상계비율과 손해액도 서로 달리 인정될 수 있는 것이므로, 원고들이 엘지화재해상보험 주식회사를 상대로 한 손해배상 소송에서 승소한 금액을 전부 지급받았다고 하더라도 그 금액이 이 사건 손해배상 소송에서 산정된 손해액에 미치지 못한다면 피고는 그 차액을 원고들에게 지급할 의무가 있는 것이다.”라고 판시했다.\n(3) 과실상계\n불법행위에 있어서와 마찬가지로 공동불법행위에 있어서도 과실상계가 인정되는데, 이때 다수인 가해자에 대한 피해자의 과실을 어떻게 상계할 것인지가 문제 된다. 이에 대하여 판례는 원칙적으로 공동불법행위에 있어서 과실상계는 공동불법행위자 전원의 과실과 피해자의 공동불법행위자 전원에 대한 과실을 전체적으로 평가해야 한다고 본다(전체평가설). 다만, 고의가해자와 과실가해자가 있는 경우 고의가해자는 피해자에게 과실상계를 주장할 수 없지만 과실가해자는 피해자에게 과실상계를 주장할 수 있다.\nv 대법원 1997. 4. 11. 선고 97다3118 판결 : [사실관계] 소외 1은 그 소유의 승용차로 경부고속도로 하행선을 운전하여 가던 중 조향장치를 제대로 조작하지 못하고 중앙분리대를 들이받아 그 곳에 설치된 철제 방현망(가로 3.68m, 세로 0.6m) 5개를 파손시켜 그 중 1개를 상행선인 반대차선 2차선 상으로 떨어뜨렸는데, 약 10분 후 소외 망인이 승용차를 운전하고 상행선을 주행하다 위 방현망에 걸려 좌측 앞바퀴 등이 파손된 채 차량이 우측으로 쏠리면서 약 25m를 진행하다가 전방 차량들이 정체된 틈을 타 그 승용차에서 내려 이상 유무를 살피고자 동 승용차의 뒷쪽으로 걸어 오고 있던 중, 때마침 소외 2가 고속버스를 운전하고 상행선 2차선 상을 시속 약 95km로 망인 승용차 뒤를 따라 진행하다가 약 3m 전방에서 위 방현망을 발견하고 이를 피하고자 1차선으로 급히 차선을 변경하다가 1차선 상에서 차량 정체로 서행하고 있는 소외 르망 승용차와의 충돌 위험을 느껴 이를 피하고자 다시 조향장치를 우측으로 조작하였으나 미치지 못하고 위 르망 승용차 우측 뒷부분을 위 고속버스 좌측 앞부분으로 충격한 후 2차선 상으로 급진입하면서 위와 같이 걸어 나오고 있던 소외 망인을 위 고속버스의 앞부분으로 충격하여 동인으로 하여금 뇌좌상 등으로 즉시 그 자리에서 사망하게 하였다. 망인의 유족인 원고는 소외 1과 소외 2의 보험회사인 피고들을 상대로 손해배상소송을 제기하였다.\n[법원의 판단] 소외 1에게 사망사고의 책임이 있는가에 관해 법원은 상당인과관계를 인정하여 책임을 긍정하였다. 다음으로 과실상계를 함에 있어서 소외 1과 소외 2의 과실비율이 다르지만 전체적으로 평가하여 망인 : 소외 1, 2의 과실비율을 40:60으로 인정하였다.\n[판결요지] 공동불법행위 책임은 가해자 각 개인의 행위에 대하여 개별적으로 그로 인한 손해를 구하는 것이 아니라 그 가해자들이 공동으로 가한 불법행위에 대하여 그 책임을 추궁하는 것으로, 법원이 피해자의 과실을 들어 과실상계를 함에 있어서는 피해자의 공동불법행위자 각인에 대한 과실비율이 서로 다르더라도 피해자의 과실을 공동불법행위자 각인에 대한 과실로 개별적으로 평가할 것이 아니고 그들 전원에 대한 과실로 전체적으로 평가하여야 할 것이다.(이하 판결에서 공통)\nv 대법원 1998. 6. 12, 선고 96다55631 판결 : [사안정리] 丙의 자동차가 중앙선을 침범하여 甲의 승용차를 충돌하였고, 이 사고로 멈춰서있던 甲의 승용차를 뒤따라오던 乙의 자동차가 추돌하였다. 丙은 중앙선을 침범하여 과실이 크지만, 乙은 전방주시의무위반과 과속으로 그 정도가 약하였다. 甲 또한 전방주시의무를 게을리하여 丙과 충돌하는 사고를 당하였다. 甲이 乙에게 손해배상을 청구한 사안에서 원심은 과실상계를 하여 乙의 책임을 30%로 제한했지만, 대법원은 전체적 평가설에 비추어 과실상계를 너무 많이 했다고 하여 원심을 파기환송했다.\n[1] 공동불법행위의 성립에는 공동불법행위자 상호 간에 의사의 공통이나 공동의 인식이 필요하지 아니하고 객관적으로 각 행위에 관련공동성이 있으면 족하므로, 관련공동성 있는 행위에 의하여 손해가 발생하였다면 그 손해배상책임을 면할 수 없다.\n[2] 공동불법행위책임은 가해자 각 개인의 행위에 대하여 개별적으로 그로 인한 손해를 구하는 것이 아니라 가해자들이"},{"n":142,"text":"공동으로 가한 불법행위에 대하여 그 책임을 추궁하는 것으로, 법원이 피해자의 과실을 들어 과실상계를 함에 있어서는 피해자의 공동불법행위자 각인에 대한 과실비율이 서로 다르더라도 피해자의 과실을 공동불법행위자 각인에 대한 과실로 개별적으로 평가할 것이 아니고 그들 전원에 대한 과실로 전체적으로 평가하여야 한다.\nv 대법원 2000. 9. 8. 선고 99다48245 판결 : [사안정리] 축구골대의 하자로 인한 장파열과 전원상의 과실로 인한 사망 사건에서 법원은 “망인의 사망에 대한 피고 1(관광농원 경영자)의 과실과 피고 3(의사)의 과실(피고 2는 병원)이 동일하지 않더라도 ... 원고측의 과실을 피고들 전원의 과실과 전체적으로 평가”하여 원고 : 피고전체의 과실비율을 40 : 60으로 정하였다.\nv 대법원 2007. 6. 14. 선고 2005다32999 판결 : [사실관계] 피고는 자산관리주식회사(이하 소외 회사)의 영업부장이다. 피고는 원고에게 소외 회사 경영진으로부터 교육받은 내용을 그대로 들려주며 투자를 권유하고 소외 회사의 투자설명회에 참가하도록 적극 유도하였는데, 소외 회사 경영진은 원고가 투자한 금원을 불법적으로 수신하여 편취하였다. 원고도 경영진의 투자금 편취사실을 모른 채 9억 원을 투자하여 현재 약 6억 원의 손해를 입고 있다. 원고는 피고에 대하여 공동불법행위에 따른 손해배상책임을 물었다.\n[법원의 판단] 원심법원은 고의의 방조를 인정하였다. 대법원은 고의는 부정하였지만 과실에 의한 방조를 인정하였고, 결국 손해배상책임은 인정되었다. 문제는 과실상계가 어떻게 되는가이다.\n원심은 피고의 고의를 인정하여 과실상계를 인정하지 않았다. 그러나 대법원은 피고에게 과실만이 있다고 하여 과실상계를 인정하였다. 그 근거는 다음과 같다: “공동불법행위의 경우 ... 과실상계를 함에 있어서는 피해자의 공동불법행위자 각인에 대한 과실비율이 서로 다르더라도 피해자의 과실을 공동불법행위자 각인에 대한 과실로 개별적으로 평가할 것이 아니고 그들 전원에 대한 과실로 전체적으로 평가하여야 할 것이며, 이 경우 피해자의 부주의를 이용하여 고의로 불법행위를 저지른 자가 바로 그 피해자의 부주의를 이유로 자신의 책임을 감하여 달라고 주장하는 것은 허용될 수 없는 것이나, 불법행위자 중의 일부에게 그러한 사유가 있다고 하여 그러한 사유가 없는 다른 불법행위자까지도 과실상계의 주장을 할 수 없다고 해석할 것은 아니다. 그렇다면 피고가 과실로써 방조행위를 하여 공동불법행위책임을 부담하게 된 이 사건에서 다른 공동불법행위자인 소외인 등이 원고의 부주의를 이용하여 고의로 불법행위를 저질렀다는 사유만으로 피고의 과실상계 주장이 허용되지 않는 것으로 볼 수는 없[다.]”\nv 대법원 2010. 2. 11. 선고 2009다68408 판결: 공동불법행위책임은 가해자 각 개인의 행위에 대하여 개별적으로 그로 인한 손해를 구하는 것이 아니라 가해자들이 공동으로 가한 불법행위에 대하여 그 책임을 추궁하는 것이므로, 법원이 피해자의 과실을 들어 과실상계를 함에 있어서는 피해자의 공동불법행위자 각인에 대한 과실비율이 서로 다르더라도 피해자의 과실을 공동불법행위자 각인에 대한 과실로 개별적으로 평가할 것이 아니고 그들 전원에 대한 과실로 전체적으로 평가하여야 하나, 이는 과실상계를 위한 피해자의 과실을 평가함에 있어서 공동불법행위자 전원에 대한 과실로 전체적으로 평가하여야 한다는 것이지, 공동불법행위자 중에 고의로 불법행위를 행한 자가 있는 경우에는 피해자에게 과실이 없는 것으로 보아야 한다거나 모든 불법행위자가 과실상계의 주장을 할 수 없게 된다는 의미는 아니다.\nv 대법원 2018. 3. 22. 선고 2012다74236 전원합의체 판결: 금액이 다른 채무가 서로 부진정연대 관계에 있을 때 다액채무자가 일부 변제를 하는 경우 변제로 인하여 먼저 소멸하는 부분은 당사자의 의사와 채무 전액의 지급을 확실히 확보하려는 부진정연대채무 제도의 취지에 비추어 볼 때 다액채무자가 단독으로 채무를 부담하는 부분으로 보아야 한다. 이러한 법리는 사용자의 손해배상액이 피해자의 과실을 참작하여 과실상계를 한 결과 타인에게 직접 손해를 가한 피용자 자신의 손해배상액과 달라졌는데 다액채무자인 피용자가 손해배상액의 일부를 변제한 경우에 적용되고, 공동불법행위자들의 피해자에 대한 과실비율이 달라 손해배상액이 달라졌는데 다액채무자인 공동불법행위자가 손해배상액의 일부를 변제한 경우에도 적용된다. 또한 중개보조원을 고용한 개업공인중개사의 공인중개사법 제30조 제1항에 따른 손해배상액이 과실상계를 한 결과 거래당사자에게 직접 손해를 가한 중개보조원 자신의 손해배상액과 달라졌는데 다액채무자인 중개보조원이 손해배상액의 일부를 변제한 경우에도 마찬가지이다.\n(4) 공동불법행위에 있어서 구상관계\n[사례] 甲․乙․丙은 丁에게 상해를 가하여 丁에게 치료비, 위자료를 포함하여 총 9천만 원의 손해가 발생하였다. 이때 손해배상과 관련한 법률관계는?\n<解說> 공동불법행위자 甲․乙․丙이 丁에게 상해를 가하여 치료비를 포함한 9천만 원의 손해가 발생한 경우, 피해자 丁과의 관계에서 甲․乙․丙은 손해배상액 전부인 9천만 원에 대한 책임을 각각 지게 되므로 자신의 부담부분을 가지고 丁의 청구에 대항할 수 없으며, 피해자 丁은 甲․乙․丙 중 아무에게나 손해배상액 전부를 청구할 수 있다. 그러나 丁의 손해에 대하여 甲․乙․丙 간의 기여도가 다르므로 공동불법행위자인 이들 간에는 내부적으로 부담부분이 달리 정해질 수 있다. 따라서 만약 피해자 丁이 공동불법행위자 중 1인인 乙에게 손해배상액 전부인 9천만 원을 청구한 경우, 乙은 丁에 대하여 전액을 배상하여야 한다. 만약 손해에 대한 甲․乙․丙의 기여도가 각각 5:3:1이라면 이 경우 乙은 3천만 원(3/9)은 자신의 채무를 변제한 것이 되나, 나머지 6천만 원에 대해서는 다른 공동불법행위자인 甲과 丙에게 5:1의 비율로 구상할 수 있게 된다. 그리고 공동불법행위자들 간의 내부적인 부담부분은 각자의 고의나 과실,"},{"n":143,"text":"위법성, 변제능력 및 그 밖에도 신의칙에 따라서 결정하게 된다. 그러나 부담부분을 결정할 수 없는 경우에 각 행위자의 부담부분은 균등한 것으로 추정된다(제424조).\n공동불법행위자들은 부진정연대채무를 부담하게 된다. 따라서 이들 사이에는 주관적 공동관계가 존재하지 않으며 상호 간에 구상관계가 발생하지 않는 것이 원칙이다. 그러나 통설과 판례는 손해의 공평한 분담의 차원에서 공동불법행위자들 간에 과실비율에 따른 부담부분을 인정하여 자신의 부담부분을 넘는 배상의무를 이행한 자에게 구상권을 인정한다. 이때 구상채무는 원칙적으로 분할채무이다. 그러나 내부 부담비율이 0인 자가 다른 공동불법행위자에게 책임을 추궁할 때라면 부진정연대채무가 된다. 이는 내부 부담비율이 0인 공동불법행위자를 내부관계에서는 피해자와 유사하게 보기 때문이다.\nv 대법원 1997. 12. 12. 선고 96다50896 판결 : [1] 공동불법행위자는 채권자에 대한 관계에서는 연대책임(부진정연대채무)을 지되, 공동불법행위자들 내부관계에서는 일정한 부담 부분이 있고, 이 부담 부분은 공동불법행위자의 과실의 정도에 따라 정하여지는 것으로서 공동불법행위자 중 1인이 자기의 부담 부분 이상을 변제하여 공동의 면책을 얻게 하였을 때에는 다른 공동불법행위자에게 그 부담 부분의 비율에 따라 구상권을 행사할 수 있다.\n[2] 공동불법행위자 중 1인이 다른 공동불법행위자에 대하여 구상권을 행사하기 위하여는 자기의 부담 부분 이상을 변제하여 공동의 면책을 얻었음을 주장·입증하여야 하며, 위와 같은 법리는 피해자의 다른 공동불법행위자에 대한 손해배상청구권이 시효소멸한 후에 구상권을 행사하는 경우라고 하여 달리 볼 것이 아니다.\n[3] 피해자가 부진정연대채무자 중 1인에 대하여 손해배상에 관한 권리를 포기하거나 채무를 면제하는 의사표시를 하였다 하더라도 다른 채무자에 대하여 그 효력이 미친다고 볼 수는 없다.\n[4] 공동불법행위자 간 구상권의 발생 시점은 구상권자가 현실로 피해자에게 손해배상금을 지급한 때이다.\nv 구상권을 행사하는 공동불법행위자 측에 과실이 없는 경우 구상채무가 부진정연대관계에 있는지 여부(대판 2005. 10. 13, 2003다24147) : [사실관계] 운전자 甲은 빗길에 미끄러지는 바람에 중앙선을 침범하여 마주오던 택시 乙과 충돌하였고, 乙의 택시와 안전거리를 확보하지 않은 채 뒤따라오던 丙은 甲의 자동차의 사고로 정지해 있던 乙의 택시를 충돌하였다. 이 사고로 乙의 택시의 승객인 丁이 상해를 입었다. 이에 乙의 택시회사가 속한 전국택시운송사업조합연합회 X는 승객 丁에게 손해배상액 전부를 배상하고 난 뒤, 보험자대위(상법 제682조)에 따라 乙 소속 택시회사의 구상권을 대위행사하였다. 이때 X는 甲․丙 중 1인에게 손해배상액의 전부를 구상할 있는지 여부.\n[판결요지] 공동불법행위자 중 1인에 대하여 구상의무를 부담하는 다른 공동불법행위자가 수인인 경우에는 특별한 사정이 없는 이상 그들의 구상권자에 대한 채무는 각자의 부담 부분에 따른 분할채무로 봄이 상당하지만, 구상권자인 공동불법행위자측에 과실이 없는 경우, 즉 내부적인 부담 부분이 전혀 없는 경우에는 이와 달리 그에 대한 수인의 구상의무 사이의 관계를 부진정연대관계로 봄이 상당하다. (乙 택시의 기사에게는 과실이 없음)\nv 공동불법행위에 대하여 민법 제426조의 적용여부(대판 1998. 6. 26, 98다5777) : [사실관계] 甲은 乙과 공사계약을 체결하였고, 이에 甲이 운영하는 회사소속 직원인 丙이 乙 소유 공장에서 작업을 하던 중 甲의 피용자 X와 乙의 피용자 Y의 과실로 화재가 발생하여 丙이 화상을 입어 사망하였다. 이에 甲은 丙에게 손해전액을 배상하고 乙에게 구상권을 행사하였으나, 乙은 甲이 손해배상을 하면서 자신에게 사전이나 사후에도 아무런 통지를 하지 않았으며 자신은 丙에게 손해배상채무의 면제를 받았던 사실을 들어 구상의무에 응할 수 없다고 한다.\n[판결요지] 민법 제426조가 연대채무에 있어서의 변제에 관하여 채무자 상호 간에 통지의무를 인정하고 있는 취지는, 연대채무에 있어서는 채무자들 상호 간에 공동목적을 위한 주관적인 연관관계가 있고 이와 같은 주관적인 연관관계의 발생 근거가 된 대내적 관계에 터잡아 채무자 상호 간에 출연분담에 관한 관련관계가 있게 되므로, 구상관계에 있어서도 상호 밀접한 주관적인 관련관계를 인정하고 변제에 관하여 상호 통지의무를 인정함으로써 과실 없는 변제자를 보다 보호하려는 데 있으므로, 이와 같이 출연분담에 관한 주관적인 밀접한 연관관계가 없고 단지 채권만족이라는 목적만을 공통으로 하고 있는 부진정 연대채무에 있어서는 그 변제에 관하여 채무자 상호 간에 통지의무 관계를 인정할 수 없고, 변제로 인한 공동면책이 있는 경우에 있어서는 채무자 상호 간에 어떤 대내적인 특별관계에서 또는 형평의 관점에서 손해를 분담하는 관계가 있게 되는데 불과하다고 할 것이므로, 부진정 연대채무에 해당하는 공동불법행위로 인한 손해배상채무에 있어서도 채무자 상호 간에 구상요건으로서의 통지에 관한 민법의 위 규정을 유추 적용할 수는 없다.\nv 공동불법행위자 중 1인에 대한 채무면제의 효력(대판 1969. 8. 26, 69다962) : [사실관계] 광업권자인 甲(대한석탄공사)는 채굴업자인 乙에게 채굴에 관한 도급계약을 체결하면서, 채굴작업 중 갱내사고에 대해서는 수급인인 乙이 일체의 책임을 지기로 하였다. 그런데 작업 도중 乙의 피용자인 丙이 갱내 낙반사고로 중상을 입게 되었다. 이 낙반사고에 대하여 甲은 광산보안법상 갱내 낙반사고주의의무를 위반하였고, 乙은 丙의 사용자로서 갱내안전시설을 제대로 설치․관리하지 못한 데에 과실이 있음이 증명되었다. 그리고 피해자 丙은 乙에 대하여 손해배상청구권을 포기하기로 약정하였다. 이때 丙이 甲에 대하여 손해배상을 청구하는 경우, 甲이 丙의 乙에 대한 손해배상청구권의 포기로서 대항할 수 있는지 여부. [판결요지] 광업권자가 그 갱내의 광물 채굴작업을 제3자에게 도급시켜 그 수급자가 그 작업에 있어서의 모든 감독책임을 지기로 하고 그 갱내의 보안상의 의무와그 작업 중의 사고로 인한 재해보상의 책임을 부담하기로 한 도급계약이 있다고 하여 광업권자의 광산보안법상의 보안의무에 아무런 영향이 없다."},{"n":144,"text":"v 구상권의 소멸시효(대판 1996. 3. 26, 96다3791) : [사실관계] 甲 합자회사의 피용자인 乙의 과실로 발생한 교통사고로 丙이 손해를 입었고(2001. 10. 30), 이에 甲 회사와 공제계약을 체결한 공제조합 丁이 공제계약에 따라서 피해자 丙에게 손해배상채무를 이행하였다(2002. 5. 15). 이에 丁은 보험자대위에 따라 甲회사가 乙에 대하여 가지는 구상권을 행사하였으나(2005. 3. 20), 乙은 공동불법행위자인 자신에 대한 피해자의 손해배상채권이 3년의 소멸시효로 소멸하였음을 들어 丁이 보험자대위로 취득한 자신에 대한 구상권도 소멸하였다고 주장한다.\n[판결요지] [1] 피해자에게 손해배상을 한 공동불법행위자의 다른 공동불법행위자에 대한 구상권은 피해자의 다른 공동불법행위자에 대한 손해배상채권과는 그 발생 원인과 법적 성질을 달리하는 별개의 독립한 권리이므로, 공동불법행위자가 다른 공동불법행위자에 대한 구상권을 취득한 이후에 피해자의 그 다른 공동불법행위자에 대한 손해배상채권이 시효로 소멸되었다고 하여 그러한 사정만으로 이미 취득한 구상권이 소멸된다고 할 수 없다.\n[2] 공동불법행위자의 다른 공동불법행위자에 대한 구상권의 소멸시효는 그 구상권이 발생한 시점, 즉 구상권자가 공동면책행위를 한 때로부터 기산하여야 할 것이고, 그 기간도 일반 채권과 같이 10년으로 보아야 한다.\n[3] 공제조합이 공동불법행위자 중의 1인과 체결한 공제계약에 따라 그 공동불법행위자를 위하여 직접 피해자에게 배상함으로써 그 공동불법행위자의 다른 공동불법행위자에 대한 구상권을 보험자대위의 법리에 따라 취득한 경우, 공제계약이 상행위에 해당한다고 하여 그로 인하여 취득한 구상권 자체가 상사채권으로 변한다고 할 수 없다.\nv 대판 2001. 2. 15, 96다42420 : [사실관계] 민간인인 소외 甲은 1990. 3. 7. 소외회사 소유의 트럭을 운전하던 중, 피고 대한민국 산하 경찰청 소속 의경인 소외 乙이 운전하는 공무용 오토바이와 충돌하여, 위 오토바이 뒷좌석에 타고 있던 의경인 소외 丙이 상해를 입었다. 소외회사의 보험자인 원고 전국화물자동차운송사업조합연합회는 피해자 丙에게 치료비 및 합의금으로 4,733만 원을 지급한 후, 피고 대한민국에 대하여 피고의 부담부분이 50%라고 주장하면서 구상금을 구하는 소송을 제기하였다.\n[관련조문] 헌법 제29조(국가·공공단체의 배상책임) ① 공무원의 직무상 불법행위로 손해를 받은 국민은 법률이 정하는 바에 의하여 국가 또는 공공단체에 정당한 배상을 청구할 수 있다. 이 경우 공무원 자신의 책임은 면제되지 아니한다.\n② 군인·군무원·경찰공무원 기타 법률이 정하는 자가 전투·훈련 등 직무집행과 관련하여 받은 손해에 대하여는 법률이 정하는 보상 외에 국가 또는 공공단체에 공무원의 직무상 불법행위로 인한 배상은 청구할 수 없다.\n국가배상법 제2조(배상책임) ① 국가 또는 지방자치단체는 공무원이 그 직무를 집행함에 당하여 고의 또는 과실로 법령에 위반하여 타인에게 손해를 가하거나, 자동차손해배상보장법의 규정에 의하여 손해배상의 책임이 있는 때에는 이 법에 의하여 그 손해를 배상하여야 한다. 다만, 군인·군무원·경찰공무원 또는 향토예비군대원이 전투·훈련·기타 직무집행과 관련하거나 국방 또는 치안유지의 목적상 사용하는 시설 및 자동차·함선·항공기·기타 운반기구 안에서 전사·순직 또는 공상을 입은 경우에 본인 또는 그 유족이 다른 법령의 규정에 의하여 재해보상금·유족연금·상이연금 등의 보상을 지급받을 수 있을 때 에는 이 법 및 민법의 규정에 의한 손해배상을 청구할 수 없다.\n[판결요지] [다수의견] 헌법 제29조 제2항, 국가배상법 제2조 제1항 단서의 입법 취지를 관철하기 위하여는, 국가배상법 제2조 제1항 단서가 적용되는 공무원의 직무상 불법행위로 인하여 직무집행과 관련하여 피해를 입은 군인 등에 대하여 위 불법행위에 관련된 일반국민(법인을 포함한다. 이하 '민간인'이라 한다)이 공동불법행위책임, 사용자책임, 자동차운행자책임 등에 의하여 그 손해를 자신의 귀책부분을 넘어서 배상한 경우에도, 국가 등은 피해 군인 등에 대한 국가배상책임을 면할 뿐만 아니라, 나아가 민간인에 대한 국가의 귀책비율에 따른 구상의무도 부담하지 않는다고 하여야 할 것이다. 그러나 위와 같은 경우, 민간인은 여전히 공동불법행위자 등이라는 이유로 피해 군인 등의 손해 전부를 배상할 책임을 부담하도록 하면서 국가 등에 대하여는 귀책비율에 따른 구상을 청구할 수 없도록 한다면, 공무원의 직무활동으로 빚어지는 이익의 귀속주체인 국가 등과 민간인과의 관계에서 원래는 국가 등이 부담하여야 할 손해까지 민간인이 부담하는 부당한 결과가 될 것이고(가해 공무원에게 경과실이 있는 경우에는 그 공무원은 손해배상책임을 부담하지 아니하므로 민간인으로서는 자신이 손해발생에 기여한 귀책부분을 넘는 손해까지 종국적으로 부담하는 불이익을 받게 될 것이고, 가해 공무원에게 고의 또는 중과실이 있는 경우에도 그 무자력 위험을 사용관계에 있는 국가 등이 부담하는 것이 아니라 오히려 민간인이 감수하게 되는 결과가 된다.), 이는 위 헌법과 국가배상법의 규정에 의하여도 정당화될 수 없다고 할 것이다. 이러한 부당한 결과를 방지하면서 위 헌법 및 국가배상법 규정의 입법 취지를 관철하기 위하여는, 피해 군인 등은 위 헌법 및 국가배상법 규정에 의하여 국가 등에 대한 배상청구권을 상실한 대신에 자신의 과실 유무나 그 정도와 관계없이 무자력의 위험부담이 없는 확실한 국가보상의 혜택을 받을 수 있는 지위에 있게 되는 특별한 이익을 누리고 있음에 반하여 민간인으로서는 손해 전부를 배상할 의무를 부담하면서도 국가 등에 대한 구상권을 행사할 수 없다고 한다면 부당하게 권리침해를 당하게 되는 결과가 되는 것과 같은 각 당사자의 이해관계의 실질을 고려하여, 위와 같은 경우에는 공동불법행위자 등이 부진정연대채무자로서 각자 피해자의 손해 전부를 배상할 의무를 부담하는 공동불법행위의 일반적인 경우와 달리 예외적으로 민간인은 피해 군인 등에 대하여 그 손해 중 국가 등이 민간인에 대한 구상의무를 부담한다면 그 내부적인 관계에서 부담하여야 할 부분을 제외한 나머지 자신의 부담부분에 한하여 손해배상의무를 부담하고, 한편 국가 등에 대하여는 그 귀책부분의 구상을 청구할 수 없다고 해석함이 상당하다 할 것이고, 이러한 해석이 손해의 공평·타당한 부담을 그 지도원리로 하는 손해배상제도의 이상에도 맞는다 할 것이다.\n[반대의견] 불법행위법은 피해자의 구제와 손해의 공평·타당한 부담·분배를 그 목적으로 하는바, 이러한 목적에 입각한 불법행위법의 일반원칙에 따르면 직접 불법행위를 한 자뿐만 아니라 그 사용자, 자동차운행자 등 손해의 발생에 대하여 일정한 책임이 있는 자들로 하여금 각자 피해자의 손해 전부를 배상할 의무를 부담하게 함으로써 피해자를 두텁게 보호하고, 한편 불법행위로 인한 손해발생에 관한 복수의 책임주체 중 일방이 피해자에게 그 손해를 자신의 귀책부분을"},{"n":145,"text":"넘어서 배상한 때에는 다른 책임주체에 대하여 그들 사이에서 손해발생에 기여한 정도 등 실질관계에 따라 정하여지는 부담부분을 구상할 수 있도록 함으로써 손해의 공평·타당한 부담·분배를 도모하게 되는 것이다. 이러한 불법행위법의 목적과 일반원칙에 비추어 볼 때, 가해 공무원의 사용자로서의 지위에서 피해 군인 등의 손해발생에 책임이 있는 국가 등의 손해배상의무가 위 헌법 및 국가배상법의 규정에 의하여 배제 또는 면제되었다고 하더라도, 피해자를 보호하기 위해서는 그 손해발생의 다른 책임주체인 민간인의 손해배상의무까지 감축된다고 할 수 없고 그 민간인은 여전히 피해 군인 등의 손해 전부를 배상할 의무가 있는 것이다. 한편, 손해의 공평·타당한 부담·배분을 위해서는 군인 등의 손해를 배상한 민간인이 국가 등에 대하여 구상권을 행사할 수 있다고 해석하여야 한다. 만약 국가 등이 군인 등의 손해 전부를 배상한 민간인에 대한 구상의무까지 부담하지 않는다면, 국가 등은 공무원의 직무행위로 빚어지는 이익의 귀속주체로서 그 손해의 발생에 책임이 있는 경우에도 그 손해 중 민간인과의 관계에서 원래는 자신이 부담함이 마땅한 부분을 민간인에게 전가시킴으로써 재산상 불이익을 주게 될 것인데, 이러한 결과는 공평과 재산권 보장의 정신에 반하고, 그것은 다수의견도 지적하는 바와 같이 위 헌법 및 국가배상법의 규정에 의하여 정당화될 수는 없기 때문이다.\n[보충의견] 다수의견은 공동불법행위자의 책임에 관하여 피해자를 두텁게 보호하기 위하여 그동안 우리의 지배적 학설과 판례가 취하여 온, 공동불법행위자는 각자 손해 전부에 대한 배상의무를 부담한다는 원칙은 여전히 타당하다고 보지만, 법률에 의하여 보장되는 국가보상청구권제도에 의하여 피해자의 구제가 확실해 보이는 이 사건과 같은 경우에 민간인이 국가에 대하여 구상권을 행사할 수 없다고 봄으로 인하여 민간인이 부당한 손해를 입을 수 있는 위험을 방지하기 위하여 앞에서 본 바와 같은 특별한 사정을 기초로 예외적으로 공동불법행위자인 민간인의 손해배상의무를 제한하려는 것이므로, 이로 인하여 불법행위제도에 의한 피해자 보호의 취지가 특별히 훼손된다거나 불법행위로 인한 피해자의 구제에 관하여 일관성 없는 차별적 처리를 초래할 위험이 있다고 볼 수는 없으며, 민간인의 손해배상의무가 제한된다고 보는 것은 피해자가 누구로부터 먼저 배상이나 보상을 받느냐에 따라 민간인이 최종적으로 부담할 손해배상액에 차이가 생기고, 경우에 따라서는 민간인의 부담 아래 피해자가 과잉배상을 받게 되는 부당한 결과를 방지하기 위한 것으로서, 민간인은 그 손해배상의무의 제한으로 인하여 부당한 이득을 얻는 것이 아니라, 그 반대의 경우에 발생할 수 있는 부당한 손해를 입을 위험이 없게 될 뿐이므로 다수의견이 피해자보다 민간인을 부당하게 더 두텁게 보호하려는 것으로 볼 수도 없다.\nv 대법원 2001. 1. 19. 선고 2000다33607 판결: 불법행위에 있어서 부진정연대채무의 관계에 있는 복수의 책임주체 중 1인이 자기 부담 부분 이상을 변제하여 공동의 면책을 얻게 하고 다른 부진정연대채무자에 대하여 그 부담 부분의 비율에 따라 구상권을 행사하는 경우 부담 부분의 비율을 판단함에 있어서는, 불법행위 및 손해와 관련하여 그 발생 내지 확대에 대한 각 부진정연대채무자의 주의의무의 정도에 상응한 과실의 정도를 비롯한 기여도 등 사고 내지 손해와 직접적으로 관련된 대외적 요소를 고려하여야 함은 물론, 나아가 부진정연대채무자 사이에 특별한 내부적 법률관계가 있어 그 실질적 관계를 기초로 한 요소를 참작하지 않으면 현저하게 형평에 어긋난다고 인정되는 경우에는 그 대내적 요소도 참작하여야 하며, 일정한 경우에는 그와 같은 제반 사정에 비추어 손해의 공평한 분담이라는 견지에서 신의칙상 상당하다고 인정되는 한도 내에서만 구상권을 행사하도록 제한할 수도 있다."}]);